static rtcore_private_storage::profile_kind
rtcore_v04_private_storage_profile() {
  static const rtcore_private_storage::profile_kind profile = []() {
    rtcore_private_storage::profile_kind parsed =
        rtcore_private_storage::kProfileLegacyShared832;
    const char *value =
        getenv(rtcore_private_storage::kSelectorEnvironmentName);
    const rtcore_private_storage::status_kind status =
        rtcore_private_storage::parse_profile(value, &parsed);
    if (status != rtcore_private_storage::kStatusOk) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_PRIVATE_STORAGE_PROFILE_FAULT "
              "selector=%s value=%s status=%s\n",
              rtcore_private_storage::kSelectorEnvironmentName,
              value != NULL ? value : "<null>",
              rtcore_private_storage::status_name(status));
      fflush(stderr);
      abort();
    }
    return parsed;
  }();
  return profile;
}

static rtcore_handoff_storage::profile_kind
rtcore_v04_handoff_storage_profile() {
  static const rtcore_handoff_storage::profile_kind profile = []() {
    rtcore_handoff_storage::profile_kind parsed =
        rtcore_handoff_storage::kProfileGlobal128;
    const char *value =
        getenv(rtcore_handoff_storage::kSelectorEnvironmentName);
    const rtcore_handoff_storage::status_kind status =
        rtcore_handoff_storage::parse_profile(value, &parsed);
    if (status != rtcore_handoff_storage::kStatusOk) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_HANDOFF_STORAGE_PROFILE_FAULT "
              "selector=%s value=%s status=%s\n",
              rtcore_handoff_storage::kSelectorEnvironmentName,
              value != NULL ? value : "<null>",
              rtcore_handoff_storage::status_name(status));
      fflush(stderr);
      abort();
    }
    return parsed;
  }();
  return profile;
}

static rtcore_private_placement::profile_kind
rtcore_v04_private_placement_profile() {
  static const rtcore_private_placement::profile_kind profile = []() {
    rtcore_private_placement::profile_kind parsed =
        rtcore_private_placement::kProfileGlobal384;
    const char *value =
        getenv(rtcore_private_placement::kSelectorEnvironmentName);
    rtcore_private_placement::status_kind status =
        rtcore_private_placement::parse_profile(value, &parsed);
    if (status == rtcore_private_placement::kStatusOk) {
      status = rtcore_private_placement::validate_storage_authority(
          parsed, rtcore_v04_private_storage_profile() ==
                      rtcore_private_storage::kProfileGlobal384);
    }
    if (status != rtcore_private_placement::kStatusOk) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_PRIVATE_PLACEMENT_PROFILE_FAULT "
              "selector=%s value=%s storage_profile=%s status=%s\n",
              rtcore_private_placement::kSelectorEnvironmentName,
              value != NULL ? value : "<null>",
              rtcore_private_storage::profile_name(
                  rtcore_v04_private_storage_profile()),
              rtcore_private_placement::status_name(status));
      fflush(stderr);
      abort();
    }
    return parsed;
  }();
  return profile;
}

static bool rtcore_v04_shared_placement_active() {
  return rtcore_v04_handoff_storage_profile() !=
             rtcore_handoff_storage::kProfileGlobal128 ||
         rtcore_v04_private_placement_profile() !=
             rtcore_private_placement::kProfileGlobal384;
}

static unsigned rtcore_v04_handoff_shared_uint_config(
    const char *name, unsigned default_value) {
  const char *value = getenv(name);
  if (value == NULL || value[0] == '\0') return default_value;
  char *end = NULL;
  const unsigned long parsed = strtoul(value, &end, 10);
  if (end == value || *end != '\0' || parsed == 0 || parsed > UINT_MAX) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_HANDOFF_SHARED_CONFIG_FAULT "
            "field=%s value=%s\n",
            name, value);
    fflush(stderr);
    abort();
  }
  return static_cast<unsigned>(parsed);
}

static rtcore_handoff_shared_timing::config_v0
rtcore_v04_handoff_shared_config() {
  rtcore_handoff_shared_timing::config_v0 config =
      rtcore_handoff_shared_timing::default_config();
  config.issue_budget = rtcore_v04_handoff_shared_uint_config(
      "VULKAN_SIM_RTCORE_REPLAY_V04_HANDOFF_SHARED_ISSUE_BUDGET",
      config.issue_budget);
  config.response_budget = rtcore_v04_handoff_shared_uint_config(
      "VULKAN_SIM_RTCORE_REPLAY_V04_HANDOFF_SHARED_RESPONSE_BUDGET",
      config.response_budget);
  config.base_latency = rtcore_v04_handoff_shared_uint_config(
      "VULKAN_SIM_RTCORE_REPLAY_V04_HANDOFF_SHARED_BASE_LATENCY",
      config.base_latency);
  config.ingress_capacity = rtcore_v04_handoff_shared_uint_config(
      "VULKAN_SIM_RTCORE_REPLAY_V04_HANDOFF_SHARED_INGRESS_CAPACITY",
      config.ingress_capacity);
  config.outstanding_capacity = rtcore_v04_handoff_shared_uint_config(
      "VULKAN_SIM_RTCORE_REPLAY_V04_HANDOFF_SHARED_OUTSTANDING_CAPACITY",
      config.outstanding_capacity);
  config.response_capacity = rtcore_v04_handoff_shared_uint_config(
      "VULKAN_SIM_RTCORE_REPLAY_V04_HANDOFF_SHARED_RESPONSE_CAPACITY",
      config.response_capacity);
  if (!rtcore_handoff_shared_timing::config_valid(config)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_HANDOFF_SHARED_CONFIG_FAULT "
            "field=combined status=invalid_configuration\n");
    fflush(stderr);
    abort();
  }
  return config;
}

static unsigned rtcore_v04_handoff_shared_charge_for_lanes(
    unsigned active_lane_count) {
  uint32_t bytes_per_lane = 0;
  const rtcore_handoff_storage::status_kind status =
      rtcore_handoff_storage::shared_bytes_per_lane(
          rtcore_v04_handoff_storage_profile(), &bytes_per_lane);
  if (status != rtcore_handoff_storage::kStatusOk ||
      (bytes_per_lane != 0 &&
       active_lane_count > UINT_MAX / bytes_per_lane)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_HANDOFF_SHARED_RESOURCE_FAULT "
            "active_lane_count=%u bytes_per_lane=%u status=%s\n",
            active_lane_count, bytes_per_lane,
            rtcore_handoff_storage::status_name(status));
    fflush(stderr);
    abort();
  }
  return active_lane_count * bytes_per_lane;
}

static unsigned rtcore_v04_private_shared_charge_for_lanes(
    unsigned active_lane_count) {
  uint32_t bytes_per_lane = 0;
  const rtcore_private_placement::status_kind status =
      rtcore_private_placement::shared_bytes_per_lane(
          rtcore_v04_private_placement_profile(), &bytes_per_lane);
  if (status != rtcore_private_placement::kStatusOk ||
      (bytes_per_lane != 0 &&
       active_lane_count > UINT_MAX / bytes_per_lane)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_PRIVATE_SHARED_RESOURCE_FAULT "
            "active_lane_count=%u bytes_per_lane=%u status=%s\n",
            active_lane_count, bytes_per_lane,
            rtcore_private_placement::status_name(status));
    fflush(stderr);
    abort();
  }
  return active_lane_count * bytes_per_lane;
}

static unsigned rtcore_v04_combined_shared_charge_for_lanes(
    unsigned active_lane_count) {
  const unsigned handoff =
      rtcore_v04_handoff_shared_charge_for_lanes(active_lane_count);
  const unsigned private_state =
      rtcore_v04_private_shared_charge_for_lanes(active_lane_count);
  if (private_state > UINT_MAX - handoff) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_SHARED_RESOURCE_FAULT "
            "active_lane_count=%u handoff_bytes=%u private_bytes=%u "
            "status=overflow\n",
            active_lane_count, handoff, private_state);
    fflush(stderr);
    abort();
  }
  return handoff + private_state;
}

static bool rtcore_replay_model_preset_simple_enabled() {
  static int enabled = []() {
    const char *value = getenv("VULKAN_SIM_RTCORE_REPLAY_MODEL_PRESET");
    if (value == NULL || *value == '\0' || strcmp(value, "0") == 0) {
      return 0;
    }
    return (strcmp(value, "simple") == 0 ||
            strcmp(value, "simple_replay_local") == 0 ||
            strcmp(value, "1") == 0)
               ? 1
               : 0;
  }();
  return enabled != 0;
}

static bool rtcore_shader_continuation_force_no_resubmit_enabled() {
  static int enabled = []() {
    const char *value =
        getenv("VULKAN_SIM_RTCORE_SHADER_CONTINUATION_FORCE_NO_RESUBMIT");
    if (value == NULL || *value == '\0') {
      return 0;
    }
    return strcmp(value, "0") != 0 ? 1 : 0;
  }();
  return enabled != 0;
}

static unsigned rtcore_shader_continuation_uint_config(const char *name,
                                                       unsigned default_value) {
  const char *value = getenv(name);
  if (value == NULL || *value == '\0') {
    return default_value;
  }

  char *end = NULL;
  const unsigned long parsed = strtoul(value, &end, 10);
  if (end == value || *end != '\0') {
    return default_value;
  }
  if (parsed > UINT_MAX) {
    return UINT_MAX;
  }
  return (unsigned)parsed;
}

