static bool rtcore_shader_call_payload_debug_enabled() {
  static const bool enabled = []() {
    const char *value =
        getenv("VULKAN_SIM_RTCORE_SHADER_CALL_PAYLOAD_DEBUG");
    return value != NULL &&
           (strcmp(value, "1") == 0 || strcmp(value, "true") == 0 ||
            strcmp(value, "TRUE") == 0 || strcmp(value, "on") == 0 ||
            strcmp(value, "ON") == 0);
  }();
  return enabled;
}

static void rtcore_print_shader_call_payload(
    const char *phase, unsigned owner_hw_sid, unsigned warp_uid,
    unsigned warp_id, unsigned lane_id, unsigned cohort_index,
    unsigned long long cycle, ptx_thread_info *thread) {
  if (!rtcore_shader_call_payload_debug_enabled()) return;
  if (thread == NULL) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_SHADER_CALL_PAYLOAD_DEBUG_FAULT "
            "phase=%s owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
            "cohort_index=%u fault=thread_state_missing\n",
            phase, owner_hw_sid, warp_uid, warp_id, lane_id, cohort_index);
    abort();
  }
  unsigned long long payload_address = 0;
  unsigned payload_size = 0;
  std::array<uint32_t, 12> words = {};
  if (!rtcore_read_shader_call_payload_debug_snapshot(
          thread, &payload_address, &payload_size, words.data())) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_SHADER_CALL_PAYLOAD_DEBUG_FAULT "
            "phase=%s owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
            "cohort_index=%u payload_address=0x%llx payload_size=%u "
            "fault=ray_payload_missing\n",
            phase, owner_hw_sid, warp_uid, warp_id, lane_id, cohort_index,
            payload_address, payload_size);
    abort();
  }

  unsigned long long hash = 1469598103934665603ull;
  const unsigned char *bytes =
      reinterpret_cast<const unsigned char *>(words.data());
  for (unsigned byte = 0; byte < sizeof(words); ++byte) {
    hash ^= bytes[byte];
    hash *= 1099511628211ull;
  }
  printf("GPGPU-Sim RTCORE_SHADER_CALL_PAYLOAD_DEBUG "
         "phase=%s owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
         "cohort_index=%u payload_address=0x%llx payload_size=%u "
         "payload_hash=0x%016llx "
         "words=%08x,%08x,%08x,%08x,%08x,%08x,"
         "%08x,%08x,%08x,%08x,%08x,%08x cycle=%llu\n",
         phase, owner_hw_sid, warp_uid, warp_id, lane_id, cohort_index,
         payload_address, payload_size,
         hash, words[0], words[1], words[2], words[3], words[4], words[5],
         words[6], words[7], words[8], words[9], words[10], words[11],
         cycle);
  fflush(stdout);
}

static bool rtcore_replay_env_enabled_or_model_preset(const char *name,
                                                      bool preset_enabled) {
  const char *value = getenv(name);
  if (value != NULL && *value != '\0') {
    return strcmp(value, "0") != 0;
  }
  return preset_enabled && rtcore_replay_model_preset_simple_enabled();
}

struct rtcore_warp_admission_budget_cycle_state {
  rtcore_warp_admission_budget_cycle_state() : cycle(0), used(0) {}
  unsigned long long cycle;
  unsigned used;
};

static std::map<unsigned, rtcore_warp_admission_budget_cycle_state>
    g_rtcore_warp_admission_budget_by_owner;

static unsigned rtcore_warp_admission_budget_config() {
  static unsigned budget = []() {
    const char *value =
        getenv("VULKAN_SIM_RTCORE_REPLAY_WARP_ADMISSION_BUDGET");
    if (value == NULL || *value == '\0') {
      return 1u;
    }
    char *end = NULL;
    unsigned long parsed = strtoul(value, &end, 10);
    if (end == value || parsed == 0) {
      return 1u;
    }
    if (parsed > 1024) {
      return 1024u;
    }
    return static_cast<unsigned>(parsed);
  }();
  return budget;
}

static unsigned rtcore_request_state_release_budget_config() {
  static unsigned budget = []() {
    const char *value =
        getenv("VULKAN_SIM_RTCORE_REQUEST_STATE_RELEASE_BUDGET");
    if (value == NULL || *value == '\0') {
      return 32u;
    }
    char *end = NULL;
    const unsigned long parsed = strtoul(value, &end, 10);
    if (end == value || *end != '\0' || parsed == 0) {
      return 32u;
    }
    return static_cast<unsigned>(parsed > 32 ? 32 : parsed);
  }();
  return budget;
}

static rtcore_warp_admission_budget_cycle_state &
rtcore_warp_admission_budget_state_for_owner(unsigned owner_hw_sid,
                                             unsigned long long issue_cycle) {
  rtcore_warp_admission_budget_cycle_state &state =
      g_rtcore_warp_admission_budget_by_owner[owner_hw_sid];
  if (state.cycle != issue_cycle) {
    state.cycle = issue_cycle;
    state.used = 0;
  }
  return state;
}

static bool rtcore_replay_cycle_hook_enabled() {
  static int cached_enabled = -1;
  if (cached_enabled < 0) {
    cached_enabled = rtcore_replay_env_enabled_or_model_preset(
                         "VULKAN_SIM_RTCORE_REPLAY_CYCLE_HOOK", true)
                         ? 1
                         : 0;
  }
  return cached_enabled != 0;
}

