static unsigned g_rtcore_next_shader_continuation_metadata_lookup_generation =
    1;
static unsigned g_rtcore_next_shader_continuation_handoff_read_generation = 1;

static void rtcore_complete_shader_continuation_pending(
    const rtcore_shader_continuation_dispatcher_pending_key &key,
    unsigned long long completion_cycle) {
  std::map<rtcore_shader_continuation_dispatcher_pending_key,
           std::vector<rtcore_shader_continuation_dispatcher_pending_entry> >
      ::iterator suspended =
          g_rtcore_shader_continuation_dispatcher_suspended.find(key);
  if (suspended == g_rtcore_shader_continuation_dispatcher_suspended.end() ||
      suspended->second.empty()) {
    g_rtcore_shader_continuation_dispatcher_pending.erase(key);
    if (suspended != g_rtcore_shader_continuation_dispatcher_suspended.end()) {
      g_rtcore_shader_continuation_dispatcher_suspended.erase(suspended);
    }
    return;
  }
  const rtcore_shader_continuation_dispatcher_pending_entry child =
      g_rtcore_shader_continuation_dispatcher_pending[key];
  rtcore_shader_continuation_dispatcher_pending_entry parent =
      suspended->second.back();
  suspended->second.pop_back();
  if (parent.logical_trace_invocation_id !=
          child.parent_trace_invocation_id ||
      parent.logical_trace_depth + 1 != child.logical_trace_depth ||
      !parent.call_inflight) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_KHR_RECURSIVE_TRACE_FAULT "
            "owner_hw_sid=%u warp_id=%u child_invocation_id=%u "
            "parent_invocation_id=%u depth=%u "
            "fault=parent_restore_identity_mismatch_fail_closed\n",
            key.owner_hw_sid, key.warp_id,
            child.logical_trace_invocation_id,
            child.parent_trace_invocation_id, child.logical_trace_depth);
    abort();
  }
  g_rtcore_shader_continuation_dispatcher_pending[key] = parent;
  if (suspended->second.empty()) {
    g_rtcore_shader_continuation_dispatcher_suspended.erase(suspended);
  }
  printf("GPGPU-Sim RTCORE_KHR_RECURSIVE_TRACE_PARENT_RESTORE "
         "owner_hw_sid=%u warp_id=%u child_invocation_id=%u "
         "parent_invocation_id=%u child_depth=%u parent_depth=%u "
         "parent_call_inflight=1 restore_cycle=%llu validated=1\n",
         key.owner_hw_sid, key.warp_id, child.logical_trace_invocation_id,
         parent.logical_trace_invocation_id, child.logical_trace_depth,
         parent.logical_trace_depth, completion_cycle);
  fflush(stdout);
}

static bool rtcore_validate_v04_native_source_authority(
    const rtcore_shader_continuation_dispatcher_pending_entry &entry,
    unsigned owner_hw_sid, unsigned lane,
    const ptx_instruction *source_inst, ptx_thread_info *thread) {
  if (!rtcore_v04_direct_completion(entry) || lane >= 32 ||
      source_inst == NULL || thread == NULL ||
      (entry.v04_native_identity_valid_mask & (1u << lane)) == 0) {
    return false;
  }
  const operand_info &context_operand = source_inst->operand_lookup(1);
  const operand_info &handoff_operand = source_inst->operand_lookup(2);
  const unsigned long long context_ptr =
      thread->get_reg(context_operand.get_symbol()).u64;
  const unsigned long long handoff_window_base =
      thread->get_reg(handoff_operand.get_symbol()).u64;
  if (context_ptr != entry.lane_v04_context_ptrs[lane] ||
      handoff_window_base !=
          entry.lane_v04_handoff_window_bases[lane]) {
    return false;
  }
  if (entry.v04_functional_only_completion) {
    return rtcore_validate_v04_functional_only_continuation_lane_authority(
        owner_hw_sid, entry.warp_uid, entry.warp_id,
        entry.active_mask, entry.v04_native_resident_generation,
        entry.v04_native_completion_transaction_generation, lane,
        context_ptr, handoff_window_base,
        entry.lane_v04_token_ids[lane],
        entry.lane_v04_token_allocator_generations[lane],
        entry.lane_v04_window_generations[lane],
        entry.lane_v04_packed_request_keys[lane],
        entry.lane_v04_request_generations[lane]);
  }
  return rtcore_validate_v04_native_continuation_lane_authority(
      owner_hw_sid, entry.warp_uid, entry.warp_id,
      entry.active_mask, entry.v04_native_resident_generation,
      entry.v04_native_completion_transaction_generation, lane,
      context_ptr, handoff_window_base,
      entry.lane_v04_token_ids[lane],
      entry.lane_v04_token_allocator_generations[lane],
      entry.lane_v04_window_generations[lane],
      entry.lane_v04_packed_request_keys[lane],
      entry.lane_v04_request_generations[lane]);
}

static bool rtcore_validate_v04_native_source_authority(
    const rtcore_replay_warp_completion_entry_snapshot &snapshot,
    unsigned owner_hw_sid, unsigned lane,
    const ptx_instruction *source_inst, ptx_thread_info *thread) {
  if (!rtcore_v04_direct_completion(snapshot) || lane >= 32 ||
      source_inst == NULL || thread == NULL ||
      (snapshot.v04_native_identity_valid_mask & (1u << lane)) == 0) {
    return false;
  }
  const operand_info &context_operand = source_inst->operand_lookup(1);
  const operand_info &handoff_operand = source_inst->operand_lookup(2);
  const unsigned long long context_ptr =
      thread->get_reg(context_operand.get_symbol()).u64;
  const unsigned long long handoff_window_base =
      thread->get_reg(handoff_operand.get_symbol()).u64;
  if (context_ptr != snapshot.v04_native_context_ptr[lane] ||
      handoff_window_base !=
          snapshot.v04_native_handoff_window_base[lane]) {
    return false;
  }
  if (snapshot.v04_functional_only_completion) {
    return rtcore_validate_v04_functional_only_continuation_lane_authority(
        owner_hw_sid, snapshot.warp_uid, snapshot.warp_id,
        snapshot.active_mask,
        snapshot.v04_native_resident_generation,
        snapshot.v04_native_completion_transaction_generation, lane,
        context_ptr, handoff_window_base,
        snapshot.v04_native_token_id[lane],
        snapshot.v04_native_token_allocator_generation[lane],
        snapshot.v04_native_window_generation[lane],
        snapshot.v04_native_packed_request_key[lane],
        snapshot.v04_native_request_generation[lane]);
  }
  return rtcore_validate_v04_native_continuation_lane_authority(
      owner_hw_sid, snapshot.warp_uid, snapshot.warp_id,
      snapshot.active_mask,
      snapshot.v04_native_resident_generation,
      snapshot.v04_native_completion_transaction_generation, lane,
      context_ptr, handoff_window_base,
      snapshot.v04_native_token_id[lane],
      snapshot.v04_native_token_allocator_generation[lane],
      snapshot.v04_native_window_generation[lane],
      snapshot.v04_native_packed_request_key[lane],
      snapshot.v04_native_request_generation[lane]);
}

static void rtcore_mark_v04_native_dispatch_cohort_complete(
    unsigned owner_hw_sid,
    const rtcore_shader_continuation_dispatcher_pending_entry &entry,
    unsigned completed_lane_mask) {
  if (entry.v04_functional_only_completion) {
    if (!rtcore_mark_v04_functional_only_dispatch_cohort_complete(
            owner_hw_sid, entry.warp_uid, entry.warp_id,
            entry.active_mask, entry.v04_native_resident_generation,
            entry.v04_native_completion_transaction_generation,
            completed_lane_mask)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_FUNCTIONAL_ONLY_FAULT "
              "owner_hw_sid=%u warp_uid=%u warp_id=%u "
              "completed_lane_mask=0x%08x "
              "fault=dispatch_cohort_completion_rejected\n",
              owner_hw_sid, entry.warp_uid, entry.warp_id,
              completed_lane_mask);
      fflush(stderr);
      abort();
    }
    return;
  }
  if (!entry.v04_native_resident_completion) return;
  if (!rtcore_mark_v04_native_continuation_dispatch_complete(
          owner_hw_sid, entry.warp_uid, entry.warp_id, entry.active_mask,
          entry.v04_native_resident_generation,
          entry.v04_native_completion_transaction_generation,
          completed_lane_mask)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_NATIVE_CONTINUATION_FAULT "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u "
            "completed_lane_mask=0x%08x "
            "fault=dispatch_cohort_completion_rejected\n",
            owner_hw_sid, entry.warp_uid, entry.warp_id,
            completed_lane_mask);
    fflush(stderr);
    abort();
  }
}

static bool rtcore_v04_completion_resident_slot(
    const rtcore_shader_continuation_dispatcher_pending_entry &entry,
    unsigned lane_mask, unsigned *resident_warp_slot) {
  namespace request_owner = rtcore::v04::request_owner;
  if (resident_warp_slot == NULL || lane_mask == 0 ||
      (lane_mask & ~entry.v04_native_identity_valid_mask) != 0) {
    return false;
  }
  bool found = false;
  unsigned selected_slot = 0;
  for (unsigned lane = 0; lane < 32; ++lane) {
    if ((lane_mask & (1u << lane)) == 0) continue;
    request_owner::internal_request_key_fields_v0 fields = {};
    if (request_owner::unpack_internal_request_key(
            entry.lane_v04_packed_request_keys[lane], &fields) !=
        request_owner::kStatusOk) {
      return false;
    }
    if (found && selected_slot != fields.resident_warp_slot) {
      return false;
    }
    selected_slot = fields.resident_warp_slot;
    found = true;
  }
  if (!found) return false;
  *resident_warp_slot = selected_slot;
  return true;
}

static void rtcore_record_v04_conservation_cohort_event_or_abort(
    unsigned owner_hw_sid,
    const rtcore_shader_continuation_dispatcher_pending_entry &entry,
    rtcore::v04::conservation::event_kind event,
    unsigned cohort_lane_mask, unsigned cohort_seq,
    unsigned long long current_cycle) {
  if (!rtcore::v04::conservation::enabled()) return;
  rtcore::v04::conservation::warp_event_v0 record = {};
  record.cycle = current_cycle;
  record.owner_hw_sid = owner_hw_sid;
  record.warp_uid = entry.warp_uid;
  record.warp_id = entry.warp_id;
  if (!rtcore_v04_completion_resident_slot(
          entry, cohort_lane_mask, &record.resident_warp_slot)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_CONSERVATION_FAULT "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u "
            "cohort_lane_mask=0x%08x "
            "phase=cohort_launch_resident_slot\n",
            owner_hw_sid, entry.warp_uid, entry.warp_id,
            cohort_lane_mask);
    fflush(stderr);
    abort();
  }
  record.resident_generation =
      entry.v04_native_resident_generation;
  record.completion_transaction_generation =
      entry.v04_native_completion_transaction_generation;
  record.active_mask = entry.active_mask;
  record.lane_mask = cohort_lane_mask;
  record.cohort_seq = cohort_seq;
  record.event = event;
  if (!rtcore::v04::conservation::emit_warp_event(record)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_CONSERVATION_FAULT "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u "
            "cohort_lane_mask=0x%08x cohort_seq=%u phase=%s\n",
            owner_hw_sid, entry.warp_uid, entry.warp_id,
            cohort_lane_mask, cohort_seq,
            rtcore::v04::conservation::event_name(event));
    fflush(stderr);
    abort();
  }
}

static void rtcore_publish_v04_terminated_final_cohort(
    unsigned owner_hw_sid,
    rtcore_shader_continuation_dispatcher_pending_entry *entry,
    unsigned terminal_lane_mask) {
  if (entry == NULL || !rtcore_v04_direct_completion(*entry) ||
      terminal_lane_mask == 0 ||
      (terminal_lane_mask & entry->pending_shader_terminal_mask) !=
          terminal_lane_mask) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_NATIVE_CONTINUATION_FAULT "
            "owner_hw_sid=%u terminal_lane_mask=0x%08x "
            "fault=terminated_final_cohort_identity_invalid\n",
            owner_hw_sid, terminal_lane_mask);
    fflush(stderr);
    abort();
  }
  if (entry->v04_native_resident_completion &&
      !rtcore_mark_v04_native_shader_terminal_publication(
          owner_hw_sid, entry->warp_uid, entry->warp_id,
          entry->active_mask, entry->v04_native_resident_generation,
          entry->v04_native_completion_transaction_generation,
          terminal_lane_mask)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_NATIVE_CONTINUATION_FAULT "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u "
            "terminal_lane_mask=0x%08x "
            "fault=shader_terminal_publication_rejected\n",
            owner_hw_sid, entry->warp_uid, entry->warp_id,
            terminal_lane_mask);
    fflush(stderr);
    abort();
  }
  entry->pending_shader_terminal_mask &= ~terminal_lane_mask;
  printf("GPGPU-Sim RTCORE_V04_TERMINATE_FINAL_SHADER_COMPLETE "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u "
         "terminal_lane_mask=0x%08x "
         "final_shader_authority=shadercore_continuation_dispatcher "
         "terminal_publication_after_final_shader=1\n",
         owner_hw_sid, entry->warp_uid, entry->warp_id,
         terminal_lane_mask);
  fflush(stdout);
}

static void rtcore_stage_v04_terminated_closest_hit_cohort(
    unsigned owner_hw_sid,
    rtcore_shader_continuation_dispatcher_pending_entry *entry,
    unsigned cohort_index, unsigned terminal_lane_mask) {
  if (entry == NULL || !rtcore_v04_direct_completion(*entry) ||
      cohort_index >= entry->cohort_count || terminal_lane_mask == 0 ||
      (terminal_lane_mask & ~entry->cohort_lane_masks[cohort_index]) != 0 ||
      entry->cohort_sbt_record_addrs[cohort_index] == 0 ||
      entry->cohort_sbt_record_components[cohort_index] != 1) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_NATIVE_CONTINUATION_FAULT "
            "owner_hw_sid=%u terminal_lane_mask=0x%08x "
            "fault=terminate_final_shader_staging_invalid\n",
            owner_hw_sid, terminal_lane_mask);
    fflush(stderr);
    abort();
  }

  entry->pending_shader_terminal_mask |= terminal_lane_mask;
  entry->cohort_lane_masks[cohort_index] = terminal_lane_mask;
  entry->cohort_shader_ids[cohort_index] = UINT_MAX;
  entry->cohort_sbt_aligned_32b_addrs[cohort_index] =
      entry->cohort_sbt_record_addrs[cohort_index] &
      ~static_cast<unsigned long long>(
          RTCORE_V02_LSU_MEMORY_REQUEST_GRANULE_BYTES - 1);
  entry->cohort_sbt_record_components[cohort_index] = 0;
  entry->target_shader_id_ready_mask &= ~terminal_lane_mask;
  for (unsigned lane = 0; lane < 32; ++lane) {
    if ((terminal_lane_mask & (1u << lane)) != 0) {
      entry->lane_reasons[lane] =
          RTCORE_SHADER_CONTINUATION_REASON_CLOSEST_HIT_READY;
    }
  }
  printf("GPGPU-Sim RTCORE_V04_TERMINATE_FINAL_SHADER_STAGED "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
         "terminal_lane_mask=0x%08x target_reason=%u "
         "shader_record_component=0 "
         "final_shader_authority=shadercore_continuation_dispatcher\n",
         owner_hw_sid, entry->warp_uid, entry->warp_id, cohort_index,
         terminal_lane_mask,
         RTCORE_SHADER_CONTINUATION_REASON_CLOSEST_HIT_READY);
  fflush(stdout);
}

static unsigned rtcore_shader_continuation_cohort_reason(
    const rtcore_shader_continuation_dispatcher_pending_entry &entry,
    unsigned cohort_index) {
  assert(cohort_index < entry.cohort_count);
  const unsigned cohort_lane_mask = entry.cohort_lane_masks[cohort_index];
  unsigned reason = 0;
  for (unsigned lane = 0; lane < 32; ++lane) {
    if ((cohort_lane_mask & (1u << lane)) == 0) continue;
    if (reason == 0) {
      reason = entry.lane_reasons[lane];
    } else {
      assert(reason == entry.lane_reasons[lane]);
    }
  }
  assert(reason != 0);
  return reason;
}

static void rtcore_enqueue_shader_continuation_dispatcher_pending(
    unsigned owner_hw_sid, unsigned warp_uid, unsigned warp_id,
    unsigned dynamic_warp_id, unsigned active_mask,
    unsigned target_shader_id_ready_mask, unsigned candidate_mask,
    unsigned cohort_count,
    const unsigned cohort_lane_masks[32],
    const unsigned cohort_shader_ids[32],
    const unsigned long long cohort_context_ptrs[32],
    const unsigned long long cohort_sbt_record_addrs[32],
    const unsigned long long cohort_sbt_aligned_32b_addrs[32],
    const unsigned cohort_sbt_record_components[32],
    unsigned static_inst_pc,
    const rtcore_replay_warp_completion_entry_snapshot &snapshot,
    unsigned long long enqueue_cycle) {
  if (candidate_mask == 0 || cohort_count == 0) {
    return;
  }
  assert(cohort_count <= 32);

  rtcore_shader_continuation_dispatcher_pending_key key;
  key.owner_hw_sid = owner_hw_sid;
  key.warp_id = warp_id;
  std::map<rtcore_shader_continuation_dispatcher_pending_key,
           rtcore_shader_continuation_dispatcher_pending_entry>::iterator
      existing = g_rtcore_shader_continuation_dispatcher_pending.find(key);
  const bool nested_trace =
      existing != g_rtcore_shader_continuation_dispatcher_pending.end() &&
      existing->second.valid;
  if (nested_trace &&
      (!rtcore_khr_recursive_trace_enabled() ||
       !existing->second.call_inflight)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_KHR_RECURSIVE_TRACE_FAULT "
            "owner_hw_sid=%u warp_id=%u "
            "fault=unexpected_live_parent_pending_fail_closed\n",
            owner_hw_sid, warp_id);
    abort();
  }
  const unsigned pipeline_trace_depth =
      rtcore_khr_max_pipeline_trace_depth();
  if (nested_trace && existing->second.logical_trace_depth + 1 >=
                          pipeline_trace_depth) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_KHR_RECURSIVE_TRACE_DEPTH_FAULT "
            "owner_hw_sid=%u warp_id=%u parent_invocation_id=%u "
            "parent_depth=%u pipeline_trace_depth=%u "
            "fault=trace_depth_overflow_fail_closed\n",
            owner_hw_sid, warp_id,
            existing->second.logical_trace_invocation_id,
            existing->second.logical_trace_depth,
            pipeline_trace_depth);
    abort();
  }

  rtcore_shader_continuation_dispatcher_pending_entry entry;
  entry.logical_trace_invocation_id = g_rtcore_next_trace_invocation_id++;
  if (g_rtcore_next_trace_invocation_id == 0) {
    g_rtcore_next_trace_invocation_id = 1;
  }
  if (nested_trace) {
    entry.parent_trace_invocation_id =
        existing->second.logical_trace_invocation_id;
    entry.logical_trace_depth = existing->second.logical_trace_depth + 1;
    g_rtcore_shader_continuation_dispatcher_suspended[key].push_back(
        existing->second);
    printf("GPGPU-Sim RTCORE_KHR_RECURSIVE_TRACE_CHILD_ADMIT "
           "owner_hw_sid=%u warp_id=%u parent_invocation_id=%u "
           "child_invocation_id=%u child_depth=%u active_mask=0x%08x "
           "physical_cta_admission=0 physical_warp_admission=0 "
           "parent_suspended=1\n",
           owner_hw_sid, warp_id, entry.parent_trace_invocation_id,
           entry.logical_trace_invocation_id, entry.logical_trace_depth,
           active_mask);
    fflush(stdout);
  }
  entry.valid = true;
  entry.warp_uid = warp_uid;
  entry.warp_id = warp_id;
  entry.dynamic_warp_id = dynamic_warp_id;
  entry.active_mask = active_mask;
  entry.target_shader_id_ready_mask = target_shader_id_ready_mask;
  entry.candidate_mask = candidate_mask;
  entry.cohort_count = cohort_count;
  for (unsigned index = 0; index < cohort_count && index < 32; ++index) {
    entry.cohort_lane_masks[index] = cohort_lane_masks[index];
    entry.cohort_shader_ids[index] = cohort_shader_ids[index];
    entry.cohort_context_ptrs[index] = cohort_context_ptrs[index];
    entry.cohort_sbt_record_addrs[index] = cohort_sbt_record_addrs[index];
    entry.cohort_sbt_aligned_32b_addrs[index] =
        cohort_sbt_aligned_32b_addrs[index];
    entry.cohort_sbt_record_components[index] =
        cohort_sbt_record_components[index];
  }
  entry.static_inst_pc = static_inst_pc;
  entry.v04_native_resident_completion =
      snapshot.v04_native_resident_completion;
  entry.v04_functional_only_completion =
      snapshot.v04_functional_only_completion;
  entry.v04_native_resident_generation =
      snapshot.v04_native_resident_generation;
  entry.v04_native_completion_transaction_generation =
      snapshot.v04_native_completion_transaction_generation;
  entry.v04_native_identity_valid_mask =
      snapshot.v04_native_identity_valid_mask;
  for (unsigned lane = 0; lane < 32; ++lane) {
    entry.lane_reasons[lane] = snapshot.lane_completion_reason[lane];
    if (rtcore_v04_direct_completion(snapshot)) {
      entry.lane_hit_record_selectors[lane] = 0;
      const std::array<uint32_t, rtcore::abi_v04::kWordCount> words = [&]() {
        std::array<uint32_t, rtcore::abi_v04::kWordCount> value = {};
        for (unsigned word = 0; word < rtcore::abi_v04::kWordCount; ++word) {
          value[word] = snapshot.handoff_words[lane][word];
        }
        return value;
      }();
      entry.lane_primitive_indices[lane] =
          rtcore::abi_v04::extract_field(
              words, rtcore::abi_v04::kPrimitiveIndex);
      entry.lane_instance_indices[lane] =
          rtcore::abi_v04::extract_field(
              words, rtcore::abi_v04::kInstanceIndex);
      entry.lane_hit_kinds[lane] =
          rtcore::abi_v04::extract_field(
              words, rtcore::abi_v04::kHitKind);
      entry.lane_hit_group_indices[lane] =
          rtcore::abi_v04::extract_field(
              words, rtcore::abi_v04::kSbtRecordOffset);
      entry.lane_geometry_types[lane] =
          entry.lane_reasons[lane] ==
                  RTCORE_SHADER_CONTINUATION_REASON_ANY_HIT_REQUIRED
              ? 1u
              : 2u;
      entry.lane_geometry_indices[lane] =
          rtcore::abi_v04::extract_field(
              words, rtcore::abi_v04::kGeometryIndex);
    } else {
      entry.lane_hit_record_selectors[lane] =
          snapshot.handoff_words[lane][1] +
          snapshot.handoff_words[lane][4] * snapshot.handoff_words[lane][2] +
          snapshot.handoff_words[lane][3];
      entry.lane_primitive_indices[lane] = snapshot.handoff_words[lane][6];
      entry.lane_instance_indices[lane] = snapshot.handoff_words[lane][7];
      entry.lane_hit_kinds[lane] = snapshot.handoff_words[lane][9] & 0xffu;
      entry.lane_hit_group_indices[lane] = snapshot.handoff_words[lane][3];
      entry.lane_geometry_types[lane] =
          (snapshot.handoff_words[lane][9] >> 8) & 0xffu;
      entry.lane_geometry_indices[lane] = snapshot.handoff_words[lane][4];
    }
    entry.lane_v04_boundary_ray_tmax_fp32[lane] =
        snapshot.v04_shadow_handoff_words[lane]
                                           [rtcore::abi_v04::kBoundaryRayTmaxFp32.word];
    entry.lane_v04_boundary_ray_tmax_valid[lane] =
        (snapshot.v04_shadow_boundary_image_valid_mask & (1u << lane)) != 0;
    entry.lane_boundary_candidates[lane] =
        snapshot.boundary_candidates[lane];
    entry.lane_v04_context_ptrs[lane] =
        snapshot.v04_native_context_ptr[lane];
    entry.lane_v04_handoff_window_bases[lane] =
        snapshot.v04_native_handoff_window_base[lane];
    entry.lane_v04_token_ids[lane] =
        snapshot.v04_native_token_id[lane];
    entry.lane_v04_token_allocator_generations[lane] =
        snapshot.v04_native_token_allocator_generation[lane];
    entry.lane_v04_window_generations[lane] =
        snapshot.v04_native_window_generation[lane];
    entry.lane_v04_packed_request_keys[lane] =
        snapshot.v04_native_packed_request_key[lane];
    entry.lane_v04_request_generations[lane] =
        snapshot.v04_native_request_generation[lane];
  }
  entry.enqueue_cycle = enqueue_cycle;

  g_rtcore_shader_continuation_dispatcher_pending[key] = entry;
}

static bool rtcore_issue_shader_continuation_sbt_metadata_request(
    unsigned owner_hw_sid,
    rtcore_shader_continuation_dispatcher_pending_entry &entry,
    unsigned long long current_cycle) {
  assert(entry.metadata_lookup_state ==
         RTCORE_SHADER_CONTINUATION_SBT_METADATA_NOT_REQUESTED);
  assert(entry.cohort_cursor < entry.cohort_count);
  const bool shared_l1d_request_route_enabled =
      rtcore_shared_lsu_frontend_arbiter_gate_enabled() ||
      rtcore_explicit_shared_l1d_request_arbiter_gate_enabled();
  if (!rtcore_replay_cycle_hook_enabled() ||
      !rtcore_replay_memory_unit_l1d_client_enabled() ||
      !shared_l1d_request_route_enabled) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_SHADER_CONTINUATION_SBT_METADATA_FAULT "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
            "cycle_hook_enabled=%u l1d_client_enabled=%u "
            "shared_l1d_request_route_enabled=%u "
            "fault=required_memory_route_disabled_fail_closed\n",
            owner_hw_sid, entry.warp_uid, entry.warp_id,
            entry.cohort_cursor,
            rtcore_replay_cycle_hook_enabled() ? 1u : 0u,
            rtcore_replay_memory_unit_l1d_client_enabled() ? 1u : 0u,
            shared_l1d_request_route_enabled ? 1u : 0u);
    fflush(stderr);
    return false;
  }
  const unsigned cohort_index = entry.cohort_cursor;
  const unsigned long long aligned_32b_addr =
      entry.cohort_sbt_aligned_32b_addrs[cohort_index];
  if (aligned_32b_addr == 0) {
    return false;
  }

  unsigned generation =
      g_rtcore_next_shader_continuation_metadata_lookup_generation++;
  if (generation == 0) {
    generation =
        g_rtcore_next_shader_continuation_metadata_lookup_generation++;
  }

  rtcore_memory_unit_request_snapshot snapshot = {};
  snapshot.valid = true;
  snapshot.response_target =
      RTCORE_V02_LSU_RESPONSE_TARGET_SHADER_CONTINUATION;
  snapshot.owner_hw_sid = owner_hw_sid;
  snapshot.rt_request_id = entry.warp_id;
  snapshot.lane_id = cohort_index;
  snapshot.memory_op_seq = generation;
  snapshot.chunk_id = 0;
  snapshot.chunk_count = 1;
  snapshot.access_kind = RTCORE_V02_LSU_ACCESS_SBT_METADATA;
  snapshot.aligned_32b_addr = aligned_32b_addr;
  snapshot.is_write = false;
  snapshot.issue_cycle = current_cycle;
  if (!rtcore_push_back_memory_unit_request_for_sm(owner_hw_sid, &snapshot)) {
    return false;
  }

  entry.metadata_lookup_state =
      RTCORE_SHADER_CONTINUATION_SBT_METADATA_WAITING_RESPONSE;
  entry.metadata_lookup_generation = generation;
  entry.metadata_lookup_aligned_32b_addr = aligned_32b_addr;
  entry.metadata_lookup_request_cycle = current_cycle;
  entry.metadata_lookup_response_cycle = 0;
  entry.metadata_lookup_wait_scheduler_cycles = 0;
  printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_SBT_METADATA_REQUEST "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
         "generation=%u cohort_lane_mask=0x%08x cohort_shader_id=%u "
         "context_ptr=0x%llx sbt_record_addr=0x%llx "
         "shader_record_component=%u "
         "aligned_32b_addr=0x%llx bytes=%u chunk_id=0 chunk_count=1 "
         "memory_route=shared_lsu_l1d request_cycle=%llu\n",
         owner_hw_sid, entry.warp_uid, entry.warp_id, cohort_index,
         generation, entry.cohort_lane_masks[cohort_index],
         entry.cohort_shader_ids[cohort_index],
         entry.cohort_context_ptrs[cohort_index],
         entry.cohort_sbt_record_addrs[cohort_index],
         entry.cohort_sbt_record_components[cohort_index], aligned_32b_addr,
         RTCORE_V02_LSU_MEMORY_REQUEST_GRANULE_BYTES, current_cycle);
  fflush(stdout);
  return true;
}

static void rtcore_record_shader_continuation_sbt_metadata_response(
    const rtcore_memory_unit_request_snapshot &snapshot,
    unsigned long long response_cycle) {
  rtcore_shader_continuation_dispatcher_pending_key key;
  key.owner_hw_sid = snapshot.owner_hw_sid;
  key.warp_id = snapshot.rt_request_id;
  std::map<rtcore_shader_continuation_dispatcher_pending_key,
           rtcore_shader_continuation_dispatcher_pending_entry>::iterator it =
      g_rtcore_shader_continuation_dispatcher_pending.find(key);
  const bool identity_matches =
      it != g_rtcore_shader_continuation_dispatcher_pending.end() &&
      it->second.valid &&
      it->second.metadata_lookup_state ==
          RTCORE_SHADER_CONTINUATION_SBT_METADATA_WAITING_RESPONSE &&
      it->second.cohort_cursor == snapshot.lane_id &&
      it->second.metadata_lookup_generation == snapshot.memory_op_seq &&
      it->second.metadata_lookup_aligned_32b_addr ==
          snapshot.aligned_32b_addr &&
      snapshot.response_target ==
          RTCORE_V02_LSU_RESPONSE_TARGET_SHADER_CONTINUATION &&
      snapshot.access_kind == RTCORE_V02_LSU_ACCESS_SBT_METADATA &&
      snapshot.chunk_id == 0 && snapshot.chunk_count == 1 &&
      !snapshot.is_write;
  if (!identity_matches) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_SHADER_CONTINUATION_SBT_METADATA_FAULT "
            "owner_hw_sid=%u warp_id=%u cohort_index=%u generation=%u "
            "aligned_32b_addr=0x%llx "
            "fault=stale_duplicate_or_mismatched_response_fail_closed\n",
            snapshot.owner_hw_sid, snapshot.rt_request_id, snapshot.lane_id,
            snapshot.memory_op_seq, snapshot.aligned_32b_addr);
    fflush(stderr);
    abort();
  }

  rtcore_shader_continuation_dispatcher_pending_entry &entry = it->second;
  entry.metadata_lookup_state =
      RTCORE_SHADER_CONTINUATION_SBT_METADATA_RESPONSE_READY;
  entry.metadata_lookup_response_cycle = response_cycle;
  printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_SBT_METADATA_RESPONSE "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
         "generation=%u aligned_32b_addr=0x%llx "
         "request_cycle=%llu response_cycle=%llu response_latency=%llu "
         "wake_target=shader_continuation_dispatcher\n",
         snapshot.owner_hw_sid, entry.warp_uid, entry.warp_id,
         snapshot.lane_id, snapshot.memory_op_seq,
         snapshot.aligned_32b_addr, entry.metadata_lookup_request_cycle,
         response_cycle,
         response_cycle >= entry.metadata_lookup_request_cycle
             ? response_cycle - entry.metadata_lookup_request_cycle
             : 0ull);
  fflush(stdout);
}

static rtcore::v04::address_range_registry::live_access_v0
rtcore_shader_continuation_handoff_live_access(
    const rtcore_memory_unit_request_snapshot &snapshot) {
  namespace registry = rtcore::v04::address_range_registry;
  registry::live_access_v0 access = {};
  access.owner.owner_hw_sid = snapshot.owner_hw_sid;
  access.owner.resident_warp_generation =
      snapshot.v04_dispatch_handoff_read.resident_warp_generation;
  access.owner.window_generation =
      snapshot.v04_dispatch_handoff_read.window_generation;
  access.lane_id = static_cast<uint8_t>(snapshot.lane_id);
  access.object = registry::kObjectHandoff;
  access.access = registry::kAccessHandoffShaderDispatchRead;
  access.aligned_32b_address = snapshot.aligned_32b_addr;
  access.byte_mask = snapshot.byte_mask;
  return access;
}

static bool rtcore_shader_continuation_selector_from_handoff(
    const uint32_t raw[rtcore::abi_v04::kWordCount], unsigned reason,
    unsigned *selector_out) {
  if (raw == NULL || selector_out == NULL) return false;
  std::array<uint32_t, rtcore::abi_v04::kWordCount> words = {};
  std::copy(raw, raw + rtcore::abi_v04::kWordCount, words.begin());
  uint64_t selector = 0;
  if (reason == RTCORE_SHADER_CONTINUATION_REASON_MISS) {
    selector = rtcore::abi_v04::extract_field(
        words, rtcore::abi_v04::kMissIndex);
  } else if (reason == RTCORE_SHADER_CONTINUATION_REASON_CLOSEST_HIT_READY ||
             reason == RTCORE_SHADER_CONTINUATION_REASON_ANY_HIT_REQUIRED ||
             reason == RTCORE_SHADER_CONTINUATION_REASON_INTERSECTION_REQUIRED) {
    const uint64_t offset = rtcore::abi_v04::extract_field(
        words, rtcore::abi_v04::kSbtRecordOffset);
    const uint64_t stride = rtcore::abi_v04::extract_field(
        words, rtcore::abi_v04::kSbtRecordStride);
    const uint64_t contribution = words[rtcore::abi_v04::kInstanceSbtContribution.word];
    const uint64_t geometry = words[rtcore::abi_v04::kGeometryIndex.word];
    selector = offset + contribution + geometry * stride;
  } else {
    return false;
  }
  if (selector > UINT_MAX) return false;
  *selector_out = static_cast<unsigned>(selector);
  return true;
}

static bool rtcore_issue_shader_continuation_handoff_reads(
    unsigned owner_hw_sid,
    rtcore_shader_continuation_dispatcher_pending_entry &entry,
    unsigned phase, unsigned long long current_cycle) {
  namespace bridge = rtcore::v04::pre_submit_publication;
  namespace registry = rtcore::v04::address_range_registry;
  if (!rtcore_v04_direct_completion(entry) ||
      (phase != RTCORE_SHADER_CONTINUATION_HANDOFF_READ_PHASE_SELECTION &&
       phase != RTCORE_SHADER_CONTINUATION_HANDOFF_READ_PHASE_ATTRIBUTES) ||
      entry.cohort_cursor >= entry.cohort_count ||
      entry.handoff_read_pending_count != 0) {
    return false;
  }
  const unsigned cohort_index = entry.cohort_cursor;
  const unsigned cohort_lane_mask = entry.cohort_lane_masks[cohort_index];
  if (phase == RTCORE_SHADER_CONTINUATION_HANDOFF_READ_PHASE_SELECTION) {
    for (unsigned lane = 0; lane < 32; ++lane) {
      if ((cohort_lane_mask & (1u << lane)) == 0) continue;
      entry.lane_handoff_response_chunk_mask[lane] = 0;
      entry.lane_v04_live_window_generations[lane] = 0;
      std::fill(entry.lane_handoff_words[lane],
                entry.lane_handoff_words[lane] +
                    rtcore::abi_v04::kWordCount,
                0u);
    }
  }
  unsigned generation =
      g_rtcore_next_shader_continuation_handoff_read_generation++;
  if (generation == 0) {
    generation =
        g_rtcore_next_shader_continuation_handoff_read_generation++;
  }

  std::vector<rtcore_memory_unit_request_snapshot> staged;
  for (unsigned lane = 0; lane < 32; ++lane) {
    if ((cohort_lane_mask & (1u << lane)) == 0) continue;
    std::array<uint32_t, rtcore::abi_v04::kWordCount> words = {};
    std::copy(entry.lane_handoff_words[lane],
              entry.lane_handoff_words[lane] + rtcore::abi_v04::kWordCount,
              words.begin());
    const rtcore::abi_v04::shader_input::dispatcher_read_plan plan =
        phase == RTCORE_SHADER_CONTINUATION_HANDOFF_READ_PHASE_SELECTION
            ? rtcore::abi_v04::shader_input::dispatch_selection_read_plan(
                  entry.lane_reasons[lane])
            : rtcore::abi_v04::shader_input::dispatch_attribute_read_plan(
                  words, entry.lane_reasons[lane]);
    if (!plan.valid()) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_FAULT "
              "owner_hw_sid=%u warp_id=%u cohort_index=%u lane_id=%u "
              "phase=%u fault=invalid_reason_selected_plan error=%s\n",
              owner_hw_sid, entry.warp_id, cohort_index, lane, phase,
              rtcore::abi_v04::shader_input::error_name(plan.status));
      fflush(stderr);
      goto rollback;
    }
    uint64_t lane_address = 0;
    if (!rtcore::abi_v04::shader_input::lane_slot_address(
            entry.lane_v04_handoff_window_bases[lane], lane,
            &lane_address)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_FAULT "
              "owner_hw_sid=%u warp_id=%u cohort_index=%u lane_id=%u "
              "phase=%u fault=lane_slot_address_invalid_fail_closed\n",
              owner_hw_sid, entry.warp_id, cohort_index, lane, phase);
      fflush(stderr);
      goto rollback;
    }
    for (unsigned read = 0; read < plan.read_count; ++read) {
      const rtcore::abi_v04::shader_input::dispatcher_chunk_read &chunk =
          plan.reads[read];
      if (chunk.chunk >=
              rtcore::abi_v04::shader_input::kLaneSlotChunkCount ||
          chunk.byte_mask == 0 ||
          lane_address > UINT64_MAX -
                             static_cast<uint64_t>(chunk.chunk) *
                                 RTCORE_V02_LSU_MEMORY_REQUEST_GRANULE_BYTES) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_FAULT "
                "owner_hw_sid=%u warp_id=%u cohort_index=%u lane_id=%u "
                "phase=%u chunk=%u byte_mask=0x%08x "
                "fault=chunk_plan_invalid_fail_closed\n",
                owner_hw_sid, entry.warp_id, cohort_index, lane, phase,
                chunk.chunk, chunk.byte_mask);
        fflush(stderr);
        goto rollback;
      }
      rtcore_memory_unit_request_snapshot snapshot = {};
      snapshot.valid = true;
      snapshot.address_space = RTCORE_MEMORY_ADDRESS_SPACE_GLOBAL;
      snapshot.operation = RTCORE_MEMORY_OPERATION_READ;
      snapshot.destination = RTCORE_MEMORY_DESTINATION_LEGACY;
      snapshot.response_target =
          RTCORE_V02_LSU_RESPONSE_TARGET_SHADER_CONTINUATION;
      snapshot.owner_hw_sid = owner_hw_sid;
      snapshot.rt_request_id = entry.warp_id;
      snapshot.lane_id = lane;
      snapshot.resident_warp_id = entry.warp_id;
      snapshot.request_generation = entry.v04_native_resident_generation;
      snapshot.memory_op_seq = generation;
      snapshot.access_kind = RTCORE_V02_LSU_ACCESS_HANDOFF_DISPATCH_READ;
      snapshot.aligned_32b_addr =
          lane_address + static_cast<uint64_t>(chunk.chunk) *
                             RTCORE_V02_LSU_MEMORY_REQUEST_GRANULE_BYTES;
      snapshot.byte_mask = chunk.byte_mask;
      snapshot.is_write = false;
      snapshot.issue_cycle = current_cycle;
      snapshot.v04_dispatch_handoff_read.resident_warp_generation =
          entry.v04_native_resident_generation;
      snapshot.v04_dispatch_handoff_read.dynamic_warp_id =
          entry.dynamic_warp_id;
      snapshot.v04_dispatch_handoff_read.warp_uid = entry.warp_uid;
      snapshot.v04_dispatch_handoff_read.cohort_lane_mask = cohort_lane_mask;
      snapshot.v04_dispatch_handoff_read.dispatch_generation = generation;
      snapshot.v04_dispatch_handoff_read.cohort_index =
          static_cast<uint16_t>(cohort_index);
      snapshot.v04_dispatch_handoff_read.lane_slot_chunk = chunk.chunk;
      snapshot.v04_dispatch_handoff_read.lane_read_count =
          static_cast<uint8_t>(plan.read_count);
      snapshot.v04_dispatch_handoff_read.phase = static_cast<uint8_t>(phase);
      snapshot.v04_dispatch_handoff_read.valid = 1;
      snapshot.v04_dispatch_handoff_read.preaccepted = 1;
      if (!rtcore_v04_add_semantic_memory_slice(
              &snapshot.v04_semantic_memory,
              RTCORE_V04_SEMANTIC_TAG_HANDOFF_SHADER_DISPATCH_READ,
              snapshot.byte_mask)) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_FAULT "
                "owner_hw_sid=%u warp_id=%u cohort_index=%u lane_id=%u "
                "phase=%u chunk=%u fault=semantic_slice_invalid_fail_closed\n",
                owner_hw_sid, entry.warp_id, cohort_index, lane, phase,
                chunk.chunk);
        fflush(stderr);
        goto rollback;
      }
      registry::live_access_v0 access = {};
      uint8_t verified_lane_slot_chunk = 0xffu;
      const bridge::status_kind access_status =
          bridge::shared_bridge().preflight_live_handoff_access(
              owner_hw_sid, entry.v04_native_resident_generation,
              static_cast<uint8_t>(lane),
              registry::kAccessHandoffShaderDispatchRead,
              snapshot.aligned_32b_addr, snapshot.byte_mask, &access,
              &verified_lane_slot_chunk);
      if (access_status != bridge::kStatusOk ||
          verified_lane_slot_chunk != chunk.chunk ||
          (entry.lane_v04_live_window_generations[lane] != 0 &&
           entry.lane_v04_live_window_generations[lane] !=
               access.owner.window_generation)) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_FAULT "
                "owner_hw_sid=%u warp_id=%u cohort_index=%u lane_id=%u "
                "phase=%u chunk=%u aligned_32b_addr=0x%llx "
                "bridge_status=%s fault=live_owner_preflight_fail_closed\n",
                owner_hw_sid, entry.warp_id, cohort_index, lane, phase,
                chunk.chunk, snapshot.aligned_32b_addr,
                bridge::status_name(access_status));
        fflush(stderr);
        goto rollback;
      }
      entry.lane_v04_live_window_generations[lane] =
          access.owner.window_generation;
      snapshot.v04_dispatch_handoff_read.window_generation =
          access.owner.window_generation;
      const bridge::status_kind preaccept_status =
          bridge::shared_bridge().begin_live_access_preaccept(access);
      if (preaccept_status != bridge::kStatusOk) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_FAULT "
                "owner_hw_sid=%u warp_id=%u cohort_index=%u lane_id=%u "
                "phase=%u chunk=%u aligned_32b_addr=0x%llx "
                "window_generation=%u bridge_status=%s "
                "fault=live_preaccept_rejected_fail_closed\n",
                owner_hw_sid, entry.warp_id, cohort_index, lane, phase,
                chunk.chunk, snapshot.aligned_32b_addr,
                snapshot.v04_dispatch_handoff_read.window_generation,
                bridge::status_name(preaccept_status));
        fflush(stderr);
        goto rollback;
      }
      staged.push_back(snapshot);
    }
  }

  if (phase == RTCORE_SHADER_CONTINUATION_HANDOFF_READ_PHASE_SELECTION &&
      staged.empty()) {
    return false;
  }
  if (staged.empty()) {
    entry.handoff_read_state =
        RTCORE_SHADER_CONTINUATION_HANDOFF_READ_CONTEXT_READY;
    return true;
  }
  for (unsigned index = 0; index < staged.size(); ++index) {
    staged[index].chunk_id = index;
    staged[index].chunk_count = staged.size();
    if (!rtcore_push_back_memory_unit_request_for_sm(owner_hw_sid,
                                                     &staged[index])) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_FAULT "
              "owner_hw_sid=%u warp_id=%u phase=%u "
              "fault=request_enqueue_fail_closed\n",
              owner_hw_sid, entry.warp_id, phase);
      fflush(stderr);
      abort();
    }
  }
  entry.handoff_read_state =
      phase == RTCORE_SHADER_CONTINUATION_HANDOFF_READ_PHASE_SELECTION
          ? RTCORE_SHADER_CONTINUATION_HANDOFF_READ_WAITING_SELECTION
          : RTCORE_SHADER_CONTINUATION_HANDOFF_READ_WAITING_ATTRIBUTES;
  entry.handoff_read_generation = generation;
  entry.handoff_read_pending_count = staged.size();
  entry.handoff_read_request_cycle = current_cycle;
  entry.handoff_read_response_cycle = 0;
  printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_REQUEST "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
         "generation=%u phase=%u cohort_lane_mask=0x%08x "
         "request_count=%zu memory_route=sm_continuation_l1d "
         "request_cycle=%llu\n",
         owner_hw_sid, entry.warp_uid, entry.warp_id, cohort_index,
         generation, phase, cohort_lane_mask, staged.size(), current_cycle);
  fflush(stdout);
  return true;

rollback:
  for (std::vector<rtcore_memory_unit_request_snapshot>::const_iterator it =
           staged.begin();
       it != staged.end(); ++it) {
    if (bridge::shared_bridge().cancel_live_access_preaccept(
            rtcore_shader_continuation_handoff_live_access(*it)) !=
        bridge::kStatusOk) {
      abort();
    }
  }
  return false;
}

static void rtcore_reset_shader_continuation_handoff_read(
    rtcore_shader_continuation_dispatcher_pending_entry *entry) {
  if (entry == NULL) return;
  entry->handoff_read_state =
      RTCORE_SHADER_CONTINUATION_HANDOFF_READ_NOT_REQUESTED;
  entry->handoff_read_generation = 0;
  entry->handoff_read_pending_count = 0;
  entry->handoff_read_request_cycle = 0;
  entry->handoff_read_response_cycle = 0;
  entry->handoff_selection_materialized = false;
}

static void rtcore_record_shader_continuation_handoff_read_response(
    const rtcore_memory_unit_request_snapshot &snapshot,
    unsigned long long response_cycle, unsigned long long response_address,
    const uint8_t *payload, unsigned payload_bytes) {
  namespace bridge = rtcore::v04::pre_submit_publication;
  namespace registry = rtcore::v04::address_range_registry;
  rtcore_shader_continuation_dispatcher_pending_key key = {};
  key.owner_hw_sid = snapshot.owner_hw_sid;
  key.warp_id = snapshot.rt_request_id;
  std::map<rtcore_shader_continuation_dispatcher_pending_key,
           rtcore_shader_continuation_dispatcher_pending_entry>::iterator it =
      g_rtcore_shader_continuation_dispatcher_pending.find(key);
  const unsigned phase = snapshot.v04_dispatch_handoff_read.phase;
  const bool waiting_phase =
      it != g_rtcore_shader_continuation_dispatcher_pending.end() &&
      ((phase == RTCORE_SHADER_CONTINUATION_HANDOFF_READ_PHASE_SELECTION &&
        it->second.handoff_read_state ==
            RTCORE_SHADER_CONTINUATION_HANDOFF_READ_WAITING_SELECTION) ||
       (phase == RTCORE_SHADER_CONTINUATION_HANDOFF_READ_PHASE_ATTRIBUTES &&
        it->second.handoff_read_state ==
            RTCORE_SHADER_CONTINUATION_HANDOFF_READ_WAITING_ATTRIBUTES));
  if (!waiting_phase || !it->second.valid || snapshot.is_write ||
      snapshot.v04_dispatch_handoff_read.valid != 1 ||
      snapshot.v04_dispatch_handoff_read.preaccepted != 0 ||
      snapshot.v04_live_transaction.valid != 1 ||
      snapshot.memory_op_seq != it->second.handoff_read_generation ||
      snapshot.v04_dispatch_handoff_read.dispatch_generation !=
          it->second.handoff_read_generation ||
      snapshot.v04_dispatch_handoff_read.resident_warp_generation !=
          it->second.v04_native_resident_generation ||
      snapshot.request_generation !=
          it->second.v04_native_resident_generation ||
      snapshot.v04_dispatch_handoff_read.dynamic_warp_id !=
          it->second.dynamic_warp_id ||
      snapshot.v04_dispatch_handoff_read.warp_uid != it->second.warp_uid ||
      snapshot.resident_warp_id != it->second.warp_id ||
      it->second.cohort_cursor >= it->second.cohort_count ||
      snapshot.v04_dispatch_handoff_read.cohort_index !=
          it->second.cohort_cursor ||
      snapshot.v04_dispatch_handoff_read.cohort_lane_mask !=
          it->second.cohort_lane_masks[it->second.cohort_cursor] ||
      snapshot.v04_dispatch_handoff_read.lane_read_count == 0 ||
      snapshot.lane_id >= 32 ||
      (it->second.cohort_lane_masks[it->second.cohort_cursor] &
       (1u << snapshot.lane_id)) == 0 ||
      snapshot.v04_dispatch_handoff_read.window_generation !=
          it->second.lane_v04_live_window_generations[snapshot.lane_id] ||
      response_address != snapshot.aligned_32b_addr || payload == NULL ||
      payload_bytes != RTCORE_V02_LSU_MEMORY_REQUEST_GRANULE_BYTES ||
      it->second.handoff_read_pending_count == 0) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_FAULT "
            "owner_hw_sid=%u warp_id=%u lane_id=%u phase=%u "
            "fault=stale_duplicate_or_mismatched_response_fail_closed\n",
            snapshot.owner_hw_sid, snapshot.rt_request_id,
            snapshot.lane_id, phase);
    fflush(stderr);
    abort();
  }
  rtcore_shader_continuation_dispatcher_pending_entry &entry = it->second;
  std::array<uint32_t, rtcore::abi_v04::kWordCount> current = {};
  std::copy(entry.lane_handoff_words[snapshot.lane_id],
            entry.lane_handoff_words[snapshot.lane_id] +
                rtcore::abi_v04::kWordCount,
            current.begin());
  const rtcore::abi_v04::shader_input::dispatcher_read_plan expected =
      phase == RTCORE_SHADER_CONTINUATION_HANDOFF_READ_PHASE_SELECTION
          ? rtcore::abi_v04::shader_input::dispatch_selection_read_plan(
                entry.lane_reasons[snapshot.lane_id])
          : rtcore::abi_v04::shader_input::dispatch_attribute_read_plan(
                current, entry.lane_reasons[snapshot.lane_id]);
  bool expected_request = false;
  for (unsigned read = 0; expected.valid() && read < expected.read_count;
       ++read) {
    if (expected.reads[read].chunk ==
            snapshot.v04_dispatch_handoff_read.lane_slot_chunk &&
        expected.reads[read].byte_mask == snapshot.byte_mask) {
      expected_request = true;
      break;
    }
  }
  const uint8_t chunk =
      snapshot.v04_dispatch_handoff_read.lane_slot_chunk;
  uint64_t expected_lane_address = 0;
  const uint64_t expected_chunk_offset =
      static_cast<uint64_t>(chunk) *
      RTCORE_V02_LSU_MEMORY_REQUEST_GRANULE_BYTES;
  const bool expected_address =
      chunk < rtcore::abi_v04::shader_input::kLaneSlotChunkCount &&
      rtcore::abi_v04::shader_input::lane_slot_address(
          entry.lane_v04_handoff_window_bases[snapshot.lane_id],
          snapshot.lane_id, &expected_lane_address) &&
      expected_lane_address <= UINT64_MAX - expected_chunk_offset &&
      snapshot.aligned_32b_addr ==
          expected_lane_address + expected_chunk_offset;
  if (!expected_request ||
      snapshot.v04_dispatch_handoff_read.lane_read_count !=
          expected.read_count ||
      chunk >= rtcore::abi_v04::shader_input::kLaneSlotChunkCount ||
      !expected_address ||
      (entry.lane_handoff_response_chunk_mask[snapshot.lane_id] &
       (uint8_t{1} << chunk)) != 0) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_FAULT "
            "owner_hw_sid=%u warp_id=%u lane_id=%u phase=%u chunk=%u "
            "fault=unexpected_or_duplicate_chunk_fail_closed\n",
            snapshot.owner_hw_sid, snapshot.rt_request_id,
            snapshot.lane_id, phase, chunk);
    fflush(stderr);
    abort();
  }

  registry::transaction_token_v0 token = {};
  token.transaction_id = snapshot.v04_live_transaction.transaction_id;
  token.record_id = snapshot.v04_live_transaction.record_id;
  token.owner_hw_sid = snapshot.v04_live_transaction.owner_hw_sid;
  token.owner_generation = snapshot.v04_live_transaction.owner_generation;
  token.window_generation = snapshot.v04_live_transaction.window_generation;
  token.lane_id = snapshot.v04_live_transaction.lane_id;
  token.object = static_cast<registry::object_kind>(
      snapshot.v04_live_transaction.object);
  token.access = static_cast<registry::access_kind>(
      snapshot.v04_live_transaction.access);
  if (token.access != registry::kAccessHandoffShaderDispatchRead ||
      bridge::shared_bridge().complete_live_access(token) !=
          registry::kStatusOk) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_FAULT "
            "owner_hw_sid=%u warp_id=%u lane_id=%u phase=%u "
            "fault=live_transaction_complete_fail_closed\n",
            snapshot.owner_hw_sid, snapshot.rt_request_id,
            snapshot.lane_id, phase);
    fflush(stderr);
    abort();
  }

  const unsigned chunk_byte_base =
      chunk * RTCORE_V02_LSU_MEMORY_REQUEST_GRANULE_BYTES;
  for (unsigned byte = 0; byte < payload_bytes; ++byte) {
    if ((snapshot.byte_mask & (uint32_t{1} << byte)) == 0) continue;
    const unsigned lane_byte = chunk_byte_base + byte;
    const unsigned word = lane_byte / sizeof(uint32_t);
    const unsigned byte_in_word = lane_byte % sizeof(uint32_t);
    entry.lane_handoff_words[snapshot.lane_id][word] |=
        static_cast<uint32_t>(payload[byte]) << (byte_in_word * 8);
  }
  entry.lane_handoff_response_chunk_mask[snapshot.lane_id] |=
      uint8_t{1} << chunk;
  --entry.handoff_read_pending_count;
  entry.handoff_read_response_cycle = response_cycle;
  if (entry.handoff_read_pending_count == 0) {
    if (phase ==
        RTCORE_SHADER_CONTINUATION_HANDOFF_READ_PHASE_SELECTION) {
      entry.handoff_read_state =
          RTCORE_SHADER_CONTINUATION_HANDOFF_READ_SELECTION_READY;
    } else {
      entry.handoff_read_state =
          RTCORE_SHADER_CONTINUATION_HANDOFF_READ_CONTEXT_READY;
    }
  }
  printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_RESPONSE "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
         "generation=%u lane_id=%u phase=%u slot_chunk=%u "
         "pending_count=%u request_cycle=%llu response_cycle=%llu\n",
         snapshot.owner_hw_sid, entry.warp_uid, entry.warp_id,
         entry.cohort_cursor, entry.handoff_read_generation,
         snapshot.lane_id, phase, chunk, entry.handoff_read_pending_count,
         entry.handoff_read_request_cycle, response_cycle);
  fflush(stdout);
}

static bool rtcore_materialize_shader_continuation_target_selection(
    shader_core_ctx *shader, unsigned owner_hw_sid,
    rtcore_shader_continuation_dispatcher_pending_entry *entry,
    unsigned long long current_cycle) {
  if (shader == NULL || entry == NULL ||
      !rtcore_v04_direct_completion(*entry) ||
      entry->handoff_read_state !=
          RTCORE_SHADER_CONTINUATION_HANDOFF_READ_SELECTION_READY ||
      entry->handoff_selection_materialized ||
      entry->cohort_cursor >= entry->cohort_count) {
    return false;
  }

  const unsigned cohort_index = entry->cohort_cursor;
  const unsigned cohort_lane_mask = entry->cohort_lane_masks[cohort_index];
  ptx_thread_info **thread_info = shader->get_thread_info();
  const unsigned warp_size = shader->get_warp_size();
  bool first_lane = true;
  unsigned cohort_reason = 0;
  unsigned cohort_selector = 0;
  unsigned long long cohort_context_ptr = 0;
  unsigned long long cohort_record_addr = 0;
  unsigned long long cohort_aligned_32b_addr = 0;
  unsigned cohort_component = UINT_MAX;

  for (unsigned lane = 0; lane < warp_size && lane < 32; ++lane) {
    if ((cohort_lane_mask & (1u << lane)) == 0) continue;
    ptx_thread_info *thread = thread_info[entry->warp_id * warp_size + lane];
    const ptx_instruction *source_inst =
        thread != NULL ? thread->get_inst(entry->static_inst_pc) : NULL;
    unsigned selector = 0;
    unsigned long long context_ptr = 0;
    unsigned long long record_addr = 0;
    unsigned long long aligned_32b_addr = 0;
    unsigned component = UINT_MAX;
    const unsigned reason = entry->lane_reasons[lane];
    const bool source_ready = source_inst != NULL;
    const bool authority_ready =
        source_ready && rtcore_validate_v04_native_source_authority(
                            *entry, owner_hw_sid, lane, source_inst, thread);
    const bool selector_ready =
        rtcore_shader_continuation_selector_from_handoff(
            entry->lane_handoff_words[lane], reason, &selector);
    const bool address_ready =
        source_ready && selector_ready &&
        rtcore_shader_continuation_load_sbt_metadata_request_address(
            source_inst, thread, reason, selector, &context_ptr,
            &record_addr, &aligned_32b_addr, &component);
    if (!source_ready || !authority_ready || !selector_ready ||
        !address_ready) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_SHADER_CONTINUATION_TARGET_SELECTION_FAULT "
              "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
              "lane_id=%u reason=%u source_ready=%u authority_ready=%u "
              "selector_ready=%u address_ready=%u selector=%u "
              "static_inst_pc=0x%x\n",
              owner_hw_sid, entry->warp_uid, entry->warp_id, cohort_index,
              lane, reason, source_ready ? 1u : 0u,
              authority_ready ? 1u : 0u, selector_ready ? 1u : 0u,
              address_ready ? 1u : 0u, selector, entry->static_inst_pc);
      fflush(stderr);
      return false;
    }
    if (first_lane) {
      first_lane = false;
      cohort_reason = reason;
      cohort_selector = selector;
      cohort_context_ptr = context_ptr;
      cohort_record_addr = record_addr;
      cohort_aligned_32b_addr = aligned_32b_addr;
      cohort_component = component;
    } else if (reason != cohort_reason || selector != cohort_selector ||
               record_addr != cohort_record_addr ||
               aligned_32b_addr != cohort_aligned_32b_addr ||
               component != cohort_component) {
      return false;
    }
    entry->lane_hit_record_selectors[lane] = selector;
  }
  if (first_lane || cohort_component > 1) return false;

  entry->cohort_context_ptrs[cohort_index] = cohort_context_ptr;
  entry->cohort_sbt_record_addrs[cohort_index] = cohort_record_addr;
  entry->cohort_sbt_aligned_32b_addrs[cohort_index] =
      cohort_aligned_32b_addr;
  entry->cohort_sbt_record_components[cohort_index] = cohort_component;
  entry->handoff_selection_materialized = true;
  printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_TARGET_SELECTION "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
         "cohort_lane_mask=0x%08x reason=%u selector=%u "
         "sbt_record_addr=0x%llx aligned_32b_addr=0x%llx "
         "shader_record_component=%u "
         "selection_source=timed_v04_handoff_response "
         "selection_cycle=%llu\n",
         owner_hw_sid, entry->warp_uid, entry->warp_id, cohort_index,
         cohort_lane_mask, cohort_reason, cohort_selector,
         cohort_record_addr, cohort_aligned_32b_addr, cohort_component,
         current_cycle);
  fflush(stdout);
  return true;
}

struct rtcore_shader_continuation_pseudo_op_result {
  rtcore_shader_continuation_pseudo_op_result()
      : pending_found(false), issued(false) {}
  bool pending_found;
  bool issued;
};

static rtcore_shader_continuation_pseudo_op_result
rtcore_service_shader_continuation_pseudo_op(
    shader_core_ctx *shader, unsigned owner_hw_sid, unsigned warp_id,
    unsigned dynamic_warp_id, unsigned current_pc,
    unsigned long long current_cycle) {
  rtcore_shader_continuation_pseudo_op_result result;
  rtcore_shader_continuation_dispatcher_pending_key key;
  key.owner_hw_sid = owner_hw_sid;
  key.warp_id = warp_id;

  std::map<rtcore_shader_continuation_dispatcher_pending_key,
           rtcore_shader_continuation_dispatcher_pending_entry>::iterator it =
      g_rtcore_shader_continuation_dispatcher_pending.find(key);
  if (it == g_rtcore_shader_continuation_dispatcher_pending.end() ||
      !it->second.valid) {
    return result;
  }

  result.pending_found = true;
  rtcore_shader_continuation_dispatcher_pending_entry &entry = it->second;
  assert(entry.dynamic_warp_id == dynamic_warp_id);

  if (entry.call_inflight) {
    if (current_pc != entry.return_pc) {
      result.pending_found = false;
      return result;
    }

    assert(entry.current_cohort_index == entry.cohort_cursor);
    assert(entry.body_issue_count > 0);
    const unsigned completed_cohort_index = entry.current_cohort_index;
    const unsigned completed_lane_mask =
        entry.cohort_lane_masks[completed_cohort_index];
    const unsigned completed_shader_id =
        entry.cohort_shader_ids[completed_cohort_index];
    const unsigned completed_conservation_cohort_seq =
        entry.conservation_inflight_cohort_seq;
    const unsigned completed_reason = rtcore_shader_continuation_cohort_reason(
        entry, completed_cohort_index);
    const bool handoff_return_required =
        rtcore_shader_continuation_requires_handoff_return(completed_reason);
    const bool terminated_final_cohort =
        completed_reason ==
            RTCORE_SHADER_CONTINUATION_REASON_CLOSEST_HIT_READY &&
        (completed_lane_mask & entry.pending_shader_terminal_mask) ==
            completed_lane_mask;
    assert(entry.current_call_requires_handoff_return ==
           handoff_return_required);
    assert(completed_conservation_cohort_seq != 0);
    ptx_thread_info **thread_info = shader->get_thread_info();
    const unsigned warp_size = shader->get_warp_size();
    for (unsigned lane = 0; lane < warp_size && lane < 32; ++lane) {
      if ((completed_lane_mask & (1u << lane)) == 0) continue;
      rtcore_print_shader_call_payload(
          "return", owner_hw_sid, entry.warp_uid, entry.warp_id, lane,
          completed_cohort_index, current_cycle,
          thread_info[warp_id * warp_size + lane]);
    }
    unsigned shader_terminal_lane_mask = 0;
    if (entry.current_call_requires_handoff_return) {
      if (rtcore_v04_direct_completion(entry) &&
          !entry.current_call_live_publication_fence_issued) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_V04_LIVE_PUBLICATION_FAULT "
                "owner_hw_sid=%u warp_uid=%u warp_id=%u "
                "cohort_index=%u fault=return_without_epilogue_fence\n",
                owner_hw_sid, entry.warp_uid, entry.warp_id,
                completed_cohort_index);
        abort();
      }
      for (unsigned lane = 0; lane < warp_size && lane < 32; ++lane) {
        const unsigned lane_mask = 1u << lane;
        if ((completed_lane_mask & lane_mask) == 0) continue;
        ptx_thread_info *thread = thread_info[warp_id * warp_size + lane];
        assert(thread != NULL);
        const ptx_instruction *source_inst =
            thread->get_inst(entry.static_inst_pc);
        if (rtcore_v04_direct_completion(entry) &&
            !rtcore_validate_v04_native_source_authority(
                entry, owner_hw_sid, lane, source_inst, thread)) {
          fprintf(stderr,
                  "GPGPU-Sim RTCORE_V04_NATIVE_CONTINUATION_FAULT "
                  "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
                  "fault=shader_return_resident_authority_mismatch\n",
                  owner_hw_sid, entry.warp_uid, entry.warp_id, lane);
          fflush(stderr);
          abort();
        }
        const unsigned reason = entry.lane_reasons[lane];
        unsigned hit_result = 0;
        unsigned reported_t = 0;
        unsigned reported_metadata = 0;
        bool return_valid = false;
        bool lane_terminated = false;
        if (rtcore_v04_direct_completion(entry)) {
          std::array<uint32_t, rtcore::abi_v04::kWordCount> words = {};
          const unsigned long long lane_base =
              entry.handoff_window_base +
              lane * RTCORE_HANDOFF_WINDOW_SLOT_BYTES;
          thread->get_global_memory()->read_simulator_backing(
              lane_base, sizeof(words), words.data());
          const rtcore::abi_v04::shadow::shader_return_observation
              observation =
                  rtcore::abi_v04::shadow::decode_shader_return_words(
                      words, reason);
          hit_result = words[rtcore::abi_v04::kCommitRetainedCandidate.word];
          reported_t = words[rtcore::abi_v04::kReportedTFp32.word];
          reported_metadata =
              words[rtcore::abi_v04::kReportedHitKind.word];
          return_valid = observation.valid();
          if (return_valid &&
              (observation.traversal_effect & (1u << 2)) != 0) {
            shader_terminal_lane_mask |= lane_mask;
            lane_terminated = true;
          }
        } else {
          unsigned shader_return_words[3] = {};
          const unsigned long long shader_return_base =
              entry.handoff_window_base +
              lane * RTCORE_HANDOFF_WINDOW_SLOT_BYTES + 52;
          thread->get_global_memory()->read_simulator_backing(
              shader_return_base, sizeof(shader_return_words),
              shader_return_words);
          hit_result = shader_return_words[0];
          reported_t = shader_return_words[1];
          reported_metadata = shader_return_words[2];
          return_valid =
              (hit_result & 0xffffff00u) == 0 &&
              ((reason ==
                    RTCORE_SHADER_CONTINUATION_REASON_ANY_HIT_REQUIRED &&
                (hit_result == 2 || hit_result == 3)) ||
               (reason ==
                    RTCORE_SHADER_CONTINUATION_REASON_INTERSECTION_REQUIRED &&
                (hit_result == 1 || hit_result == 4)));
        }
        printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_SHADER_RETURN_STORE "
               "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
               "cohort_index=%u handoff_window_base=0x%llx reason=%u "
               "return_control=0x%08x "
               "reported_t=0x%08x reported_metadata=0x%08x valid=%u "
               "return_abi=%s handoff_return_producer=shader_store "
               "return_cycle=%llu\n",
               owner_hw_sid, entry.warp_uid, entry.warp_id, lane,
               completed_cohort_index, entry.handoff_window_base, reason,
               hit_result, reported_t, reported_metadata,
               return_valid ? 1u : 0u,
               rtcore_v04_direct_completion(entry) ? "v04" : "v03",
               current_cycle);
        fflush(stdout);
        if (!return_valid) {
          fprintf(stderr,
                  "GPGPU-Sim RTCORE_SHADER_CONTINUATION_CALL_FRAME_FAULT "
                  "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
                  "fault=invalid_shader_return_store_fail_closed\n",
                  owner_hw_sid, entry.warp_uid, entry.warp_id, lane);
          abort();
        }
        if (entry.v04_functional_only_completion && lane_terminated &&
            !rtcore_apply_v04_functional_only_terminal_shader_return(
                owner_hw_sid, entry.warp_uid, entry.warp_id,
                entry.active_mask, lane, source_inst, thread)) {
          fprintf(stderr,
                  "GPGPU-Sim RTCORE_V04_FUNCTIONAL_ONLY_FAULT "
                  "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
                  "fault=terminal_shader_return_rejected\n",
                  owner_hw_sid, entry.warp_uid, entry.warp_id, lane);
          fflush(stderr);
          abort();
        }
      }
      if (shader_terminal_lane_mask != 0 &&
          completed_reason !=
              RTCORE_SHADER_CONTINUATION_REASON_ANY_HIT_REQUIRED) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_V04_NATIVE_CONTINUATION_FAULT "
                "owner_hw_sid=%u warp_uid=%u warp_id=%u "
                "terminal_lane_mask=0x%08x "
                "fault=unsupported_non_anyhit_terminate_fail_closed\n",
                owner_hw_sid, entry.warp_uid, entry.warp_id,
                shader_terminal_lane_mask);
        fflush(stderr);
        abort();
      }
    }
    const unsigned completed_dispatch_stage =
        rtcore_resident_dispatch_stage_for_reason_v0(completed_reason);
    unsigned remaining_logical_frame_depth = 0;
    for (unsigned lane = 0; lane < warp_size && lane < 32; ++lane) {
      if ((completed_lane_mask & (1u << lane)) == 0) continue;
      const unsigned depth = entry.lane_dispatch_depth[lane];
      if (depth == 0 ||
          completed_dispatch_stage ==
              RTCORE_RESIDENT_DISPATCH_STAGE_INVALID) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_RESIDENT_DISPATCH_FRAME_FAULT "
                "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
                "entry_id=%u depth=%u "
                "fault=logical_dispatch_underflow_fail_closed\n",
                owner_hw_sid, entry.warp_uid, entry.warp_id, lane,
                completed_shader_id, depth);
        abort();
      }
      const rtcore_resident_dispatch_frame_v0 &frame =
          entry.lane_dispatch_frames[lane][depth - 1];
      if (frame.entry_id != completed_shader_id ||
          frame.stage != completed_dispatch_stage ||
          frame.cohort_index != completed_cohort_index ||
          frame.return_pc != entry.return_pc ||
          frame.return_rpc != entry.return_rpc ||
          frame.return_token != completed_conservation_cohort_seq) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_RESIDENT_DISPATCH_FRAME_FAULT "
                "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
                "entry_id=%u stage=%u token=%u "
                "fault=stale_or_mismatched_dispatch_return_fail_closed\n",
                owner_hw_sid, entry.warp_uid, entry.warp_id, lane,
                completed_shader_id, completed_dispatch_stage,
                completed_conservation_cohort_seq);
        abort();
      }
      entry.lane_dispatch_frames[lane][depth - 1] = {};
      entry.lane_dispatch_depth[lane] = depth - 1;
      remaining_logical_frame_depth = std::max(
          remaining_logical_frame_depth, depth - 1);
    }
    printf("GPGPU-Sim RTCORE_RESIDENT_DISPATCH_FRAME_RETURN "
           "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
           "cohort_lane_mask=0x%08x entry_id=%u stage=%s token=%u "
           "remaining_logical_frame_depth=%u validated=1 "
           "return_cycle=%llu\n",
           owner_hw_sid, entry.warp_uid, entry.warp_id,
           completed_cohort_index, completed_lane_mask,
           completed_shader_id,
           rtcore_resident_dispatch_stage_name_v0(completed_dispatch_stage),
           completed_conservation_cohort_seq,
           remaining_logical_frame_depth, current_cycle);
    fflush(stdout);
    const unsigned completed_dispatch_lane_mask =
        terminated_final_cohort
            ? completed_lane_mask
            : completed_lane_mask & ~shader_terminal_lane_mask;
    entry.call_inflight = false;
    entry.current_call_requires_handoff_return = false;
    entry.current_call_live_publication_fence_issued = false;
    entry.current_cohort_index = UINT_MAX;
    entry.metadata_lookup_state =
        RTCORE_SHADER_CONTINUATION_SBT_METADATA_NOT_REQUESTED;
    entry.metadata_lookup_generation = 0;
    entry.metadata_lookup_aligned_32b_addr = 0;
    entry.metadata_lookup_request_cycle = 0;
    entry.metadata_lookup_response_cycle = 0;
    entry.metadata_lookup_wait_scheduler_cycles = 0;
    rtcore_reset_shader_continuation_handoff_read(&entry);
    if (shader_terminal_lane_mask != 0) {
      rtcore_stage_v04_terminated_closest_hit_cohort(
          owner_hw_sid, &entry, completed_cohort_index,
          shader_terminal_lane_mask);
    } else {
      entry.cohort_cursor++;
    }
    const bool all_cohorts_complete =
        entry.cohort_cursor >= entry.cohort_count;
    printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_CALL_FRAME_RETURN "
           "owner_hw_sid=%u warp_uid=%u warp_id=%u dynamic_warp_id=%u "
           "cohort_index=%u cohort_lane_mask=0x%08x cohort_shader_id=%u "
           "cohort_reason=%u handoff_return_required=%u "
           "return_pc=0x%x return_rpc=0x%x body_issue_count=%u "
           "cohort_cursor=%u cohort_count=%u all_cohorts_complete=%u "
           "call_launch_cycle=%llu return_cycle=%llu "
           "shader_execution_model=shadercore_control_transfer\n",
           owner_hw_sid, entry.warp_uid, entry.warp_id, dynamic_warp_id,
           completed_cohort_index, completed_lane_mask, completed_shader_id,
           completed_reason, handoff_return_required ? 1u : 0u,
           entry.return_pc, entry.return_rpc, entry.body_issue_count,
           entry.cohort_cursor, entry.cohort_count,
           all_cohorts_complete ? 1u : 0u, entry.call_launch_cycle,
           current_cycle);
    fflush(stdout);
    if (terminated_final_cohort) {
      rtcore_publish_v04_terminated_final_cohort(
          owner_hw_sid, &entry, completed_lane_mask);
    }
    if (completed_dispatch_lane_mask != 0) {
      rtcore_mark_v04_native_dispatch_cohort_complete(
          owner_hw_sid, entry, completed_dispatch_lane_mask);
    }
    rtcore_record_v04_conservation_cohort_event_or_abort(
        owner_hw_sid, entry,
        rtcore::v04::conservation::kEventCohortComplete,
        completed_lane_mask, completed_conservation_cohort_seq,
        current_cycle);
    entry.conservation_inflight_cohort_seq = 0;
    entry.body_issue_count = 0;
    if (all_cohorts_complete) {
      rtcore_complete_shader_continuation_pending(key, current_cycle);
    }
    return result;
  }

  if (entry.metadata_lookup_state ==
      RTCORE_SHADER_CONTINUATION_SBT_METADATA_WAITING_RESPONSE) {
    entry.metadata_lookup_wait_scheduler_cycles++;
    return result;
  }
  if (entry.handoff_read_state ==
          RTCORE_SHADER_CONTINUATION_HANDOFF_READ_WAITING_SELECTION ||
      entry.handoff_read_state ==
          RTCORE_SHADER_CONTINUATION_HANDOFF_READ_WAITING_ATTRIBUTES) {
    return result;
  }

  const bool same_cycle_acquire_blocked = current_cycle <= entry.enqueue_cycle;
  const unsigned visible_candidate_mask = entry.candidate_mask;
  const char *status = same_cycle_acquire_blocked
                           ? "same_cycle_acquire_blocked"
                           : "pending_visible_at_shadercore_issue";

  printf("GPGPU-Sim "
         "RTCORE_SHADER_CONTINUATION_DISPATCHER_ISSUE_SITE_PREFLIGHT "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u dynamic_warp_id=%u "
         "active_mask=0x%08x scheduler_active_mask=0x%08x "
         "target_shader_id_ready_mask=0x%08x candidate_mask=0x%08x "
         "visible_candidate_mask=0x%08x static_inst_pc=0x%llx "
         "dispatcher_issue_site_pending_found=%u "
         "shadercore_issue_site_preflight_consumed=%u "
         "dispatcher_issue_site_status=%s enqueue_cycle=%llu "
         "shadercore_issue_cycle=%llu\n",
         owner_hw_sid, entry.warp_uid, entry.warp_id, dynamic_warp_id,
         entry.active_mask, entry.active_mask,
         entry.target_shader_id_ready_mask, entry.candidate_mask,
         visible_candidate_mask, 0ull, 1u,
         same_cycle_acquire_blocked ? 0u : 1u, status, entry.enqueue_cycle,
         current_cycle);

  const bool metadata_response_ready =
      entry.metadata_lookup_state ==
      RTCORE_SHADER_CONTINUATION_SBT_METADATA_RESPONSE_READY;
  const bool pseudo_op_ready =
      !same_cycle_acquire_blocked;
  const char *callshader_action =
      same_cycle_acquire_blocked
          ? "blocked_same_cycle_acquire"
          : (metadata_response_ready
                 ? "launched_shadercore_call_frame"
                 : "deferred_for_sbt_metadata_request");
  printf("GPGPU-Sim "
         "RTCORE_SHADER_CONTINUATION_DISPATCHER_ISSUE_SITE_ACTION "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u dynamic_warp_id=%u "
         "active_mask=0x%08x scheduler_active_mask=0x%08x "
         "dispatcher_issue_site_pseudo_op_enabled=1 "
         "dispatcher_issue_site_pseudo_op_ready=%u "
         "target_shader_id_ready_mask=0x%08x candidate_mask=0x%08x "
         "visible_candidate_mask=0x%08x "
         "dispatcher_issue_site_callshader_action=%s "
         "dispatcher_issue_site_callshader_lane_mask=0x%08x "
         "static_inst_pc=0x%llx shadercore_issue_cycle=%llu\n",
         owner_hw_sid, entry.warp_uid, entry.warp_id, dynamic_warp_id,
         entry.active_mask, entry.active_mask, pseudo_op_ready ? 1u : 0u,
         entry.target_shader_id_ready_mask, entry.candidate_mask,
         visible_candidate_mask, callshader_action, 0u, 0ull, current_cycle);

  if (same_cycle_acquire_blocked) {
    printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_PSEUDO_OP_SERVICE "
           "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
           "cohort_cursor=%u cohort_count=%u pseudo_op_issued=0 "
           "original_pc_issued=0 pseudo_op_status=same_cycle_acquire_blocked "
           "acquire_cycle=%llu service_cycle=%llu\n",
           owner_hw_sid, entry.warp_uid, entry.warp_id, entry.active_mask,
           entry.cohort_cursor, entry.cohort_count, entry.enqueue_cycle,
           current_cycle);
    fflush(stdout);
    return result;
  }

  if (rtcore_v04_direct_completion(entry) &&
      entry.handoff_read_state ==
          RTCORE_SHADER_CONTINUATION_HANDOFF_READ_NOT_REQUESTED) {
    if (!rtcore_issue_shader_continuation_handoff_reads(
            owner_hw_sid, entry,
            RTCORE_SHADER_CONTINUATION_HANDOFF_READ_PHASE_SELECTION,
            current_cycle)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_FAULT "
              "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
              "fault=selection_request_issue_fail_closed\n",
              owner_hw_sid, entry.warp_uid, entry.warp_id,
              entry.cohort_cursor);
      fflush(stderr);
      abort();
    }
    result.issued = true;
    return result;
  }
  if (rtcore_v04_direct_completion(entry) &&
      entry.handoff_read_state !=
          RTCORE_SHADER_CONTINUATION_HANDOFF_READ_SELECTION_READY &&
      entry.handoff_read_state !=
          RTCORE_SHADER_CONTINUATION_HANDOFF_READ_CONTEXT_READY) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_FAULT "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
            "fault=selection_state_invalid_fail_closed\n",
            owner_hw_sid, entry.warp_uid, entry.warp_id,
            entry.cohort_cursor);
    fflush(stderr);
    abort();
  }
  if (rtcore_v04_direct_completion(entry) &&
      entry.handoff_read_state ==
          RTCORE_SHADER_CONTINUATION_HANDOFF_READ_SELECTION_READY &&
      !entry.handoff_selection_materialized &&
      !rtcore_materialize_shader_continuation_target_selection(
          shader, owner_hw_sid, &entry, current_cycle)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_FAULT "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
            "fault=response_backed_target_selection_fail_closed\n",
            owner_hw_sid, entry.warp_uid, entry.warp_id,
            entry.cohort_cursor);
    fflush(stderr);
    abort();
  }

  if (entry.metadata_lookup_state ==
      RTCORE_SHADER_CONTINUATION_SBT_METADATA_NOT_REQUESTED) {
    if (!rtcore_issue_shader_continuation_sbt_metadata_request(
            owner_hw_sid, entry, current_cycle)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_SHADER_CONTINUATION_SBT_METADATA_FAULT "
              "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
              "fault=request_enqueue_fail_closed\n",
              owner_hw_sid, entry.warp_uid, entry.warp_id,
              entry.cohort_cursor);
      fflush(stderr);
      abort();
    }
    result.issued = true;
    return result;
  }
  assert(entry.metadata_lookup_state ==
         RTCORE_SHADER_CONTINUATION_SBT_METADATA_RESPONSE_READY);
  assert(entry.metadata_lookup_response_cycle >=
         entry.metadata_lookup_request_cycle);
  assert(current_cycle >= entry.metadata_lookup_response_cycle);

  assert(entry.cohort_cursor < entry.cohort_count);
  const unsigned cohort_index = entry.cohort_cursor;
  const unsigned cohort_lane_mask = entry.cohort_lane_masks[cohort_index];
  assert(shader != NULL);
  ptx_thread_info **thread_info = shader->get_thread_info();
  const unsigned warp_size = shader->get_warp_size();
  unsigned representative_lane = 0;
  while (representative_lane < warp_size && representative_lane < 32 &&
         (cohort_lane_mask & (1u << representative_lane)) == 0) {
    representative_lane++;
  }
  if (representative_lane >= warp_size || representative_lane >= 32) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_SHADER_CONTINUATION_SBT_METADATA_FAULT "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
            "fault=empty_decode_cohort_fail_closed\n",
            owner_hw_sid, entry.warp_uid, entry.warp_id, cohort_index);
    abort();
  }
  ptx_thread_info *decode_thread =
      thread_info[warp_id * warp_size + representative_lane];
  const unsigned component = entry.cohort_sbt_record_components[cohort_index];
  const unsigned long long component_offset =
      static_cast<unsigned long long>(component) * sizeof(uint32_t);
  const unsigned long long record_addr =
      entry.cohort_sbt_record_addrs[cohort_index];
  if (decode_thread == NULL || component > 1 ||
      record_addr > ULLONG_MAX - component_offset) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_SHADER_CONTINUATION_SBT_METADATA_FAULT "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
            "fault=invalid_device_decode_address_fail_closed\n",
            owner_hw_sid, entry.warp_uid, entry.warp_id, cohort_index);
    abort();
  }
  const unsigned long long metadata_addr = record_addr + component_offset;
  uint32_t decoded_shader_id = UINT_MAX;
  if (!decode_thread->get_global_memory()->read_vulkan_buffer(
          (mem_addr_t)metadata_addr, sizeof(decoded_shader_id),
          &decoded_shader_id)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_SHADER_CONTINUATION_SBT_METADATA_FAULT "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
            "metadata_addr=0x%llx fault=unmapped_sbt_content_fail_closed\n",
            owner_hw_sid, entry.warp_uid, entry.warp_id, cohort_index,
            metadata_addr);
    abort();
  }
  const unsigned cohort_reason = rtcore_shader_continuation_cohort_reason(
      entry, cohort_index);
  const int target_kind =
      rtcore_compatibility_shader_target_kind(decoded_shader_id, cohort_reason);
  const char *target_kind_name =
      target_kind == 1 ? "shader" : (target_kind == 0 ? "null" : "invalid");
  printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_SBT_METADATA_DECODE "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
         "generation=%u aligned_32b_addr=0x%llx metadata_addr=0x%llx "
         "shader_record_component=%u shader_id=%u target_kind=%s "
         "content_source=simulator_mapped_sbt decode_cycle=%llu\n",
         owner_hw_sid, entry.warp_uid, entry.warp_id, cohort_index,
         entry.metadata_lookup_generation,
         entry.metadata_lookup_aligned_32b_addr, metadata_addr, component,
         decoded_shader_id, target_kind_name, current_cycle);
  fflush(stdout);
  if (target_kind < 0) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_SHADER_CONTINUATION_SBT_METADATA_FAULT "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
            "shader_id=%u reason=%u "
            "fault=malformed_or_stage_mismatch_fail_closed\n",
            owner_hw_sid, entry.warp_uid, entry.warp_id, cohort_index,
            decoded_shader_id, cohort_reason);
    abort();
  }
  if (target_kind == 1 && rtcore_v04_direct_completion(entry) &&
      entry.handoff_read_state ==
          RTCORE_SHADER_CONTINUATION_HANDOFF_READ_SELECTION_READY) {
    if (!rtcore_issue_shader_continuation_handoff_reads(
            owner_hw_sid, entry,
            RTCORE_SHADER_CONTINUATION_HANDOFF_READ_PHASE_ATTRIBUTES,
            current_cycle)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_FAULT "
              "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
              "fault=attribute_request_issue_fail_closed\n",
              owner_hw_sid, entry.warp_uid, entry.warp_id,
              entry.cohort_cursor);
      fflush(stderr);
      abort();
    }
    if (entry.handoff_read_state ==
        RTCORE_SHADER_CONTINUATION_HANDOFF_READ_WAITING_ATTRIBUTES) {
      result.issued = true;
      return result;
    }
  }
  if (target_kind == 1 && rtcore_v04_direct_completion(entry) &&
      entry.handoff_read_state !=
          RTCORE_SHADER_CONTINUATION_HANDOFF_READ_CONTEXT_READY) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_FAULT "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
            "fault=context_state_invalid_fail_closed\n",
            owner_hw_sid, entry.warp_uid, entry.warp_id,
            entry.cohort_cursor);
    fflush(stderr);
    abort();
  }
  entry.cohort_shader_ids[cohort_index] = decoded_shader_id;
  if (target_kind == 0) {
    const bool terminal_no_shader =
        cohort_reason == RTCORE_SHADER_CONTINUATION_REASON_MISS ||
        cohort_reason == RTCORE_SHADER_CONTINUATION_REASON_CLOSEST_HIT_READY;
    if (rtcore_v04_direct_completion(entry) &&
        rtcore_shader_continuation_requires_handoff_return(
            cohort_reason)) {
      unsigned live_window_generation = 0;
      const uint32_t default_effect =
          cohort_reason ==
                  RTCORE_SHADER_CONTINUATION_REASON_ANY_HIT_REQUIRED
              ? 1u
              : 0u;
      for (unsigned lane = 0; lane < warp_size && lane < 32; ++lane) {
        const unsigned lane_mask = 1u << lane;
        if ((cohort_lane_mask & lane_mask) == 0) continue;
        ptx_thread_info *thread =
            thread_info[warp_id * warp_size + lane];
        const ptx_instruction *source_inst =
            thread != NULL ? thread->get_inst(entry.static_inst_pc) : NULL;
        if (source_inst == NULL ||
            !rtcore_validate_v04_native_source_authority(
                entry, owner_hw_sid, lane, source_inst, thread)) {
          fprintf(stderr,
                  "GPGPU-Sim RTCORE_SHADER_CONTINUATION_SBT_METADATA_FAULT "
                  "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
                  "fault=no_shader_source_context_missing\n",
                  owner_hw_sid, entry.warp_uid, entry.warp_id, lane);
          abort();
        }
        const operand_info &handoff_operand =
            source_inst->operand_lookup(2);
        const ptx_reg_t handoff_value =
            thread->get_reg(handoff_operand.get_symbol());
        const unsigned lane_window_generation =
            entry.lane_v04_live_window_generations[lane];
        if (lane_window_generation == 0 ||
            (live_window_generation != 0 &&
             live_window_generation != lane_window_generation)) {
          fprintf(stderr,
                  "GPGPU-Sim RTCORE_V04_LIVE_PUBLICATION_FAULT "
                  "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
                  "fault=null_shader_window_generation_mismatch\n",
                  owner_hw_sid, entry.warp_uid, entry.warp_id, lane);
          abort();
        }
        live_window_generation = lane_window_generation;
        const unsigned long long effect_address =
            handoff_value.u64 +
            static_cast<unsigned long long>(lane) *
                RTCORE_HANDOFF_WINDOW_SLOT_BYTES +
            rtcore::abi_v04::kCommitRetainedCandidate.word *
                sizeof(uint32_t);
        thread->get_global_memory()->write_simulator_backing(
            effect_address, sizeof(default_effect), &default_effect);
      }
      rtcore::v04::pre_submit_publication::
          live_publication_round_request_v0 no_shader = {};
      no_shader.owner_hw_sid = owner_hw_sid;
      no_shader.dynamic_warp_id = dynamic_warp_id;
      no_shader.warp_id = warp_id;
      no_shader.resident_warp_generation =
          entry.v04_native_resident_generation;
      no_shader.window_generation = live_window_generation;
      no_shader.completion_transaction_generation =
          entry.v04_native_completion_transaction_generation;
      no_shader.cohort_index = cohort_index;
      no_shader.expected_lane_mask = cohort_lane_mask;
      const rtcore::v04::pre_submit_publication::status_kind no_shader_status =
          rtcore::v04::pre_submit_publication::shared_bridge()
              .authorize_no_shader_live_publication(no_shader);
      if (no_shader_status !=
          rtcore::v04::pre_submit_publication::kStatusOk) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_V04_LIVE_PUBLICATION_FAULT "
                "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
                "fault=null_shader_authorization_rejected status=%s\n",
                owner_hw_sid, entry.warp_uid, entry.warp_id, cohort_index,
                rtcore::v04::pre_submit_publication::status_name(
                    no_shader_status));
        abort();
      }
      printf("GPGPU-Sim RTCORE_V04_NATIVE_NO_SHADER_RETURN "
             "owner_hw_sid=%u warp_uid=%u warp_id=%u "
             "cohort_lane_mask=0x%08x reason=%u effect=0x%08x "
             "policy_source=sbt_null_shader "
             "publication_contract=no_shader_no_lsu_transaction "
             "completion_generation=%u return_cycle=%llu\n",
             owner_hw_sid, entry.warp_uid, entry.warp_id,
             cohort_lane_mask, cohort_reason, default_effect,
             no_shader.completion_transaction_generation, current_cycle);
      fflush(stdout);
    }
    const bool terminated_final_no_shader =
        cohort_reason ==
            RTCORE_SHADER_CONTINUATION_REASON_CLOSEST_HIT_READY &&
        (cohort_lane_mask & entry.pending_shader_terminal_mask) ==
            cohort_lane_mask;
    if (terminated_final_no_shader) {
      rtcore_publish_v04_terminated_final_cohort(
          owner_hw_sid, &entry, cohort_lane_mask);
    }
    const unsigned conservation_cohort_seq =
        entry.conservation_next_cohort_seq++;
    rtcore_record_v04_conservation_cohort_event_or_abort(
        owner_hw_sid, entry,
        rtcore::v04::conservation::kEventCohortLaunch,
        cohort_lane_mask, conservation_cohort_seq, current_cycle);
    rtcore_mark_v04_native_dispatch_cohort_complete(
        owner_hw_sid, entry, cohort_lane_mask);
    rtcore_record_v04_conservation_cohort_event_or_abort(
        owner_hw_sid, entry,
        rtcore::v04::conservation::kEventCohortComplete,
        cohort_lane_mask, conservation_cohort_seq, current_cycle);
    const char *no_shader_action = terminal_no_shader
                                       ? "terminal_no_shader"
                                       : "continuation_no_shader_resume";
    printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_SBT_NO_SHADER "
           "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
           "generation=%u aligned_32b_addr=0x%llx "
           "cohort_lane_mask=0x%08x cohort_reason=%u "
           "no_shader_action=%s no_shader_cycle=%llu\n",
           owner_hw_sid, entry.warp_uid, entry.warp_id, cohort_index,
           entry.metadata_lookup_generation,
           entry.metadata_lookup_aligned_32b_addr, cohort_lane_mask,
           cohort_reason, no_shader_action, current_cycle);
    fflush(stdout);
    entry.metadata_lookup_state =
        RTCORE_SHADER_CONTINUATION_SBT_METADATA_NOT_REQUESTED;
    entry.metadata_lookup_generation = 0;
    entry.metadata_lookup_aligned_32b_addr = 0;
    entry.metadata_lookup_request_cycle = 0;
    entry.metadata_lookup_response_cycle = 0;
    entry.metadata_lookup_wait_scheduler_cycles = 0;
    rtcore_reset_shader_continuation_handoff_read(&entry);
    entry.cohort_cursor++;
    const bool all_cohorts_complete =
        entry.cohort_cursor >= entry.cohort_count;
    if (all_cohorts_complete) {
      rtcore_complete_shader_continuation_pending(key, current_cycle);
    }
    result.issued = true;
    return result;
  }

  entry.target_shader_id_ready_mask |= cohort_lane_mask;
  const unsigned cohort_shader_id = decoded_shader_id;
  const unsigned cohort_dispatch_stage =
      rtcore_resident_dispatch_stage_for_reason_v0(cohort_reason);
  rtcore_resident_dispatch_entry_v0 dispatch_entry = {};
  const int dispatch_entry_status =
      rtcore_resolve_resident_dispatch_entry_v0(
          cohort_shader_id, cohort_dispatch_stage, &dispatch_entry);
  function_info *target_func = dispatch_entry.function;
  if (dispatch_entry_status != 1 || dispatch_entry.valid != 1 ||
      cohort_dispatch_stage == RTCORE_RESIDENT_DISPATCH_STAGE_INVALID ||
      dispatch_entry.entry_id != cohort_shader_id ||
      dispatch_entry.stage != cohort_dispatch_stage ||
      target_func == NULL) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_RESIDENT_DISPATCH_ENTRY_FAULT "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
            "cohort_shader_id=%u expected_stage=%u status=%d "
            "fault=unresolved_or_stage_mismatched_entry_fail_closed\n",
            owner_hw_sid, entry.warp_uid, entry.warp_id, cohort_index,
            cohort_shader_id, cohort_dispatch_stage, dispatch_entry_status);
    abort();
  }
  printf("GPGPU-Sim RTCORE_RESIDENT_DISPATCH_ENTRY_VALIDATE "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
         "entry_id=%u stage=%s registration_index=%u validated=1 "
         "validation_cycle=%llu\n",
         owner_hw_sid, entry.warp_uid, entry.warp_id, cohort_index,
         dispatch_entry.entry_id,
         rtcore_resident_dispatch_stage_name_v0(dispatch_entry.stage),
         dispatch_entry.registration_index, current_cycle);
  fflush(stdout);
  unsigned return_pc = 0;
  unsigned return_rpc = 0;
  unsigned long long handoff_window_base = 0;
  const bool requires_handoff_return =
      rtcore_shader_continuation_requires_handoff_return(cohort_reason);
  for (unsigned lane = 0; lane < warp_size && lane < 32; ++lane) {
    const unsigned lane_mask = 1u << lane;
    if ((cohort_lane_mask & lane_mask) == 0) continue;
    ptx_thread_info *thread = thread_info[warp_id * warp_size + lane];
    const ptx_instruction *source_inst =
        thread != NULL ? thread->get_inst(entry.static_inst_pc) : NULL;
    unsigned long long lane_handoff_window_base = 0;
    if (thread != NULL && source_inst != NULL) {
      const operand_info &handoff_operand = source_inst->operand_lookup(2);
      lane_handoff_window_base =
          thread->get_reg(handoff_operand.get_symbol()).u64;
    }
    const bool native_authority_ready =
        !rtcore_v04_direct_completion(entry) ||
        rtcore_validate_v04_native_source_authority(
            entry, owner_hw_sid, lane, source_inst, thread);
    const rtcore_boundary_candidate_snapshot &boundary_candidate =
        entry.lane_boundary_candidates[lane];
    const bool compatibility_context_ready =
        rtcore_v04_direct_completion(entry)
            ? (native_authority_ready && thread != NULL &&
               source_inst != NULL &&
               rtcore_prepare_v04_direct_shader_input_context(
                   source_inst, thread, entry.lane_reasons[lane], lane,
                   lane_handoff_window_base,
                   entry.lane_handoff_words[lane],
                   rtcore::abi_v04::kWordCount))
            : (thread != NULL && source_inst != NULL &&
               (!requires_handoff_return || boundary_candidate.valid) &&
               rtcore_prepare_compatibility_shader_continuation_context(
                   source_inst, thread, entry.lane_reasons[lane],
                   entry.lane_hit_record_selectors[lane],
                   requires_handoff_return ? boundary_candidate.event_seq : 0,
                   requires_handoff_return
                       ? boundary_candidate.shader_counter
                       : 0,
                   requires_handoff_return ? boundary_candidate.hit_data_ref
                                           : 0,
                   requires_handoff_return
                       ? boundary_candidate.hit_group_index
                       : entry.lane_hit_group_indices[lane],
                   requires_handoff_return
                       ? boundary_candidate.geometry_type
                       : entry.lane_geometry_types[lane],
                   requires_handoff_return
                       ? boundary_candidate.geometry_index
                       : entry.lane_geometry_indices[lane],
                   entry.lane_primitive_indices[lane],
                   entry.lane_instance_indices[lane],
                   entry.lane_hit_kinds[lane],
                   entry.lane_v04_boundary_ray_tmax_fp32[lane],
                   requires_handoff_return &&
                       entry.lane_v04_boundary_ray_tmax_valid[lane]));
    if (thread == NULL || source_inst == NULL ||
        !native_authority_ready ||
        !compatibility_context_ready) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_SHADER_CONTINUATION_CALL_FRAME_FAULT "
              "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
              "cohort_index=%u cohort_shader_id=%u "
              "fault=compatibility_shader_context_fail_closed\n",
              owner_hw_sid, entry.warp_uid, entry.warp_id, lane,
              cohort_index, cohort_shader_id);
      abort();
    }
    if (handoff_window_base == 0) {
      handoff_window_base = lane_handoff_window_base;
    } else if (handoff_window_base != lane_handoff_window_base) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_SHADER_CONTINUATION_CALL_FRAME_FAULT "
              "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
              "fault=cohort_handoff_base_mismatch_fail_closed\n",
              owner_hw_sid, entry.warp_uid, entry.warp_id, lane);
      abort();
    }
    if (!rtcore_v04_direct_completion(entry) &&
        rtcore_v04_shader_builtin_consumer_runtime_enabled() &&
        !rtcore_validate_v04_shader_builtin_compatibility_context(
            source_inst, thread, entry.lane_reasons[lane], lane,
            lane_handoff_window_base)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_SHADER_BUILTIN_COMPATIBILITY_FAULT "
              "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
              "cohort_index=%u cohort_shader_id=%u "
              "fault=legacy_source_mismatch_fail_closed\n",
              owner_hw_sid, entry.warp_uid, entry.warp_id, lane,
              cohort_index, cohort_shader_id);
      abort();
    }
  }
  const bool supported_reason =
      cohort_reason == RTCORE_SHADER_CONTINUATION_REASON_MISS ||
      cohort_reason == RTCORE_SHADER_CONTINUATION_REASON_CLOSEST_HIT_READY ||
      requires_handoff_return;
  if (!supported_reason) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_SHADER_CONTINUATION_CALL_FRAME_FAULT "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u "
            "fault=unsupported_call_frame_reason_fail_closed reason=%u\n",
            owner_hw_sid, entry.warp_uid, entry.warp_id, cohort_reason);
    abort();
  }
  for (unsigned lane = 0; lane < warp_size && lane < 32; ++lane) {
    if ((cohort_lane_mask & (1u << lane)) == 0) continue;
    rtcore_print_shader_call_payload(
        "launch", owner_hw_sid, entry.warp_uid, entry.warp_id, lane,
        cohort_index, current_cycle,
        thread_info[warp_id * warp_size + lane]);
  }
  const unsigned default_hit_result =
      cohort_reason == RTCORE_SHADER_CONTINUATION_REASON_ANY_HIT_REQUIRED
          ? 2u
          : 1u;
  for (unsigned lane = 0; lane < warp_size && lane < 32; ++lane) {
    if ((cohort_lane_mask & (1u << lane)) == 0) continue;
    if (entry.lane_dispatch_depth[lane] >=
        RTCORE_RESIDENT_DISPATCH_MAX_DEPTH) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_RESIDENT_DISPATCH_FRAME_FAULT "
              "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
              "entry_id=%u depth=%u capacity=%u "
              "fault=logical_dispatch_depth_overflow_fail_closed\n",
              owner_hw_sid, entry.warp_uid, entry.warp_id, lane,
              cohort_shader_id, entry.lane_dispatch_depth[lane],
              RTCORE_RESIDENT_DISPATCH_MAX_DEPTH);
      abort();
    }
  }
  assert(shader->rtcore_launch_shader_continuation_cohort(
      warp_id, cohort_lane_mask, target_func, handoff_window_base,
      default_hit_result, requires_handoff_return, &return_pc, &return_rpc));
  if (requires_handoff_return && rtcore_v04_direct_completion(entry)) {
    unsigned live_window_generation = 0;
    for (unsigned lane = 0; lane < warp_size && lane < 32; ++lane) {
      if ((cohort_lane_mask & (1u << lane)) == 0) continue;
      const unsigned lane_generation =
          entry.lane_v04_live_window_generations[lane];
      if (lane_generation == 0 ||
          (live_window_generation != 0 &&
           live_window_generation != lane_generation)) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_V04_LIVE_PUBLICATION_FAULT "
                "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
                "fault=cohort_window_generation_mismatch\n",
                owner_hw_sid, entry.warp_uid, entry.warp_id, lane);
        abort();
      }
      live_window_generation = lane_generation;
    }
    rtcore::v04::pre_submit_publication::
        live_publication_round_request_v0 round = {};
    round.owner_hw_sid = owner_hw_sid;
    round.dynamic_warp_id = dynamic_warp_id;
    round.warp_id = warp_id;
    round.resident_warp_generation =
        entry.v04_native_resident_generation;
    round.window_generation = live_window_generation;
    round.completion_transaction_generation =
        entry.v04_native_completion_transaction_generation;
    round.cohort_index = cohort_index;
    round.expected_lane_mask = cohort_lane_mask;
    round.expected_return_byte_mask = 0x0000000fu;
    const rtcore::v04::pre_submit_publication::status_kind arm_status =
        rtcore::v04::pre_submit_publication::shared_bridge()
            .arm_live_publication_round(round);
    if (arm_status !=
        rtcore::v04::pre_submit_publication::kStatusOk) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_LIVE_PUBLICATION_FAULT "
              "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
              "completion_generation=%u fault=round_arm_rejected "
              "status=%s\n",
              owner_hw_sid, entry.warp_uid, entry.warp_id, cohort_index,
              round.completion_transaction_generation,
              rtcore::v04::pre_submit_publication::status_name(arm_status));
      abort();
    }
    entry.live_publication_round = round;
    printf("GPGPU-Sim RTCORE_V04_LIVE_PUBLICATION_ROUND_ARM "
           "owner_hw_sid=%u warp_uid=%u warp_id=%u dynamic_warp_id=%u "
           "resident_generation=%u window_generation=%u "
           "completion_generation=%u cohort_index=%u "
           "expected_lane_mask=0x%08x expected_return_byte_mask=0x%08x "
           "arm_cycle=%llu\n",
           owner_hw_sid, entry.warp_uid, entry.warp_id, dynamic_warp_id,
           round.resident_warp_generation, round.window_generation,
           round.completion_transaction_generation, round.cohort_index,
           round.expected_lane_mask, round.expected_return_byte_mask,
           current_cycle);
    fflush(stdout);
  }
  const unsigned conservation_cohort_seq =
      entry.conservation_next_cohort_seq++;
  unsigned cohort_logical_frame_depth = 0;
  for (unsigned lane = 0; lane < warp_size && lane < 32; ++lane) {
    if ((cohort_lane_mask & (1u << lane)) == 0) continue;
    const unsigned depth = entry.lane_dispatch_depth[lane];
    rtcore_resident_dispatch_frame_v0 &frame =
        entry.lane_dispatch_frames[lane][depth];
    frame.entry_id = dispatch_entry.entry_id;
    frame.stage = dispatch_entry.stage;
    frame.cohort_index = cohort_index;
    frame.return_pc = return_pc;
    frame.return_rpc = return_rpc;
    frame.return_token = conservation_cohort_seq;
    entry.lane_dispatch_depth[lane] = depth + 1;
    cohort_logical_frame_depth =
        std::max(cohort_logical_frame_depth, depth + 1);
  }
  rtcore_record_v04_conservation_cohort_event_or_abort(
      owner_hw_sid, entry,
      rtcore::v04::conservation::kEventCohortLaunch,
      cohort_lane_mask, conservation_cohort_seq, current_cycle);
  entry.conservation_inflight_cohort_seq =
      conservation_cohort_seq;
  entry.call_inflight = true;
  entry.current_call_requires_handoff_return = requires_handoff_return;
  entry.current_call_live_publication_fence_issued = false;
  entry.return_pc = return_pc;
  entry.return_rpc = return_rpc;
  entry.current_cohort_index = cohort_index;
  entry.call_launch_cycle = current_cycle;
  entry.body_issue_count = 0;
  entry.handoff_window_base = handoff_window_base;
  printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_CALL_FRAME_LAUNCH "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u dynamic_warp_id=%u "
         "cohort_index=%u generation=%u aligned_32b_addr=0x%llx "
         "cohort_lane_mask=0x%08x cohort_shader_id=%u "
         "cohort_reason=%u handoff_return_required=%u "
         "validated_entry_stage=%s logical_frame_depth=%u "
         "target_pc=0x%llx return_pc=0x%x return_rpc=0x%x "
         "cohort_cursor=%u cohort_count=%u launch_cycle=%llu "
         "metadata_request_cycle=%llu metadata_response_cycle=%llu "
         "metadata_wait_scheduler_cycles=%llu "
         "shader_execution_model=shadercore_control_transfer\n",
         owner_hw_sid, entry.warp_uid, entry.warp_id, dynamic_warp_id,
         cohort_index, entry.metadata_lookup_generation,
         entry.metadata_lookup_aligned_32b_addr, cohort_lane_mask,
         cohort_shader_id, cohort_reason,
         requires_handoff_return ? 1u : 0u,
         rtcore_resident_dispatch_stage_name_v0(dispatch_entry.stage),
         cohort_logical_frame_depth,
         static_cast<unsigned long long>(target_func->get_start_PC()),
         return_pc, return_rpc, entry.cohort_cursor, entry.cohort_count,
         current_cycle, entry.metadata_lookup_request_cycle,
         entry.metadata_lookup_response_cycle,
         entry.metadata_lookup_wait_scheduler_cycles);
  printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_PSEUDO_OP_SERVICE "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
         "candidate_mask=0x%08x cohort_index=%u "
         "cohort_lane_mask=0x%08x cohort_shader_id=%u "
         "cohort_cursor=%u cohort_count=%u "
         "all_cohorts_complete=0 pseudo_op_issued=1 original_pc_issued=0 "
         "pseudo_op_status=launched_shadercore_call_frame "
         "acquire_cycle=%llu service_cycle=%llu\n",
         owner_hw_sid, entry.warp_uid, entry.warp_id, entry.active_mask,
         visible_candidate_mask, cohort_index, cohort_lane_mask,
         cohort_shader_id, entry.cohort_cursor, entry.cohort_count,
         entry.enqueue_cycle, current_cycle);
  fflush(stdout);
  result.issued = true;
  return result;
}

static void rtcore_record_shader_continuation_body_issue(
    unsigned owner_hw_sid, unsigned warp_id, unsigned dynamic_warp_id,
    unsigned static_inst_pc, unsigned issued_lane_mask,
    unsigned long long issue_cycle) {
  rtcore_shader_continuation_dispatcher_pending_key key;
  key.owner_hw_sid = owner_hw_sid;
  key.warp_id = warp_id;
  std::map<rtcore_shader_continuation_dispatcher_pending_key,
           rtcore_shader_continuation_dispatcher_pending_entry>::iterator it =
      g_rtcore_shader_continuation_dispatcher_pending.find(key);
  if (it == g_rtcore_shader_continuation_dispatcher_pending.end() ||
      !it->second.valid || !it->second.call_inflight) {
    return;
  }

  rtcore_shader_continuation_dispatcher_pending_entry &entry = it->second;
  assert(entry.dynamic_warp_id == dynamic_warp_id);
  assert(entry.current_cohort_index < entry.cohort_count);
  entry.body_issue_count++;
  printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_BODY_ISSUE "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u dynamic_warp_id=%u "
         "cohort_index=%u cohort_lane_mask=0x%08x cohort_shader_id=%u "
         "issued_lane_mask=0x%08x static_inst_pc=0x%x "
         "body_issue_ordinal=%u issue_cycle=%llu\n",
         owner_hw_sid, entry.warp_uid, entry.warp_id, dynamic_warp_id,
         entry.current_cohort_index,
         entry.cohort_lane_masks[entry.current_cohort_index],
         entry.cohort_shader_ids[entry.current_cohort_index], issued_lane_mask,
         static_inst_pc, entry.body_issue_count, issue_cycle);
  fflush(stdout);
}

static bool rtcore_shader_continuation_call_inflight(
    unsigned owner_hw_sid, unsigned warp_id, unsigned dynamic_warp_id) {
  rtcore_shader_continuation_dispatcher_pending_key key;
  key.owner_hw_sid = owner_hw_sid;
  key.warp_id = warp_id;
  std::map<rtcore_shader_continuation_dispatcher_pending_key,
           rtcore_shader_continuation_dispatcher_pending_entry>::const_iterator
      it = g_rtcore_shader_continuation_dispatcher_pending.find(key);
  return it != g_rtcore_shader_continuation_dispatcher_pending.end() &&
         it->second.valid && it->second.call_inflight &&
         it->second.dynamic_warp_id == dynamic_warp_id;
}

static bool rtcore_claim_shader_continuation_live_publication_fence(
    gpgpu_context *context, unsigned owner_hw_sid, unsigned warp_id,
    unsigned dynamic_warp_id, address_type pc,
    rtcore::v04::pre_submit_publication::
        live_publication_round_request_v0 *round) {
  if (context == NULL || round == NULL) return false;
  rtcore_shader_continuation_dispatcher_pending_key key;
  key.owner_hw_sid = owner_hw_sid;
  key.warp_id = warp_id;
  std::map<rtcore_shader_continuation_dispatcher_pending_key,
           rtcore_shader_continuation_dispatcher_pending_entry>::iterator
      it = g_rtcore_shader_continuation_dispatcher_pending.find(key);
  if (it == g_rtcore_shader_continuation_dispatcher_pending.end() ||
      !it->second.valid || !it->second.call_inflight ||
      !it->second.current_call_requires_handoff_return ||
      it->second.current_call_live_publication_fence_issued ||
      !rtcore_v04_direct_completion(it->second) ||
      it->second.dynamic_warp_id != dynamic_warp_id) {
    return false;
  }
  const ptx_instruction *fence = context->pc_to_instruction(pc);
  const ptx_instruction *next =
      fence != NULL
          ? context->pc_to_instruction(pc + fence->inst_size())
          : NULL;
  if (fence == NULL || fence->get_opcode() != MEMBAR_OP ||
      !fence->is_global_membar() || next == NULL ||
      (next->get_opcode() != RET_OP && next->get_opcode() != RETP_OP)) {
    return false;
  }
  *round = it->second.live_publication_round;
  const bool valid =
      round->completion_transaction_generation != 0 &&
      round->cohort_index == it->second.current_cohort_index;
  if (valid) it->second.current_call_live_publication_fence_issued = true;
  return valid;
}

