static rtcore_memory_unit_request_snapshot
rtcore_v02_lsu_sideband_snapshot_from_result(
    const rtcore_replay_cycle_hook_result &result) {
  if (result.memory_unit_snapshot.valid) {
    return result.memory_unit_snapshot;
  }
  rtcore_memory_unit_request_snapshot snapshot = {};
  snapshot.valid = result.lsu_sideband_valid;
  snapshot.response_target = result.lsu_sideband_response_target;
  snapshot.owner_hw_sid = result.lsu_sideband_owner_hw_sid;
  snapshot.rt_request_id = result.lsu_sideband_rt_request_id;
  snapshot.lane_id = result.lsu_sideband_lane_id;
  snapshot.memory_op_seq = result.lsu_sideband_memory_op_seq;
  snapshot.chunk_id = result.lsu_sideband_chunk_id;
  snapshot.chunk_count = result.lsu_sideband_chunk_count;
  snapshot.access_kind = result.lsu_sideband_access_kind;
  snapshot.aligned_32b_addr = result.lsu_sideband_aligned_32b_addr;
  snapshot.is_write = result.lsu_sideband_is_write;
  snapshot.issue_cycle = result.lsu_sideband_issue_cycle;
  return snapshot;
}

static bool rtcore_requeue_v02_lsu_sideband_request_for_retry(
    const rtcore_replay_cycle_hook_result &result) {
  const rtcore_memory_unit_request_snapshot snapshot =
      rtcore_v02_lsu_sideband_snapshot_from_result(result);
  return rtcore_push_back_memory_unit_request_for_sm(
      result.lsu_sideband_owner_hw_sid, &snapshot);
}

static void rtcore_record_v02_lsu_sideband_immediate_completion_kind(
    unsigned access_kind) {
  if (access_kind == RTCORE_V02_LSU_ACCESS_NODE_FETCH) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_node_immediate_completion_count++;
  } else if (access_kind == RTCORE_V02_LSU_ACCESS_PRIMITIVE_FETCH) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_primitive_immediate_completion_count++;
  } else if (access_kind == RTCORE_V02_LSU_ACCESS_STACK_LOAD) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_stack_load_immediate_completion_count++;
  } else if (access_kind == RTCORE_V02_LSU_ACCESS_HANDOFF_ACQUIRE) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_handoff_acquire_immediate_completion_count++;
  }
}

static void rtcore_record_v02_lsu_sideband_response_wakeup_kind(
    const rtcore_memory_unit_request_snapshot &snapshot) {
  if (snapshot.is_write) {
    if (snapshot.access_kind == RTCORE_V02_LSU_ACCESS_STACK_STORE) {
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_sideband_stack_store_nonblocking_completion_count++;
    } else if (
        snapshot.access_kind ==
            RTCORE_V02_LSU_ACCESS_HANDOFF_PUBLICATION_STORE ||
        snapshot.access_kind ==
            RTCORE_MEMORY_ACCESS_HANDOFF_PUBLICATION_WRITE) {
      if (snapshot.access_kind ==
              RTCORE_MEMORY_ACCESS_HANDOFF_PUBLICATION_WRITE ||
          !rtcore_v04_live_publication_memory_op_seq(
              snapshot.memory_op_seq)) {
        g_rtcore_replay_cycle_hook_consumer_stats
            .v02_lsu_sideband_handoff_publication_store_nonblocking_completion_count++;
      }
    } else if (snapshot.access_kind == RTCORE_V02_LSU_ACCESS_RESULT_STORE) {
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_sideband_result_store_nonblocking_completion_count++;
    }
    return;
  }

  if (snapshot.access_kind == RTCORE_V02_LSU_ACCESS_NODE_FETCH) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_node_response_wakeup_count++;
  } else if (snapshot.access_kind == RTCORE_V02_LSU_ACCESS_PRIMITIVE_FETCH) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_primitive_response_wakeup_count++;
  } else if (snapshot.access_kind == RTCORE_V02_LSU_ACCESS_STACK_LOAD) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_stack_load_response_wakeup_count++;
  } else if (snapshot.access_kind == RTCORE_V02_LSU_ACCESS_HANDOFF_ACQUIRE) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_handoff_acquire_response_wakeup_count++;
  }
}

static void rtcore_record_v02_lsu_sideband_response_latency(
    const rtcore_memory_unit_request_snapshot &snapshot,
    unsigned long long response_cycle) {
  if (response_cycle < snapshot.issue_cycle) {
    return;
  }
  const unsigned long long latency = response_cycle - snapshot.issue_cycle;
  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_response_latency_observation_count++;
  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_response_latency_total_cycles += latency;
  if (latency >
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_sideband_response_latency_max_cycles) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_response_latency_max_cycles = latency;
  }
  if (snapshot.is_write) {
    return;
  }
  if (snapshot.access_kind == RTCORE_V02_LSU_ACCESS_NODE_FETCH) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_node_response_latency_observation_count++;
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_node_response_latency_total_cycles += latency;
  } else if (snapshot.access_kind == RTCORE_V02_LSU_ACCESS_PRIMITIVE_FETCH) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_primitive_response_latency_observation_count++;
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_primitive_response_latency_total_cycles += latency;
  } else if (snapshot.access_kind == RTCORE_V02_LSU_ACCESS_STACK_LOAD) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_stack_load_response_latency_observation_count++;
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_stack_load_response_latency_total_cycles += latency;
  } else if (snapshot.access_kind == RTCORE_V02_LSU_ACCESS_HANDOFF_ACQUIRE) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_handoff_acquire_response_latency_observation_count++;
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_handoff_acquire_response_latency_total_cycles +=
        latency;
  }
}

static void rtcore_record_v04_memory_conservation_or_abort(
    const rtcore_memory_unit_request_snapshot &snapshot,
    bool response, unsigned long long cycle) {
  if (rtcore_record_v04_memory_conservation_event(
          &snapshot, response, cycle)) {
    return;
  }
  fprintf(stderr,
          "GPGPU-Sim RTCORE_V04_CONSERVATION_FAULT "
          "owner_hw_sid=%u request_key=0x%08x generation=%u "
          "memory_op_seq=%u chunk_id=%u chunk_count=%u phase=%s\n",
          snapshot.owner_hw_sid, snapshot.rt_request_id,
          snapshot.request_generation, snapshot.memory_op_seq,
          snapshot.chunk_id, snapshot.chunk_count,
          response ? "memory_response" : "memory_request");
  fflush(stderr);
  abort();
}

static bool rtcore_v04_live_handoff_acquire_request(
    const rtcore_memory_unit_request_snapshot &snapshot) {
  return snapshot.valid && !snapshot.is_write &&
         snapshot.access_kind == RTCORE_V02_LSU_ACCESS_HANDOFF_ACQUIRE &&
         snapshot.v04_live_handoff_acquire.valid == 1;
}

static bool rtcore_v04_dispatch_handoff_read_request(
    const rtcore_memory_unit_request_snapshot &snapshot) {
  return snapshot.valid && !snapshot.is_write &&
         snapshot.address_space == RTCORE_MEMORY_ADDRESS_SPACE_GLOBAL &&
         snapshot.operation == RTCORE_MEMORY_OPERATION_READ &&
         snapshot.response_target ==
             RTCORE_V02_LSU_RESPONSE_TARGET_SHADER_CONTINUATION &&
         snapshot.access_kind ==
             RTCORE_V02_LSU_ACCESS_HANDOFF_DISPATCH_READ &&
         snapshot.v04_dispatch_handoff_read.valid == 1;
}

static bool rtcore_v04_global384_private_init_request(
    const rtcore_memory_unit_request_snapshot &snapshot) {
  return snapshot.valid && snapshot.is_write &&
         snapshot.address_space == RTCORE_MEMORY_ADDRESS_SPACE_GLOBAL &&
         snapshot.operation == RTCORE_MEMORY_OPERATION_WRITE &&
         snapshot.destination ==
             RTCORE_MEMORY_DESTINATION_PRIVATE_COMMIT_ACK &&
         snapshot.access_kind == RTCORE_MEMORY_ACCESS_PRIVATE_FRONTIER_INIT &&
         snapshot.v04_global384_private_init.valid == 1;
}

static bool rtcore_v04_global384_private_runtime_write_request(
    const rtcore_memory_unit_request_snapshot &snapshot) {
  return snapshot.valid && snapshot.is_write &&
         snapshot.address_space == RTCORE_MEMORY_ADDRESS_SPACE_GLOBAL &&
         snapshot.operation == RTCORE_MEMORY_OPERATION_WRITE &&
         snapshot.destination ==
             RTCORE_MEMORY_DESTINATION_PRIVATE_COMMIT_ACK &&
         snapshot.access_kind ==
             RTCORE_MEMORY_ACCESS_PRIVATE_RUNTIME_WRITE &&
         snapshot.v04_private_write.valid == 1;
}

static bool rtcore_v04_global384_private_read_request(
    const rtcore_memory_unit_request_snapshot &snapshot) {
  return snapshot.valid && !snapshot.is_write &&
         snapshot.address_space == RTCORE_MEMORY_ADDRESS_SPACE_GLOBAL &&
         snapshot.operation == RTCORE_MEMORY_OPERATION_READ &&
         snapshot.access_kind == RTCORE_MEMORY_ACCESS_PRIVATE_STATE_384_READ &&
         snapshot.v04_private_state_384_read.valid == 1 &&
         snapshot.v04_private_state_384_read.storage_profile ==
             rtcore_private_storage::kProfileGlobal384;
}

static bool rtcore_v04_private_shared_identity_for_snapshot(
    const rtcore_memory_unit_request_snapshot &snapshot,
    uint32_t *tag_set, unsigned *canonical_chunk) {
  if (tag_set == NULL || canonical_chunk == NULL) return false;
  const bool private_transport =
      rtcore_v04_global384_private_init_request(snapshot) ||
      rtcore_v04_global384_private_runtime_write_request(snapshot) ||
      rtcore_v04_global384_private_read_request(snapshot);
  if (!private_transport) return false;
  if (snapshot.v04_semantic_memory.valid != 1 ||
      !rtcore_v04_semantic_memory_snapshot_valid(
          snapshot.v04_semantic_memory, snapshot.byte_mask) ||
      !rtcore_private_placement::exact_private_tag_set(
          snapshot.v04_semantic_memory.tag_set) ||
      snapshot.v04_semantic_memory.canonical_private_chunk_valid != 1 ||
      snapshot.v04_semantic_memory.canonical_private_chunk >=
          rtcore_private_placement::kChunkCount) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_PRIVATE_SHARED_IDENTITY_FAULT "
            "owner_hw_sid=%u request_key=0x%08x access_kind=%u "
            "operation_chunk=%u tag_set=0x%08x canonical_chunk=%u "
            "canonical_valid=%u\n",
            snapshot.owner_hw_sid, snapshot.rt_request_id,
            snapshot.access_kind, snapshot.chunk_id,
            snapshot.v04_semantic_memory.tag_set,
            snapshot.v04_semantic_memory.canonical_private_chunk,
            snapshot.v04_semantic_memory.canonical_private_chunk_valid);
    fflush(stderr);
    abort();
  }
  *tag_set = snapshot.v04_semantic_memory.tag_set;
  *canonical_chunk =
      snapshot.v04_semantic_memory.canonical_private_chunk;
  return true;
}

static void rtcore_accept_v04_global384_private_init_or_abort(
    rtcore_memory_unit_request_snapshot *snapshot,
    unsigned long long accept_cycle) {
  if (snapshot == NULL ||
      !rtcore_v04_global384_private_init_request(*snapshot)) {
    return;
  }
  if (!rtcore_accept_v04_global384_private_init_write(snapshot,
                                                       accept_cycle)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_GLOBAL384_PRIVATE_INIT_FAULT "
            "phase=accept owner_hw_sid=%u request_key=0x%08x lane_id=%u "
            "chunk_id=%u address=0x%llx\n",
            snapshot->owner_hw_sid, snapshot->rt_request_id,
            snapshot->lane_id, snapshot->chunk_id,
            snapshot->aligned_32b_addr);
    fflush(stderr);
    abort();
  }
}

static rtcore::v04::address_range_registry::live_access_v0
rtcore_v04_live_handoff_acquire_access(
    const rtcore_memory_unit_request_snapshot &snapshot) {
  namespace registry = rtcore::v04::address_range_registry;
  registry::live_access_v0 access = {};
  access.owner.owner_hw_sid = snapshot.owner_hw_sid;
  access.owner.resident_warp_generation =
      snapshot.v04_live_handoff_acquire.resident_warp_generation;
  access.owner.window_generation =
      snapshot.v04_live_handoff_acquire.window_generation;
  access.lane_id = static_cast<uint8_t>(snapshot.lane_id);
  access.object = registry::kObjectHandoff;
  access.access = registry::kAccessHandoffRtcoreAcquire;
  access.aligned_32b_address = snapshot.aligned_32b_addr;
  access.byte_mask = snapshot.byte_mask;
  return access;
}

static void rtcore_v04_live_handoff_acquire_fail_closed(
    const char *phase,
    rtcore::v04::pre_submit_publication::status_kind bridge_status,
    const rtcore_memory_unit_request_snapshot &snapshot) {
  fprintf(stderr,
          "GPGPU-Sim RTCORE_V04_LIVE_HANDOFF_ACQUIRE_FAULT "
          "phase=%s bridge_status=%s owner_hw_sid=%u request_id=%u "
          "lane_id=%u resident_generation=%u window_generation=%u "
          "address=0x%llx chunk_id=%u\n",
          phase,
          rtcore::v04::pre_submit_publication::status_name(bridge_status),
          snapshot.owner_hw_sid, snapshot.rt_request_id, snapshot.lane_id,
          snapshot.v04_live_handoff_acquire.resident_warp_generation,
          snapshot.v04_live_handoff_acquire.window_generation,
          snapshot.aligned_32b_addr, snapshot.chunk_id);
  fflush(stderr);
  abort();
}

static void rtcore_accept_v04_live_handoff_acquire_or_abort(
    rtcore_memory_unit_request_snapshot *snapshot) {
  namespace bridge = rtcore::v04::pre_submit_publication;
  namespace registry = rtcore::v04::address_range_registry;
  if (snapshot == NULL ||
      !rtcore_v04_live_handoff_acquire_request(*snapshot)) {
    return;
  }
  if (snapshot->v04_live_handoff_acquire.preaccepted != 1 ||
      snapshot->v04_live_transaction.valid != 0) {
    rtcore_v04_live_handoff_acquire_fail_closed(
        "accept-state", bridge::kStatusGroupConflict, *snapshot);
  }
  registry::transaction_token_v0 token = {};
  const bridge::status_kind status =
      bridge::shared_bridge().accept_preaccepted_live_access(
          rtcore_v04_live_handoff_acquire_access(*snapshot), &token);
  if (status != bridge::kStatusOk) {
    rtcore_v04_live_handoff_acquire_fail_closed(
        "accept-preaccepted", status, *snapshot);
  }
  snapshot->v04_live_handoff_acquire.preaccepted = 0;
  snapshot->v04_live_transaction.transaction_id = token.transaction_id;
  snapshot->v04_live_transaction.record_id = token.record_id;
  snapshot->v04_live_transaction.owner_hw_sid = token.owner_hw_sid;
  snapshot->v04_live_transaction.owner_generation = token.owner_generation;
  snapshot->v04_live_transaction.window_generation = token.window_generation;
  snapshot->v04_live_transaction.lane_id = token.lane_id;
  snapshot->v04_live_transaction.object =
      static_cast<uint8_t>(token.object);
  snapshot->v04_live_transaction.access =
      static_cast<uint8_t>(token.access);
  snapshot->v04_live_transaction.valid = 1;
  printf("GPGPU-Sim RTCORE_V04_HANDOFF_ACQUIRE_TICKET_ACCEPT "
         "owner_hw_sid=%u dynamic_warp_id=%u submit_warp_uid=%u "
         "warp_id=%u resident_generation=%u window_generation=%u "
         "active_mask=0x%08x lane_id=%u chunk_id=%u address=0x%llx "
         "transaction_kind=%u transaction_id=%llu result=accepted\n",
         snapshot->owner_hw_sid,
         snapshot->v04_live_handoff_acquire.dynamic_warp_id,
         snapshot->v04_live_handoff_acquire.submit_warp_uid,
         snapshot->resident_warp_id,
         snapshot->v04_live_handoff_acquire.resident_warp_generation,
         snapshot->v04_live_handoff_acquire.window_generation,
         snapshot->v04_live_handoff_acquire.acquire_active_mask,
         snapshot->lane_id, snapshot->chunk_id, snapshot->aligned_32b_addr,
         snapshot->v04_live_handoff_acquire.transaction_kind,
         static_cast<unsigned long long>(token.transaction_id));
  fflush(stdout);
}

static void rtcore_accept_v04_dispatch_handoff_read_or_abort(
    rtcore_memory_unit_request_snapshot *snapshot) {
  namespace bridge = rtcore::v04::pre_submit_publication;
  namespace registry = rtcore::v04::address_range_registry;
  if (snapshot == NULL ||
      !rtcore_v04_dispatch_handoff_read_request(*snapshot)) {
    return;
  }
  if (snapshot->v04_dispatch_handoff_read.preaccepted != 1 ||
      snapshot->v04_live_transaction.valid != 0) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_FAULT "
            "owner_hw_sid=%u warp_id=%u lane_id=%u "
            "phase=%u fault=accept_state_invalid_fail_closed\n",
            snapshot->owner_hw_sid, snapshot->rt_request_id,
            snapshot->lane_id,
            snapshot->v04_dispatch_handoff_read.phase);
    fflush(stderr);
    abort();
  }
  registry::transaction_token_v0 token = {};
  const bridge::status_kind status =
      bridge::shared_bridge().accept_preaccepted_live_access(
          rtcore_shader_continuation_handoff_live_access(*snapshot),
          &token);
  if (status != bridge::kStatusOk ||
      token.access != registry::kAccessHandoffShaderDispatchRead) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_FAULT "
            "owner_hw_sid=%u warp_id=%u lane_id=%u phase=%u "
            "bridge_status=%s fault=accept_preaccepted_fail_closed\n",
            snapshot->owner_hw_sid, snapshot->rt_request_id,
            snapshot->lane_id,
            snapshot->v04_dispatch_handoff_read.phase,
            bridge::status_name(status));
    fflush(stderr);
    abort();
  }
  snapshot->v04_dispatch_handoff_read.preaccepted = 0;
  snapshot->v04_live_transaction.transaction_id = token.transaction_id;
  snapshot->v04_live_transaction.record_id = token.record_id;
  snapshot->v04_live_transaction.owner_hw_sid = token.owner_hw_sid;
  snapshot->v04_live_transaction.owner_generation = token.owner_generation;
  snapshot->v04_live_transaction.window_generation = token.window_generation;
  snapshot->v04_live_transaction.lane_id = token.lane_id;
  snapshot->v04_live_transaction.object =
      static_cast<uint8_t>(token.object);
  snapshot->v04_live_transaction.access =
      static_cast<uint8_t>(token.access);
  snapshot->v04_live_transaction.valid = 1;
}

static void rtcore_complete_v04_live_handoff_acquire_or_abort(
    const rtcore_memory_unit_request_snapshot &snapshot,
    unsigned long long completion_cycle, unsigned long long response_address,
    const uint8_t *bound_read_payload, unsigned bound_read_payload_bytes) {
  namespace bridge = rtcore::v04::pre_submit_publication;
  namespace registry = rtcore::v04::address_range_registry;
  if (!rtcore_v04_live_handoff_acquire_request(snapshot)) return;
  if (snapshot.v04_live_handoff_acquire.preaccepted != 0 ||
      snapshot.v04_live_transaction.valid != 1) {
    rtcore_v04_live_handoff_acquire_fail_closed(
        "complete-state", bridge::kStatusGroupConflict, snapshot);
  }
  registry::transaction_token_v0 token = {};
  token.transaction_id = snapshot.v04_live_transaction.transaction_id;
  token.record_id = snapshot.v04_live_transaction.record_id;
  token.owner_hw_sid = snapshot.v04_live_transaction.owner_hw_sid;
  token.owner_generation = snapshot.v04_live_transaction.owner_generation;
  token.window_generation = snapshot.v04_live_transaction.window_generation;
  token.lane_id = snapshot.v04_live_transaction.lane_id;
  token.object = static_cast<registry::object_kind>(
      snapshot.v04_live_transaction.object);
  token.access = static_cast<registry::access_kind>(
      snapshot.v04_live_transaction.access);
  const unsigned transaction_kind =
      snapshot.v04_live_handoff_acquire.transaction_kind;
  const bool response_context_valid =
      response_address == snapshot.aligned_32b_addr &&
      bound_read_payload != NULL &&
      bound_read_payload_bytes ==
          RTCORE_V02_LSU_MEMORY_REQUEST_GRANULE_BYTES;
  bool tracker_valid = false;
  if (transaction_kind ==
      RTCORE_V04_HANDOFF_ACQUIRE_TRANSACTION_INITIAL) {
    tracker_valid =
        response_context_valid &&
        rtcore_validate_v04_global384_initial_handoff_acquire_chunk(
            &snapshot, bound_read_payload, bound_read_payload_bytes);
  } else if (transaction_kind ==
             RTCORE_V04_HANDOFF_ACQUIRE_TRANSACTION_RESUBMIT) {
    tracker_valid =
        response_context_valid &&
        rtcore_validate_v04_global384_resubmit_handoff_acquire_chunk(
            &snapshot, bound_read_payload, bound_read_payload_bytes);
  }
  if (!tracker_valid) {
    rtcore_v04_live_handoff_acquire_fail_closed(
        "precommit-validation", bridge::kStatusGroupConflict,
        snapshot);
  }
  const registry::status_kind status =
      bridge::shared_bridge().complete_live_access(token);
  if (status != registry::kStatusOk) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_LIVE_HANDOFF_ACQUIRE_FAULT "
            "phase=complete registry_status=%s transaction_id=%llu\n",
            registry::status_name(status),
            static_cast<unsigned long long>(token.transaction_id));
    fflush(stderr);
    abort();
  }
  bool tracker_completed = false;
  if (transaction_kind ==
      RTCORE_V04_HANDOFF_ACQUIRE_TRANSACTION_INITIAL) {
    tracker_completed =
        rtcore_complete_v04_global384_initial_handoff_acquire_chunk(
            &snapshot, bound_read_payload, bound_read_payload_bytes,
            completion_cycle);
  } else if (transaction_kind ==
             RTCORE_V04_HANDOFF_ACQUIRE_TRANSACTION_RESUBMIT) {
    tracker_completed =
        rtcore_complete_v04_global384_resubmit_handoff_acquire_chunk(
            &snapshot, bound_read_payload, bound_read_payload_bytes,
            completion_cycle);
  }
  if (!tracker_completed) {
    rtcore_v04_live_handoff_acquire_fail_closed(
        "tracker-complete", bridge::kStatusGroupConflict,
        snapshot);
  }
  printf("GPGPU-Sim RTCORE_V04_HANDOFF_ACQUIRE_TICKET_COMPLETE "
         "owner_hw_sid=%u dynamic_warp_id=%u submit_warp_uid=%u "
         "warp_id=%u resident_generation=%u window_generation=%u "
         "active_mask=0x%08x lane_id=%u chunk_id=%u address=0x%llx "
         "transaction_kind=%u transaction_id=%llu "
         "payload_source=cache_accept_snapshot result=completed\n",
         snapshot.owner_hw_sid,
         snapshot.v04_live_handoff_acquire.dynamic_warp_id,
         snapshot.v04_live_handoff_acquire.submit_warp_uid,
         snapshot.resident_warp_id,
         snapshot.v04_live_handoff_acquire.resident_warp_generation,
         snapshot.v04_live_handoff_acquire.window_generation,
         snapshot.v04_live_handoff_acquire.acquire_active_mask,
         snapshot.lane_id, snapshot.chunk_id, snapshot.aligned_32b_addr,
         snapshot.v04_live_handoff_acquire.transaction_kind,
         static_cast<unsigned long long>(token.transaction_id));
  fflush(stdout);
}

static void rtcore_record_v02_lsu_sideband_response_completion(
    const rtcore_memory_unit_request_snapshot &snapshot,
    unsigned long long response_cycle, memory_space *global_memory,
    unsigned long long response_address,
    const uint8_t *bound_read_payload, unsigned bound_read_payload_bytes) {
  if (!snapshot.valid) {
    return;
  }
  if (rtcore_v04_global384_private_init_request(snapshot)) {
    if (!rtcore_complete_v04_global384_private_init_write(
            &snapshot, global_memory, response_address, response_cycle)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_GLOBAL384_PRIVATE_INIT_FAULT "
              "phase=ack owner_hw_sid=%u request_key=0x%08x lane_id=%u "
              "chunk_id=%u response_address=0x%llx expected_address=0x%llx\n",
              snapshot.owner_hw_sid, snapshot.rt_request_id,
              snapshot.lane_id, snapshot.chunk_id, response_address,
              snapshot.aligned_32b_addr);
      fflush(stderr);
      abort();
    }
    rtcore_record_v04_memory_conservation_or_abort(
        snapshot, true, response_cycle);
    return;
  }
  if (rtcore_v04_global384_private_runtime_write_request(snapshot)) {
    if (!rtcore_complete_v04_global384_private_runtime_write(
            &snapshot, global_memory, response_address,
            response_cycle)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_GLOBAL384_PRIVATE_RUNTIME_WRITE_FAULT "
              "phase=ack owner_hw_sid=%u request_key=0x%08x lane_id=%u "
              "operation_seq=%u commit_epoch=%u memory_op_seq=%u "
              "chunk_id=%u response_address=0x%llx "
              "expected_address=0x%llx\n",
              snapshot.owner_hw_sid, snapshot.rt_request_id,
              snapshot.lane_id,
              snapshot.v04_private_write.producer_operation_seq,
              snapshot.v04_private_write.producer_commit_epoch,
              snapshot.memory_op_seq, snapshot.chunk_id,
              response_address, snapshot.aligned_32b_addr);
      fflush(stderr);
      abort();
    }
    rtcore_record_v04_memory_conservation_or_abort(
        snapshot, true, response_cycle);
    return;
  }
  if (snapshot.destination ==
          RTCORE_MEMORY_DESTINATION_SHORT_STACK_QUEUE_FILL &&
      snapshot.access_kind ==
          RTCORE_MEMORY_ACCESS_SHORT_STACK_RETURN_INSTANCE_READ) {
    uint8_t response_payload[
        rtcore::v04::private_frontier::kSharedAccessChunkBytes] = {};
    if (global_memory == NULL ||
        response_address != snapshot.aligned_32b_addr) {
      fprintf(
          stderr,
          "GPGPU-Sim RTCORE_V04_SHORT_STACK_RETURN_READ_FAULT "
          "owner_hw_sid=%u request_key=0x%08x generation=%u "
          "chunk_id=%u chunk_count=%u response_addr=0x%llx "
          "expected_addr=0x%llx fault=response_context_invalid\n",
          snapshot.owner_hw_sid, snapshot.rt_request_id,
          snapshot.request_generation, snapshot.chunk_id,
          snapshot.chunk_count, response_address,
          snapshot.aligned_32b_addr);
      fflush(stderr);
      abort();
    }
    global_memory->read(
        snapshot.aligned_32b_addr, sizeof(response_payload),
        response_payload);
    if (!rtcore_accept_v04_short_stack_return_instance_read(
            &snapshot, response_payload, sizeof(response_payload),
            response_cycle)) {
      fprintf(
          stderr,
          "GPGPU-Sim RTCORE_V04_SHORT_STACK_RETURN_READ_FAULT "
          "owner_hw_sid=%u request_key=0x%08x generation=%u "
          "chunk_id=%u chunk_count=%u response_addr=0x%llx\n",
          snapshot.owner_hw_sid, snapshot.rt_request_id,
          snapshot.request_generation, snapshot.chunk_id,
          snapshot.chunk_count, response_address);
      fflush(stderr);
      abort();
    }
    rtcore_record_v04_memory_conservation_or_abort(
        snapshot, true, response_cycle);
    return;
  }
  if (snapshot.destination ==
          RTCORE_MEMORY_DESTINATION_PRIVATE_BOUNDARY_FILL &&
      snapshot.access_kind ==
          RTCORE_MEMORY_ACCESS_PRIVATE_STATE_384_READ) {
    const bool response_valid =
        snapshot.address_space == RTCORE_MEMORY_ADDRESS_SPACE_GLOBAL &&
        snapshot.operation == RTCORE_MEMORY_OPERATION_READ &&
        !snapshot.is_write &&
        snapshot.v04_private_state_384_read.storage_profile ==
            rtcore::v04::private_storage::kProfileGlobal384 &&
        response_address == snapshot.aligned_32b_addr &&
        bound_read_payload != NULL &&
        bound_read_payload_bytes ==
            rtcore::v04::private_state_384::kChunkBytes;
    if (!response_valid ||
        !rtcore_accept_v04_private_boundary_state_384_read_response(
            &snapshot, bound_read_payload, bound_read_payload_bytes,
            response_cycle)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_GLOBAL384_BOUNDARY_READ_FAULT "
              "owner_hw_sid=%u request_key=0x%08x generation=%u "
              "operation_seq=%u chunk_id=%u chunk_count=%u "
              "response_addr=0x%llx expected_addr=0x%llx\n",
              snapshot.owner_hw_sid, snapshot.rt_request_id,
              snapshot.request_generation,
              snapshot.v04_private_state_384_read.operation_sequence,
              snapshot.chunk_id, snapshot.chunk_count,
              response_address, snapshot.aligned_32b_addr);
      fflush(stderr);
      abort();
    }
    rtcore_record_v04_global384_semantic_last_arrival(
        &snapshot, response_cycle);
    printf("GPGPU-Sim RTCORE_V04_GLOBAL384_BOUNDARY_RESPONSE_ACCEPTED "
           "owner_hw_sid=%u request_key=0x%08x generation=%u "
           "operation_seq=%u reservation_generation=%u "
           "chunk_id=%u chunk_count=%u response_addr=0x%llx "
           "source=l1d_completion_bytes "
           "payload_capture=cache_accept_snapshot\n",
           snapshot.owner_hw_sid, snapshot.rt_request_id,
           snapshot.request_generation,
           snapshot.v04_private_state_384_read.operation_sequence,
           snapshot.v04_private_state_384_read.reservation_generation,
           snapshot.chunk_id, snapshot.chunk_count, response_address);
    fflush(stdout);
    rtcore_record_v04_memory_conservation_or_abort(
        snapshot, true, response_cycle);
    return;
  }
  if (snapshot.destination ==
          RTCORE_MEMORY_DESTINATION_TARGET_QUEUE_FILL &&
      snapshot.access_kind ==
          RTCORE_MEMORY_ACCESS_PRIVATE_STATE_384_READ) {
    const bool response_valid =
        snapshot.address_space == RTCORE_MEMORY_ADDRESS_SPACE_GLOBAL &&
        snapshot.operation == RTCORE_MEMORY_OPERATION_READ &&
        !snapshot.is_write &&
        snapshot.v04_private_state_384_read.storage_profile ==
            rtcore::v04::private_storage::kProfileGlobal384 &&
        response_address == snapshot.aligned_32b_addr &&
        bound_read_payload != NULL &&
        bound_read_payload_bytes ==
            rtcore::v04::private_state_384::kChunkBytes;
    if (!response_valid ||
        !rtcore_accept_v04_target_private_state_384_read_response(
            &snapshot, bound_read_payload, bound_read_payload_bytes,
            response_cycle)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_GLOBAL384_TARGET_READ_FAULT "
              "owner_hw_sid=%u request_key=0x%08x generation=%u "
              "operation_seq=%u chunk_id=%u chunk_count=%u "
              "response_addr=0x%llx expected_addr=0x%llx\n",
              snapshot.owner_hw_sid, snapshot.rt_request_id,
              snapshot.request_generation,
              snapshot.v04_private_state_384_read.operation_sequence,
              snapshot.chunk_id, snapshot.chunk_count,
              response_address, snapshot.aligned_32b_addr);
      fflush(stderr);
      abort();
    }
    rtcore_record_v04_global384_semantic_last_arrival(
        &snapshot, response_cycle);
    printf("GPGPU-Sim RTCORE_V04_GLOBAL384_TARGET_PRIVATE_RESPONSE_ACCEPTED "
           "owner_hw_sid=%u request_key=0x%08x generation=%u "
           "operation_seq=%u reservation_generation=%u "
           "chunk_id=%u chunk_count=%u response_addr=0x%llx "
           "source=l1d_completion_bytes "
           "payload_capture=cache_accept_snapshot\n",
           snapshot.owner_hw_sid, snapshot.rt_request_id,
           snapshot.request_generation,
           snapshot.v04_private_state_384_read.operation_sequence,
           snapshot.v04_private_state_384_read.reservation_generation,
           snapshot.chunk_id, snapshot.chunk_count, response_address);
    fflush(stdout);
    rtcore_record_v04_memory_conservation_or_abort(
        snapshot, true, response_cycle);
    return;
  }
  if (snapshot.destination ==
          RTCORE_MEMORY_DESTINATION_SHORT_STACK_QUEUE_FILL &&
      snapshot.access_kind ==
          RTCORE_MEMORY_ACCESS_PRIVATE_STATE_384_READ) {
    const bool response_valid =
        snapshot.address_space == RTCORE_MEMORY_ADDRESS_SPACE_GLOBAL &&
        snapshot.operation == RTCORE_MEMORY_OPERATION_READ &&
        !snapshot.is_write &&
        snapshot.v04_private_state_384_read.storage_profile ==
            rtcore::v04::private_storage::kProfileGlobal384 &&
        response_address == snapshot.aligned_32b_addr &&
        bound_read_payload != NULL &&
        bound_read_payload_bytes ==
            rtcore::v04::private_state_384::kChunkBytes;
    if (!response_valid ||
        !rtcore_accept_v04_short_stack_private_state_384_read_response(
            &snapshot, bound_read_payload, bound_read_payload_bytes,
            response_cycle)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_GLOBAL384_SHORT_STACK_READ_FAULT "
              "owner_hw_sid=%u request_key=0x%08x generation=%u "
              "operation_seq=%u chunk_id=%u chunk_count=%u "
              "response_addr=0x%llx expected_addr=0x%llx\n",
              snapshot.owner_hw_sid, snapshot.rt_request_id,
              snapshot.request_generation,
              snapshot.v04_private_state_384_read.operation_sequence,
              snapshot.chunk_id, snapshot.chunk_count,
              response_address, snapshot.aligned_32b_addr);
      fflush(stderr);
      abort();
    }
    rtcore_record_v04_global384_semantic_last_arrival(
        &snapshot, response_cycle);
    rtcore_record_v04_memory_conservation_or_abort(
        snapshot, true, response_cycle);
    return;
  }
  if (snapshot.destination ==
          RTCORE_MEMORY_DESTINATION_TARGET_QUEUE_FILL &&
      snapshot.access_kind ==
          RTCORE_MEMORY_ACCESS_STACK_SPILL_RECOVERY_READ &&
      snapshot.v04_target_raw_read.private_storage_profile ==
          rtcore::v04::private_storage::kProfileGlobal384) {
    const bool response_valid =
        snapshot.address_space == RTCORE_MEMORY_ADDRESS_SPACE_GLOBAL &&
        snapshot.operation == RTCORE_MEMORY_OPERATION_READ &&
        !snapshot.is_write &&
        response_address == snapshot.aligned_32b_addr &&
        bound_read_payload != NULL &&
        bound_read_payload_bytes ==
            rtcore::v04::private_state_384::kChunkBytes;
    if (!response_valid ||
        !rtcore_accept_v04_stack_spill_recovery_read_response(
            &snapshot, bound_read_payload, bound_read_payload_bytes,
            response_cycle)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_GLOBAL384_TRANSITION_RECOVERY_FAULT "
              "owner_hw_sid=%u request_key=0x%08x generation=%u "
              "target_operation_seq=%u chunk_id=%u chunk_count=%u "
              "response_addr=0x%llx expected_addr=0x%llx\n",
              snapshot.owner_hw_sid, snapshot.rt_request_id,
              snapshot.request_generation,
              snapshot.v04_target_raw_read.target_operation_seq,
              snapshot.chunk_id, snapshot.chunk_count,
              response_address, snapshot.aligned_32b_addr);
      fflush(stderr);
      abort();
    }
    rtcore_record_v04_memory_conservation_or_abort(
        snapshot, true, response_cycle);
    return;
  }
  if (snapshot.destination ==
      RTCORE_MEMORY_DESTINATION_TARGET_QUEUE_FILL) {
    uint8_t response_payload[
        rtcore::v04::target_memory::kRawReadChunkBytes] = {};
    const rtcore::v04::live_global_memory::status_kind materialize_status =
        rtcore::v04::live_global_memory::materialize_functional_response(
            snapshot, global_memory, response_address, response_payload,
            sizeof(response_payload));
    if (snapshot.access_kind !=
            RTCORE_MEMORY_ACCESS_TARGET_RAW_READ ||
        materialize_status !=
            rtcore::v04::live_global_memory::kStatusOk ||
        !rtcore_accept_v04_target_raw_read_response(
            &snapshot, response_payload, sizeof(response_payload),
            response_cycle)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_TARGET_RAW_RESPONSE_FAULT "
              "owner_hw_sid=%u request_key=0x%08x generation=%u "
              "reservation_id=%llu slot=%u slot_generation=%u "
              "chunk_id=%u chunk_count=%u response_addr=0x%llx "
              "materialize_status=%s\n",
              snapshot.owner_hw_sid, snapshot.rt_request_id,
              snapshot.request_generation,
              static_cast<unsigned long long>(
                  snapshot.v04_target_raw_read.reservation_id),
              snapshot.v04_target_raw_read.target_slot_index,
              snapshot.v04_target_raw_read.target_slot_generation,
              snapshot.chunk_id, snapshot.chunk_count,
              response_address,
              rtcore::v04::live_global_memory::status_name(
                  materialize_status));
      fflush(stderr);
      abort();
    }
    rtcore_record_v04_memory_conservation_or_abort(
        snapshot, true, response_cycle);
    return;
  }
  const bool v04_live_publication_store =
      snapshot.access_kind ==
          RTCORE_V02_LSU_ACCESS_HANDOFF_PUBLICATION_STORE &&
      rtcore_v04_live_publication_memory_op_seq(snapshot.memory_op_seq);
  const bool v04_native_publication_store =
      snapshot.access_kind ==
          RTCORE_MEMORY_ACCESS_HANDOFF_PUBLICATION_WRITE &&
      rtcore_v04_native_publication_memory_op_seq(
          snapshot.memory_op_seq);
  if (v04_native_publication_store) {
    if (!rtcore_accept_v04_handoff_publication_response(
            &snapshot, response_cycle)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_NATIVE_BOUNDARY_FAULT "
              "owner_hw_sid=%u request_key=0x%08x "
              "memory_op_seq=%u phase=response "
              "fault=publication_response_rejected\n",
              snapshot.owner_hw_sid, snapshot.rt_request_id,
              snapshot.memory_op_seq);
      fflush(stderr);
      abort();
    }
    rtcore_record_v04_memory_conservation_or_abort(
        snapshot, true, response_cycle);
    return;
  }
  if (snapshot.access_kind == RTCORE_V02_LSU_ACCESS_STACK_STORE ||
      (snapshot.access_kind ==
           RTCORE_V02_LSU_ACCESS_HANDOFF_PUBLICATION_STORE &&
       !v04_live_publication_store) ||
      (snapshot.access_kind ==
           RTCORE_MEMORY_ACCESS_HANDOFF_PUBLICATION_WRITE &&
       !v04_native_publication_store) ||
      snapshot.access_kind == RTCORE_V02_LSU_ACCESS_RESULT_STORE) {
    return;
  }
  if (snapshot.response_target ==
          RTCORE_V02_LSU_RESPONSE_TARGET_SHADER_CONTINUATION &&
      snapshot.access_kind == RTCORE_V02_LSU_ACCESS_SBT_METADATA) {
    rtcore_record_shader_continuation_sbt_metadata_response(snapshot,
                                                            response_cycle);
    return;
  }
  if (snapshot.response_target ==
          RTCORE_V02_LSU_RESPONSE_TARGET_SHADER_CONTINUATION &&
      snapshot.access_kind ==
          RTCORE_V02_LSU_ACCESS_HANDOFF_DISPATCH_READ) {
    rtcore_record_shader_continuation_handoff_read_response(
        snapshot, response_cycle, response_address,
        bound_read_payload, bound_read_payload_bytes);
    rtcore_record_v04_global384_semantic_last_arrival(
        &snapshot, response_cycle);
    rtcore_record_v04_memory_conservation_or_abort(
        snapshot, true, response_cycle);
    return;
  }
  rtcore_record_memory_unit_response(
      snapshot.owner_hw_sid, snapshot.rt_request_id, snapshot.memory_op_seq,
      snapshot.chunk_id, snapshot.chunk_count, snapshot.response_target,
      response_cycle);
  rtcore_record_v04_memory_conservation_or_abort(
      snapshot, true, response_cycle);
}

static void rtcore_v02_lsu_update_sideband_pending_count() {
  unsigned long long pending_waiter_count = 0;
  for (std::map<unsigned, rtcore_v04_pending_memory_transaction>::iterator it =
           g_rtcore_v02_lsu_pending_memory_requests.begin();
       it != g_rtcore_v02_lsu_pending_memory_requests.end(); ++it) {
    pending_waiter_count += it->second.waiters.size();
  }
  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_pending_request_count =
      pending_waiter_count;
  if (g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_sideband_pending_request_count >
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_sideband_max_pending_request_count) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_max_pending_request_count =
        g_rtcore_replay_cycle_hook_consumer_stats
            .v02_lsu_sideband_pending_request_count;
  }
}

static const char *rtcore_v02_lsu_selected_cache_kind_name(unsigned kind) {
  if (kind == 1u) {
    return "L1D";
  }
  if (kind == 2u) {
    return "L0";
  }
  return "none";
}

static void rtcore_record_v02_lsu_cache_config_identity(
    bool selected_l1d, baseline_cache *cache, unsigned current_mshr_entries) {
  if (!rtcore_memory_unit_cache_config_identity_log_enabled() || cache == NULL) {
    return;
  }
  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_cache_config_identity_observation_count++;
  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_selected_cache_kind = selected_l1d ? 1u : 2u;
  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_selected_cache_config_mshr_entries =
      cache->get_mshr_entries();
  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_selected_cache_config_mshr_max_merge =
      cache->get_mshr_max_merge();
  if (current_mshr_entries >
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_sideband_selected_cache_current_mshr_entries_max) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_selected_cache_current_mshr_entries_max =
        current_mshr_entries;
  }
}

static void rtcore_maybe_log_memory_unit_cache_config_identity_stats(
    unsigned owner_hw_sid) {
  if (!rtcore_memory_unit_cache_config_identity_log_enabled()) {
    return;
  }
  if (g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_sideband_cache_config_identity_observation_count == 0) {
    return;
  }
  printf("GPGPU-Sim RTCORE_REPLAY_MEMORY_UNIT_CACHE_CONFIG_IDENTITY_STATS "
         "owner_hw_sid=%u cache_config_identity_enabled=1 "
         "selected_cache_kind=%s selected_cache_config_mshr_entries=%u "
         "selected_cache_config_mshr_max_merge=%u "
         "selected_cache_current_mshr_entries_max=%u observations=%llu\n",
         owner_hw_sid,
         rtcore_v02_lsu_selected_cache_kind_name(
             g_rtcore_replay_cycle_hook_consumer_stats
                 .v02_lsu_sideband_selected_cache_kind),
         g_rtcore_replay_cycle_hook_consumer_stats
             .v02_lsu_sideband_selected_cache_config_mshr_entries,
         g_rtcore_replay_cycle_hook_consumer_stats
             .v02_lsu_sideband_selected_cache_config_mshr_max_merge,
         g_rtcore_replay_cycle_hook_consumer_stats
             .v02_lsu_sideband_selected_cache_current_mshr_entries_max,
         g_rtcore_replay_cycle_hook_consumer_stats
             .v02_lsu_sideband_cache_config_identity_observation_count);
}

static bool rtcore_record_v02_lsu_sideband_icnt_injection(mem_fetch *mf) {
  if (!rtcore_replay_memory_unit_l1d_client_enabled() || mf == NULL) {
    return false;
  }
  std::map<unsigned, rtcore_v04_pending_memory_transaction>::iterator it =
      g_rtcore_v02_lsu_pending_memory_requests.find(mf->get_request_uid());
  if (it == g_rtcore_v02_lsu_pending_memory_requests.end()) {
    return false;
  }

  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_icnt_injection_count++;
  if (mf->get_is_write()) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_icnt_injection_write_count++;
  } else {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_icnt_injection_read_count++;
  }
  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_icnt_injection_flit_count +=
      mf->get_num_flits(true);
  const unsigned long long waiter_count = it->second.waiters.size();
  if (waiter_count >
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_sideband_icnt_injection_max_waiter_count) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_icnt_injection_max_waiter_count =
        waiter_count;
  }
  return true;
}

static unsigned rtcore_complete_v02_lsu_sideband_pending_response(
    mem_fetch *mf, unsigned long long response_cycle,
    unsigned *last_owner_hw_sid, memory_space *global_memory) {
  if (mf == NULL) {
    return 0;
  }

  std::map<unsigned, rtcore_v04_pending_memory_transaction>::iterator it =
      g_rtcore_v02_lsu_pending_memory_requests.find(mf->get_request_uid());
  if (it == g_rtcore_v02_lsu_pending_memory_requests.end()) {
    return 0;
  }
  if (it->second.waiters.empty()) {
    g_rtcore_v02_lsu_read_payload_by_mem_fetch_uid.erase(
        mf->get_request_uid());
    g_rtcore_v02_lsu_pending_memory_requests.erase(it);
    return 0;
  }

  const std::map<unsigned,
                 rtcore_memory_unit_read_payload_snapshot>::const_iterator
      payload = g_rtcore_v02_lsu_read_payload_by_mem_fetch_uid.find(
          mf->get_request_uid());
  const uint8_t *bound_read_payload =
      payload != g_rtcore_v02_lsu_read_payload_by_mem_fetch_uid.end() &&
              payload->second.valid &&
              payload->second.aligned_32b_addr == mf->get_addr()
          ? payload->second.bytes.data()
          : NULL;
  const unsigned bound_read_payload_bytes =
      bound_read_payload != NULL
          ? RTCORE_V02_LSU_MEMORY_REQUEST_GRANULE_BYTES
          : 0;

  if (last_owner_hw_sid != NULL) {
    *last_owner_hw_sid = it->second.waiters.front().owner_hw_sid;
  }
  rtcore_v04_semantic_finalize_physical(
      mf->get_request_uid(), it->second, response_cycle);
  for (std::vector<rtcore_memory_unit_request_snapshot>::const_iterator
           waiter_it = it->second.waiters.begin();
       waiter_it != it->second.waiters.end(); ++waiter_it) {
    if (it->second.semantic_valid) {
      rtcore_v04_semantic_record_logical_response(*waiter_it,
                                                  response_cycle);
    }
    rtcore_record_v02_lsu_sideband_response_latency(*waiter_it,
                                                    response_cycle);
    rtcore_record_v02_lsu_sideband_response_wakeup_kind(*waiter_it);
    rtcore_record_v02_lsu_sideband_response_completion(*waiter_it,
                                                       response_cycle,
                                                       global_memory,
                                                       mf->get_addr(),
                                                       bound_read_payload,
                                                       bound_read_payload_bytes);
    rtcore_complete_v04_live_handoff_acquire_or_abort(
        *waiter_it, response_cycle, mf->get_addr(),
        bound_read_payload, bound_read_payload_bytes);
  }
  const unsigned completed_count = it->second.waiters.size();
  if (completed_count > 1) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_same_cycle_fanout_wake_count += completed_count;
  }
  g_rtcore_v02_lsu_read_payload_by_mem_fetch_uid.erase(
      mf->get_request_uid());
  g_rtcore_v04_semantic_completing_physical.erase(mf->get_request_uid());
  g_rtcore_v02_lsu_pending_memory_requests.erase(it);
  return completed_count;
}

static bool rtcore_maybe_complete_v02_lsu_sideband_ready_access(
    mem_fetch *mf, unsigned long long response_cycle,
    memory_space *global_memory) {
  if (mf == NULL ||
      g_rtcore_v02_lsu_pending_memory_requests.find(mf->get_request_uid()) ==
          g_rtcore_v02_lsu_pending_memory_requests.end()) {
    return false;
  }

  unsigned owner_hw_sid = 0;
  const unsigned completed_count =
      rtcore_complete_v02_lsu_sideband_pending_response(
          mf, response_cycle, &owner_hw_sid, global_memory);
  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_response_wakeup_count += completed_count;
  rtcore_v02_lsu_update_sideband_pending_count();
  rtcore_maybe_log_memory_unit_request_offer_stats(owner_hw_sid);
  return true;
}

static new_addr_type rtcore_memory_unit_effective_addr(
    const rtcore_replay_cycle_hook_result &result) {
  if (!rtcore_memory_unit_same_cycle_32b_merge_stress_enabled()) {
    return static_cast<new_addr_type>(result.lsu_sideband_aligned_32b_addr);
  }
  const rtcore_memory_unit_request_snapshot snapshot =
      rtcore_v02_lsu_sideband_snapshot_from_result(result);
  if (snapshot.destination ==
      RTCORE_MEMORY_DESTINATION_TARGET_QUEUE_FILL) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_TARGET_RAW_CONFIGURATION_FAULT "
            "owner_hw_sid=%u request_key=0x%08x "
            "fault=same_cycle_merge_stress_rewrites_data_address\n",
            snapshot.owner_hw_sid, snapshot.rt_request_id);
    fflush(stderr);
    abort();
  }
  if (rtcore_v04_global384_private_runtime_write_request(snapshot)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_GLOBAL384_PRIVATE_RUNTIME_WRITE_FAULT "
            "owner_hw_sid=%u request_key=0x%08x "
            "fault=same_cycle_merge_stress_rewrites_private_address\n",
            snapshot.owner_hw_sid, snapshot.rt_request_id);
    fflush(stderr);
    abort();
  }
  if (rtcore_v04_native_publication_requires_exact_address(snapshot)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_NATIVE_BOUNDARY_CONFIGURATION_FAULT "
            "owner_hw_sid=%u request_key=0x%08x "
            "fault=same_cycle_merge_stress_rewrites_publication_address\n",
            snapshot.owner_hw_sid, snapshot.rt_request_id);
    fflush(stderr);
    abort();
  }
  if (snapshot.destination ==
          RTCORE_MEMORY_DESTINATION_PRIVATE_BOUNDARY_FILL &&
      snapshot.access_kind ==
          RTCORE_MEMORY_ACCESS_PRIVATE_STATE_384_READ) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_GLOBAL384_BOUNDARY_CONFIGURATION_FAULT "
            "owner_hw_sid=%u request_key=0x%08x "
            "fault=same_cycle_merge_stress_rewrites_private_address\n",
            snapshot.owner_hw_sid, snapshot.rt_request_id);
    fflush(stderr);
    abort();
  }
  return static_cast<new_addr_type>(
      0x70000000ull +
      static_cast<unsigned long long>(result.lsu_sideband_owner_hw_sid) *
          0x1000ull);
}

static unsigned rtcore_v04_storage_traffic_class_for_sideband(
    const rtcore_memory_unit_request_snapshot &snapshot) {
  if (snapshot.v04_semantic_memory.valid == 1) {
    return mem_fetch::RTCORE_V04_STORAGE_TRAFFIC_V04_STORAGE;
  }
  if (snapshot.access_kind == RTCORE_V02_LSU_ACCESS_SBT_METADATA) {
    return mem_fetch::RTCORE_V04_STORAGE_TRAFFIC_CONTINUATION_METADATA;
  }
  if (snapshot.access_kind == RTCORE_V02_LSU_ACCESS_NODE_FETCH ||
      snapshot.access_kind == RTCORE_V02_LSU_ACCESS_PRIMITIVE_FETCH ||
      snapshot.access_kind == RTCORE_MEMORY_ACCESS_TARGET_RAW_READ) {
    return mem_fetch::RTCORE_V04_STORAGE_TRAFFIC_V04_BVH;
  }
  return mem_fetch::RTCORE_V04_STORAGE_TRAFFIC_V04_STORAGE;
}

static void rtcore_memory_unit_refresh_same_cycle_32b_merge_map(
    unsigned long long cycle) {
  if (!g_rtcore_memory_unit_same_cycle_32b_merge_map_initialized ||
      g_rtcore_memory_unit_same_cycle_32b_merge_map_cycle != cycle) {
    g_rtcore_memory_unit_same_cycle_32b_merge_mf_by_key.clear();
    g_rtcore_memory_unit_same_cycle_32b_merge_map_cycle = cycle;
    g_rtcore_memory_unit_same_cycle_32b_merge_map_initialized = true;
  }
}

static bool rtcore_try_merge_memory_unit_same_cycle_32b(
    const rtcore_replay_cycle_hook_result &result, new_addr_type addr,
    rtcore_memory_unit_request_snapshot *snapshot) {
  if (!rtcore_memory_unit_same_cycle_32b_merge_enabled()) {
    return false;
  }
  if (result.lsu_sideband_is_write ||
      (snapshot != NULL && snapshot->is_write)) {
    return false;
  }
  rtcore_memory_unit_refresh_same_cycle_32b_merge_map(result.cycle);
  rtcore_memory_unit_same_cycle_32b_merge_key key = {};
  key.owner_hw_sid = result.lsu_sideband_owner_hw_sid;
  key.cycle = result.cycle;
  key.aligned_32b_addr = static_cast<unsigned long long>(addr);
  key.is_write = result.lsu_sideband_is_write;
  std::map<rtcore_memory_unit_same_cycle_32b_merge_key, mem_fetch *>::iterator
      key_it = g_rtcore_memory_unit_same_cycle_32b_merge_mf_by_key.find(key);
  if (key_it == g_rtcore_memory_unit_same_cycle_32b_merge_mf_by_key.end()) {
    return false;
  }
  mem_fetch *source_mf = key_it->second;
  if (source_mf == NULL) abort();
  std::map<unsigned, rtcore_v04_pending_memory_transaction>::iterator
      pending_it =
          g_rtcore_v02_lsu_pending_memory_requests.find(
              source_mf->get_request_uid());
  if (pending_it == g_rtcore_v02_lsu_pending_memory_requests.end()) {
    g_rtcore_memory_unit_same_cycle_32b_merge_mf_by_key.erase(key_it);
    return false;
  }
  if (snapshot == NULL) return false;
  if (rtcore_v04_storage_attribution_enabled()) {
    const unsigned cls =
        rtcore_v04_storage_traffic_class_for_sideband(*snapshot);
    source_mf->merge_rtcore_v04_storage_traffic_class_set(
        uint32_t{1} << (cls - 1u));
  }
  if (rtcore_v04_multiwarp_stats_enabled()) {
    bool cross_warp = false;
    for (std::vector<rtcore_memory_unit_request_snapshot>::const_iterator it =
             pending_it->second.waiters.begin();
         it != pending_it->second.waiters.end(); ++it) {
      if (it->resident_warp_id != snapshot->resident_warp_id) {
        cross_warp = true;
        break;
      }
    }
    rtcore_v04_multiwarp_stats &stats =
        rtcore_v04_multiwarp_stats_for(snapshot->owner_hw_sid);
    if (cross_warp) {
      stats.same_cycle_merge_cross_warp++;
    } else {
      stats.same_cycle_merge_same_warp++;
    }
  }
  rtcore_accept_v04_live_handoff_acquire_or_abort(snapshot);
  rtcore_accept_v04_dispatch_handoff_read_or_abort(snapshot);
  if (rtcore_v04_global384_semantic_accounting_enabled() &&
      snapshot->v04_semantic_memory.valid == 1) {
    rtcore_v04_semantic_observe_logical(*snapshot);
    rtcore_v04_semantic_record_accept(
        snapshot, source_mf->get_request_uid(), result.cycle);
    const unsigned source_handoff_chunk =
        rtcore_v04_semantic_handoff_chunk_for_mem_fetch(source_mf);
    const unsigned child_handoff_chunk =
        rtcore_v04_semantic_handoff_chunk_for_snapshot(*snapshot);
    if ((source_handoff_chunk < 4u) != (child_handoff_chunk < 4u) ||
        (source_handoff_chunk < 4u &&
         source_handoff_chunk != child_handoff_chunk)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_SEMANTIC_ACCOUNTING_FAULT "
              "fault=same_cycle_merge_cross_handoff_chunk source=%u "
              "child=%u\n",
              source_handoff_chunk, child_handoff_chunk);
      fflush(stderr);
      abort();
    }
    source_mf->merge_rtcore_v04_semantic_tag_set(
        snapshot->v04_semantic_memory.tag_set);
    if (child_handoff_chunk < 4u) {
      source_mf->merge_rtcore_v04_handoff_chunk(child_handoff_chunk);
    }
    rtcore_v04_semantic_tag_set_stats_for(
        snapshot->v04_semantic_memory.tag_set)
        .same_cycle_merged_child++;
    if (child_handoff_chunk < 4u) {
      rtcore_v04_semantic_handoff_chunk_stats_for(
          snapshot->v04_semantic_memory.tag_set, child_handoff_chunk)
          .lifecycle.same_cycle_merged_child++;
    }
    if (!pending_it->second.semantic_valid) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_SEMANTIC_ACCOUNTING_FAULT "
              "fault=semantic_child_merged_into_nonsemantic_source\n");
      fflush(stderr);
      abort();
    }
  }
  pending_it->second.waiters.push_back(*snapshot);
  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_accepted_count++;
  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_same_cycle_merge_count++;
  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_same_cycle_merged_waiter_count++;
  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_same_cycle_real_mem_fetch_saved_count++;
  rtcore_v02_lsu_update_sideband_pending_count();
  return true;
}

static void rtcore_register_memory_unit_same_cycle_32b_merge_source(
    const rtcore_replay_cycle_hook_result &result, new_addr_type addr,
    mem_fetch *mf) {
  if (!rtcore_memory_unit_same_cycle_32b_merge_enabled() || mf == NULL) {
    return;
  }
  const rtcore_memory_unit_request_snapshot snapshot =
      rtcore_v02_lsu_sideband_snapshot_from_result(result);
  if (result.lsu_sideband_is_write || snapshot.is_write) {
    return;
  }
  rtcore_memory_unit_refresh_same_cycle_32b_merge_map(result.cycle);
  rtcore_memory_unit_same_cycle_32b_merge_key key = {};
  key.owner_hw_sid = result.lsu_sideband_owner_hw_sid;
  key.cycle = result.cycle;
  key.aligned_32b_addr = static_cast<unsigned long long>(addr);
  key.is_write = result.lsu_sideband_is_write;
  g_rtcore_memory_unit_same_cycle_32b_merge_mf_by_key[key] = mf;
}

enum rtcore_memory_unit_offer_outcome {
  RTCORE_MEMORY_UNIT_OFFER_NONE = 0,
  RTCORE_MEMORY_UNIT_OFFER_L1D_ACCESS_PROGRESS,
  RTCORE_MEMORY_UNIT_OFFER_SHARED_PROGRESS,
  RTCORE_MEMORY_UNIT_OFFER_SAME_CYCLE_MERGED,
  RTCORE_MEMORY_UNIT_OFFER_L1D_ARBITER_BLOCKED,
  RTCORE_MEMORY_UNIT_OFFER_L1D_DATA_PORT_BLOCKED,
  RTCORE_MEMORY_UNIT_OFFER_L1D_RESERVATION_BLOCKED,
  RTCORE_MEMORY_UNIT_OFFER_SHARED_BACKPRESSURE_BLOCKED,
  RTCORE_MEMORY_UNIT_OFFER_REJECTED,
};

static bool rtcore_memory_unit_offer_accepted(
    rtcore_memory_unit_offer_outcome outcome) {
  return outcome == RTCORE_MEMORY_UNIT_OFFER_L1D_ACCESS_PROGRESS ||
         outcome == RTCORE_MEMORY_UNIT_OFFER_SHARED_PROGRESS ||
         outcome == RTCORE_MEMORY_UNIT_OFFER_SAME_CYCLE_MERGED;
}

static bool rtcore_memory_unit_offer_used_l1d_frontend(
    rtcore_memory_unit_offer_outcome outcome) {
  return outcome == RTCORE_MEMORY_UNIT_OFFER_L1D_ACCESS_PROGRESS;
}

struct rtcore_memory_attempt_identity {
  unsigned rt_request_id;
  unsigned request_generation;
  unsigned memory_op_seq;
  unsigned chunk_id;
};

static bool rtcore_v04_memory_attempt_is_bound(
    const rtcore_memory_unit_request_snapshot &snapshot) {
  return snapshot.valid && snapshot.rt_request_id != 0 &&
         snapshot.request_generation != 0 &&
         snapshot.memory_op_seq != 0 && snapshot.lane_id < 32;
}

static rtcore_memory_attempt_identity rtcore_memory_attempt_identity_from(
    const rtcore_memory_unit_request_snapshot &snapshot) {
  rtcore_memory_attempt_identity identity = {};
  identity.rt_request_id = snapshot.rt_request_id;
  identity.request_generation = snapshot.request_generation;
  identity.memory_op_seq = snapshot.memory_op_seq;
  identity.chunk_id = snapshot.chunk_id;
  return identity;
}

static bool rtcore_memory_attempt_identity_matches(
    const rtcore_memory_attempt_identity &identity,
    const rtcore_memory_unit_request_snapshot &snapshot) {
  return identity.rt_request_id == snapshot.rt_request_id &&
         identity.request_generation == snapshot.request_generation &&
         identity.memory_op_seq == snapshot.memory_op_seq &&
         identity.chunk_id == snapshot.chunk_id;
}

static void rtcore_emit_memory_unit_attempt(
    const rtcore_memory_unit_request_snapshot &snapshot,
    unsigned long long service_cycle, unsigned arbitration_slot,
    rtcore::v04::stall_attribution::stage_kind stage,
    rtcore::v04::stall_attribution::outcome_kind outcome,
    rtcore::v04::stall_attribution::action_kind action,
    rtcore::v04::stall_attribution::reason_kind reason) {
  if (!rtcore::v04::stall_attribution::enabled()) return;
  // Compatibility control and shader-continuation sideband requests predate
  // the V0.4 lane-operation identity contract. They remain visible through
  // their existing counters but are outside this attempt-accounting boundary.
  if (!rtcore_v04_memory_attempt_is_bound(snapshot)) {
    return;
  }
  rtcore::v04::stall_attribution::attempt_record_v0 record = {};
  record.service_cycle = service_cycle;
  record.owner_hw_sid = snapshot.owner_hw_sid;
  record.request_identity = snapshot.rt_request_id;
  record.request_generation = snapshot.request_generation;
  record.operation_seq = snapshot.memory_op_seq;
  record.chunk_id = snapshot.chunk_id;
  record.chunk_count = snapshot.chunk_count;
  record.arbitration_slot = static_cast<uint16_t>(
      std::min(arbitration_slot, 0xffffu));
  record.lane_id = static_cast<uint8_t>(snapshot.lane_id);
  record.unit = rtcore::v04::stall_attribution::kUnitMemory;
  record.stage = stage;
  record.outcome = outcome;
  record.action = action;
  record.reason = reason;
  rtcore::v04::stall_attribution::emit_attempt(record);
}

static rtcore_memory_unit_offer_outcome
rtcore_maybe_accept_memory_unit_l1d_client(
    const rtcore_replay_cycle_hook_result &result,
    shader_core_mem_fetch_allocator *mf_allocator,
    const shader_core_config *config, shader_core_ctx *core,
    baseline_cache *l1d_cache, baseline_cache *l0_cache,
    shader_core_stats *stats, unsigned sid) {
  (void)config;
  (void)l0_cache;
  if (!result.lsu_sideband_valid ||
      !rtcore_replay_memory_unit_l1d_client_enabled()) {
    return RTCORE_MEMORY_UNIT_OFFER_NONE;
  }
  const bool supported_rtcore_access_kind =
      result.lsu_sideband_access_kind == RTCORE_V02_LSU_ACCESS_HANDOFF_ACQUIRE ||
      result.lsu_sideband_access_kind == RTCORE_V02_LSU_ACCESS_NODE_FETCH ||
      result.lsu_sideband_access_kind ==
          RTCORE_V02_LSU_ACCESS_PRIMITIVE_FETCH ||
      result.lsu_sideband_access_kind == RTCORE_V02_LSU_ACCESS_STACK_LOAD ||
      result.lsu_sideband_access_kind == RTCORE_V02_LSU_ACCESS_STACK_STORE ||
      result.lsu_sideband_access_kind ==
          RTCORE_V02_LSU_ACCESS_HANDOFF_PUBLICATION_STORE ||
      result.lsu_sideband_access_kind ==
          RTCORE_MEMORY_ACCESS_HANDOFF_PUBLICATION_WRITE ||
      result.lsu_sideband_access_kind ==
          RTCORE_MEMORY_ACCESS_PRIVATE_FRONTIER_INIT ||
      result.lsu_sideband_access_kind ==
          RTCORE_MEMORY_ACCESS_PRIVATE_RUNTIME_WRITE ||
      result.lsu_sideband_access_kind == RTCORE_V02_LSU_ACCESS_RESULT_STORE ||
      result.lsu_sideband_access_kind ==
          RTCORE_MEMORY_ACCESS_TARGET_RAW_READ ||
      result.lsu_sideband_access_kind ==
          RTCORE_MEMORY_ACCESS_PRIVATE_STATE_384_READ ||
      result.lsu_sideband_access_kind ==
          RTCORE_MEMORY_ACCESS_STACK_SPILL_RECOVERY_READ ||
      result.lsu_sideband_access_kind ==
          RTCORE_MEMORY_ACCESS_SHORT_STACK_RETURN_INSTANCE_READ;
  const bool shader_continuation_sbt_access =
      result.lsu_sideband_response_target ==
          RTCORE_V02_LSU_RESPONSE_TARGET_SHADER_CONTINUATION &&
      result.lsu_sideband_access_kind == RTCORE_V02_LSU_ACCESS_SBT_METADATA &&
      !result.lsu_sideband_is_write;
  const bool shader_continuation_handoff_access =
      result.lsu_sideband_response_target ==
          RTCORE_V02_LSU_RESPONSE_TARGET_SHADER_CONTINUATION &&
      result.lsu_sideband_access_kind ==
          RTCORE_V02_LSU_ACCESS_HANDOFF_DISPATCH_READ &&
      !result.lsu_sideband_is_write;
  const bool supported_shader_continuation_access =
      shader_continuation_sbt_access || shader_continuation_handoff_access;
  const bool supported_rtcore_access =
      result.lsu_sideband_response_target ==
          RTCORE_V02_LSU_RESPONSE_TARGET_RTCORE &&
      supported_rtcore_access_kind;
  if (!supported_rtcore_access && !supported_shader_continuation_access) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_rejected_count++;
    return RTCORE_MEMORY_UNIT_OFFER_REJECTED;
  }

  baseline_cache *cache = l1d_cache;
  if (cache == NULL || mf_allocator == NULL || core == NULL || stats == NULL) {
    const rtcore_memory_unit_request_snapshot snapshot =
        rtcore_v02_lsu_sideband_snapshot_from_result(result);
    if (shader_continuation_sbt_access) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_SHADER_CONTINUATION_SBT_METADATA_FAULT "
              "owner_hw_sid=%u warp_id=%u cohort_index=%u generation=%u "
              "fault=missing_l1d_client_fail_closed\n",
              result.lsu_sideband_owner_hw_sid,
              result.lsu_sideband_rt_request_id,
              result.lsu_sideband_lane_id,
              result.lsu_sideband_memory_op_seq);
      fflush(stderr);
      abort();
    }
    if (shader_continuation_handoff_access) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_SHADER_CONTINUATION_HANDOFF_READ_FAULT "
              "owner_hw_sid=%u warp_id=%u lane_id=%u generation=%u "
              "fault=missing_l1d_client_fail_closed\n",
              result.lsu_sideband_owner_hw_sid,
              result.lsu_sideband_rt_request_id,
              result.lsu_sideband_lane_id,
              result.lsu_sideband_memory_op_seq);
      fflush(stderr);
      abort();
    }
    if (rtcore_v04_live_handoff_acquire_request(snapshot) ||
        snapshot.destination ==
            RTCORE_MEMORY_DESTINATION_TARGET_QUEUE_FILL ||
        snapshot.destination ==
            RTCORE_MEMORY_DESTINATION_SHORT_STACK_QUEUE_FILL ||
        snapshot.destination ==
            RTCORE_MEMORY_DESTINATION_PRIVATE_BOUNDARY_FILL ||
        snapshot.destination ==
            RTCORE_MEMORY_DESTINATION_HANDOFF_PUBLICATION_ACK ||
        rtcore_v04_global384_private_init_request(snapshot) ||
        rtcore_v04_global384_private_runtime_write_request(snapshot)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_MEMORY_UNIT_L1D_CLIENT_FAULT "
              "owner_hw_sid=%u request_key=%u lane_id=%u generation=%u "
              "fault=missing_l1d_client_fail_closed\n",
              snapshot.owner_hw_sid, snapshot.rt_request_id,
              snapshot.lane_id, snapshot.request_generation);
      fflush(stderr);
      abort();
    }
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_rejected_count++;
    return RTCORE_MEMORY_UNIT_OFFER_REJECTED;
  }

  const new_addr_type addr = rtcore_memory_unit_effective_addr(result);
  const bool is_write = result.lsu_sideband_is_write;
  rtcore_memory_unit_request_snapshot snapshot =
      rtcore_v02_lsu_sideband_snapshot_from_result(result);
  uint32_t shared_tag_set = 0;
  unsigned shared_chunk = kRtcoreV04InvalidHandoffChunk;
  const bool routes_to_handoff_shared =
      rtcore_v04_handoff_shared_identity_for_snapshot(
          snapshot, &shared_tag_set, &shared_chunk) &&
      rtcore_handoff_storage::routes_chunk_to_shared(
          rtcore_v04_handoff_storage_profile(), shared_tag_set,
          shared_chunk);
  uint32_t private_shared_tag_set = 0;
  unsigned private_shared_chunk = rtcore_private_placement::kChunkCount;
  const bool private_placement_active =
      rtcore_v04_private_placement_profile() !=
      rtcore_private_placement::kProfileGlobal384;
  const bool has_private_shared_identity =
      private_placement_active &&
      rtcore_v04_private_shared_identity_for_snapshot(
          snapshot, &private_shared_tag_set, &private_shared_chunk);
  const bool routes_to_private_shared =
      has_private_shared_identity &&
      rtcore_private_placement::routes_chunk_to_shared(
          rtcore_v04_private_placement_profile(), private_shared_tag_set,
          private_shared_chunk);
  const bool routes_to_shared =
      routes_to_handoff_shared || routes_to_private_shared;
  if (routes_to_handoff_shared && routes_to_private_shared) abort();
  if (!routes_to_shared &&
      rtcore_try_merge_memory_unit_same_cycle_32b(result, addr, &snapshot)) {
    rtcore_record_v04_memory_conservation_or_abort(
        snapshot, false, result.cycle);
    if (shader_continuation_sbt_access) {
      printf("GPGPU-Sim "
             "RTCORE_SHADER_CONTINUATION_SBT_METADATA_L1D_ACCEPT "
             "owner_hw_sid=%u warp_id=%u cohort_index=%u generation=%u "
             "aligned_32b_addr=0x%llx cache_status=SAME_CYCLE_MERGE "
             "accept_cycle=%llu\n",
             result.lsu_sideband_owner_hw_sid,
             result.lsu_sideband_rt_request_id,
             result.lsu_sideband_lane_id,
             result.lsu_sideband_memory_op_seq,
             result.lsu_sideband_aligned_32b_addr, result.cycle);
      fflush(stdout);
    }
    return RTCORE_MEMORY_UNIT_OFFER_SAME_CYCLE_MERGED;
  }

  const bool semantic_accounting =
      rtcore_v04_global384_semantic_accounting_enabled() &&
      snapshot.v04_semantic_memory.valid == 1;
  if (semantic_accounting) {
    rtcore_v04_semantic_record_issue_attempt(snapshot);
  }

  if (routes_to_shared) {
    mem_fetch *mf = mf_allocator->alloc(
        addr, is_write ? GLOBAL_ACC_W : GLOBAL_ACC_R,
        RTCORE_V02_LSU_MEMORY_REQUEST_GRANULE_BYTES, is_write,
        result.cycle);
    mf->set_raytrace();
    if (rtcore_v04_storage_attribution_enabled()) {
      mf->set_rtcore_v04_storage_traffic_class(
          rtcore_v04_storage_traffic_class_for_sideband(snapshot));
    }
    mf->set_rtcore_v04_handoff_shared_backend();
    if (routes_to_handoff_shared) {
      mf->set_rtcore_v04_handoff_chunk(shared_chunk);
    }
    if (semantic_accounting) {
      mf->set_rtcore_v04_semantic_tag_set(
          snapshot.v04_semantic_memory.tag_set);
    }
    mf->set_uncoalesced_addr(addr);
    mf->set_uncoalesced_base_addr(addr);
    rtcore_v04_handoff_shared_payload payload = {};
    payload.mf = mf;
    payload.rt_client = true;
    payload.rt_snapshot_valid = true;
    payload.object = routes_to_handoff_shared
                         ? rtcore_handoff_shared_timing::kObjectHandoff
                         : rtcore_handoff_shared_timing::kObjectPrivate;
    payload.rt_snapshot = snapshot;
    if (!rtcore_v04_enqueue_handoff_shared_request(
            sid, static_cast<rtcore_handoff_shared_timing::object_kind>(
                     payload.object),
            routes_to_handoff_shared ? shared_chunk : private_shared_chunk,
            result.cycle, payload)) {
      if (semantic_accounting) {
        rtcore_v04_semantic_record_frontend_blocked(snapshot);
      }
      const bool requeued =
          rtcore_requeue_v02_lsu_sideband_request_for_retry(result);
      if (!requeued) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_MEMORY_UNIT_REQUEUE_FAULT "
                "owner_hw_sid=%u request_key=%u lane_id=%u generation=%u "
                "fault=shared_placement_ingress_retry_rejected\n",
                snapshot.owner_hw_sid, snapshot.rt_request_id,
                snapshot.lane_id, snapshot.request_generation);
        fflush(stderr);
        abort();
      }
      delete mf;
      return RTCORE_MEMORY_UNIT_OFFER_SHARED_BACKPRESSURE_BLOCKED;
    }
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_accepted_count++;
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_real_mem_fetch_count++;
    stats->rt_mem_requests++;
    return RTCORE_MEMORY_UNIT_OFFER_SHARED_PROGRESS;
  }

  if (!cache->data_port_free()) {
    if (semantic_accounting) {
      rtcore_v04_semantic_record_frontend_blocked(snapshot);
    }
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_rejected_count++;
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_cache_data_port_blocked_count++;
    const bool requeued =
        rtcore_requeue_v02_lsu_sideband_request_for_retry(result);
    if (!requeued) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_MEMORY_UNIT_REQUEUE_FAULT "
              "owner_hw_sid=%u request_key=%u lane_id=%u generation=%u "
              "fault=l1d_data_port_retry_rejected\n",
              snapshot.owner_hw_sid, snapshot.rt_request_id,
              snapshot.lane_id, snapshot.request_generation);
      fflush(stderr);
      abort();
    }
    return RTCORE_MEMORY_UNIT_OFFER_L1D_DATA_PORT_BLOCKED;
  }

  if (!core->consume_rtcore_shared_l1d_request_grant(
          RTCORE_SHARED_L1D_REQUEST_CLIENT_RT)) {
    if (semantic_accounting) {
      rtcore_v04_semantic_record_frontend_blocked(snapshot);
    }
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_rejected_count++;
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_l1d_arbiter_blocked_count++;
    const bool requeued =
        rtcore_requeue_v02_lsu_sideband_request_for_retry(result);
    if (!requeued) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_MEMORY_UNIT_REQUEUE_FAULT "
              "owner_hw_sid=%u request_key=%u lane_id=%u generation=%u "
              "fault=shared_l1d_arbiter_retry_rejected\n",
              snapshot.owner_hw_sid, snapshot.rt_request_id,
              snapshot.lane_id, snapshot.request_generation);
      fflush(stderr);
      abort();
    }
    return RTCORE_MEMORY_UNIT_OFFER_L1D_ARBITER_BLOCKED;
  }

  mem_fetch *mf = mf_allocator->alloc(
      addr, is_write ? GLOBAL_ACC_W : GLOBAL_ACC_R,
      RTCORE_V02_LSU_MEMORY_REQUEST_GRANULE_BYTES, is_write, result.cycle);
  mf->set_raytrace();
  if (rtcore_v04_storage_attribution_enabled()) {
    mf->set_rtcore_v04_storage_traffic_class(
        rtcore_v04_storage_traffic_class_for_sideband(snapshot));
  }
  uint32_t handoff_policy_tag_set = 0;
  unsigned handoff_policy_chunk = kRtcoreV04InvalidHandoffChunk;
  if (rtcore_v04_handoff_cache_policy_identity_for_snapshot(
          snapshot, &handoff_policy_tag_set, &handoff_policy_chunk)) {
    mf->set_rtcore_v04_handoff_cache_policy_eligibility(
        handoff_policy_tag_set, handoff_policy_chunk);
  }
  if (semantic_accounting) {
    const unsigned handoff_chunk =
        rtcore_v04_semantic_handoff_chunk_for_snapshot(snapshot);
    if (handoff_chunk < 4u) {
      mf->set_rtcore_v04_handoff_chunk(handoff_chunk);
    }
    mf->set_rtcore_v04_semantic_tag_set(
        snapshot.v04_semantic_memory.tag_set);
  }
  mf->set_uncoalesced_addr(addr);
  mf->set_uncoalesced_base_addr(addr);

  std::list<cache_event> events;
  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_cache_request_count++;
  stats->rt_mem_requests++;
  const unsigned mshr_entries_before_access = cache->num_mshr_entries();
  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_mshr_observation_count++;
  if (mshr_entries_before_access >
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_sideband_mshr_entries_before_access_max) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_mshr_entries_before_access_max =
        mshr_entries_before_access;
  }
  core->record_rtcore_shared_l1d_cache_access(
      RTCORE_SHARED_L1D_REQUEST_CLIENT_RT);
  if (semantic_accounting) {
    rtcore_v04_semantic_record_cache_lookup(snapshot);
  }
  cache_access_observation cache_observation;
  const enum cache_request_policy_hint cache_policy_hint =
      rtcore_v04_handoff_cache_policy_hint_for(mf);
  const enum cache_request_status status =
      cache->access_with_policy_observation(
          mf->get_addr(), mf, result.cycle, events, &cache_observation,
          cache_policy_hint);
  rtcore_v04_record_handoff_cache_policy_attempt(
      mf, cache_observation, status, events);
  const bool lower_memory_read_sent = was_read_sent(events);
  const bool lower_memory_write_sent = was_write_sent(events);
  const bool lower_memory_writeallocate_sent = was_writeallocate_sent(events);
  const bool lower_memory_any_request_sent =
      lower_memory_read_sent || lower_memory_write_sent ||
      lower_memory_writeallocate_sent;
  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_lower_memory_event_observation_count++;
  if (lower_memory_read_sent) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_lower_memory_read_request_sent_count++;
  }
  if (lower_memory_write_sent) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_lower_memory_write_request_sent_count++;
  }
  if (lower_memory_writeallocate_sent) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_lower_memory_writeallocate_request_sent_count++;
  }
  if (lower_memory_any_request_sent) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_lower_memory_any_request_sent_count++;
  } else {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_lower_memory_no_request_count++;
  }
  const unsigned mshr_entries_after_access = cache->num_mshr_entries();
  if (mshr_entries_after_access >
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_sideband_mshr_entries_after_access_max) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_mshr_entries_after_access_max =
        mshr_entries_after_access;
  }
  rtcore_record_v02_lsu_cache_config_identity(true, cache,
                                              mshr_entries_after_access);
  if (status == RESERVATION_FAIL) {
    if (semantic_accounting) {
      rtcore_v04_semantic_record_cache_retry(
          snapshot, cache_observation.probe_status,
          cache_observation.access_status);
    }
    if (shader_continuation_sbt_access) {
      printf("GPGPU-Sim "
             "RTCORE_SHADER_CONTINUATION_SBT_METADATA_L1D_BACKPRESSURE "
             "owner_hw_sid=%u warp_id=%u cohort_index=%u generation=%u "
             "aligned_32b_addr=0x%llx cache_status=%s "
             "backpressure_cycle=%llu\n",
             result.lsu_sideband_owner_hw_sid,
             result.lsu_sideband_rt_request_id,
             result.lsu_sideband_lane_id,
             result.lsu_sideband_memory_op_seq,
             result.lsu_sideband_aligned_32b_addr,
             cache_request_status_str(status), result.cycle);
      fflush(stdout);
    }
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_rejected_count++;
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_cache_reservation_fail_count++;
    const bool requeued =
        rtcore_requeue_v02_lsu_sideband_request_for_retry(result);
    if (!requeued) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_MEMORY_UNIT_REQUEUE_FAULT "
              "owner_hw_sid=%u request_key=%u lane_id=%u generation=%u "
              "fault=l1d_reservation_retry_rejected\n",
              snapshot.owner_hw_sid, snapshot.rt_request_id,
              snapshot.lane_id, snapshot.request_generation);
      fflush(stderr);
      abort();
    }
    delete mf;
    return RTCORE_MEMORY_UNIT_OFFER_L1D_RESERVATION_BLOCKED;
  }

  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_accepted_count++;
  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_real_mem_fetch_count++;
  if (status == HIT && !is_write) {
    rtcore_memory_unit_read_payload_snapshot read_payload = {};
    if (!rtcore_capture_memory_unit_read_payload(
            core->get_gpu()->get_global_memory(), mf->get_addr(),
            &read_payload)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_MEMORY_UNIT_READ_PAYLOAD_FAULT "
              "owner_hw_sid=%u request_key=%u address=0x%llx "
              "phase=cache_hit_capture\n",
              snapshot.owner_hw_sid, snapshot.rt_request_id,
              static_cast<unsigned long long>(mf->get_addr()));
      fflush(stderr);
      abort();
    }
    rtcore_accept_v04_live_handoff_acquire_or_abort(&snapshot);
    rtcore_accept_v04_dispatch_handoff_read_or_abort(&snapshot);
    if (shader_continuation_sbt_access) {
      printf("GPGPU-Sim "
             "RTCORE_SHADER_CONTINUATION_SBT_METADATA_L1D_ACCEPT "
             "owner_hw_sid=%u warp_id=%u cohort_index=%u generation=%u "
             "aligned_32b_addr=0x%llx cache_status=%s "
             "accept_cycle=%llu\n",
             result.lsu_sideband_owner_hw_sid,
             result.lsu_sideband_rt_request_id,
             result.lsu_sideband_lane_id,
             result.lsu_sideband_memory_op_seq,
             result.lsu_sideband_aligned_32b_addr,
             cache_request_status_str(status), result.cycle);
      fflush(stdout);
    }
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_cache_hit_count++;
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_cache_read_hit_immediate_count++;
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_immediate_completion_count++;
    rtcore_record_v02_lsu_sideband_immediate_completion_kind(
        result.lsu_sideband_access_kind);
    stats->rt_total_cacheline_fetched[sid]++;
    rtcore_v04_pending_memory_transaction immediate = {};
    rtcore_v04_semantic_prepare_physical_transaction(
        &immediate, &snapshot, mf->get_request_uid(), result.cycle,
        cache_observation, lower_memory_read_sent, lower_memory_write_sent,
        lower_memory_writeallocate_sent);
    rtcore_v04_semantic_finalize_physical(
        mf->get_request_uid(), immediate, result.cycle);
    if (immediate.semantic_valid) {
      rtcore_v04_semantic_record_logical_response(snapshot, result.cycle);
    }
    rtcore_record_v04_memory_conservation_or_abort(
        snapshot, false, result.cycle);
    rtcore_record_v02_lsu_sideband_response_completion(
        snapshot, result.cycle, core->get_gpu()->get_global_memory(),
        mf->get_addr(), read_payload.bytes.data(),
        read_payload.bytes.size());
    rtcore_complete_v04_live_handoff_acquire_or_abort(
        snapshot, result.cycle, mf->get_addr(),
        read_payload.bytes.data(), read_payload.bytes.size());
    g_rtcore_v04_semantic_completing_physical.erase(mf->get_request_uid());
    delete mf;
    return RTCORE_MEMORY_UNIT_OFFER_L1D_ACCESS_PROGRESS;
  }
  if (status == HIT && is_write) {
    rtcore_accept_v04_global384_private_init_or_abort(&snapshot,
                                                      result.cycle);
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_cache_hit_count++;
    if (!lower_memory_any_request_sent) {
      if (rtcore_v04_global384_private_init_request(snapshot) ||
          rtcore_v04_global384_private_runtime_write_request(snapshot)) {
        g_rtcore_replay_cycle_hook_consumer_stats
            .v02_lsu_sideband_immediate_completion_count++;
        rtcore_record_v02_lsu_sideband_immediate_completion_kind(
            result.lsu_sideband_access_kind);
        rtcore_v04_pending_memory_transaction immediate = {};
        rtcore_v04_semantic_prepare_physical_transaction(
            &immediate, &snapshot, mf->get_request_uid(), result.cycle,
            cache_observation, lower_memory_read_sent,
            lower_memory_write_sent, lower_memory_writeallocate_sent);
        rtcore_v04_semantic_finalize_physical(
            mf->get_request_uid(), immediate, result.cycle);
        if (immediate.semantic_valid) {
          rtcore_v04_semantic_record_logical_response(snapshot, result.cycle);
        }
        rtcore_record_v04_memory_conservation_or_abort(
            snapshot, false, result.cycle);
        rtcore_record_v02_lsu_sideband_response_completion(
            snapshot, result.cycle, core->get_gpu()->get_global_memory(),
            mf->get_addr(), NULL, 0);
        g_rtcore_v04_semantic_completing_physical.erase(
            mf->get_request_uid());
        delete mf;
        return RTCORE_MEMORY_UNIT_OFFER_L1D_ACCESS_PROGRESS;
      }
    }
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_cache_write_hit_pending_count++;
    rtcore_v04_semantic_prepare_physical_transaction(
        &g_rtcore_v02_lsu_pending_memory_requests[mf->get_request_uid()],
        &snapshot, mf->get_request_uid(), result.cycle, cache_observation,
        lower_memory_read_sent, lower_memory_write_sent,
        lower_memory_writeallocate_sent);
    rtcore_record_v04_memory_conservation_or_abort(
        snapshot, false, result.cycle);
    rtcore_register_memory_unit_same_cycle_32b_merge_source(result, addr, mf);
    rtcore_v02_lsu_update_sideband_pending_count();
    return RTCORE_MEMORY_UNIT_OFFER_L1D_ACCESS_PROGRESS;
  }
  if (status != MISS && status != SECTOR_MISS) {
    if (semantic_accounting) {
      rtcore_v04_semantic_record_cache_retry(
          snapshot, cache_observation.probe_status,
          cache_observation.access_status);
    }
    if (shader_continuation_sbt_access) {
      printf("GPGPU-Sim "
             "RTCORE_SHADER_CONTINUATION_SBT_METADATA_L1D_BACKPRESSURE "
             "owner_hw_sid=%u warp_id=%u cohort_index=%u generation=%u "
             "aligned_32b_addr=0x%llx cache_status=%s "
             "backpressure_cycle=%llu\n",
             result.lsu_sideband_owner_hw_sid,
             result.lsu_sideband_rt_request_id,
             result.lsu_sideband_lane_id,
             result.lsu_sideband_memory_op_seq,
             result.lsu_sideband_aligned_32b_addr,
             cache_request_status_str(status), result.cycle);
      fflush(stdout);
    }
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_rejected_count++;
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_cache_reservation_fail_count++;
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_cache_unexpected_status_reject_count++;
    if (status == HIT_RESERVED) {
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_sideband_cache_hit_reserved_reject_count++;
    }
    const bool requeued =
        rtcore_requeue_v02_lsu_sideband_request_for_retry(result);
    if (!requeued) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_MEMORY_UNIT_REQUEUE_FAULT "
              "owner_hw_sid=%u request_key=%u lane_id=%u generation=%u "
              "fault=l1d_status_retry_rejected cache_status=%s\n",
              snapshot.owner_hw_sid, snapshot.rt_request_id,
              snapshot.lane_id, snapshot.request_generation,
              cache_request_status_str(status));
      fflush(stderr);
      abort();
    }
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_accepted_count--;
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_real_mem_fetch_count--;
    delete mf;
    return RTCORE_MEMORY_UNIT_OFFER_L1D_RESERVATION_BLOCKED;
  }

  rtcore_memory_unit_read_payload_snapshot read_payload = {};
  if (!is_write &&
      !rtcore_capture_memory_unit_read_payload(
          core->get_gpu()->get_global_memory(), mf->get_addr(),
          &read_payload)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_MEMORY_UNIT_READ_PAYLOAD_FAULT "
            "owner_hw_sid=%u request_key=%u address=0x%llx "
            "phase=cache_miss_capture\n",
            snapshot.owner_hw_sid, snapshot.rt_request_id,
            static_cast<unsigned long long>(mf->get_addr()));
    fflush(stderr);
    abort();
  }

  rtcore_accept_v04_live_handoff_acquire_or_abort(&snapshot);
  rtcore_accept_v04_dispatch_handoff_read_or_abort(&snapshot);
  rtcore_accept_v04_global384_private_init_or_abort(&snapshot,
                                                    result.cycle);

  if (shader_continuation_sbt_access) {
    printf("GPGPU-Sim "
           "RTCORE_SHADER_CONTINUATION_SBT_METADATA_L1D_ACCEPT "
           "owner_hw_sid=%u warp_id=%u cohort_index=%u generation=%u "
           "aligned_32b_addr=0x%llx cache_status=%s accept_cycle=%llu\n",
           result.lsu_sideband_owner_hw_sid,
           result.lsu_sideband_rt_request_id, result.lsu_sideband_lane_id,
           result.lsu_sideband_memory_op_seq,
           result.lsu_sideband_aligned_32b_addr,
           cache_request_status_str(status), result.cycle);
    fflush(stdout);
  }

  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_cache_miss_count++;
  if (status == MISS) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_cache_line_miss_count++;
  } else if (status == SECTOR_MISS) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_cache_sector_miss_count++;
  }
  rtcore_v04_semantic_prepare_physical_transaction(
      &g_rtcore_v02_lsu_pending_memory_requests[mf->get_request_uid()],
      &snapshot, mf->get_request_uid(), result.cycle, cache_observation,
      lower_memory_read_sent, lower_memory_write_sent,
      lower_memory_writeallocate_sent);
  if (!is_write) {
    g_rtcore_v02_lsu_read_payload_by_mem_fetch_uid[mf->get_request_uid()] =
        read_payload;
  }
  rtcore_record_v04_memory_conservation_or_abort(
      snapshot, false, result.cycle);
  rtcore_register_memory_unit_same_cycle_32b_merge_source(result, addr, mf);
  rtcore_v02_lsu_update_sideband_pending_count();
  return RTCORE_MEMORY_UNIT_OFFER_L1D_ACCESS_PROGRESS;
}

static rtcore_replay_cycle_hook_result
rtcore_make_result_with_v02_lsu_sideband_snapshot(
    const rtcore_replay_cycle_hook_result &base,
    const rtcore_memory_unit_request_snapshot &snapshot) {
  rtcore_replay_cycle_hook_result result = base;
  result.lsu_sideband_valid = snapshot.valid;
  result.lsu_sideband_response_target = snapshot.response_target;
  result.lsu_sideband_owner_hw_sid = snapshot.owner_hw_sid;
  result.lsu_sideband_rt_request_id = snapshot.rt_request_id;
  result.lsu_sideband_lane_id = snapshot.lane_id;
  result.lsu_sideband_memory_op_seq = snapshot.memory_op_seq;
  result.lsu_sideband_chunk_id = snapshot.chunk_id;
  result.lsu_sideband_chunk_count = snapshot.chunk_count;
  result.lsu_sideband_access_kind = snapshot.access_kind;
  result.lsu_sideband_aligned_32b_addr = snapshot.aligned_32b_addr;
  result.lsu_sideband_is_write = snapshot.is_write;
  result.lsu_sideband_issue_cycle = snapshot.issue_cycle;
  result.memory_unit_snapshot = snapshot;
  return result;
}

static rtcore_memory_unit_offer_outcome
rtcore_consume_memory_unit_request_offer_from_rt_unit(
    const rtcore_replay_cycle_hook_result &result,
    shader_core_mem_fetch_allocator *mf_allocator,
    const shader_core_config *config, shader_core_ctx *core,
    baseline_cache *l1d_cache, baseline_cache *l0_cache,
    shader_core_stats *stats, unsigned sid) {
  if (!result.lsu_sideband_valid) {
    return RTCORE_MEMORY_UNIT_OFFER_NONE;
  }
  if (result.memory_unit_snapshot.address_space ==
      RTCORE_MEMORY_ADDRESS_SPACE_SHARED) {
    const bool private_shared_write =
        result.memory_unit_snapshot.operation ==
            RTCORE_MEMORY_OPERATION_WRITE &&
        result.memory_unit_snapshot.destination ==
            RTCORE_MEMORY_DESTINATION_PRIVATE_COMMIT_ACK &&
        (result.memory_unit_snapshot.access_kind ==
             RTCORE_MEMORY_ACCESS_PRIVATE_FRONTIER_INIT ||
         result.memory_unit_snapshot.access_kind ==
             RTCORE_MEMORY_ACCESS_PRIVATE_RUNTIME_WRITE);
    const bool target_private_read =
        result.memory_unit_snapshot.operation ==
            RTCORE_MEMORY_OPERATION_READ &&
        result.memory_unit_snapshot.destination ==
            RTCORE_MEMORY_DESTINATION_TARGET_QUEUE_FILL &&
        result.memory_unit_snapshot.access_kind ==
            RTCORE_MEMORY_ACCESS_TARGET_PRIVATE_READ;
    const bool target_private_state_384_read =
        result.memory_unit_snapshot.operation ==
            RTCORE_MEMORY_OPERATION_READ &&
        result.memory_unit_snapshot.destination ==
            RTCORE_MEMORY_DESTINATION_TARGET_QUEUE_FILL &&
        result.memory_unit_snapshot.access_kind ==
            RTCORE_MEMORY_ACCESS_PRIVATE_STATE_384_READ;
    const bool stack_private_read =
        result.memory_unit_snapshot.operation ==
            RTCORE_MEMORY_OPERATION_READ &&
        result.memory_unit_snapshot.destination ==
            RTCORE_MEMORY_DESTINATION_STACK_QUEUE_FILL &&
        result.memory_unit_snapshot.access_kind ==
            RTCORE_MEMORY_ACCESS_STACK_PRIVATE_READ;
    const bool short_stack_private_read =
        result.memory_unit_snapshot.operation ==
            RTCORE_MEMORY_OPERATION_READ &&
        result.memory_unit_snapshot.destination ==
            RTCORE_MEMORY_DESTINATION_SHORT_STACK_QUEUE_FILL &&
        result.memory_unit_snapshot.access_kind ==
            RTCORE_MEMORY_ACCESS_SHORT_STACK_STATE_READ;
    const bool short_stack_private_state_384_read =
        result.memory_unit_snapshot.operation ==
            RTCORE_MEMORY_OPERATION_READ &&
        result.memory_unit_snapshot.destination ==
            RTCORE_MEMORY_DESTINATION_SHORT_STACK_QUEUE_FILL &&
        result.memory_unit_snapshot.access_kind ==
            RTCORE_MEMORY_ACCESS_PRIVATE_STATE_384_READ;
    const bool private_boundary_state_384_read =
        result.memory_unit_snapshot.operation ==
            RTCORE_MEMORY_OPERATION_READ &&
        result.memory_unit_snapshot.destination ==
            RTCORE_MEMORY_DESTINATION_PRIVATE_BOUNDARY_FILL &&
        result.memory_unit_snapshot.access_kind ==
            RTCORE_MEMORY_ACCESS_PRIVATE_STATE_384_READ;
    const bool stack_spill_recovery_read =
        result.memory_unit_snapshot.operation ==
            RTCORE_MEMORY_OPERATION_READ &&
        result.memory_unit_snapshot.destination ==
            RTCORE_MEMORY_DESTINATION_TARGET_QUEUE_FILL &&
        result.memory_unit_snapshot.access_kind ==
            RTCORE_MEMORY_ACCESS_STACK_SPILL_RECOVERY_READ;
    const bool handoff_ray_policy_read =
        result.memory_unit_snapshot.operation ==
            RTCORE_MEMORY_OPERATION_READ &&
        result.memory_unit_snapshot.destination ==
            RTCORE_MEMORY_DESTINATION_TARGET_QUEUE_FILL &&
        result.memory_unit_snapshot.access_kind ==
            RTCORE_MEMORY_ACCESS_HANDOFF_RAY_POLICY_READ;
    const bool accepted =
        private_shared_write
            ? rtcore_accept_v04_private_shared_request(
                  &result.memory_unit_snapshot, result.cycle)
            : (target_private_state_384_read &&
               rtcore_accept_v04_target_private_state_384_read(
                   &result.memory_unit_snapshot, result.cycle)) ||
                  (target_private_read &&
               rtcore_accept_v04_target_private_shared_read(
                   &result.memory_unit_snapshot, result.cycle)) ||
                  (stack_private_read &&
                   rtcore_accept_v04_stack_private_shared_read(
                       &result.memory_unit_snapshot, result.cycle)) ||
                  (short_stack_private_read &&
                   rtcore_accept_v04_short_stack_private_shared_read(
                       &result.memory_unit_snapshot, result.cycle)) ||
                  (short_stack_private_state_384_read &&
                   rtcore_accept_v04_short_stack_private_shared_read(
                       &result.memory_unit_snapshot, result.cycle)) ||
                  (private_boundary_state_384_read &&
                   rtcore_accept_v04_private_boundary_state_384_read(
                       &result.memory_unit_snapshot, result.cycle)) ||
                  (stack_spill_recovery_read &&
                   rtcore_accept_v04_stack_spill_recovery_shared_read(
                       &result.memory_unit_snapshot, result.cycle)) ||
                  (handoff_ray_policy_read &&
                   rtcore_accept_v04_handoff_ray_policy_shared_read(
                       &result.memory_unit_snapshot, result.cycle));
    if (!accepted) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_PRIVATE_SHARED_ACCEPT_FAULT "
              "owner_hw_sid=%u request_key=0x%08x generation=%u "
              "chunk_id=%u chunk_count=%u service_cycle=%llu\n",
              result.memory_unit_snapshot.owner_hw_sid,
              result.memory_unit_snapshot.rt_request_id,
              result.memory_unit_snapshot.request_generation,
              result.memory_unit_snapshot.chunk_id,
              result.memory_unit_snapshot.chunk_count, result.cycle);
      fflush(stderr);
      abort();
    }
    rtcore_record_v04_memory_conservation_or_abort(
        result.memory_unit_snapshot, false, result.cycle);
    rtcore_record_v04_memory_conservation_or_abort(
        result.memory_unit_snapshot, true, result.cycle);
    return RTCORE_MEMORY_UNIT_OFFER_SHARED_PROGRESS;
  }
  g_rtcore_replay_cycle_hook_consumer_stats
      .memory_unit_request_offered_count++;
  if (result.lsu_sideband_is_write) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_write_offer_count++;
  } else {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_read_offer_count++;
  }
  if (result.lsu_sideband_access_kind ==
      RTCORE_V02_LSU_ACCESS_HANDOFF_ACQUIRE) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_handoff_acquire_offer_count++;
  } else if (
      result.lsu_sideband_access_kind ==
          RTCORE_V02_LSU_ACCESS_HANDOFF_PUBLICATION_STORE ||
      result.lsu_sideband_access_kind ==
          RTCORE_MEMORY_ACCESS_HANDOFF_PUBLICATION_WRITE) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_handoff_publication_store_offer_count++;
  } else if (result.lsu_sideband_access_kind ==
             RTCORE_V02_LSU_ACCESS_NODE_FETCH) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_node_offer_count++;
  } else if (result.lsu_sideband_access_kind ==
             RTCORE_V02_LSU_ACCESS_PRIMITIVE_FETCH) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_primitive_offer_count++;
  } else if (result.lsu_sideband_access_kind ==
             RTCORE_V02_LSU_ACCESS_STACK_LOAD) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_stack_load_offer_count++;
  } else if (result.lsu_sideband_access_kind ==
             RTCORE_V02_LSU_ACCESS_STACK_STORE) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_stack_store_offer_count++;
  } else if (result.lsu_sideband_access_kind ==
             RTCORE_V02_LSU_ACCESS_RESULT_STORE) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_result_store_offer_count++;
  }
  if (result.lsu_sideband_response_target ==
      RTCORE_V02_LSU_RESPONSE_TARGET_RTCORE) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_response_target_rtcore_count++;
  } else if (result.lsu_sideband_response_target ==
             RTCORE_V02_LSU_RESPONSE_TARGET_SHADER_CONTINUATION) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_response_target_shader_continuation_count++;
  }
  if (result.lsu_sideband_chunk_count >
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_sideband_max_chunk_count) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_max_chunk_count =
        result.lsu_sideband_chunk_count;
  }
  const rtcore_memory_unit_offer_outcome outcome =
      rtcore_maybe_accept_memory_unit_l1d_client(
      result, mf_allocator, config, core, l1d_cache, l0_cache, stats, sid);
  rtcore_maybe_log_memory_unit_request_offer_stats(result.owner_hw_sid);
  return outcome;
}

static bool rtcore_maybe_consume_v02_lsu_sideband_memory_response(
    mem_fetch *mf, const shader_core_config *config, shader_core_ctx *core,
    baseline_cache *l1d_cache, baseline_cache *l0_cache) {
  (void)config;
  (void)l0_cache;
  if (!rtcore_replay_memory_unit_l1d_client_enabled() || mf == NULL) {
    return false;
  }
  std::map<unsigned, rtcore_v04_pending_memory_transaction>::iterator it =
      g_rtcore_v02_lsu_pending_memory_requests.find(mf->get_request_uid());
  if (it == g_rtcore_v02_lsu_pending_memory_requests.end()) {
    return false;
  }
  if (it->second.waiters.empty()) {
    g_rtcore_v02_lsu_read_payload_by_mem_fetch_uid.erase(
        mf->get_request_uid());
    g_rtcore_v02_lsu_pending_memory_requests.erase(it);
    rtcore_v02_lsu_update_sideband_pending_count();
    return true;
  }

  const unsigned long long current_cycle =
      core->get_gpu()->gpu_sim_cycle + core->get_gpu()->gpu_tot_sim_cycle;
  unsigned owner_hw_sid = it->second.waiters.front().owner_hw_sid;
  const bool shared_backend = it->second.shared_backend;
  const new_addr_type response_addr = mf->get_addr();
  mf->set_status(IN_SHADER_FETCHED, current_cycle);
  baseline_cache *cache = l1d_cache;
  std::list<mem_fetch *> ready_sideband_responses;
  if (it->second.waiters.front().is_write) {
    unsigned completed_count =
        rtcore_complete_v02_lsu_sideband_pending_response(
            mf, current_cycle, &owner_hw_sid,
            core->get_gpu()->get_global_memory());
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_response_wakeup_count += completed_count;
    rtcore_v02_lsu_update_sideband_pending_count();
    rtcore_maybe_log_memory_unit_request_offer_stats(owner_hw_sid);
    delete mf;
    return true;
  }
  if (cache != NULL && !shared_backend) {
    cache->fill(mf, current_cycle);
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_mshr_response_probe_count++;
    const unsigned response_probe_mshr_entries = cache->num_mshr_entries();
    if (response_probe_mshr_entries >
        g_rtcore_replay_cycle_hook_consumer_stats
            .v02_lsu_sideband_mshr_entries_at_response_probe_max) {
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_sideband_mshr_entries_at_response_probe_max =
          response_probe_mshr_entries;
    }
    rtcore_record_v02_lsu_cache_config_identity(true, cache,
                                                response_probe_mshr_entries);
    ready_sideband_responses = cache->probe_mshr(response_addr);
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_mshr_response_probe_mem_fetch_count +=
        ready_sideband_responses.size();
  }

  unsigned completed_count = 0;
  for (std::list<mem_fetch *>::iterator response_it =
           ready_sideband_responses.begin();
       response_it != ready_sideband_responses.end(); ++response_it) {
    completed_count += rtcore_complete_v02_lsu_sideband_pending_response(
        *response_it, current_cycle, &owner_hw_sid,
        core->get_gpu()->get_global_memory());
  }
  if (completed_count == 0) {
    completed_count += rtcore_complete_v02_lsu_sideband_pending_response(
        mf, current_cycle, &owner_hw_sid,
        core->get_gpu()->get_global_memory());
  }
  g_rtcore_replay_cycle_hook_consumer_stats
      .v02_lsu_sideband_response_wakeup_count += completed_count;
  rtcore_v02_lsu_update_sideband_pending_count();
  rtcore_maybe_log_memory_unit_request_offer_stats(owner_hw_sid);
  if (shared_backend) delete mf;
  return true;
}

static rtcore_replay_cycle_hook_result
rtcore_maybe_service_replay_cycle_from_rt_unit(
    unsigned owner_hw_sid, unsigned long long current_cycle) {
  rtcore_replay_cycle_hook_result result = {};
  result.owner_hw_sid = owner_hw_sid;
  result.cycle = current_cycle;
  if (!rtcore_replay_cycle_hook_enabled()) {
    return result;
  }

  bool service_enabled = false;
  bool memory_progressed = false;
  bool ready_progressed = false;
  rtcore_replay_service_cycle_identity_snapshot identity_snapshot = {};
  rtcore_memory_unit_request_snapshot sideband_snapshot = {};
  bool progressed =
      rtcore_service_replay_cycle_for_sm_with_identity_and_memory_unit(
          owner_hw_sid, current_cycle, &service_enabled, &memory_progressed,
          &ready_progressed, &identity_snapshot, &sideband_snapshot);
  result.hook_enabled = true;
  result.service_enabled = service_enabled;
  result.memory_progressed = memory_progressed;
  result.ready_progressed = ready_progressed;
  result.progressed = progressed;
  result.identity_valid = identity_snapshot.valid;
  result.identity_memory_progressed = identity_snapshot.memory_progressed;
  result.identity_ready_progressed = identity_snapshot.ready_progressed;
  result.identity_owner_hw_sid = identity_snapshot.owner_hw_sid;
  result.identity_thread_uid = identity_snapshot.thread_uid;
  result.identity_lane_id = identity_snapshot.lane_id;
  result.identity_has_warp_metadata = identity_snapshot.has_warp_metadata;
  result.identity_warp_uid = identity_snapshot.warp_uid;
  result.identity_warp_id = identity_snapshot.warp_id;
  result.identity_active_mask = identity_snapshot.active_mask;
  result.identity_static_inst_uid = identity_snapshot.static_inst_uid;
  result.lsu_sideband_valid = sideband_snapshot.valid;
  result.lsu_sideband_response_target = sideband_snapshot.response_target;
  result.lsu_sideband_owner_hw_sid = sideband_snapshot.owner_hw_sid;
  result.lsu_sideband_rt_request_id = sideband_snapshot.rt_request_id;
  result.lsu_sideband_lane_id = sideband_snapshot.lane_id;
  result.lsu_sideband_memory_op_seq = sideband_snapshot.memory_op_seq;
  result.lsu_sideband_chunk_id = sideband_snapshot.chunk_id;
  result.lsu_sideband_chunk_count = sideband_snapshot.chunk_count;
  result.lsu_sideband_access_kind = sideband_snapshot.access_kind;
  result.lsu_sideband_aligned_32b_addr =
      sideband_snapshot.aligned_32b_addr;
  result.lsu_sideband_is_write = sideband_snapshot.is_write;
  result.lsu_sideband_issue_cycle = sideband_snapshot.issue_cycle;
  result.memory_unit_snapshot = sideband_snapshot;
  rtcore_record_replay_cycle_hook_smoke(owner_hw_sid, current_cycle,
                                        service_enabled, memory_progressed,
                                        ready_progressed, progressed,
                                        identity_snapshot);
  return result;
}

static void rtcore_consume_replay_cycle_hook_result_from_rt_unit(
    const rtcore_replay_cycle_hook_result &result,
    shader_core_mem_fetch_allocator *mf_allocator,
    const shader_core_config *config, shader_core_ctx *core,
    baseline_cache *l1d_cache, baseline_cache *l0_cache,
    shader_core_stats *stats, unsigned sid) {
  if (!result.hook_enabled) {
    return;
  }
  g_rtcore_replay_cycle_hook_consumer_stats.consumed_calls++;
  g_rtcore_replay_cycle_hook_consumer_stats.last_owner_hw_sid =
      result.owner_hw_sid;
  g_rtcore_replay_cycle_hook_consumer_stats.last_cycle = result.cycle;
  g_rtcore_replay_cycle_hook_consumer_stats.hook_enabled_results++;
  if (result.service_enabled) {
    g_rtcore_replay_cycle_hook_consumer_stats.service_enabled_results++;
  }
  if (result.progressed) {
    g_rtcore_replay_cycle_hook_consumer_stats.progressed_results++;
  }
  if (result.memory_progressed) {
    g_rtcore_replay_cycle_hook_consumer_stats.memory_progressed_results++;
  }
  if (result.ready_progressed) {
    g_rtcore_replay_cycle_hook_consumer_stats.ready_progressed_results++;
  }
  const bool issue_bandwidth_gate_enabled =
      rtcore_memory_unit_issue_bandwidth_gate_enabled();
  const bool shared_frontend_gate_enabled =
      rtcore_shared_lsu_frontend_arbiter_gate_enabled() &&
      !rtcore_explicit_shared_l1d_request_arbiter_gate_enabled();
  const unsigned issue_budget_per_cycle =
      rtcore_memory_unit_issue_budget_per_cycle();
  const unsigned shared_frontend_budget_per_cycle =
      rtcore_shared_lsu_frontend_budget_per_cycle();
  unsigned sideband_issued_this_cycle = 0;
  unsigned rt_memory_issued_this_cycle = 0;
  unsigned memory_offer_attempt_count = 0;
  bool l1d_data_port_blocked_this_cycle = false;
  std::vector<rtcore_memory_attempt_identity>
      frontend_accepted_attempts;
  const auto account_memory_offer =
      [&](rtcore_memory_unit_offer_outcome outcome,
          const rtcore_memory_unit_request_snapshot &snapshot) {
        if (outcome == RTCORE_MEMORY_UNIT_OFFER_NONE) return;
        const unsigned arbitration_slot = memory_offer_attempt_count++;
        if (outcome == RTCORE_MEMORY_UNIT_OFFER_L1D_ARBITER_BLOCKED) {
          rtcore_emit_memory_unit_attempt(
              snapshot, result.cycle, arbitration_slot,
              rtcore::v04::stall_attribution::kStageFrontend,
              rtcore::v04::stall_attribution::kOutcomeStall,
              rtcore::v04::stall_attribution::kActionNone,
              rtcore::v04::stall_attribution::kReasonL1dRequestArbiter);
          return;
        }
        rtcore_emit_memory_unit_attempt(
            snapshot, result.cycle, arbitration_slot,
            rtcore::v04::stall_attribution::kStageFrontend,
            rtcore::v04::stall_attribution::kOutcomeProgress,
            rtcore::v04::stall_attribution::kActionFrontendAccept,
            rtcore::v04::stall_attribution::kReasonNone);
        if (rtcore::v04::stall_attribution::enabled() &&
            rtcore_v04_memory_attempt_is_bound(snapshot)) {
          frontend_accepted_attempts.push_back(
              rtcore_memory_attempt_identity_from(snapshot));
        }
        if (rtcore_memory_unit_offer_accepted(outcome)) {
          rtcore_emit_memory_unit_attempt(
              snapshot, result.cycle, arbitration_slot,
              rtcore::v04::stall_attribution::kStageBackend,
              rtcore::v04::stall_attribution::kOutcomeProgress,
              rtcore::v04::stall_attribution::kActionMemoryAccept,
              rtcore::v04::stall_attribution::kReasonNone);
          rt_memory_issued_this_cycle++;
          if (rtcore_memory_unit_offer_used_l1d_frontend(outcome)) {
            sideband_issued_this_cycle++;
            if (shared_frontend_gate_enabled) {
              g_rtcore_replay_cycle_hook_consumer_stats
                  .v02_lsu_shared_frontend_rt_used_count++;
              if (g_rtcore_v02_lsu_shared_frontend_blocked_by_owner
                      [result.owner_hw_sid]) {
                g_rtcore_replay_cycle_hook_consumer_stats
                    .v02_lsu_shared_frontend_rt_blocked_then_progressed_count++;
                g_rtcore_v02_lsu_shared_frontend_blocked_by_owner
                    [result.owner_hw_sid] = false;
              }
            }
          }
        } else if (
            outcome ==
            RTCORE_MEMORY_UNIT_OFFER_L1D_RESERVATION_BLOCKED) {
          rtcore_emit_memory_unit_attempt(
              snapshot, result.cycle, arbitration_slot,
              rtcore::v04::stall_attribution::kStageBackend,
              rtcore::v04::stall_attribution::kOutcomeStall,
              rtcore::v04::stall_attribution::kActionNone,
              rtcore::v04::stall_attribution::kReasonL1dReservation);
        } else if (
            outcome == RTCORE_MEMORY_UNIT_OFFER_L1D_DATA_PORT_BLOCKED) {
          l1d_data_port_blocked_this_cycle = true;
          rtcore_emit_memory_unit_attempt(
              snapshot, result.cycle, arbitration_slot,
              rtcore::v04::stall_attribution::kStageBackend,
              rtcore::v04::stall_attribution::kOutcomeStall,
              rtcore::v04::stall_attribution::kActionNone,
              rtcore::v04::stall_attribution::kReasonL1dDataPort);
        } else if (
            outcome ==
            RTCORE_MEMORY_UNIT_OFFER_SHARED_BACKPRESSURE_BLOCKED) {
          rtcore_emit_memory_unit_attempt(
              snapshot, result.cycle, arbitration_slot,
              rtcore::v04::stall_attribution::kStageBackend,
              rtcore::v04::stall_attribution::kOutcomeStall,
              rtcore::v04::stall_attribution::kActionNone,
              rtcore::v04::stall_attribution::kReasonQueueCapacity);
        } else {
          rtcore_emit_memory_unit_attempt(
              snapshot, result.cycle, arbitration_slot,
              rtcore::v04::stall_attribution::kStageBackend,
              rtcore::v04::stall_attribution::kOutcomeInvalid,
              rtcore::v04::stall_attribution::kActionNone,
              rtcore::v04::stall_attribution::kReasonInvalidOffer);
        }
      };
  if (issue_bandwidth_gate_enabled) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_issue_bandwidth_evaluations++;
  }
  unsigned shared_frontend_normal_lsu_used = 0;
  const bool shared_frontend_normal_lsu_observation_enabled =
      rtcore_shared_lsu_frontend_normal_lsu_observation_gate_enabled();
  unsigned shared_frontend_normal_lsu_observed_dispatch_busy = 0;
  unsigned shared_frontend_normal_lsu_observed_response_fifo_occupancy = 0;
  unsigned shared_frontend_normal_lsu_observed_dispatch_pressure = 0;
  unsigned shared_frontend_normal_lsu_observed_response_fifo_pressure = 0;
  unsigned shared_frontend_normal_lsu_observed_stall = 0;
  unsigned shared_frontend_normal_lsu_observed_stall_bank_conflict = 0;
  unsigned shared_frontend_normal_lsu_observed_stall_mshr = 0;
  unsigned shared_frontend_normal_lsu_observed_stall_icnt = 0;
  unsigned shared_frontend_normal_lsu_observed_stall_coal = 0;
  unsigned shared_frontend_normal_lsu_observed_stall_tlb = 0;
  unsigned shared_frontend_normal_lsu_observed_stall_data_port = 0;
  unsigned shared_frontend_normal_lsu_observed_stall_wb_icnt = 0;
  unsigned shared_frontend_normal_lsu_observed_stall_wb_cache_reservation = 0;
  if (shared_frontend_gate_enabled) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_shared_frontend_evaluations++;
    if (shared_frontend_normal_lsu_observation_enabled) {
      const rtcore_v02_lsu_shared_frontend_normal_lsu_observation observation =
          rtcore_get_v02_lsu_shared_frontend_normal_lsu_observation(
              result.owner_hw_sid);
      shared_frontend_normal_lsu_used = observation.pressure;
      shared_frontend_normal_lsu_observed_dispatch_busy =
          observation.dispatch_busy;
      shared_frontend_normal_lsu_observed_response_fifo_occupancy =
          observation.response_fifo_occupancy;
      shared_frontend_normal_lsu_observed_dispatch_pressure =
          observation.dispatch_pressure;
      shared_frontend_normal_lsu_observed_response_fifo_pressure =
          observation.response_fifo_pressure;
      if (observation.stall_active) {
        shared_frontend_normal_lsu_observed_stall = 1;
        switch (static_cast<enum mem_stage_stall_type>(
            observation.stall_reason)) {
          case BK_CONF:
            shared_frontend_normal_lsu_observed_stall_bank_conflict = 1;
            break;
          case MSHR_RC_FAIL:
            shared_frontend_normal_lsu_observed_stall_mshr = 1;
            break;
          case ICNT_RC_FAIL:
            shared_frontend_normal_lsu_observed_stall_icnt = 1;
            break;
          case COAL_STALL:
            shared_frontend_normal_lsu_observed_stall_coal = 1;
            break;
          case TLB_STALL:
            shared_frontend_normal_lsu_observed_stall_tlb = 1;
            break;
          case DATA_PORT_STALL:
            shared_frontend_normal_lsu_observed_stall_data_port = 1;
            break;
          case WB_ICNT_RC_FAIL:
            shared_frontend_normal_lsu_observed_stall_wb_icnt = 1;
            break;
          case WB_CACHE_RSRV_FAIL:
            shared_frontend_normal_lsu_observed_stall_wb_cache_reservation = 1;
            break;
          default:
            shared_frontend_normal_lsu_observed_stall = 0;
            break;
        }
      }
    } else {
      shared_frontend_normal_lsu_used =
          rtcore_shared_lsu_frontend_normal_lsu_proxy_per_cycle();
    }
    if (shared_frontend_normal_lsu_used > shared_frontend_budget_per_cycle) {
      shared_frontend_normal_lsu_used = shared_frontend_budget_per_cycle;
    }
    if (shared_frontend_normal_lsu_observation_enabled) {
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_shared_frontend_normal_lsu_observed_count +=
          shared_frontend_normal_lsu_used;
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_shared_frontend_normal_lsu_observed_dispatch_busy_count +=
          shared_frontend_normal_lsu_observed_dispatch_busy;
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_shared_frontend_normal_lsu_dispatch_pressure_count +=
          shared_frontend_normal_lsu_observed_dispatch_pressure;
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_shared_frontend_normal_lsu_response_fifo_pressure_count +=
          shared_frontend_normal_lsu_observed_response_fifo_pressure;
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_shared_frontend_normal_lsu_stall_count +=
          shared_frontend_normal_lsu_observed_stall;
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_shared_frontend_normal_lsu_stall_bank_conflict_count +=
          shared_frontend_normal_lsu_observed_stall_bank_conflict;
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_shared_frontend_normal_lsu_stall_mshr_count +=
          shared_frontend_normal_lsu_observed_stall_mshr;
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_shared_frontend_normal_lsu_stall_icnt_count +=
          shared_frontend_normal_lsu_observed_stall_icnt;
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_shared_frontend_normal_lsu_stall_coal_count +=
          shared_frontend_normal_lsu_observed_stall_coal;
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_shared_frontend_normal_lsu_stall_tlb_count +=
          shared_frontend_normal_lsu_observed_stall_tlb;
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_shared_frontend_normal_lsu_stall_data_port_count +=
          shared_frontend_normal_lsu_observed_stall_data_port;
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_shared_frontend_normal_lsu_stall_wb_icnt_count +=
          shared_frontend_normal_lsu_observed_stall_wb_icnt;
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_shared_frontend_normal_lsu_stall_wb_cache_reservation_count +=
          shared_frontend_normal_lsu_observed_stall_wb_cache_reservation;
      if (shared_frontend_normal_lsu_observed_response_fifo_occupancy >
          g_rtcore_replay_cycle_hook_consumer_stats
              .v02_lsu_shared_frontend_normal_lsu_observed_response_fifo_occupancy_max) {
        g_rtcore_replay_cycle_hook_consumer_stats
            .v02_lsu_shared_frontend_normal_lsu_observed_response_fifo_occupancy_max =
            shared_frontend_normal_lsu_observed_response_fifo_occupancy;
      }
    }
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_shared_frontend_normal_lsu_used_count +=
        shared_frontend_normal_lsu_used;
  }
  const unsigned queued_sideband_count_before_direct =
      rtcore_count_memory_unit_requests_for_sm(result.owner_hw_sid);
  unsigned sideband_scan_limit = queued_sideband_count_before_direct;
  bool direct_sideband_requeued = false;
  const bool direct_shared_request =
      result.lsu_sideband_valid &&
      result.memory_unit_snapshot.address_space ==
          RTCORE_MEMORY_ADDRESS_SPACE_SHARED;
  if (shared_frontend_gate_enabled && result.lsu_sideband_valid &&
      !direct_shared_request) {
    const rtcore_memory_unit_request_snapshot direct_snapshot =
        rtcore_v02_lsu_sideband_snapshot_from_result(result);
    direct_sideband_requeued =
        rtcore_push_front_memory_unit_request_for_sm(
            result.owner_hw_sid, &direct_snapshot);
    if (direct_sideband_requeued) {
      sideband_scan_limit++;
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_shared_frontend_direct_requeued_count++;
    }
  }
  if (!direct_sideband_requeued) {
    const rtcore_memory_unit_request_snapshot direct_snapshot =
        rtcore_v02_lsu_sideband_snapshot_from_result(result);
    const rtcore_memory_unit_offer_outcome direct_outcome =
        rtcore_consume_memory_unit_request_offer_from_rt_unit(
            result, mf_allocator, config, core, l1d_cache, l0_cache, stats,
            sid);
    account_memory_offer(direct_outcome, direct_snapshot);
  }
  unsigned max_sideband_drain_per_cycle =
      (rtcore_memory_unit_response_wait_enabled() &&
       !shared_frontend_gate_enabled)
          ? 0u
          : 4096u;
  if (issue_bandwidth_gate_enabled) {
    if (rt_memory_issued_this_cycle >= issue_budget_per_cycle) {
      max_sideband_drain_per_cycle = 0;
    } else if (!rtcore_memory_unit_response_wait_enabled() ||
               shared_frontend_gate_enabled) {
      max_sideband_drain_per_cycle =
          issue_budget_per_cycle - rt_memory_issued_this_cycle;
    }
  }
  if (l1d_data_port_blocked_this_cycle) {
    max_sideband_drain_per_cycle = 0;
  }
  unsigned queued_sideband_count_before_drain = 0;
  if (shared_frontend_gate_enabled) {
    queued_sideband_count_before_drain =
        rtcore_count_memory_unit_requests_for_sm(result.owner_hw_sid);
    if (queued_sideband_count_before_drain >
        g_rtcore_replay_cycle_hook_consumer_stats
            .v02_lsu_shared_frontend_max_rt_queue_occupancy) {
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_shared_frontend_max_rt_queue_occupancy =
          queued_sideband_count_before_drain;
    }
    unsigned shared_frontend_rt_budget = 0;
    const unsigned shared_frontend_used_before_queue =
        sideband_issued_this_cycle +
        (rtcore_shared_lsu_frontend_policy_rt_first()
             ? 0u
             : shared_frontend_normal_lsu_used);
    unsigned shared_frontend_rt_first_budget = 0;
    if (sideband_issued_this_cycle < shared_frontend_budget_per_cycle) {
      shared_frontend_rt_first_budget =
          shared_frontend_budget_per_cycle - sideband_issued_this_cycle;
    }
    unsigned shared_frontend_normal_first_budget = 0;
    const unsigned shared_frontend_normal_first_used_before_queue =
        sideband_issued_this_cycle + shared_frontend_normal_lsu_used;
    if (shared_frontend_normal_first_used_before_queue <
        shared_frontend_budget_per_cycle) {
      shared_frontend_normal_first_budget =
          shared_frontend_budget_per_cycle -
          shared_frontend_normal_first_used_before_queue;
    }
    if (shared_frontend_rt_first_budget > max_sideband_drain_per_cycle) {
      shared_frontend_rt_first_budget = max_sideband_drain_per_cycle;
    }
    if (shared_frontend_normal_first_budget > max_sideband_drain_per_cycle) {
      shared_frontend_normal_first_budget = max_sideband_drain_per_cycle;
    }
    unsigned shared_frontend_normal_lsu_budget_pressure = 0;
    if (sideband_issued_this_cycle < shared_frontend_budget_per_cycle) {
      shared_frontend_normal_lsu_budget_pressure =
          shared_frontend_budget_per_cycle - sideband_issued_this_cycle;
    }
    if (shared_frontend_normal_lsu_budget_pressure >
        shared_frontend_normal_lsu_used) {
      shared_frontend_normal_lsu_budget_pressure =
          shared_frontend_normal_lsu_used;
    }
    if (rtcore_shared_lsu_frontend_policy_rt_first()) {
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_shared_frontend_rt_first_priority_count +=
          shared_frontend_normal_lsu_budget_pressure;
    } else {
      g_rtcore_v02_lsu_shared_frontend_normal_first_pending_pressure_by_owner
          [result.owner_hw_sid] += shared_frontend_normal_lsu_budget_pressure;
    }
    const unsigned shared_frontend_rt_first_queue_budget =
        std::min(queued_sideband_count_before_drain,
                 shared_frontend_rt_first_budget);
    const unsigned shared_frontend_normal_first_queue_budget =
        std::min(queued_sideband_count_before_drain,
                 shared_frontend_normal_first_budget);
    if (!rtcore_shared_lsu_frontend_policy_rt_first()) {
      unsigned long long shared_frontend_policy_opportunity = 0;
      if (shared_frontend_rt_first_queue_budget >
          shared_frontend_normal_first_queue_budget) {
        shared_frontend_policy_opportunity =
            shared_frontend_rt_first_queue_budget -
            shared_frontend_normal_first_queue_budget;
      }
      // Normal-LSU pressure can be observed on cycles before queued RT work is
      // drained, so keep a small per-SM credit and consume it only when RT work
      // is actually blocked by the shared front-end.
      if (queued_sideband_count_before_drain > max_sideband_drain_per_cycle) {
        unsigned long long &pending_normal_pressure =
            g_rtcore_v02_lsu_shared_frontend_normal_first_pending_pressure_by_owner
                [result.owner_hw_sid];
        const unsigned long long blocked_sideband =
            queued_sideband_count_before_drain - max_sideband_drain_per_cycle;
        if (blocked_sideband > shared_frontend_policy_opportunity &&
            pending_normal_pressure > shared_frontend_policy_opportunity) {
          const unsigned long long deferred_policy_opportunity = std::min(
              blocked_sideband - shared_frontend_policy_opportunity,
              pending_normal_pressure - shared_frontend_policy_opportunity);
          shared_frontend_policy_opportunity += deferred_policy_opportunity;
        }
        if (shared_frontend_policy_opportunity > 0) {
          const unsigned long long consumed_normal_pressure =
              std::min(pending_normal_pressure,
                       shared_frontend_policy_opportunity);
          pending_normal_pressure -= consumed_normal_pressure;
        }
      }
      if (shared_frontend_policy_opportunity > 0) {
        g_rtcore_replay_cycle_hook_consumer_stats
            .v02_lsu_shared_frontend_normal_first_rt_preempted_count +=
            shared_frontend_policy_opportunity;
      }
    }
    if (shared_frontend_used_before_queue < shared_frontend_budget_per_cycle) {
      shared_frontend_rt_budget =
          shared_frontend_budget_per_cycle - shared_frontend_used_before_queue;
    }
    if (shared_frontend_rt_budget < max_sideband_drain_per_cycle) {
      max_sideband_drain_per_cycle = shared_frontend_rt_budget;
    }
    if (queued_sideband_count_before_drain > max_sideband_drain_per_cycle) {
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_shared_frontend_rt_blocked_count +=
          queued_sideband_count_before_drain - max_sideband_drain_per_cycle;
      g_rtcore_v02_lsu_shared_frontend_blocked_by_owner[result.owner_hw_sid] =
          true;
    }
  }
  unsigned drained_sideband_count = 0;
  unsigned examined_sideband_count = 0;
  rtcore_memory_unit_request_snapshot sideband_snapshot = {};
  while (examined_sideband_count < sideband_scan_limit &&
         drained_sideband_count < max_sideband_drain_per_cycle &&
         rtcore_pop_memory_unit_request_for_sm(result.owner_hw_sid,
                                                    &sideband_snapshot)) {
    examined_sideband_count++;
    const rtcore_replay_cycle_hook_result drained_result =
        rtcore_make_result_with_v02_lsu_sideband_snapshot(result,
                                                          sideband_snapshot);
    const rtcore_memory_unit_offer_outcome outcome =
        rtcore_consume_memory_unit_request_offer_from_rt_unit(
            drained_result, mf_allocator, config, core, l1d_cache, l0_cache,
            stats, sid);
    account_memory_offer(outcome, sideband_snapshot);
    if (outcome != RTCORE_MEMORY_UNIT_OFFER_L1D_ARBITER_BLOCKED &&
        outcome != RTCORE_MEMORY_UNIT_OFFER_L1D_DATA_PORT_BLOCKED) {
      drained_sideband_count++;
    }
  }
  const unsigned deferred_count =
      rtcore_count_memory_unit_requests_for_sm(result.owner_hw_sid);
  if (issue_bandwidth_gate_enabled) {
    g_rtcore_replay_cycle_hook_consumer_stats
        .v02_lsu_sideband_issue_bandwidth_issued_count +=
        rt_memory_issued_this_cycle;
    if (deferred_count > 0) {
      g_rtcore_replay_cycle_hook_consumer_stats
          .v02_lsu_sideband_issue_bandwidth_deferred_count += deferred_count;
      if (deferred_count >
          g_rtcore_replay_cycle_hook_consumer_stats
              .v02_lsu_sideband_issue_bandwidth_max_deferred_count) {
        g_rtcore_replay_cycle_hook_consumer_stats
            .v02_lsu_sideband_issue_bandwidth_max_deferred_count =
            deferred_count;
      }
      if (rt_memory_issued_this_cycle >= issue_budget_per_cycle) {
        g_rtcore_replay_cycle_hook_consumer_stats
            .v02_lsu_sideband_issue_bandwidth_budget_exhausted_count++;
      }
    }
    if (deferred_count > 0) {
      rtcore_maybe_log_memory_unit_request_offer_stats(result.owner_hw_sid);
    }
  }
  if (deferred_count != 0) {
    rtcore_memory_unit_request_snapshot blocked = {};
    if (rtcore_peek_memory_unit_request_for_sm(
            result.owner_hw_sid, &blocked)) {
      bool already_attempted = false;
      for (std::vector<rtcore_memory_attempt_identity>::const_iterator it =
               frontend_accepted_attempts.begin();
           it != frontend_accepted_attempts.end(); ++it) {
        if (rtcore_memory_attempt_identity_matches(*it, blocked)) {
          already_attempted = true;
          break;
        }
      }
      const bool issue_budget_blocked =
          issue_bandwidth_gate_enabled &&
          rt_memory_issued_this_cycle >= issue_budget_per_cycle;
      const bool frontend_budget_blocked =
          shared_frontend_gate_enabled &&
          sideband_issued_this_cycle +
                  (rtcore_shared_lsu_frontend_policy_rt_first()
                       ? 0u
                       : shared_frontend_normal_lsu_used) >=
              shared_frontend_budget_per_cycle;
      if (!already_attempted &&
          (issue_budget_blocked || frontend_budget_blocked)) {
        rtcore_emit_memory_unit_attempt(
            blocked, result.cycle, memory_offer_attempt_count,
            rtcore::v04::stall_attribution::kStageFrontend,
            rtcore::v04::stall_attribution::kOutcomeStall,
            rtcore::v04::stall_attribution::kActionNone,
            issue_budget_blocked
                ? rtcore::v04::stall_attribution::kReasonIssueBudget
                : rtcore::v04::stall_attribution::kReasonFrontendBudget);
      }
    }
  }
}

static void rtcore_record_replay_release_gate_decision(
    const rtcore_replay_cycle_hook_result &result, bool legacy_ready,
    bool release_identity_joined_for_gate,
    bool warp_completion_entry_enabled, bool warp_completion_entry_found,
    bool warp_completion_all_active_lanes_complete,
    bool warp_completion_scoreboard_handoff_delivered,
    bool candidate_warp_completion_entry_enabled,
    bool candidate_warp_completion_entry_found,
    bool candidate_warp_completion_all_active_lanes_complete,
    bool candidate_warp_completion_scoreboard_handoff_delivered,
    bool candidate_scoreboard_handoff_release_allowed,
    bool activation_enabled, bool activation_blocked,
    unsigned long long candidate_release_gate_blocked_cycles) {
  const bool aggregate_stats_log_enabled =
      rtcore_replay_release_gate_aggregate_stats_log_enabled();
  if (!aggregate_stats_log_enabled) {
    return;
  }

  g_rtcore_replay_release_gate_stats.evaluated_calls++;
  g_rtcore_replay_release_gate_stats.last_owner_hw_sid =
      result.owner_hw_sid;
  g_rtcore_replay_release_gate_stats.last_cycle = result.cycle;
  if (legacy_ready) {
    g_rtcore_replay_release_gate_stats.legacy_ready_calls++;
  }
  if (result.progressed) {
    g_rtcore_replay_release_gate_stats.hook_progressed_calls++;
  }
  const bool release_identity_joined = release_identity_joined_for_gate;
  if (release_identity_joined) {
    g_rtcore_replay_release_gate_stats.release_identity_joined_calls++;
  }
  const bool legacy_release_allowed =
      legacy_ready && result.hook_enabled && result.service_enabled &&
      result.progressed && release_identity_joined;
  if (legacy_release_allowed) {
    g_rtcore_replay_release_gate_stats.release_allowed_calls++;
  }

  const bool all_lanes_ready =
      release_identity_joined && warp_completion_entry_enabled &&
      warp_completion_entry_found &&
      warp_completion_all_active_lanes_complete;
  const bool scoreboard_handoff_release_allowed =
      legacy_ready && result.hook_enabled && result.service_enabled &&
      result.progressed && all_lanes_ready &&
      warp_completion_scoreboard_handoff_delivered;
  if (scoreboard_handoff_release_allowed) {
    g_rtcore_replay_release_gate_stats
        .all_lanes_release_allowed_calls++;
  }
  const bool all_lanes_release_blocked =
      legacy_release_allowed && !scoreboard_handoff_release_allowed;
  if (all_lanes_release_blocked) {
    g_rtcore_replay_release_gate_stats.all_lanes_release_blocked_calls++;
  }
  if (candidate_scoreboard_handoff_release_allowed) {
    g_rtcore_replay_release_gate_stats
        .candidate_scoreboard_handoff_release_allowed_calls++;
  }
  if (activation_enabled) {
    g_rtcore_replay_release_gate_stats.activation_enabled_calls++;
  }
  const bool activation_allowed =
      activation_enabled && candidate_scoreboard_handoff_release_allowed;
  const bool activation_allowed_after_block =
      activation_allowed && candidate_release_gate_blocked_cycles > 0;
  if (activation_blocked) {
    g_rtcore_replay_release_gate_stats.activation_blocked_calls++;
    g_rtcore_replay_release_gate_stats.activation_blocked_cycle_total++;
  } else if (activation_allowed) {
    g_rtcore_replay_release_gate_stats.activation_allowed_calls++;
  }
  if (activation_allowed_after_block) {
    g_rtcore_replay_release_gate_stats.activation_allowed_after_block_calls++;
  }
  if (candidate_release_gate_blocked_cycles > 0) {
    g_rtcore_replay_release_gate_stats
        .activation_blocked_cycle_observations++;
    if (candidate_release_gate_blocked_cycles >
        g_rtcore_replay_release_gate_stats
            .activation_max_candidate_blocked_cycles) {
      g_rtcore_replay_release_gate_stats
          .activation_max_candidate_blocked_cycles =
          candidate_release_gate_blocked_cycles;
    }
  }

  rtcore_maybe_log_replay_release_gate_aggregate_stats(
      result, activation_blocked || activation_allowed_after_block);
}

struct rtcore_scheduler_credit_ledger_shadow_table_owner_key {
  unsigned owner_hw_sid;
  unsigned warp_uid;
  unsigned warp_id;
  unsigned long long static_inst_pc;
  unsigned issued_active_mask;

  bool operator<(
      const rtcore_scheduler_credit_ledger_shadow_table_owner_key &other)
      const {
    if (owner_hw_sid != other.owner_hw_sid) return owner_hw_sid < other.owner_hw_sid;
    if (warp_uid != other.warp_uid) return warp_uid < other.warp_uid;
    if (warp_id != other.warp_id) return warp_id < other.warp_id;
    if (static_inst_pc != other.static_inst_pc)
      return static_inst_pc < other.static_inst_pc;
    return issued_active_mask < other.issued_active_mask;
  }
};

struct rtcore_scheduler_credit_ledger_shadow_table_mutation_result {
  rtcore_scheduler_credit_ledger_shadow_table_mutation_result()
      : entry_found(false),
        capacity_guard_passed(false),
        table_entries_before(0),
        table_entries_after(0),
        capacity_limit(32),
        owner_tuple_reserved(false),
        owner_tuple_released(false),
        capacity_reclaimed(false),
        capacity_mutated(false),
        reusable_slot_published(false),
        mutation_result("shadow_table_real_mutation_default_off"),
        transition_reason("shadow_table_real_mutation_default_off") {}

  bool entry_found;
  bool capacity_guard_passed;
  unsigned table_entries_before;
  unsigned table_entries_after;
  unsigned capacity_limit;
  bool owner_tuple_reserved;
  bool owner_tuple_released;
  bool capacity_reclaimed;
  bool capacity_mutated;
  bool reusable_slot_published;
  const char *mutation_result;
  const char *transition_reason;
};

