void shader_core_stats::event_warp_issued(unsigned s_id, unsigned warp_id,
                                          unsigned num_issued,
                                          unsigned dynamic_warp_id) {
  assert(warp_id <= m_config->max_warps_per_shader);
  for (unsigned i = 0; i < num_issued; ++i) {
    if (m_shader_dynamic_warp_issue_distro[s_id].size() <= dynamic_warp_id) {
      m_shader_dynamic_warp_issue_distro[s_id].resize(dynamic_warp_id + 1);
    }
    ++m_shader_dynamic_warp_issue_distro[s_id][dynamic_warp_id];
    if (m_shader_warp_slot_issue_distro[s_id].size() <= warp_id) {
      m_shader_warp_slot_issue_distro[s_id].resize(warp_id + 1);
    }
    ++m_shader_warp_slot_issue_distro[s_id][warp_id];
  }
}

double shader_core_stats::compue_distribution_avg(std::map<unsigned/*sid*/, std::map<unsigned/*wid*/, std::map<unsigned/*# of entries*/, long long unsigned/*cycles*/>>> & dist) {
  unsigned long long tot_cycles = 1;
  unsigned long long tot_cycles_times_entries = 0;
  for (auto it1=dist.begin(), et1=dist.end(); it1!=et1; it1++) {
    unsigned sid = it1->first;
    std::map<unsigned,std::map<unsigned,long long unsigned>> size_disto_within_core = dist[sid];
    printf("sid=%u", sid);
    for (auto it2=size_disto_within_core.begin(), et2=size_disto_within_core.end(); it2!=et2; it2++) {
      unsigned wid = it2->first;
      std::map<unsigned,long long unsigned> size_distro_within_warp = size_disto_within_core[wid];
      printf("	wid=%u", wid);
      for (auto it3=size_distro_within_warp.begin(), et3=size_distro_within_warp.end(); it3!=et3; it3++) {
        unsigned numEntries = it3->first;
        unsigned long long duration = it3->second;
        tot_cycles_times_entries += (numEntries * duration);
        tot_cycles += duration;
        printf("		%u	%llu\n", numEntries, duration);
      }
    }
  }
  dist.clear();
  return ((double)tot_cycles_times_entries/(double)tot_cycles);
}

void shader_core_stats::print_reuse_distribution_avg() {
  printf("Reuse Stats:\n");
  std::map<unsigned, double> distToReuseMap;
  std::map<unsigned, unsigned> distToReuseUpdatesMap;
  distToReuseMap.clear();
  for (auto it1=st_reuse_distro.begin(), et1=st_reuse_distro.end(); it1!=et1; it1++) {
    unsigned sid = it1->first;
    printf("sid=%u", sid);
    std::map<unsigned,std::map<unsigned,long long unsigned>> st_reuse_disto_within_core = st_reuse_distro[sid];
    for (auto it2=st_reuse_disto_within_core.begin(), et2=st_reuse_disto_within_core.end(); it2!=et2; it2++) {
      unsigned wid = it2->first;
      std::map<unsigned,long long unsigned> st_reuse_distro_within_warp = st_reuse_disto_within_core[wid];
      printf("	wid=%u", wid);
      for (auto it3=st_reuse_distro_within_warp.begin(), et3=st_reuse_distro_within_warp.end(); it3!=et3; it3++) {
        unsigned dist = it3->first;
        double reuse_duration = (double)it3->second;
        assert(dist <= MAX_ST_SIZE);
        unsigned updates = st_reuse_updates_distro[sid][wid][dist];
        printf("		%u	%f\n", dist, ((float)reuse_duration/updates));
        if (distToReuseMap.find(dist) == distToReuseMap.end()) {
          distToReuseMap[dist] = 0;
        }
        if (dist > 0) {
          distToReuseMap[dist] += reuse_duration;
        }
        distToReuseUpdatesMap[dist] += updates;
      }
    }
  }

  printf("Overall Average:\n");
  for (auto it=distToReuseMap.begin(), et=distToReuseMap.end(); it!=et; it++) {
    unsigned dist = it->first;
    double reuse_duration = it->second;
    unsigned updates = distToReuseUpdatesMap[dist];
    printf("dist=%u		%f\n", dist, (reuse_duration/updates));
  }
}

void shader_core_stats::visualizer_print(gzFile visualizer_file) {
  // warp divergence breakdown
  gzprintf(visualizer_file, "WarpDivergenceBreakdown:");
  unsigned int total = 0;
  unsigned int cf =
      (m_config->gpgpu_warpdistro_shader == -1) ? m_config->num_shader() : 1;
  gzprintf(visualizer_file, " %d",
           (shader_cycle_distro[0] - last_shader_cycle_distro[0]) / cf);
  gzprintf(visualizer_file, " %d",
           (shader_cycle_distro[1] - last_shader_cycle_distro[1]) / cf);
  gzprintf(visualizer_file, " %d",
           (shader_cycle_distro[2] - last_shader_cycle_distro[2]) / cf);
  for (unsigned i = 0; i < m_config->warp_size + 3; i++) {
    if (i >= 3) {
      total += (shader_cycle_distro[i] - last_shader_cycle_distro[i]);
      if (((i - 3) % (m_config->warp_size / 8)) ==
          ((m_config->warp_size / 8) - 1)) {
        gzprintf(visualizer_file, " %d", total / cf);
        total = 0;
      }
    }
    last_shader_cycle_distro[i] = shader_cycle_distro[i];
  }
  gzprintf(visualizer_file, "\n");

  gzprintf(visualizer_file, "RTWarpDist:");
  gzprintf(visualizer_file, " %d", n_empty_warps);
  gzprintf(visualizer_file, " %d", n_shd_warps);
  gzprintf(visualizer_file, " %d", n_rt_warps);
  gzprintf(visualizer_file, "\n");

  gzprintf(visualizer_file, "ctas_completed: %d\n", ctas_completed);
  ctas_completed = 0;
  // warp issue breakdown
  unsigned sid = m_config->gpgpu_warp_issue_shader;
  unsigned count = 0;
  unsigned warp_id_issued_sum = 0;
  gzprintf(visualizer_file, "WarpIssueSlotBreakdown:");
  if (m_shader_warp_slot_issue_distro[sid].size() > 0) {
    for (std::vector<unsigned>::const_iterator iter =
             m_shader_warp_slot_issue_distro[sid].begin();
         iter != m_shader_warp_slot_issue_distro[sid].end(); iter++, count++) {
      unsigned diff = count < m_last_shader_warp_slot_issue_distro.size()
                          ? *iter - m_last_shader_warp_slot_issue_distro[count]
                          : *iter;
      gzprintf(visualizer_file, " %d", diff);
      warp_id_issued_sum += diff;
    }
    m_last_shader_warp_slot_issue_distro = m_shader_warp_slot_issue_distro[sid];
  } else {
    gzprintf(visualizer_file, " 0");
  }
  gzprintf(visualizer_file, "\n");

#define DYNAMIC_WARP_PRINT_RESOLUTION 32
  unsigned total_issued_this_resolution = 0;
  unsigned dynamic_id_issued_sum = 0;
  count = 0;
  gzprintf(visualizer_file, "WarpIssueDynamicIdBreakdown:");
  if (m_shader_dynamic_warp_issue_distro[sid].size() > 0) {
    for (std::vector<unsigned>::const_iterator iter =
             m_shader_dynamic_warp_issue_distro[sid].begin();
         iter != m_shader_dynamic_warp_issue_distro[sid].end();
         iter++, count++) {
      unsigned diff =
          count < m_last_shader_dynamic_warp_issue_distro.size()
              ? *iter - m_last_shader_dynamic_warp_issue_distro[count]
              : *iter;
      total_issued_this_resolution += diff;
      if ((count + 1) % DYNAMIC_WARP_PRINT_RESOLUTION == 0) {
        gzprintf(visualizer_file, " %d", total_issued_this_resolution);
        dynamic_id_issued_sum += total_issued_this_resolution;
        total_issued_this_resolution = 0;
      }
    }
    if (count % DYNAMIC_WARP_PRINT_RESOLUTION != 0) {
      gzprintf(visualizer_file, " %d", total_issued_this_resolution);
      dynamic_id_issued_sum += total_issued_this_resolution;
    }
    m_last_shader_dynamic_warp_issue_distro =
        m_shader_dynamic_warp_issue_distro[sid];
    assert(warp_id_issued_sum == dynamic_id_issued_sum);
  } else {
    gzprintf(visualizer_file, " 0");
  }
  gzprintf(visualizer_file, "\n");

  // overall cache miss rates
  gzprintf(visualizer_file, "gpgpu_n_cache_bkconflict: %d\n",
           gpgpu_n_cache_bkconflict);
  gzprintf(visualizer_file, "gpgpu_n_shmem_bkconflict: %d\n",
           gpgpu_n_shmem_bkconflict);

  // instruction count per shader core
  gzprintf(visualizer_file, "shaderinsncount:  ");
  for (unsigned i = 0; i < m_config->num_shader(); i++)
    gzprintf(visualizer_file, "%u ", m_num_sim_insn[i]);
  gzprintf(visualizer_file, "\n");
  // warp instruction count per shader core
  gzprintf(visualizer_file, "shaderwarpinsncount:  ");
  for (unsigned i = 0; i < m_config->num_shader(); i++)
    gzprintf(visualizer_file, "%u ", m_num_sim_winsn[i]);
  gzprintf(visualizer_file, "\n");
  // warp divergence per shader core
  gzprintf(visualizer_file, "shaderwarpdiv: ");
  for (unsigned i = 0; i < m_config->num_shader(); i++)
    gzprintf(visualizer_file, "%u ", m_n_diverge[i]);
  gzprintf(visualizer_file, "\n");

  // AWARE aerialvision stats
  gzprintf(visualizer_file, "aware_st_size:  ");
  for (unsigned i = 0; i < m_config->num_shader(); i++)
    gzprintf(visualizer_file, "%u ", aware_st_size[i]);
  gzprintf(visualizer_file, "\n");
  gzprintf(visualizer_file, "aware_rt_size:  ");
  for (unsigned i = 0; i < m_config->num_shader(); i++)
    gzprintf(visualizer_file, "%u ", aware_rt_size[i]);
  gzprintf(visualizer_file, "\n");

  gzprintf(visualizer_file, "cacheMissRate_globalL1_all:  ");
  for (unsigned i = 0; i < m_config->num_shader(); i++)
    gzprintf(visualizer_file, "%f ", l1d_missrate[i]);
  gzprintf(visualizer_file, "\n");
  gzprintf(visualizer_file, "L1DMiss:  ");
  for (unsigned i = 0; i < m_config->num_shader(); i++)
    gzprintf(visualizer_file, "%u ", l1d_miss[i]);
  gzprintf(visualizer_file, "\n");
  gzprintf(visualizer_file, "L1DAccess:  ");
  for (unsigned i = 0; i < m_config->num_shader(); i++)
    gzprintf(visualizer_file, "%u ", l1d_access[i]);
  gzprintf(visualizer_file, "\n");
  gzprintf(visualizer_file, "L1DResFail:  ");
  for (unsigned i = 0; i < m_config->num_shader(); i++)
    gzprintf(visualizer_file, "%u ", l1d_res_fail[i]);
  gzprintf(visualizer_file, "\n");
  gzprintf(visualizer_file, "L1DHitRes:  ");
  for (unsigned i = 0; i < m_config->num_shader(); i++)
    gzprintf(visualizer_file, "%u ", l1d_hit_res[i]);
  gzprintf(visualizer_file, "\n");
  
  // Ray tracing aerialvision stats
  gzprintf(visualizer_file, "rt_nwarps:  ");
  for (unsigned i = 0; i < m_config->num_shader(); i++)
    gzprintf(visualizer_file, "%u ", rt_nwarps[i]);
  gzprintf(visualizer_file, "\n");
  gzprintf(visualizer_file, "rt_nthreads:  ");
  for (unsigned i = 0; i < m_config->num_shader(); i++)
    gzprintf(visualizer_file, "%u ", rt_nthreads[i]);
  gzprintf(visualizer_file, "\n");
  gzprintf(visualizer_file, "rt_naccesses:  ");
  for (unsigned i = 0; i < m_config->num_shader(); i++)
    gzprintf(visualizer_file, "%u ", rt_naccesses[i]);
  gzprintf(visualizer_file, "\n");
  gzprintf(visualizer_file, "rt_max_coalesce:  ");
  for (unsigned i = 0; i < m_config->num_shader(); i++)
    gzprintf(visualizer_file, "%u ", rt_max_coalesce[i]);
  gzprintf(visualizer_file, "\n");
  rt_mshr_size_total = 0;
  gzprintf(visualizer_file, "rt_mshr_size:  ");
  for (unsigned i = 0; i < m_config->num_shader(); i++) {
    gzprintf(visualizer_file, "%u ", rt_mshr_size[i]);
    rt_mshr_size_total += rt_mshr_size[i];
  }
  gzprintf(visualizer_file, "\n");
  gzprintf(visualizer_file, "rt_nthreads_intersection:  ");
  for (unsigned i = 0; i < m_config->num_shader(); i++)
    gzprintf(visualizer_file, "%u ", rt_nthreads_intersection[i]);
  gzprintf(visualizer_file, "\n");
  gzprintf(visualizer_file, "rt_mem_requests: %u\n", rt_mem_requests);
  gzprintf(visualizer_file, "rt_mshr_size_total: %u\n", rt_mshr_size_total);
  rt_mem_requests = 0;
}

#define PROGRAM_MEM_START                                      \
  0xF0000000 /* should be distinct from other memory spaces... \
                check ptx_ir.h to verify this does not overlap \
                other memory spaces */

const warp_inst_t *exec_shader_core_ctx::get_next_inst(unsigned warp_id,
                                                       address_type pc) {
  // read the inst from the functional model
  return m_gpu->gpgpu_ctx->ptx_fetch_inst(pc);
}

void exec_shader_core_ctx::get_pdom_stack_top_info(unsigned warp_id,
                                                   const warp_inst_t *pI,
                                                   unsigned *pc,
                                                   unsigned *rpc) {
  if (m_config->model == POST_DOMINATOR) {
    m_simt_stack[warp_id]->get_pdom_stack_top_info(pc, rpc);
  } else {
    m_simt_tables[warp_id]->get_pdom_active_split_info(pc, rpc);
  }
}

void exec_shader_core_ctx::update_splits_table(unsigned warp_id) {
  assert(m_config->model == AWARE_RECONVERGENCE);
  m_simt_tables[warp_id]->push_back();
}

const active_mask_t &exec_shader_core_ctx::get_active_mask(
    unsigned warp_id, const warp_inst_t *pI) {

  if (m_config->model == POST_DOMINATOR) {
    return m_simt_stack[warp_id]->get_active_mask();
  } else {
    return m_simt_tables[warp_id]->get_active_mask();
  }
}

void shader_core_ctx::decode() {
  if (m_inst_fetch_buffer.m_valid) {
    // decode 1 or 2 instructions and place them into ibuffer
    address_type pc = m_inst_fetch_buffer.m_pc;
    const warp_inst_t *pI1 = get_next_inst(m_inst_fetch_buffer.m_warp_id, pc);
    m_warp[m_inst_fetch_buffer.m_warp_id]->ibuffer_fill(0, pI1);
    m_warp[m_inst_fetch_buffer.m_warp_id]->inc_inst_in_pipeline();
    if (pI1) {
      m_stats->m_num_decoded_insn[m_sid]++;
      if (pI1->oprnd_type == INT_OP) {
        m_stats->m_num_INTdecoded_insn[m_sid]++;
      } else if (pI1->oprnd_type == FP_OP) {
        m_stats->m_num_FPdecoded_insn[m_sid]++;
      }
      const warp_inst_t *pI2 =
          get_next_inst(m_inst_fetch_buffer.m_warp_id, pc + pI1->isize);
      if (pI2) {
        m_warp[m_inst_fetch_buffer.m_warp_id]->ibuffer_fill(1, pI2);
        m_warp[m_inst_fetch_buffer.m_warp_id]->inc_inst_in_pipeline();
        m_stats->m_num_decoded_insn[m_sid]++;
        if (pI2->oprnd_type == INT_OP) {
          m_stats->m_num_INTdecoded_insn[m_sid]++;
        } else if (pI2->oprnd_type == FP_OP) {
          m_stats->m_num_FPdecoded_insn[m_sid]++;
        }
      }
    }
    m_inst_fetch_buffer.m_valid = false;
  }
}

void shader_core_ctx::fetch() {
  if (!m_inst_fetch_buffer.m_valid) {
    if (m_L1I->access_ready()) {
      mem_fetch *mf = m_L1I->next_access();
      m_warp[mf->get_wid()]->clear_imiss_pending();
      m_inst_fetch_buffer =
          ifetch_buffer_t(m_warp[mf->get_wid()]->get_pc(),
                          mf->get_access_size(), mf->get_wid());
      assert(m_warp[mf->get_wid()]->get_pc() ==
             (mf->get_addr() -
              PROGRAM_MEM_START));  // Verify that we got the instruction we
                                    // were expecting.
      m_inst_fetch_buffer.m_valid = true;
      m_warp[mf->get_wid()]->set_last_fetch(m_gpu->gpu_sim_cycle);
      delete mf;
    } else {
      // find an active warp with space in instruction buffer that is not
      // already waiting on a cache miss and get next 1-2 instructions from
      // i-cache...
      for (unsigned i = 0; i < m_config->max_warps_per_shader; i++) {
        unsigned warp_id =
            (m_last_warp_fetched + 1 + i) % m_config->max_warps_per_shader;

        // this code checks if this warp has finished executing and can be
        // reclaimed
        if (m_warp[warp_id]->hardware_done() &&
            !m_scoreboard->pendingWrites(warp_id) &&
            !m_warp[warp_id]->done_exit()) {
          bool did_exit = false;
          for (unsigned t = 0; t < m_config->warp_size; t++) {
            unsigned tid = warp_id * m_config->warp_size + t;
            if (m_threadState[tid].m_active == true) {
              m_threadState[tid].m_active = false;
              unsigned cta_id = m_warp[warp_id]->get_cta_id();
              if (m_thread[tid] == NULL) {
                register_cta_thread_exit(cta_id, m_kernel);
              } else {
                register_cta_thread_exit(cta_id,
                                         &(m_thread[tid]->get_kernel()));
              }
              m_not_completed -= 1;
              m_active_threads.reset(tid);
              did_exit = true;
            }
          }
          if (did_exit) {
            m_warp[warp_id]->set_done_exit();
          }
          if(m_gpu->simd_model() == AWARE_RECONVERGENCE) {
            update_table_stats(warp_id);
          }

          --m_active_warps;
          assert(m_active_warps >= 0);
        }

        // this code fetches instructions from the i-cache or generates memory
        bool simt_conditions = true;
        if(m_config->model == AWARE_RECONVERGENCE) simt_conditions=!is_virtualized(warp_id); 
        
        if (simt_conditions &&  
            !m_warp[warp_id]->functional_done() &&
            !m_warp[warp_id]->imiss_pending() &&
            m_warp[warp_id]->ibuffer_empty()) {
          address_type pc;
          pc = m_warp[warp_id]->get_pc();
          address_type ppc = pc + PROGRAM_MEM_START;
          unsigned nbytes = 16;
          unsigned offset_in_block =
              pc & (m_config->m_L1I_config.get_line_sz() - 1);
          if ((offset_in_block + nbytes) > m_config->m_L1I_config.get_line_sz())
            nbytes = (m_config->m_L1I_config.get_line_sz() - offset_in_block);

          // TODO: replace with use of allocator
          // mem_fetch *mf = m_mem_fetch_allocator->alloc()
          mem_access_t acc(INST_ACC_R, ppc, nbytes, false, m_gpu->gpgpu_ctx);
          mem_fetch *mf = new mem_fetch(
              acc, NULL /*we don't have an instruction yet*/, READ_PACKET_SIZE,
              warp_id, m_sid, m_tpc, m_memory_config,
              m_gpu->gpu_tot_sim_cycle + m_gpu->gpu_sim_cycle);
          std::list<cache_event> events;
          enum cache_request_status status;
          if (m_config->perfect_inst_const_cache)
            status = HIT;
          else
            status = m_L1I->access(
                (new_addr_type)ppc, mf,
                m_gpu->gpu_sim_cycle + m_gpu->gpu_tot_sim_cycle, events);

          if (status == MISS) {
            m_last_warp_fetched = warp_id;
            m_warp[warp_id]->set_imiss_pending();
            m_warp[warp_id]->set_last_fetch(m_gpu->gpu_sim_cycle);
          } else if (status == HIT) {
            m_last_warp_fetched = warp_id;
            m_inst_fetch_buffer = ifetch_buffer_t(pc, nbytes, warp_id);
            m_warp[warp_id]->set_last_fetch(m_gpu->gpu_sim_cycle);
            delete mf;
          } else {
            m_last_warp_fetched = warp_id;
            assert(status == RESERVATION_FAIL);
            delete mf;
          }
          break;
        }
      }
    }
  }

  m_L1I->cycle();
}

void exec_shader_core_ctx::func_exec_inst(warp_inst_t &inst) {
  const bool v04_root_node_submit = inst.op == RT_CORE_OP &&
                                    inst.rt_subop == RT_CORE_SUBOP_SUBMIT &&
                                    rtcore_v04_root_node_input_gate_active();
  if (v04_root_node_submit) {
    ptx_thread_info *lane_threads[32] = {};
    const unsigned warp_size = m_config->warp_size;
    assert(warp_size == 32);
    for (unsigned lane = 0; lane < warp_size; ++lane) {
      lane_threads[lane] = m_thread[inst.warp_id() * warp_size + lane];
    }
    const ptx_instruction *instruction = static_cast<const ptx_instruction *>(
        get_next_inst(inst.warp_id(), inst.pc));
    if (!rtcore_prepare_v04_root_node_packet_before_functional(
            instruction, lane_threads, m_sid, inst.get_uid(),
            inst.dynamic_warp_id(), inst.warp_id(),
            static_cast<unsigned>(inst.get_warp_active_mask().to_ulong()),
            m_gpu->gpu_tot_sim_cycle + m_gpu->gpu_sim_cycle)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_ROOT_PACKET_PRE_FUNCTIONAL_FAULT "
              "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08lx\n",
              m_sid, inst.get_uid(), inst.warp_id(),
              inst.get_warp_active_mask().to_ulong());
      fflush(stderr);
      abort();
    }
  }
  execute_warp_inst_t(inst);
  if (v04_root_node_submit &&
      !rtcore_finalize_v04_root_node_packet_after_functional(
          m_sid, inst.get_uid(), inst.warp_id(),
          static_cast<unsigned>(inst.get_warp_active_mask().to_ulong()))) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_ROOT_PACKET_POST_FUNCTIONAL_FAULT "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08lx\n",
            m_sid, inst.get_uid(), inst.warp_id(),
            inst.get_warp_active_mask().to_ulong());
    fflush(stderr);
    abort();
  }
  if (inst.is_load() || inst.is_store()) {
    inst.generate_mem_accesses();
    // inst.print_m_accessq();
  }
}

bool shader_core_ctx::rtcore_submit_handoff_shared_capacity_available(
    const warp_inst_t &inst, unsigned warp_id,
    unsigned active_mask) const {
  if (inst.op != RT_CORE_OP || inst.rt_subop != RT_CORE_SUBOP_SUBMIT ||
      !rtcore_v04_shared_placement_active()) {
    return true;
  }

  rtcore_v04_ensure_handoff_shared_report_registered();
  unsigned resident_active_lanes = 0;
  unsigned old_active_mask = 0;
  bool warp_resident = false;
  if (!rtcore_query_resident_rt_warp_active_lane_state(
          m_sid, warp_id, &resident_active_lanes, &old_active_mask,
          &warp_resident)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_HANDOFF_SHARED_RESOURCE_FAULT "
            "owner_hw_sid=%u warp_id=%u reason=resident_query_failed\n",
            m_sid, warp_id);
    fflush(stderr);
    abort();
  }

  const unsigned old_lane_count =
      warp_resident
          ? rtcore_handoff_storage::active_lane_count(old_active_mask)
          : 0;
  if (resident_active_lanes < old_lane_count) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_HANDOFF_SHARED_RESOURCE_FAULT "
            "owner_hw_sid=%u warp_id=%u resident_active_lanes=%u "
            "old_lane_count=%u reason=resident_lane_underflow\n",
            m_sid, warp_id, resident_active_lanes, old_lane_count);
    fflush(stderr);
    abort();
  }

  const unsigned base_lane_count = resident_active_lanes - old_lane_count;
  const unsigned new_lane_count =
      rtcore_handoff_storage::active_lane_count(active_mask);
  const unsigned base_rt_charge =
      rtcore_v04_combined_shared_charge_for_lanes(base_lane_count);
  const unsigned new_rt_demand =
      rtcore_v04_combined_shared_charge_for_lanes(new_lane_count);
  unsigned cta_charge = m_occupied_shmem;
  if (!m_config->gpgpu_concurrent_kernel_sm && m_kernel != NULL) {
    const gpgpu_ptx_sim_info *kernel_info =
        ptx_sim_kernel_info(m_kernel->entry());
    cta_charge = get_n_active_cta() * kernel_info->smem;
  }

  bool available = false;
  const rtcore_handoff_storage::status_kind status =
      rtcore_handoff_storage::resource_available(
          m_config->gpgpu_shmem_size, cta_charge, base_rt_charge,
          new_rt_demand, &available);
  ++g_rtcore_v04_handoff_shared_submit_admission_checks;
  if (warp_resident) {
    ++g_rtcore_v04_handoff_shared_resubmit_replacement_checks;
  }
  g_rtcore_v04_handoff_shared_peak_resident_charge = std::max(
      g_rtcore_v04_handoff_shared_peak_resident_charge,
      base_rt_charge + new_rt_demand);
  g_rtcore_v04_handoff_shared_peak_handoff_charge = std::max(
      g_rtcore_v04_handoff_shared_peak_handoff_charge,
      rtcore_v04_handoff_shared_charge_for_lanes(base_lane_count +
                                                  new_lane_count));
  g_rtcore_v04_handoff_shared_peak_private_charge = std::max(
      g_rtcore_v04_handoff_shared_peak_private_charge,
      rtcore_v04_private_shared_charge_for_lanes(base_lane_count +
                                                  new_lane_count));
  g_rtcore_v04_handoff_shared_peak_cta_charge =
      std::max(g_rtcore_v04_handoff_shared_peak_cta_charge, cta_charge);
  if (status == rtcore_handoff_storage::kStatusOk && available) return true;
  if (status != rtcore_handoff_storage::kStatusCapacityExceeded) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_HANDOFF_SHARED_RESOURCE_FAULT "
            "owner_hw_sid=%u warp_id=%u active_mask=0x%08x "
            "status=%s\n",
            m_sid, warp_id, active_mask,
            rtcore_handoff_storage::status_name(status));
    fflush(stderr);
    abort();
  }

  ++g_rtcore_v04_handoff_shared_submit_admission_stalls;
  printf("GPGPU-Sim RTCORE_V04_HANDOFF_SHARED_ADMISSION_STALL "
         "kind=submit handoff_profile=%s private_profile=%s "
         "owner_hw_sid=%u warp_id=%u "
         "active_mask=0x%08x replacement=%u capacity_bytes=%u "
         "cta_charge_bytes=%u base_rt_charge_bytes=%u "
         "new_rt_demand_bytes=%u action=stall_before_completion_reserve\n",
         rtcore_handoff_storage::profile_name(
             rtcore_v04_handoff_storage_profile()),
         rtcore_private_placement::profile_name(
             rtcore_v04_private_placement_profile()),
         m_sid, warp_id, active_mask, warp_resident ? 1u : 0u,
         m_config->gpgpu_shmem_size, cta_charge, base_rt_charge,
         new_rt_demand);
  fflush(stdout);
  return false;
}

bool shader_core_ctx::rtcore_handoff_shared_capacity_allows_cta(
    unsigned cta_shared_demand_bytes) const {
  if (!rtcore_v04_shared_placement_active()) {
    return true;
  }

  rtcore_v04_ensure_handoff_shared_report_registered();
  unsigned resident_active_lanes = 0;
  unsigned unused_active_mask = 0;
  bool unused_warp_resident = false;
  if (!rtcore_query_resident_rt_warp_active_lane_state(
          m_sid, UINT_MAX, &resident_active_lanes, &unused_active_mask,
          &unused_warp_resident)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_HANDOFF_SHARED_RESOURCE_FAULT "
            "owner_hw_sid=%u reason=cta_resident_query_failed\n",
            m_sid);
    fflush(stderr);
    abort();
  }
  const unsigned rt_charge =
      rtcore_v04_combined_shared_charge_for_lanes(resident_active_lanes);
  unsigned cta_charge = m_occupied_shmem;
  if (!m_config->gpgpu_concurrent_kernel_sm && m_kernel != NULL) {
    const gpgpu_ptx_sim_info *kernel_info =
        ptx_sim_kernel_info(m_kernel->entry());
    cta_charge = get_n_active_cta() * kernel_info->smem;
  }
  bool available = false;
  const rtcore_handoff_storage::status_kind status =
      rtcore_handoff_storage::resource_available(
          m_config->gpgpu_shmem_size, cta_charge, rt_charge,
          cta_shared_demand_bytes, &available);
  ++g_rtcore_v04_handoff_shared_cta_admission_checks;
  g_rtcore_v04_handoff_shared_peak_resident_charge =
      std::max(g_rtcore_v04_handoff_shared_peak_resident_charge, rt_charge);
  g_rtcore_v04_handoff_shared_peak_handoff_charge = std::max(
      g_rtcore_v04_handoff_shared_peak_handoff_charge,
      rtcore_v04_handoff_shared_charge_for_lanes(resident_active_lanes));
  g_rtcore_v04_handoff_shared_peak_private_charge = std::max(
      g_rtcore_v04_handoff_shared_peak_private_charge,
      rtcore_v04_private_shared_charge_for_lanes(resident_active_lanes));
  g_rtcore_v04_handoff_shared_peak_cta_charge = std::max(
      g_rtcore_v04_handoff_shared_peak_cta_charge,
      cta_charge + cta_shared_demand_bytes);
  if (status == rtcore_handoff_storage::kStatusOk && available) return true;
  if (status != rtcore_handoff_storage::kStatusCapacityExceeded) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_V04_HANDOFF_SHARED_RESOURCE_FAULT "
            "owner_hw_sid=%u status=%s reason=cta_resource_state\n",
            m_sid, rtcore_handoff_storage::status_name(status));
    fflush(stderr);
    abort();
  }
  ++g_rtcore_v04_handoff_shared_cta_admission_stalls;
  printf("GPGPU-Sim RTCORE_V04_HANDOFF_SHARED_ADMISSION_STALL "
         "kind=cta handoff_profile=%s private_profile=%s owner_hw_sid=%u "
         "capacity_bytes=%u "
         "cta_charge_bytes=%u rt_charge_bytes=%u "
         "cta_demand_bytes=%u action=stall_before_cta_issue\n",
         rtcore_handoff_storage::profile_name(
             rtcore_v04_handoff_storage_profile()),
         rtcore_private_placement::profile_name(
             rtcore_v04_private_placement_profile()),
         m_sid, m_config->gpgpu_shmem_size, cta_charge, rt_charge,
         cta_shared_demand_bytes);
  fflush(stdout);
  return false;
}

bool shader_core_ctx::rtcore_submit_resident_warp_capacity_available(
    const warp_inst_t &inst, unsigned warp_id,
    unsigned rt_core_out_pending_warps,
    const rtcore_resident_gate_materialized_input_provenance_snapshot
        &materialized_input_provenance) const {
  if (inst.op != RT_CORE_OP || inst.rt_subop != RT_CORE_SUBOP_SUBMIT) {
    return true;
  }
  const char *resident_capacity_gate = getenv(
      "VULKAN_SIM_RTCORE_RESIDENT_WARP_CAPACITY_BACKPRESSURE");
  const bool resident_capacity_gate_enabled =
      resident_capacity_gate != NULL && *resident_capacity_gate != '\0' &&
      strcmp(resident_capacity_gate, "0") != 0;
  if (!resident_capacity_gate_enabled &&
      !rtcore_symbolic_submit_issue_resource_backpressure_is_enabled()) {
    return true;
  }
  rtcore_resident_warp_demand_snapshot snapshot =
      m_rt_unit->rtcore_make_resident_warp_demand_snapshot(
          rt_core_out_pending_warps);
  unsigned resident_context_warps = 0;
  const bool candidate_already_resident =
      rtcore_query_resident_rt_warp_record(
          m_sid, warp_id, NULL, NULL, NULL, &resident_context_warps);
  snapshot.resident_live_warps =
      std::max(snapshot.resident_live_warps, resident_context_warps);
  snapshot.resident_live_plus_demand_warps =
      snapshot.resident_live_warps + (candidate_already_resident ? 0 : 1);
  snapshot.capacity_available =
      snapshot.zero_capacity_fail_closed || candidate_already_resident ||
      snapshot.resident_live_warps < snapshot.resident_rt_warp_capacity;
  return m_rt_unit->rtcore_resident_warp_capacity_available(
      inst, warp_id, m_sid, inst.pc, snapshot, materialized_input_provenance);
}

bool shader_core_ctx::rtcore_retire_frontend_issue_available(
    const warp_inst_t &inst, unsigned warp_id) const {
  if (inst.op != RT_CORE_OP ||
      !rtcore_retire_lifecycle_busy_for_owner(m_sid)) {
    return true;
  }
  printf("GPGPU-Sim RTCORE_RETIRE_FRONTEND_BUSY "
         "owner_hw_sid=%u warp_id=%u static_inst_pc=0x%llx "
         "rt_subop=%u action=stall_before_functional_issue\n",
         m_sid, warp_id, static_cast<unsigned long long>(inst.pc),
         static_cast<unsigned>(inst.rt_subop));
  fflush(stdout);
  return false;
}

bool shader_core_ctx::rtcore_submit_warp_admission_budget_available(
    const warp_inst_t &inst, unsigned warp_id,
    unsigned long long issue_cycle) const {
  if (inst.op != RT_CORE_OP || inst.rt_subop != RT_CORE_SUBOP_SUBMIT) {
    return true;
  }
  if (!rtcore_symbolic_submit_issue_resource_backpressure_is_enabled()) {
    return true;
  }
  const unsigned budget = rtcore_warp_admission_budget_config();
  const rtcore_warp_admission_budget_cycle_state &state =
      rtcore_warp_admission_budget_state_for_owner(m_sid, issue_cycle);
  if (state.used < budget) {
    return true;
  }
  printf("GPGPU-Sim PTX: RT_SUBMIT "
         "warp-admission-budget-backpressure=1, owner_hw_sid=%u, "
         "issue_cycle=%llu, warp_id=%u, static_inst_pc=0x%llx, "
         "warp_admission_budget=%u, warp_admission_used=%u, action=stall\n",
         m_sid, issue_cycle, warp_id,
         static_cast<unsigned long long>(inst.pc), budget, state.used);
  fflush(stdout);
  return false;
}

void shader_core_ctx::rtcore_submit_warp_admission_budget_consume(
    const warp_inst_t &inst, unsigned warp_id,
    unsigned long long issue_cycle) const {
  (void)warp_id;
  if (inst.op != RT_CORE_OP || inst.rt_subop != RT_CORE_SUBOP_SUBMIT) {
    return;
  }
  if (!rtcore_symbolic_submit_issue_resource_backpressure_is_enabled()) {
    return;
  }
  const unsigned budget = rtcore_warp_admission_budget_config();
  rtcore_warp_admission_budget_cycle_state &state =
      rtcore_warp_admission_budget_state_for_owner(m_sid, issue_cycle);
  if (state.used < budget) {
    state.used++;
  }
}

bool shader_core_ctx::rtcore_submit_warp_completion_entry_reserve_issue_slot(
    const warp_inst_t &inst, unsigned warp_id,
    unsigned issued_active_mask,
    const rtcore_warp_completion_entry_gate_materialized_input_provenance_snapshot
        &materialized_input_provenance) const {
  if (inst.op != RT_CORE_OP || inst.rt_subop != RT_CORE_SUBOP_SUBMIT) {
    return true;
  }
  return m_rt_unit->rtcore_warp_completion_entry_reserve_issue_slot(
      inst, warp_id, m_sid, inst.pc, issued_active_mask,
      materialized_input_provenance);
}

void shader_core_ctx::issue_warp(register_set &pipe_reg_set,
                                 const warp_inst_t *next_inst,
                                 const active_mask_t &active_mask,
                                 unsigned warp_id, unsigned sch_id,
                                 unsigned reserved_uid) {
  warp_inst_t **pipe_reg =
      pipe_reg_set.get_free(m_config->sub_core_model, sch_id);
  assert(pipe_reg);

  m_warp[warp_id]->ibuffer_free();
  assert(next_inst->valid());
  **pipe_reg = *next_inst;  // static instruction information
  (*pipe_reg)->issue(active_mask, warp_id,
                     m_gpu->gpu_tot_sim_cycle + m_gpu->gpu_sim_cycle,
                     m_warp[warp_id]->get_dynamic_warp_id(),
                     sch_id, reserved_uid);  // dynamic instruction information
  m_stats->shader_cycle_distro[2 + (*pipe_reg)->active_count()]++;
  func_exec_inst(**pipe_reg);
  const ptx_instruction *issued_ptx =
      m_gpu->gpgpu_ctx->pc_to_instruction(next_inst->pc);
  if ((*pipe_reg)->active_count() != 0 && issued_ptx != NULL &&
      issued_ptx->get_opcode() == RT_PUBLISH_TRACE_CONTEXT_OP) {
    address_type publication_fence_pc = 0;
    if (rtcore_v04_find_initial_publication_fence_pc(
            m_gpu->gpgpu_ctx, next_inst->pc,
            &publication_fence_pc)) {
      m_warp[warp_id]->arm_rtcore_v04_initial_publication_fence(
          publication_fence_pc);
    }
  }
  bool split_reaches_barrier = false;

  if (next_inst->op == BARRIER_OP) {
    m_warp[warp_id]->store_info_of_last_inst_at_barrier(*pipe_reg);

    if (get_config()->model == POST_DOMINATOR) {
      m_barriers.warp_reaches_barrier(m_warp[warp_id]->get_cta_id(), warp_id,
                                    const_cast<warp_inst_t *>(next_inst));
    } else {
      split_reaches_barrier = true;
      /* warp reaches barrier only if all its splits reach barrier */
      bool warp_reaches_barrier = m_simt_tables[warp_id]->split_reaches_barrier(next_inst->pc);
      if (warp_reaches_barrier) {
        split_reaches_barrier = false;
        m_barriers.warp_reaches_barrier(m_warp[warp_id]->get_cta_id(),warp_id,const_cast<warp_inst_t*> (next_inst));
        if (m_barriers.warps_count_at_barrier(m_warp[warp_id]->get_cta_id()) == 0) {
          unsigned n = m_config->n_thread_per_shader / m_config->warp_size;
          for (unsigned i=0; i<n; i++) {
            if (m_warp[i]->get_cta_id() == m_warp[warp_id]->get_cta_id())
              m_simt_tables[i]->release_barrier();
          }
        }
      }
    }
  } else if (next_inst->op == MEMORY_BARRIER_OP) {
    const bool initial_rt_publication =
        m_warp[warp_id]->claim_rtcore_v04_initial_publication_fence(
            next_inst->pc);
    rtcore::v04::pre_submit_publication::
        live_publication_round_request_v0 live_round = {};
    const bool live_rt_publication =
        rtcore_claim_shader_continuation_live_publication_fence(
            m_gpu->gpgpu_ctx, m_sid, warp_id,
            m_warp[warp_id]->get_dynamic_warp_id(), next_inst->pc,
            &live_round);
    if (initial_rt_publication && live_rt_publication) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_LIVE_PUBLICATION_FAULT "
              "owner_hw_sid=%u warp_id=%u pc=0x%llx "
              "fault=initial_and_live_fence_alias\n",
              m_sid, warp_id,
              static_cast<unsigned long long>(next_inst->pc));
      abort();
    }
    m_warp[warp_id]->set_membar(
        initial_rt_publication,
        live_rt_publication ? &live_round : NULL);
  }

  updateSIMTDivergenceStructures(warp_id, *pipe_reg);
  if(m_gpu->simd_model() == AWARE_RECONVERGENCE) {
    update_table_stats(warp_id);
  }

  m_scoreboard->reserveRegisters(*pipe_reg);
  m_warp[warp_id]->set_next_pc(next_inst->pc + next_inst->isize);
  if(split_reaches_barrier) m_simt_tables[warp_id]->push_back();
}

void shader_core_ctx::updateSIMTDivergenceStructuresInitialization() {
 	unsigned n = m_config->n_thread_per_shader / m_config->warp_size;
 	for (unsigned i=0; i<n; i++) {
 		m_simt_tables[i]->set_shader(this);
 	}
}

