rt_unit::rt_unit(mem_fetch_interface *icnt,
                     shader_core_mem_fetch_allocator *mf_allocator,
                     shader_core_ctx *core,
                     opndcoll_rfu_t *operand_collector,
                     Scoreboard *scoreboard, 
                     const shader_core_config *config,
                     shader_core_stats *stats,
                     unsigned sid, unsigned tpc)
    : pipelined_simd_unit(NULL, config, (unsigned int)1, core) { // rt_unit::cycle() overrides the max latency hard coded here
    
  // m_memory_config = mem_config;
  m_icnt = icnt;
  m_mf_allocator = mf_allocator;  
  m_core = core;
  m_operand_collector = operand_collector;
  m_scoreboard = scoreboard;
  m_stats = stats;
  m_sid = sid;
  m_tpc = tpc;
  
  n_warps = 0;
  
  m_L0_complet = new read_only_cache( "L0Complet", m_config->m_L0C_config, m_sid,
                                      get_shader_constant_cache_id(), icnt, 
                                      IN_L1C_MISS_QUEUE);

  L1D = m_core->get_l1d();    

  ray_coherence_config coherence_config = config->m_rt_coherence_engine_config;
  coherence_config.warp_size = config->warp_size;
  m_ray_coherence_engine = new ray_coherence_engine(sid, coherence_config, m_stats->rt_coherence_stats[sid], core);

  m_mem_rc = NO_RC_FAIL;
  m_name = "RT_CORE";
  
}


bool rt_unit::can_issue(const warp_inst_t &inst) const {
  switch (inst.op) {
    case RT_CORE_OP:
      break;
    default:
      return false;
  }
  if (rtcore_retire_lifecycle_busy_for_owner(m_sid) &&
      inst.rt_subop != RT_CORE_SUBOP_RETIRE_CONTEXT) {
    return false;
  }
  if (!m_retire_transactions.empty()) return false;
  const bool resident_capacity_available =
      n_warps < m_config->m_rt_max_warps;
  if (!resident_capacity_available) return false;
  if (!rtcore_warp_completion_entry_has_capacity(inst)) return false;
  return m_dispatch_reg->empty() && !occupied.test(inst.latency);
}
        
void rt_unit::issue(register_set &reg_set) {
  warp_inst_t *inst = *(reg_set.get_ready());
  inst->op_pipe = MEM__OP;
  pipelined_simd_unit::issue(reg_set);
  m_core->rt_mem_instruction_stats(*inst);
}

unsigned rt_unit::active_warps() {
  std::set<unsigned> warp_ids;
  for (auto it=m_current_warps.begin(); it!=m_current_warps.end(); it++) {
    unsigned warp_id = it->second.get_warp_id();
    warp_ids.insert(warp_id);
  }
  return warp_ids.size();
}

rtcore_resident_warp_demand_snapshot
rt_unit::rtcore_make_resident_warp_demand_snapshot(
    unsigned rt_core_out_pending_warps) const {
  rtcore_resident_warp_demand_snapshot snapshot;
  snapshot.live_rt_unit_warps = n_warps;
  snapshot.dispatch_pending_warps = m_dispatch_reg->empty() ? 0 : 1;
  snapshot.rt_core_out_pending_warps = rt_core_out_pending_warps;
  snapshot.resident_live_warps =
      snapshot.live_rt_unit_warps + snapshot.dispatch_pending_warps +
      snapshot.rt_core_out_pending_warps;
  snapshot.resident_rt_warp_capacity = m_config->m_rt_max_warps;
  snapshot.resident_live_plus_demand_warps =
      snapshot.resident_live_warps + 1;
  snapshot.zero_capacity_fail_closed =
      snapshot.resident_rt_warp_capacity == 0;
  snapshot.capacity_available =
      snapshot.zero_capacity_fail_closed ||
      snapshot.resident_live_warps < snapshot.resident_rt_warp_capacity;
  return snapshot;
}

bool rt_unit::rtcore_resident_warp_capacity_available(
    const warp_inst_t &inst, unsigned warp_id, unsigned owner_hw_sid,
    unsigned long long static_inst_pc,
    const rtcore_resident_warp_demand_snapshot &snapshot,
    const rtcore_resident_gate_materialized_input_provenance_snapshot
        &materialized_input_provenance) const {
  if (inst.op != RT_CORE_OP || inst.rt_subop != RT_CORE_SUBOP_SUBMIT) {
    return true;
  }
  if (snapshot.zero_capacity_fail_closed) {
    return true;
  }
  rtcore_v04_multiwarp_record_admission_probe(
      owner_hw_sid, snapshot.resident_live_warps,
      snapshot.resident_rt_warp_capacity, snapshot.capacity_available);
  if (!snapshot.capacity_available) {
    printf("GPGPU-Sim PTX: RT_SUBMIT resident-warp-backpressure, "
           "diagnostic=RT_SUBMIT issue-resource-snapshot, warp_id=%u, "
           "owner_hw_sid=%u, static_inst_pc=0x%llx, "
           "resident_live_warps=%u, resident_rt_warp_capacity=%u, "
           "resident_dispatch_pending_warps=%u, "
           "resident_rt_core_out_pending_warps=%u, "
           "resident_live_plus_demand_warps=%u, "
           "capacity_available=0, action=stall, "
           "scheduler_credit_ledger_reusable_credit_resident_gate_materialized_input_provenance=1, "
           "resident_gate_materialized_input_provenance_available=%u, "
           "has_provider_materialized_traversal_input_snapshot=%u, "
           "provider_materialized_traversal_input_snapshot_valid=%u, "
           "provider_materialized_traversal_input_snapshot_source=%s, "
           "provider_materialized_traversal_input_actual_abi_snapshot_admitted=%u, "
           "provider_materialized_traversal_input_decoded_value_record_valid=%u, "
           "provider_materialized_traversal_input_decoded_value_record_source=%s, "
           "provider_materialized_traversal_input_decoded_value_record_consumed=%u, "
           "provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid=%u, "
           "provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted=%u, "
           "provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed=%u, "
           "provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason=%s, "
           "resident_gate_materialized_input_consumes_capacity_decision=0, "
           "resident_gate_materialized_input_consumes_backpressure_behavior=0, "
           "resident_gate_decoded_value_record_source_snapshot_consumes_capacity_decision=0, "
           "resident_gate_decoded_value_record_source_snapshot_consumes_backpressure_behavior=0\n",
           warp_id, owner_hw_sid, static_inst_pc,
           snapshot.resident_live_warps, snapshot.resident_rt_warp_capacity,
           snapshot.dispatch_pending_warps,
           snapshot.rt_core_out_pending_warps,
           snapshot.resident_live_plus_demand_warps,
           materialized_input_provenance.available ? 1 : 0,
           materialized_input_provenance
                   .has_provider_materialized_traversal_input_snapshot
               ? 1
               : 0,
           materialized_input_provenance
                   .provider_materialized_traversal_input_snapshot_valid
               ? 1
               : 0,
           materialized_input_provenance
               .provider_materialized_traversal_input_snapshot_source,
           materialized_input_provenance
                   .provider_materialized_traversal_input_actual_abi_snapshot_admitted
               ? 1
               : 0,
           materialized_input_provenance
                   .provider_materialized_traversal_input_decoded_value_record_valid
               ? 1
               : 0,
           materialized_input_provenance
               .provider_materialized_traversal_input_decoded_value_record_source,
           materialized_input_provenance
                   .provider_materialized_traversal_input_decoded_value_record_consumed
               ? 1
               : 0,
           materialized_input_provenance
                   .provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid
               ? 1
               : 0,
           materialized_input_provenance
                   .provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted
               ? 1
               : 0,
           materialized_input_provenance
                   .provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed
               ? 1
               : 0,
           materialized_input_provenance
               .provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason);
    fflush(stdout);
    return false;
  }
  return true;
}

struct rtcore_warp_completion_entry_reservation_key {
  unsigned owner_hw_sid;
  unsigned warp_id;
  unsigned long long static_inst_pc;
  unsigned issued_active_mask;

  bool operator<(const rtcore_warp_completion_entry_reservation_key &other) const {
    if (owner_hw_sid != other.owner_hw_sid) {
      return owner_hw_sid < other.owner_hw_sid;
    }
    if (warp_id != other.warp_id) {
      return warp_id < other.warp_id;
    }
    if (static_inst_pc != other.static_inst_pc) {
      return static_inst_pc < other.static_inst_pc;
    }
    return issued_active_mask < other.issued_active_mask;
  }
};

static std::map<unsigned, unsigned> g_rtcore_warp_completion_entry_inflight_by_sm;
static std::set<rtcore_warp_completion_entry_reservation_key>
    g_rtcore_warp_completion_entry_reservations;

static rtcore_warp_completion_entry_reservation_key
rtcore_make_warp_completion_entry_reservation_key(
    unsigned owner_hw_sid, unsigned warp_id,
    unsigned long long static_inst_pc, unsigned issued_active_mask) {
  rtcore_warp_completion_entry_reservation_key key;
  key.owner_hw_sid = owner_hw_sid;
  key.warp_id = warp_id;
  key.static_inst_pc = static_inst_pc;
  key.issued_active_mask = issued_active_mask;
  return key;
}

static unsigned rtcore_warp_completion_entry_reservation_count(
    unsigned owner_hw_sid) {
  unsigned count = 0;
  for (std::set<rtcore_warp_completion_entry_reservation_key>::const_iterator it =
           g_rtcore_warp_completion_entry_reservations.begin();
       it != g_rtcore_warp_completion_entry_reservations.end(); ++it) {
    if (it->owner_hw_sid == owner_hw_sid) {
      count++;
    }
  }
  return count;
}

static bool rtcore_warp_completion_entry_reservation_contains(
    unsigned owner_hw_sid, unsigned warp_id,
    unsigned long long static_inst_pc, unsigned issued_active_mask) {
  const rtcore_warp_completion_entry_reservation_key key =
      rtcore_make_warp_completion_entry_reservation_key(
          owner_hw_sid, warp_id, static_inst_pc, issued_active_mask);
  return g_rtcore_warp_completion_entry_reservations.find(key) !=
         g_rtcore_warp_completion_entry_reservations.end();
}

static bool rtcore_warp_completion_entry_reservation_insert(
    unsigned owner_hw_sid, unsigned warp_id,
    unsigned long long static_inst_pc, unsigned issued_active_mask) {
  const rtcore_warp_completion_entry_reservation_key key =
      rtcore_make_warp_completion_entry_reservation_key(
          owner_hw_sid, warp_id, static_inst_pc, issued_active_mask);
  return g_rtcore_warp_completion_entry_reservations.insert(key).second;
}

static bool rtcore_warp_completion_entry_reservation_remove(
    unsigned owner_hw_sid, unsigned warp_id,
    unsigned long long static_inst_pc, unsigned issued_active_mask) {
  const rtcore_warp_completion_entry_reservation_key key =
      rtcore_make_warp_completion_entry_reservation_key(
          owner_hw_sid, warp_id, static_inst_pc, issued_active_mask);
  return g_rtcore_warp_completion_entry_reservations.erase(key) != 0;
}

unsigned rt_unit::rtcore_synthetic_completion_latency() const {
  const char *value = getenv("VULKAN_SIM_RTCORE_SYNTHETIC_COMPLETION_LATENCY");
  if (value == NULL || *value == '\0') {
    return 1;
  }

  char *end = NULL;
  const unsigned long parsed = strtoul(value, &end, 10);
  if (end == value || *end != '\0' || parsed == 0) {
    return 1;
  }
  if (parsed > UINT_MAX) {
    return UINT_MAX;
  }
  return (unsigned)parsed;
}

unsigned rt_unit::rtcore_warp_completion_entry_capacity() const {
  const char *value =
      getenv("VULKAN_SIM_RTCORE_REPLAY_WARP_COMPLETION_ENTRY_CAPACITY");
  if (value == NULL || *value == '\0') {
    return 8;
  }

  char *end = NULL;
  const unsigned long parsed = strtoul(value, &end, 10);
  if (end == value || *end != '\0' || parsed == 0) {
    return 8;
  }
  if (parsed > UINT_MAX) {
    return UINT_MAX;
  }
  return (unsigned)parsed;
}

unsigned rt_unit::rtcore_warp_completion_entry_inflight() const {
  std::map<unsigned, unsigned>::const_iterator it =
      g_rtcore_warp_completion_entry_inflight_by_sm.find(m_sid);
  if (it == g_rtcore_warp_completion_entry_inflight_by_sm.end()) {
    return 0;
  }
  return it->second;
}

rt_unit::rtcore_warp_completion_entry_state_snapshot
rt_unit::rtcore_make_warp_completion_entry_state_snapshot(
    const warp_inst_t &inst, rtcore_warp_completion_entry_action action) const {
  rtcore_warp_completion_entry_state_snapshot snapshot;
  snapshot.action = action;
  snapshot.submit = inst.rt_subop == RT_CORE_SUBOP_SUBMIT;
  snapshot.capacity = rtcore_warp_completion_entry_capacity();
  snapshot.inflight = rtcore_warp_completion_entry_inflight();
  snapshot.reserved =
      rtcore_warp_completion_entry_reservation_count(m_sid);
  snapshot.owner_hw_sid = m_sid;
  snapshot.warp_uid = inst.empty() ? 0 : inst.get_uid();
  snapshot.warp_id = inst.empty() ? 0 : inst.warp_id();
  snapshot.static_inst_pc = inst.pc;
  snapshot.issued_active_mask =
      inst.empty() ? 0 : static_cast<unsigned>(
                            inst.get_warp_active_mask().to_ulong());
  snapshot.has_reservation = rtcore_warp_completion_entry_reservation_contains(
      snapshot.owner_hw_sid, snapshot.warp_id,
      snapshot.static_inst_pc, snapshot.issued_active_mask);
  snapshot.live_plus_reserved = snapshot.inflight + snapshot.reserved;
  snapshot.capacity_enabled = snapshot.capacity != 0;
  snapshot.capacity_available =
      !snapshot.submit || !snapshot.capacity_enabled ||
      snapshot.has_reservation ||
      snapshot.live_plus_reserved < snapshot.capacity;
  return snapshot;
}

void rt_unit::rtcore_apply_warp_completion_entry_state_snapshot(
    const rtcore_warp_completion_entry_state_snapshot &snapshot) {
  if (!snapshot.submit) {
    return;
  }
  if (snapshot.action == RTCORE_WARP_COMPLETION_ENTRY_ACTION_ENQUEUE) {
    if (snapshot.has_reservation) {
      rtcore_warp_completion_entry_reservation_remove(
          snapshot.owner_hw_sid, snapshot.warp_id,
          snapshot.static_inst_pc, snapshot.issued_active_mask);
    }
    g_rtcore_warp_completion_entry_inflight_by_sm[snapshot.owner_hw_sid]++;
  } else if (snapshot.action == RTCORE_WARP_COMPLETION_ENTRY_ACTION_RETIRE) {
    std::map<unsigned, unsigned>::iterator inflight =
        g_rtcore_warp_completion_entry_inflight_by_sm.find(
            snapshot.owner_hw_sid);
    if (inflight != g_rtcore_warp_completion_entry_inflight_by_sm.end() &&
        inflight->second > 0) {
      inflight->second--;
    }
  }
}

bool rt_unit::rtcore_warp_completion_entry_reserve_issue_slot(
    const warp_inst_t &inst, unsigned warp_id, unsigned owner_hw_sid,
    unsigned long long static_inst_pc, unsigned issued_active_mask,
    const rtcore_warp_completion_entry_gate_materialized_input_provenance_snapshot
        &materialized_input_provenance) const {
  rtcore_warp_completion_entry_state_snapshot snapshot =
      rtcore_make_warp_completion_entry_state_snapshot(
          inst, RTCORE_WARP_COMPLETION_ENTRY_ACTION_RESERVE);
  snapshot.owner_hw_sid = owner_hw_sid;
  snapshot.warp_id = warp_id;
  snapshot.static_inst_pc = static_inst_pc;
  snapshot.issued_active_mask = issued_active_mask;
  snapshot.reserved =
      rtcore_warp_completion_entry_reservation_count(snapshot.owner_hw_sid);
  snapshot.has_reservation = rtcore_warp_completion_entry_reservation_contains(
      snapshot.owner_hw_sid, snapshot.warp_id,
      snapshot.static_inst_pc, snapshot.issued_active_mask);
  snapshot.live_plus_reserved = snapshot.inflight + snapshot.reserved;
  snapshot.capacity_available =
      !snapshot.submit || !snapshot.capacity_enabled ||
      snapshot.has_reservation ||
      snapshot.live_plus_reserved < snapshot.capacity;

  if (snapshot.capacity_available) {
    if (snapshot.submit && snapshot.capacity_enabled &&
        !snapshot.has_reservation) {
      rtcore_warp_completion_entry_reservation_insert(
          snapshot.owner_hw_sid, snapshot.warp_id,
          snapshot.static_inst_pc, snapshot.issued_active_mask);
    }
    return true;
  }

  printf("GPGPU-Sim PTX: RT-unit warp-completion-entry-issue-backpressure, "
         "warp_uid=%u, warp_id=%u, owner_hw_sid=%u, "
         "static_inst_pc=%llu, issued_active_mask=0x%08x, "
         "inflight=%u, reserved=%u, capacity=%u, "
         "capacity_available=0, action=stall, "
         "scheduler_credit_ledger_reusable_credit_warp_completion_entry_gate_materialized_input_provenance=1, "
         "warp_completion_entry_gate_materialized_input_provenance_available=%u, "
         "has_provider_materialized_traversal_input_snapshot=%u, "
         "provider_materialized_traversal_input_snapshot_valid=%u, "
         "provider_materialized_traversal_input_snapshot_source=%s, "
         "provider_materialized_traversal_input_actual_abi_snapshot_admitted=%u, "
         "provider_materialized_traversal_input_decoded_value_record_valid=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source=%s, "
         "provider_materialized_traversal_input_decoded_value_record_consumed=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason=%s, "
         "warp_completion_entry_gate_materialized_input_consumes_capacity_decision=0, "
         "warp_completion_entry_gate_materialized_input_consumes_reservation_behavior=0, "
         "warp_completion_entry_gate_decoded_value_record_source_snapshot_consumes_capacity_decision=0, "
         "warp_completion_entry_gate_decoded_value_record_source_snapshot_consumes_reservation_behavior=0\n",
         snapshot.warp_uid, snapshot.warp_id, snapshot.owner_hw_sid,
         snapshot.static_inst_pc, snapshot.issued_active_mask,
         snapshot.inflight, snapshot.reserved, snapshot.capacity,
         materialized_input_provenance.available ? 1 : 0,
         materialized_input_provenance
                 .has_provider_materialized_traversal_input_snapshot
             ? 1
             : 0,
         materialized_input_provenance
                 .provider_materialized_traversal_input_snapshot_valid
             ? 1
             : 0,
         materialized_input_provenance
             .provider_materialized_traversal_input_snapshot_source,
         materialized_input_provenance
                 .provider_materialized_traversal_input_actual_abi_snapshot_admitted
             ? 1
             : 0,
         materialized_input_provenance
                 .provider_materialized_traversal_input_decoded_value_record_valid
             ? 1
             : 0,
         materialized_input_provenance
             .provider_materialized_traversal_input_decoded_value_record_source,
         materialized_input_provenance
                 .provider_materialized_traversal_input_decoded_value_record_consumed
             ? 1
             : 0,
         materialized_input_provenance
                 .provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid
             ? 1
             : 0,
         materialized_input_provenance
                 .provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted
             ? 1
             : 0,
         materialized_input_provenance
                 .provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed
             ? 1
             : 0,
         materialized_input_provenance
             .provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason);
  fflush(stdout);
  return false;
}

void rt_unit::rtcore_record_warp_completion_entry_enqueue(
    const warp_inst_t &inst) {
  const rtcore_warp_completion_entry_state_snapshot snapshot =
      rtcore_make_warp_completion_entry_state_snapshot(
          inst, RTCORE_WARP_COMPLETION_ENTRY_ACTION_ENQUEUE);
  rtcore_apply_warp_completion_entry_state_snapshot(snapshot);
}

void rt_unit::rtcore_record_warp_completion_entry_retire(const warp_inst_t &inst) {
  const rtcore_warp_completion_entry_state_snapshot snapshot =
      rtcore_make_warp_completion_entry_state_snapshot(
          inst, RTCORE_WARP_COMPLETION_ENTRY_ACTION_RETIRE);
  rtcore_apply_warp_completion_entry_state_snapshot(snapshot);
}

bool rt_unit::rtcore_warp_completion_entry_has_capacity(
    const warp_inst_t &inst) const {
  const rtcore_warp_completion_entry_state_snapshot snapshot =
      rtcore_make_warp_completion_entry_state_snapshot(
          inst, RTCORE_WARP_COMPLETION_ENTRY_ACTION_CAPACITY_CHECK);
  if (snapshot.has_reservation) {
    return true;
  }
  if (snapshot.capacity_available) {
    return true;
  }

  printf("GPGPU-Sim PTX: RT-unit warp-completion-entry-backpressure, "
         "warp_uid=%u, warp_id=%u, inflight=%u, capacity=%u, "
         "capacity_available=0, action=stall\n",
         inst.get_uid(), inst.warp_id(), snapshot.inflight,
         snapshot.capacity);
  fflush(stdout);
  return false;
}

bool rt_unit::rtcore_existing_backend_latency_resource_binding_enabled() const {
  const char *value =
      getenv("VULKAN_SIM_RTCORE_EXISTING_BACKEND_LATENCY_RESOURCE_BINDING");
  if (value == NULL || *value == '\0') {
    return true;
  }
  return strcmp(value, "0") != 0 && strcmp(value, "false") != 0 &&
         strcmp(value, "off") != 0 && strcmp(value, "no") != 0;
}

bool rt_unit::rtcore_stats_completion_latency_enabled() const {
  const char *value = getenv("VULKAN_SIM_RTCORE_STATS_COMPLETION_LATENCY");
  if (value == NULL || *value == '\0') {
    return rtcore_existing_backend_latency_resource_binding_enabled();
  }
  return strcmp(value, "0") != 0 && strcmp(value, "false") != 0 &&
         strcmp(value, "off") != 0 && strcmp(value, "no") != 0;
}

unsigned rt_unit::rtcore_stats_latency_base() const {
  const char *value = getenv("VULKAN_SIM_RTCORE_STATS_LATENCY_BASE");
  if (value == NULL || *value == '\0') {
    return rtcore_synthetic_completion_latency();
  }

  char *end = NULL;
  const unsigned long parsed = strtoul(value, &end, 10);
  if (end == value || *end != '\0' || parsed == 0) {
    return rtcore_synthetic_completion_latency();
  }
  if (parsed > UINT_MAX) {
    return UINT_MAX;
  }
  return (unsigned)parsed;
}

