static unsigned rtcore_count_active_mask_lanes(unsigned active_mask) {
  unsigned count = 0;
  while (active_mask != 0) {
    count += active_mask & 1u;
    active_mask >>= 1;
  }
  return count;
}

static const unsigned RTCORE_REPLAY_COMPLETION_PACKET_SCHEMA_VERSION = 3;
static const unsigned RTCORE_V03_CONTEXT_LAYOUT_VERSION = 1;
static const unsigned RTCORE_V03_CONTEXT_TRACE_INPUT_VALID = 1;
static const unsigned RTCORE_V03_PIPELINE_PROFILE_ID = 1;
static const unsigned RTCORE_V03_BVH_FORMAT_PROFILE_ID = 1;
static const unsigned RTCORE_V03_INLINE_PAYLOAD_BASE_WORD = 16;
static const unsigned RTCORE_V03_MAX_INLINE_ATTRIBUTE_WORDS = 4;

static void rtcore_set_completion_packet_failure_reason(
    const char **failure_reason, const char *reason) {
  if (failure_reason != NULL) {
    *failure_reason = reason;
  }
}

static bool rtcore_decode_v04_shadow_boundary_values(
    const std::array<uint32_t, rtcore::abi_v04::kWordCount> &words,
    unsigned reason, rtcore::abi_v04::shadow::boundary_values *values);

static bool rtcore_validate_replay_completion_packet(
    const rtcore_replay_warp_completion_entry_snapshot &snapshot,
    unsigned expected_owner_hw_sid, unsigned expected_warp_uid,
    unsigned expected_warp_id, unsigned expected_active_mask,
    const char **failure_reason) {
  if (failure_reason != NULL) {
    *failure_reason = NULL;
  }
  if (snapshot.v04_native_resident_completion &&
      snapshot.v04_functional_only_completion) {
    rtcore_set_completion_packet_failure_reason(
        failure_reason, "multiple_v04_completion_sources");
    return false;
  }
  if (snapshot.owner_hw_sid != expected_owner_hw_sid ||
      snapshot.warp_uid != expected_warp_uid ||
      snapshot.warp_id != expected_warp_id ||
      snapshot.active_mask != expected_active_mask) {
    rtcore_set_completion_packet_failure_reason(failure_reason,
                                                "packet_key_mismatch");
    return false;
  }
  if (rtcore_v04_direct_completion(snapshot)) {
    if (snapshot.packet_schema_version !=
            RTCORE_REPLAY_COMPLETION_PACKET_SCHEMA_VERSION ||
        expected_active_mask == 0 ||
        snapshot.lane_completion_valid_mask != expected_active_mask ||
        snapshot.completed_lane_mask != expected_active_mask ||
        snapshot.result_valid_mask != expected_active_mask ||
        snapshot.admitted_lane_mask != expected_active_mask ||
        snapshot.v04_shadow_boundary_image_valid_mask !=
            expected_active_mask ||
        (snapshot.terminal_lane_mask &
         snapshot.continuation_lane_mask) != 0 ||
        (snapshot.terminal_lane_mask |
         snapshot.continuation_lane_mask) != expected_active_mask ||
        snapshot.unsupported_reason_mask != 0 ||
        snapshot.handoff_selector_valid_mask != expected_active_mask ||
        snapshot.v04_native_identity_valid_mask != expected_active_mask ||
        snapshot.v04_native_resident_generation == 0 ||
        snapshot.v04_native_completion_transaction_generation == 0 ||
        snapshot.handoff_software_return_valid_mask != 0 ||
        !snapshot.scoreboard_handoff_delivered) {
      rtcore_set_completion_packet_failure_reason(
          failure_reason, "native_packet_masks_or_delivery");
      return false;
    }
    for (unsigned lane = 0; lane < 32; ++lane) {
      const unsigned lane_mask = 1u << lane;
      if ((expected_active_mask & lane_mask) == 0) continue;
      const unsigned result = snapshot.result_data_slot[lane];
      const unsigned reason = result & 0xffu;
      const bool terminal =
          reason == RTCORE_SHADER_CONTINUATION_REASON_MISS ||
          reason ==
              RTCORE_SHADER_CONTINUATION_REASON_CLOSEST_HIT_READY;
      const bool continuation =
          reason == RTCORE_SHADER_CONTINUATION_REASON_ANY_HIT_REQUIRED ||
          reason ==
              RTCORE_SHADER_CONTINUATION_REASON_INTERSECTION_REQUIRED;
      const bool candidate_required =
          reason != RTCORE_SHADER_CONTINUATION_REASON_MISS;
      if ((result & 0x80000000u) == 0 ||
          (result & 0x7fffff00u) != 0 ||
          (!terminal && !continuation) ||
          snapshot.lane_completion_reason[lane] != reason ||
          candidate_required !=
              ((snapshot.handoff_candidate_valid_mask & lane_mask) != 0) ||
          terminal !=
              ((snapshot.terminal_lane_mask & lane_mask) != 0) ||
          continuation !=
              ((snapshot.continuation_lane_mask & lane_mask) != 0)) {
        rtcore_set_completion_packet_failure_reason(
            failure_reason, "native_packet_result_or_reason");
        return false;
      }
      if (snapshot.v04_native_context_ptr[lane] == 0 ||
          snapshot.v04_native_handoff_window_base[lane] == 0 ||
          snapshot.v04_native_token_id[lane] == 0 ||
          snapshot.v04_native_token_allocator_generation[lane] == 0 ||
          snapshot.v04_native_window_generation[lane] == 0 ||
          snapshot.v04_native_packed_request_key[lane] == 0 ||
          snapshot.v04_native_request_generation[lane] == 0) {
        rtcore_set_completion_packet_failure_reason(
            failure_reason, "native_packet_resident_identity");
        return false;
      }
      std::array<uint32_t, rtcore::abi_v04::kWordCount> words = {};
      for (unsigned word = 0;
           word < rtcore::abi_v04::kWordCount; ++word) {
        words[word] =
            snapshot.v04_shadow_handoff_words[lane][word];
      }
      rtcore::abi_v04::shadow::boundary_values values;
      if (!rtcore_decode_v04_shadow_boundary_values(
              words, reason, &values) ||
          !rtcore::abi_v04::validate_reserved_zero(words) ||
          !rtcore::abi_v04::shadow::validate_boundary_publication(
               words, words, reason, values).matches()) {
        rtcore_set_completion_packet_failure_reason(
            failure_reason, "native_packet_handoff_encoding");
        return false;
      }
      const uint64_t selector =
          reason == RTCORE_SHADER_CONTINUATION_REASON_MISS
              ? rtcore::abi_v04::extract_field(
                    words, rtcore::abi_v04::kMissIndex)
              : static_cast<uint64_t>(rtcore::abi_v04::extract_field(
                    words,
                    rtcore::abi_v04::kInstanceSbtContribution)) +
                    static_cast<uint64_t>(
                        rtcore::abi_v04::extract_field(
                            words, rtcore::abi_v04::kGeometryIndex)) *
                        rtcore::abi_v04::extract_field(
                            words, rtcore::abi_v04::kSbtRecordStride) +
                    rtcore::abi_v04::extract_field(
                        words, rtcore::abi_v04::kSbtRecordOffset);
      if (selector > UINT_MAX) {
        rtcore_set_completion_packet_failure_reason(
            failure_reason, "native_packet_sbt_selector_overflow");
        return false;
      }
    }
    return true;
  }
  if (snapshot.packet_schema_version !=
      RTCORE_REPLAY_COMPLETION_PACKET_SCHEMA_VERSION) {
    rtcore_set_completion_packet_failure_reason(failure_reason,
                                                "packet_schema_mismatch");
    return false;
  }
  if (expected_active_mask == 0 ||
      snapshot.lane_completion_valid_mask != expected_active_mask ||
      snapshot.completed_lane_mask != expected_active_mask ||
      snapshot.result_valid_mask != expected_active_mask ||
      snapshot.admitted_lane_mask != expected_active_mask) {
    rtcore_set_completion_packet_failure_reason(failure_reason,
                                                "packet_completion_mask");
    return false;
  }
  if ((snapshot.terminal_lane_mask & snapshot.continuation_lane_mask) != 0 ||
      (snapshot.terminal_lane_mask | snapshot.continuation_lane_mask) !=
          expected_active_mask ||
      snapshot.unsupported_reason_mask != 0) {
    rtcore_set_completion_packet_failure_reason(failure_reason,
                                                "packet_reason_masks");
    return false;
  }
  if (snapshot.context_profile_valid_mask != expected_active_mask) {
    rtcore_set_completion_packet_failure_reason(failure_reason,
                                                "packet_profile_mask");
    return false;
  }
  const unsigned packet_side_masks =
      snapshot.handoff_selector_valid_mask |
      snapshot.handoff_candidate_valid_mask |
      snapshot.handoff_software_return_valid_mask |
      snapshot.reported_attribute_metadata_valid_mask |
      snapshot.inline_payload_location_valid_mask;
  if ((packet_side_masks & ~expected_active_mask) != 0 ||
      (snapshot.inline_payload_location_valid_mask &
       ~snapshot.reported_attribute_metadata_valid_mask) != 0 ||
      snapshot.inline_payload_base_word !=
          RTCORE_V03_INLINE_PAYLOAD_BASE_WORD ||
      snapshot.max_inline_attribute_words !=
          RTCORE_V03_MAX_INLINE_ATTRIBUTE_WORDS) {
    rtcore_set_completion_packet_failure_reason(failure_reason,
                                                "packet_handoff_masks");
    return false;
  }

  unsigned selector_required_mask = 0;
  unsigned candidate_required_mask = 0;
  for (unsigned lane = 0; lane < 32; ++lane) {
    const unsigned lane_mask = 1u << lane;
    if ((expected_active_mask & lane_mask) == 0) {
      continue;
    }
    const unsigned reason = snapshot.lane_completion_reason[lane];
    if (reason == RTCORE_SHADER_CONTINUATION_REASON_MISS ||
        reason == RTCORE_SHADER_CONTINUATION_REASON_CLOSEST_HIT_READY ||
        reason == RTCORE_SHADER_CONTINUATION_REASON_ANY_HIT_REQUIRED ||
        reason == RTCORE_SHADER_CONTINUATION_REASON_INTERSECTION_REQUIRED) {
      selector_required_mask |= lane_mask;
    }
    if (reason == RTCORE_SHADER_CONTINUATION_REASON_CLOSEST_HIT_READY ||
        reason == RTCORE_SHADER_CONTINUATION_REASON_ANY_HIT_REQUIRED ||
        reason == RTCORE_SHADER_CONTINUATION_REASON_INTERSECTION_REQUIRED) {
      candidate_required_mask |= lane_mask;
    }
  }
  if (snapshot.handoff_selector_valid_mask != selector_required_mask ||
      snapshot.handoff_candidate_valid_mask != candidate_required_mask) {
    rtcore_set_completion_packet_failure_reason(failure_reason,
                                                "packet_dependent_facts");
    return false;
  }
  if ((snapshot.handoff_software_return_valid_mask &
       ~snapshot.continuation_lane_mask) != 0) {
    rtcore_set_completion_packet_failure_reason(
        failure_reason, "packet_software_return_mask");
    return false;
  }

  for (unsigned lane = 0; lane < 32; ++lane) {
    const unsigned lane_mask = 1u << lane;
    if ((expected_active_mask & lane_mask) == 0) {
      continue;
    }
    const unsigned v_result = snapshot.result_data_slot[lane];
    const unsigned reason = v_result & 0xffu;
    if ((v_result & 0x80000000u) == 0 ||
        (v_result & 0x7fffff00u) != 0 || reason == 0 || reason > 7 ||
        snapshot.lane_completion_reason[lane] != reason) {
      rtcore_set_completion_packet_failure_reason(failure_reason,
                                                  "packet_v_result");
      return false;
    }
    if (snapshot.context_layout_version[lane] !=
            RTCORE_V03_CONTEXT_LAYOUT_VERSION ||
        (snapshot.context_valid_flags[lane] &
         RTCORE_V03_CONTEXT_TRACE_INPUT_VALID) == 0 ||
        (snapshot.context_valid_flags[lane] & ~0x07u) != 0 ||
        snapshot.pipeline_profile_id[lane] !=
            RTCORE_V03_PIPELINE_PROFILE_ID ||
        snapshot.bvh_format_profile_id[lane] !=
            RTCORE_V03_BVH_FORMAT_PROFILE_ID) {
      rtcore_set_completion_packet_failure_reason(failure_reason,
                                                  "packet_context_profile");
      return false;
    }

    const bool terminal_reason =
        reason == RTCORE_SHADER_CONTINUATION_REASON_MISS ||
        reason == RTCORE_SHADER_CONTINUATION_REASON_CLOSEST_HIT_READY ||
        reason == RTCORE_SHADER_CONTINUATION_REASON_TRACE_DONE_NO_SHADER;
    const bool continuation_reason =
        reason == RTCORE_SHADER_CONTINUATION_REASON_ANY_HIT_REQUIRED ||
        reason == RTCORE_SHADER_CONTINUATION_REASON_INTERSECTION_REQUIRED;
    if ((terminal_reason !=
         ((snapshot.terminal_lane_mask & lane_mask) != 0)) ||
        (continuation_reason !=
         ((snapshot.continuation_lane_mask & lane_mask) != 0)) ||
        reason == RTCORE_SHADER_CONTINUATION_REASON_FAULT ||
        reason == RTCORE_SHADER_CONTINUATION_REASON_UNSUPPORTED) {
      rtcore_set_completion_packet_failure_reason(failure_reason,
                                                  "packet_reason_class");
      return false;
    }
    if ((snapshot.reported_attribute_metadata_valid_mask & lane_mask) != 0) {
      const unsigned metadata = snapshot.handoff_words[lane][15];
      const unsigned word_count = (metadata >> 8) & 0xffu;
      const unsigned base_word = (metadata >> 16) & 0xffu;
      const unsigned format = (metadata >> 24) & 0xffu;
      if (reason != RTCORE_SHADER_CONTINUATION_REASON_INTERSECTION_REQUIRED ||
          (snapshot.handoff_software_return_valid_mask & lane_mask) == 0 ||
          word_count == 0 ||
          word_count > snapshot.max_inline_attribute_words ||
          base_word != snapshot.inline_payload_base_word || format != 2 ||
          (snapshot.inline_payload_location_valid_mask & lane_mask) == 0) {
        rtcore_set_completion_packet_failure_reason(
            failure_reason, "packet_reported_attribute_metadata");
        return false;
      }
    }
  }
  return true;
}

static void rtcore_log_v04_completion_boundary(
    const rtcore_replay_warp_completion_entry_snapshot &snapshot,
    unsigned long long observation_cycle) {
  if (!rtcore_v04_direct_completion(snapshot)) return;

  const char *driver =
      snapshot.v04_functional_only_completion ? "functional_only" : "timing";
  for (unsigned lane = 0; lane < 32; ++lane) {
    const unsigned lane_mask = 1u << lane;
    if ((snapshot.lane_completion_valid_mask & lane_mask) == 0) continue;
    const bool terminal =
        (snapshot.terminal_lane_mask & lane_mask) != 0;
    printf("GPGPU-Sim RTCORE_V04_COMPLETION_BOUNDARY "
           "driver=%s owner_hw_sid=%u warp_uid=%u warp_id=%u "
           "lane_id=%u context_ptr=0x%llx "
           "handoff_window_base=0x%llx reason=%u decision=%s "
           "resident_generation=%u "
           "completion_transaction_generation=%u "
           "observation_cycle=%llu\n",
           driver, snapshot.owner_hw_sid, snapshot.warp_uid,
           snapshot.warp_id, lane,
           snapshot.v04_native_context_ptr[lane],
           snapshot.v04_native_handoff_window_base[lane],
           snapshot.lane_completion_reason[lane],
           terminal ? "terminal" : "continuation",
           snapshot.v04_native_resident_generation,
           snapshot.v04_native_completion_transaction_generation,
           observation_cycle);
  }
  fflush(stdout);
}

static bool rtcore_decode_v04_shadow_boundary_values(
    const std::array<uint32_t, rtcore::abi_v04::kWordCount> &words,
    unsigned reason, rtcore::abi_v04::shadow::boundary_values *values) {
  if (values == NULL) return false;
  *values = rtcore::abi_v04::shadow::boundary_values();
  if (reason == rtcore::abi_v04::kReasonMiss ||
      reason == rtcore::abi_v04::kReasonTraceDoneNoShader) {
    return true;
  }
  if (!rtcore::abi_v04::shadow::boundary_reason_has_candidate(reason)) {
    return false;
  }

  values->candidate_valid = true;
  values->instance_metadata_reference =
      static_cast<uint64_t>(rtcore::abi_v04::extract_field(
          words, rtcore::abi_v04::kInstanceMetadataReferenceLow32)) |
      (static_cast<uint64_t>(rtcore::abi_v04::extract_field(
           words, rtcore::abi_v04::kInstanceMetadataReferenceHigh32))
       << 32);
  values->instance_sbt_contribution = rtcore::abi_v04::extract_field(
      words, rtcore::abi_v04::kInstanceSbtContribution);
  values->geometry_index = rtcore::abi_v04::extract_field(
      words, rtcore::abi_v04::kGeometryIndex);
  values->boundary_ray_tmax_fp32 = rtcore::abi_v04::extract_field(
      words, rtcore::abi_v04::kBoundaryRayTmaxFp32);
  values->primitive_index = rtcore::abi_v04::extract_field(
      words, rtcore::abi_v04::kPrimitiveIndex);
  values->instance_index = rtcore::abi_v04::extract_field(
      words, rtcore::abi_v04::kInstanceIndex);
  values->instance_custom_index = rtcore::abi_v04::extract_field(
      words, rtcore::abi_v04::kInstanceCustomIndex);
  values->hit_kind = rtcore::abi_v04::extract_field(
      words, rtcore::abi_v04::kHitKind);
  values->input_attribute_word_count = rtcore::abi_v04::extract_field(
      words, rtcore::abi_v04::kInputAttributeWordCount);
  values->input_attribute_location = rtcore::abi_v04::extract_field(
      words, rtcore::abi_v04::kInputAttributeLocation);
  values->input_attribute_format = rtcore::abi_v04::extract_field(
      words, rtcore::abi_v04::kInputAttributeFormat);
  const rtcore::abi_v04::field_spec inline_attributes[] = {
      rtcore::abi_v04::kInlineAttributeWord0,
      rtcore::abi_v04::kInlineAttributeWord1,
      rtcore::abi_v04::kInlineAttributeWord2,
      rtcore::abi_v04::kInlineAttributeWord3,
  };
  for (unsigned word = 0; word < 4; ++word) {
    values->inline_attribute_words[word] =
        rtcore::abi_v04::extract_field(words, inline_attributes[word]);
  }

  if (reason == rtcore::abi_v04::kReasonAnyHitRequired) {
    values->geometry_type =
        rtcore::abi_v04::shadow::kBoundaryGeometryTriangle;
  } else if (reason == rtcore::abi_v04::kReasonIntersectionRequired) {
    values->geometry_type =
        rtcore::abi_v04::shadow::kBoundaryGeometryProcedural;
  } else {
    values->geometry_type =
        values->hit_kind == 0xfeu || values->hit_kind == 0xffu
            ? rtcore::abi_v04::shadow::kBoundaryGeometryTriangle
            : rtcore::abi_v04::shadow::kBoundaryGeometryProcedural;
  }
  return true;
}

static bool rtcore_validate_v04_shadow_completion_packet_image(
    const rtcore_replay_warp_completion_entry_snapshot &snapshot,
    unsigned expected_active_mask, const char **failure_reason) {
  const unsigned valid_mask =
      snapshot.v04_shadow_boundary_image_valid_mask;
  if ((valid_mask & ~expected_active_mask) != 0 ||
      (valid_mask != 0 && valid_mask != expected_active_mask)) {
    rtcore_set_completion_packet_failure_reason(
        failure_reason, "v04_shadow_boundary_image_mask");
    return false;
  }

  for (unsigned lane = 0; lane < 32; ++lane) {
    const unsigned lane_mask = 1u << lane;
    std::array<uint32_t, rtcore::abi_v04::kWordCount> words = {};
    bool all_zero = true;
    for (unsigned word = 0; word < rtcore::abi_v04::kWordCount; ++word) {
      words[word] = snapshot.v04_shadow_handoff_words[lane][word];
      all_zero = all_zero && words[word] == 0;
    }
    if ((valid_mask & lane_mask) == 0) {
      if (!all_zero) {
        rtcore_set_completion_packet_failure_reason(
            failure_reason, "v04_shadow_boundary_image_without_valid");
        return false;
      }
      continue;
    }

    const unsigned reason = snapshot.lane_completion_reason[lane];
    // The completion image is observed before the resumed shader executes.
    // A return consumer must arm exactly one sentinel for a shader boundary;
    // every other reason and every consumer-disabled path requires zero.
    const uint32_t unpublished_return_sentinel =
        rtcore::abi_v04::kReservedMasks[
            rtcore::abi_v04::kCommitRetainedCandidate.word];
    const uint32_t return_control =
        words[rtcore::abi_v04::kCommitRetainedCandidate.word];
    const bool return_consumer_enabled =
        rtcore_candidate_gate_state_for(
            "VULKAN_SIM_RTCORE_ABI_V04_SHADOW_SHADER_RETURN_CONSUMER") ==
        RTCORE_CANDIDATE_GATE_ENABLED;
    const bool shader_return_required =
        rtcore::abi_v04::shadow::
            shader_return_reason_requires_publication(reason);
    const uint32_t expected_return_control =
        return_consumer_enabled && shader_return_required
            ? unpublished_return_sentinel
            : 0u;
    if (return_control != expected_return_control ||
        words[rtcore::abi_v04::kReportedTFp32.word] != 0u ||
        words[rtcore::abi_v04::kReportedHitKind.word] != 0u) {
      rtcore_set_completion_packet_failure_reason(
          failure_reason, "v04_shadow_shader_return_prepublication");
      return false;
    }
    words[rtcore::abi_v04::kCommitRetainedCandidate.word] = 0u;

    rtcore::abi_v04::shadow::boundary_values values;
    if (!rtcore_decode_v04_shadow_boundary_values(words, reason, &values)) {
      rtcore_set_completion_packet_failure_reason(
          failure_reason, "v04_shadow_boundary_image_reason");
      return false;
    }
    const rtcore::abi_v04::shadow::boundary_validation validation =
        rtcore::abi_v04::shadow::validate_boundary_publication(
            words, words, reason, values);
    if (!rtcore::abi_v04::validate_reserved_zero(words) ||
        !validation.matches()) {
      rtcore_set_completion_packet_failure_reason(
          failure_reason, "v04_shadow_boundary_image_encoding");
      return false;
    }
  }
  return true;
}

static bool rtcore_observe_v04_shadow_completion_packet_image(
    const rtcore_replay_warp_completion_entry_snapshot &snapshot,
    unsigned expected_active_mask, unsigned long long current_cycle,
    const char **failure_reason) {
  if (!rtcore_validate_v04_shadow_completion_packet_image(
          snapshot, expected_active_mask, failure_reason)) {
    return false;
  }
  if (snapshot.v04_shadow_boundary_image_valid_mask == 0) {
    return true;
  }
  printf("GPGPU-Sim RTCORE_V04_SHADOW_COMPLETION_PACKET_IMAGE "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
         "image_valid_mask=0x%08x image_word_count=%u "
         "scoreboard_handoff_delivered=1 observation_cycle=%llu "
         "validation=valid observation_only=1 live_handoff_write=0 "
         "functional_authority=0 v03_completion_authority=1\n",
         snapshot.owner_hw_sid, snapshot.warp_uid, snapshot.warp_id,
         expected_active_mask, snapshot.v04_shadow_boundary_image_valid_mask,
         rtcore_count_active_mask_lanes(
             snapshot.v04_shadow_boundary_image_valid_mask) *
             rtcore::abi_v04::kWordCount,
         current_cycle);
  fflush(stdout);
  return true;
}

static void rtcore_apply_replay_completion_packet_test_corruption(
    rtcore_replay_warp_completion_entry_snapshot *snapshot) {
  const char *mode = getenv("VULKAN_SIM_RTCORE_TEST_PACKET_CORRUPTION");
  if (snapshot == NULL || mode == NULL || *mode == '\0') {
    return;
  }
  unsigned active_lane = 0;
  while (active_lane < 32 &&
         (snapshot->active_mask & (1u << active_lane)) == 0) {
    active_lane++;
  }
  if (strcmp(mode, "key") == 0) {
    snapshot->warp_uid++;
  } else if (strcmp(mode, "mask") == 0) {
    snapshot->lane_completion_valid_mask ^=
        active_lane < 32 ? (1u << active_lane) : 1u;
  } else if (strcmp(mode, "schema") == 0) {
    snapshot->packet_schema_version = 0;
  } else if (strcmp(mode, "layout") == 0) {
    if (active_lane < 32) {
      snapshot->context_layout_version[active_lane] = 0;
    }
  } else if (strcmp(mode, "profile") == 0) {
    if (active_lane < 32) {
      snapshot->pipeline_profile_id[active_lane] = 0;
    }
  } else if (strcmp(mode, "reason") == 0) {
    if (active_lane < 32) {
      snapshot->result_data_slot[active_lane] = 0x80000000u | 0xffu;
    }
  } else if (strcmp(mode, "software_return") == 0) {
    unsigned terminal_lane = active_lane;
    for (unsigned lane = 0; lane < 32; ++lane) {
      if ((snapshot->terminal_lane_mask & (1u << lane)) != 0) {
        terminal_lane = lane;
        break;
      }
    }
    if (terminal_lane < 32) {
      snapshot->handoff_software_return_valid_mask |= 1u << terminal_lane;
    }
  } else if (strcmp(mode, "v04_mask") == 0) {
    snapshot->v04_shadow_boundary_image_valid_mask ^=
        active_lane < 32 ? (1u << active_lane) : 1u;
  } else if (strcmp(mode, "v04_reserved") == 0) {
    unsigned image_lane = 0;
    while (image_lane < 32 &&
           (snapshot->v04_shadow_boundary_image_valid_mask &
            (1u << image_lane)) == 0) {
      image_lane++;
    }
    if (image_lane < 32) {
      snapshot->v04_shadow_handoff_words[image_lane][27] = 1u;
    }
  }
}

static unsigned rtcore_shader_continuation_reason_mask(
    const rtcore_replay_warp_completion_entry_snapshot &snapshot,
    unsigned reason) {
  unsigned mask = 0;
  for (unsigned lane = 0; lane < 32; ++lane) {
    const unsigned lane_mask = 1u << lane;
    if ((snapshot.lane_completion_valid_mask & lane_mask) == 0) {
      continue;
    }
    if (snapshot.lane_completion_reason[lane] == reason) {
      mask |= lane_mask;
    }
  }
  return mask;
}

static unsigned rtcore_shader_continuation_dispatcher_cohort_count(
    unsigned reason_oracle_anyhit_mask,
    unsigned reason_oracle_intersection_mask,
    unsigned reason_synthetic_split_mask) {
  unsigned count = 0;
  if (reason_oracle_intersection_mask != 0) {
    count++;
  }
  if (reason_oracle_anyhit_mask != 0) {
    count++;
  }
  if (reason_synthetic_split_mask != 0) {
    count++;
  }
  return count;
}

static unsigned rtcore_shader_continuation_mix_selector_word(
    unsigned key, unsigned value) {
  key ^= value + 0x9e3779b9u + (key << 6) + (key >> 2);
  return key;
}

static unsigned rtcore_shader_continuation_target_selector_key(
    const rtcore_replay_warp_completion_entry_snapshot &snapshot,
    unsigned lane) {
  unsigned key = snapshot.lane_completion_reason[lane];
  for (unsigned word = 1; word <= 12; ++word) {
    key = rtcore_shader_continuation_mix_selector_word(
        key, snapshot.handoff_words[lane][word]);
  }
  return key;
}

static unsigned rtcore_shader_continuation_target_selector_cohort_count(
    const rtcore_replay_warp_completion_entry_snapshot &snapshot,
    unsigned target_selector_ready_mask,
    unsigned reason_oracle_anyhit_mask,
    unsigned reason_oracle_intersection_mask,
    unsigned reason_synthetic_split_mask) {
  unsigned selector_keys[32] = {};
  unsigned selector_key_count = 0;
  for (unsigned lane = 0; lane < 32; ++lane) {
    const unsigned lane_mask = 1u << lane;
    if ((target_selector_ready_mask & lane_mask) == 0) {
      continue;
    }
    const unsigned key =
        rtcore_shader_continuation_target_selector_key(snapshot, lane);
    bool seen = false;
    for (unsigned index = 0; index < selector_key_count; ++index) {
      if (selector_keys[index] == key) {
        seen = true;
        break;
      }
    }
    if (!seen && selector_key_count < 32) {
      selector_keys[selector_key_count++] = key;
    }
  }

  const unsigned fallback_mask =
      (reason_oracle_anyhit_mask | reason_oracle_intersection_mask |
       reason_synthetic_split_mask) &
      ~target_selector_ready_mask;
  unsigned fallback_cohort_count = 0;
  if ((fallback_mask & reason_oracle_intersection_mask) != 0) {
    fallback_cohort_count++;
  }
  if ((fallback_mask & reason_oracle_anyhit_mask) != 0) {
    fallback_cohort_count++;
  }
  if ((fallback_mask & reason_synthetic_split_mask) != 0) {
    fallback_cohort_count++;
  }
  return selector_key_count + fallback_cohort_count;
}

static unsigned rtcore_shader_continuation_hit_record_selector_ready_mask(
    const rtcore_replay_warp_completion_entry_snapshot &snapshot,
    unsigned target_reason_mask) {
  return target_reason_mask & snapshot.handoff_selector_valid_mask &
         snapshot.handoff_candidate_valid_mask;
}

static unsigned rtcore_shader_continuation_hit_record_selector_key(
    const rtcore_replay_warp_completion_entry_snapshot &snapshot,
    unsigned lane) {
  if (rtcore_v04_direct_completion(snapshot)) {
    std::array<uint32_t, rtcore::abi_v04::kWordCount> words = {};
    for (unsigned word = 0; word < rtcore::abi_v04::kWordCount; ++word) {
      words[word] = snapshot.handoff_words[lane][word];
    }
    return rtcore::abi_v04::extract_field(
               words, rtcore::abi_v04::kInstanceSbtContribution) +
           rtcore::abi_v04::extract_field(
               words, rtcore::abi_v04::kGeometryIndex) *
               rtcore::abi_v04::extract_field(
                   words, rtcore::abi_v04::kSbtRecordStride) +
           rtcore::abi_v04::extract_field(
               words, rtcore::abi_v04::kSbtRecordOffset);
  }
  return snapshot.handoff_words[lane][3] +
         snapshot.handoff_words[lane][4] *
             snapshot.handoff_words[lane][2] +
         snapshot.handoff_words[lane][1];
}

static unsigned rtcore_shader_continuation_sbt_record_selector_ready_mask(
    const rtcore_replay_warp_completion_entry_snapshot &snapshot,
    unsigned target_reason_mask) {
  const unsigned miss_mask = rtcore_shader_continuation_reason_mask(
      snapshot, RTCORE_SHADER_CONTINUATION_REASON_MISS);
  const unsigned hit_reason_mask = target_reason_mask & ~miss_mask;
  return target_reason_mask & snapshot.handoff_selector_valid_mask &
         (miss_mask |
          (hit_reason_mask & snapshot.handoff_candidate_valid_mask));
}

static unsigned rtcore_shader_continuation_sbt_record_selector_key(
    const rtcore_replay_warp_completion_entry_snapshot &snapshot,
    unsigned lane) {
  if (snapshot.lane_completion_reason[lane] ==
      RTCORE_SHADER_CONTINUATION_REASON_MISS) {
    if (rtcore_v04_direct_completion(snapshot)) {
      std::array<uint32_t, rtcore::abi_v04::kWordCount> words = {};
      for (unsigned word = 0; word < rtcore::abi_v04::kWordCount; ++word) {
        words[word] = snapshot.handoff_words[lane][word];
      }
      return rtcore::abi_v04::extract_field(
          words, rtcore::abi_v04::kMissIndex);
    }
    return snapshot.handoff_words[lane][1];
  }
  return rtcore_shader_continuation_hit_record_selector_key(snapshot, lane);
}

static unsigned rtcore_shader_continuation_shader_record_component(
    unsigned completion_reason) {
  if (completion_reason == RTCORE_SHADER_CONTINUATION_REASON_MISS ||
      completion_reason ==
          RTCORE_SHADER_CONTINUATION_REASON_CLOSEST_HIT_READY) {
    return 0;
  }
  if (rtcore_shader_continuation_requires_handoff_return(completion_reason)) {
    return 1;
  }
  return UINT_MAX;
}

static unsigned rtcore_shader_continuation_hit_record_selector_cohort_count(
    const rtcore_replay_warp_completion_entry_snapshot &snapshot,
    unsigned hit_record_selector_ready_mask) {
  unsigned selector_keys[32] = {};
  unsigned selector_key_count = 0;
  for (unsigned lane = 0; lane < 32; ++lane) {
    const unsigned lane_mask = 1u << lane;
    if ((hit_record_selector_ready_mask & lane_mask) == 0) {
      continue;
    }
    const unsigned key =
        rtcore_shader_continuation_hit_record_selector_key(snapshot, lane);
    bool seen = false;
    for (unsigned index = 0; index < selector_key_count; ++index) {
      if (selector_keys[index] == key) {
        seen = true;
        break;
      }
    }
    if (!seen && selector_key_count < 32) {
      selector_keys[selector_key_count++] = key;
    }
  }
  return selector_key_count;
}

static unsigned rtcore_shader_continuation_cohort_reason_priority(
    unsigned reason) {
  switch (reason) {
    case RTCORE_SHADER_CONTINUATION_REASON_INTERSECTION_REQUIRED:
      return 0;
    case RTCORE_SHADER_CONTINUATION_REASON_ANY_HIT_REQUIRED:
      return 1;
    case RTCORE_SHADER_CONTINUATION_REASON_CLOSEST_HIT_READY:
      return 2;
    case RTCORE_SHADER_CONTINUATION_REASON_MISS:
      return 3;
    default:
      return UINT_MAX;
  }
}

static unsigned rtcore_shader_continuation_collect_sbt_address_cohorts(
    const rtcore_replay_warp_completion_entry_snapshot &snapshot,
    unsigned sbt_address_ready_mask, unsigned target_reason_mask,
    unsigned lane_masks[32]) {
  unsigned cohort_count = 0;
  unsigned selector_keys[32] = {};
  unsigned reason_keys[32] = {};
  for (unsigned lane = 0; lane < 32; ++lane) {
    const unsigned lane_mask = 1u << lane;
    if ((sbt_address_ready_mask & lane_mask) == 0 ||
        (target_reason_mask & lane_mask) == 0) {
      continue;
    }
    const unsigned selector_key =
        rtcore_shader_continuation_sbt_record_selector_key(snapshot, lane);
    const unsigned completion_reason = snapshot.lane_completion_reason[lane];
    bool seen = false;
    for (unsigned index = 0; index < cohort_count; ++index) {
      if (selector_keys[index] == selector_key &&
          reason_keys[index] == completion_reason) {
        seen = true;
        break;
      }
    }
    if (!seen && cohort_count < 32) {
      selector_keys[cohort_count] = selector_key;
      reason_keys[cohort_count] = completion_reason;
      lane_masks[cohort_count] = 0;
      cohort_count++;
    }
    for (unsigned index = 0; index < cohort_count; ++index) {
      if (selector_keys[index] == selector_key &&
          reason_keys[index] == completion_reason) {
        lane_masks[index] |= lane_mask;
        break;
      }
    }
  }
  for (unsigned index = 0; index < cohort_count; ++index) {
    for (unsigned next = index + 1; next < cohort_count; ++next) {
      const unsigned index_priority =
          rtcore_shader_continuation_cohort_reason_priority(
              reason_keys[index]);
      const unsigned next_priority =
          rtcore_shader_continuation_cohort_reason_priority(
              reason_keys[next]);
      const bool next_first =
          next_priority < index_priority ||
          (next_priority == index_priority &&
           selector_keys[next] < selector_keys[index]);
      if (!next_first) continue;
      std::swap(selector_keys[index], selector_keys[next]);
      std::swap(reason_keys[index], reason_keys[next]);
      std::swap(lane_masks[index], lane_masks[next]);
    }
  }
  return cohort_count;
}

static unsigned rtcore_shader_continuation_sbt_address_cohort_count(
    const rtcore_replay_warp_completion_entry_snapshot &snapshot,
    unsigned sbt_address_ready_mask, unsigned target_reason_mask) {
  unsigned lane_masks[32] = {};
  return rtcore_shader_continuation_collect_sbt_address_cohorts(
      snapshot, sbt_address_ready_mask, target_reason_mask, lane_masks);
}

static void rtcore_record_shader_continuation_sbt_address_cohorts(
    unsigned owner_hw_sid, unsigned warp_uid, unsigned warp_id,
    unsigned active_mask,
    const rtcore_replay_warp_completion_entry_snapshot &snapshot,
    unsigned sbt_address_ready_mask, unsigned target_reason_mask,
    unsigned long long current_cycle) {
  unsigned lane_masks[32] = {};
  const unsigned cohort_count =
      rtcore_shader_continuation_collect_sbt_address_cohorts(
          snapshot, sbt_address_ready_mask, target_reason_mask, lane_masks);

  for (unsigned index = 0; index < cohort_count; ++index) {
    unsigned representative_lane = 0;
    while (representative_lane < 32 &&
           (lane_masks[index] & (1u << representative_lane)) == 0) {
      representative_lane++;
    }
    assert(representative_lane < 32);
    const unsigned selector_key =
        rtcore_shader_continuation_sbt_record_selector_key(
            snapshot, representative_lane);
    const unsigned completion_reason =
        snapshot.lane_completion_reason[representative_lane];
    const unsigned target_shader_record_component =
        rtcore_shader_continuation_shader_record_component(completion_reason);
    printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_SBT_ADDRESS_COHORT "
           "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
           "sbt_address_cohort_index=%u "
           "sbt_address_lane_mask=0x%08x "
           "target_hit_record_selector=%u "
           "target_completion_reason=%u "
           "target_shader_record_component=%u "
           "target_resolution_state=deferred_until_lsu_response "
           "shader_side_decision_cycle=%llu\n",
           owner_hw_sid, warp_uid, warp_id, active_mask, index,
           lane_masks[index], selector_key, completion_reason,
           target_shader_record_component, current_cycle);
  }
}

static void rtcore_record_shader_continuation_callshader_context_preflight(
    const shader_core_ctx *core, const warp_inst_t &inst, unsigned owner_hw_sid,
    unsigned warp_uid, unsigned warp_id, unsigned active_mask,
    unsigned sbt_address_ready_mask,
    unsigned long long current_cycle) {
  unsigned thread_mask = 0;
  unsigned instruction_pointer_mask = 0;

  shader_core_ctx *mutable_core = const_cast<shader_core_ctx *>(core);
  ptx_thread_info **thread_info =
      mutable_core != NULL ? mutable_core->get_thread_info() : NULL;
  const unsigned warp_size =
      mutable_core != NULL ? mutable_core->get_warp_size() : 32;

  for (unsigned lane = 0; lane < 32 && lane < warp_size; ++lane) {
    const unsigned lane_mask = 1u << lane;
    if ((sbt_address_ready_mask & lane_mask) == 0) {
      continue;
    }
    ptx_thread_info *thread = NULL;
    if (thread_info != NULL) {
      const unsigned hw_tid = warp_id * warp_size + lane;
      thread = thread_info[hw_tid];
    }
    if (thread == NULL) {
      continue;
    }
    thread_mask |= lane_mask;
    if (thread->get_inst(inst.pc) != NULL) {
      instruction_pointer_mask |= lane_mask;
    }
  }

  const unsigned missing_thread_mask =
      sbt_address_ready_mask & ~thread_mask;
  const unsigned missing_instruction_pointer_mask =
      sbt_address_ready_mask & ~instruction_pointer_mask;
  const unsigned ready_mask =
      sbt_address_ready_mask & thread_mask & instruction_pointer_mask;
  const char *status =
      ready_mask != 0
          ? "sbt_address_preflight_ready"
          : (sbt_address_ready_mask == 0
                 ? "no_sbt_address_candidate"
                 : (missing_thread_mask != 0
                        ? "missing_thread_context"
                        : (missing_instruction_pointer_mask != 0
                               ? "missing_instruction_pointer"
                               : "preflight_blocked_unknown")));

  printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_CALLSHADER_CONTEXT_PREFLIGHT "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
         "callshader_context_sbt_address_ready_mask=0x%08x "
         "callshader_context_thread_mask=0x%08x "
         "callshader_context_missing_thread_mask=0x%08x "
         "callshader_context_instruction_pointer_mask=0x%08x "
         "callshader_context_missing_instruction_pointer_mask=0x%08x "
         "callshader_context_ready_mask=0x%08x "
         "target_function_resolution=deferred_until_lsu_response "
         "callshader_context_status=%s "
         "direct_callshader_action=preflight_only_no_call "
         "shader_side_decision_cycle=%llu\n",
         owner_hw_sid, warp_uid, warp_id, active_mask,
         sbt_address_ready_mask, thread_mask, missing_thread_mask,
         instruction_pointer_mask, missing_instruction_pointer_mask,
         ready_mask, status, current_cycle);
}

static void rtcore_record_shader_continuation_direct_callshader_action(
    const shader_core_ctx *core, const warp_inst_t &inst, unsigned owner_hw_sid,
    unsigned warp_uid, unsigned warp_id, unsigned active_mask,
    const rtcore_replay_warp_completion_entry_snapshot &snapshot,
    unsigned target_reason_mask, unsigned sbt_address_ready_mask,
    unsigned long long current_cycle) {
  unsigned candidate_mask = 0;
  unsigned missing_thread_mask = 0;
  unsigned missing_instruction_pointer_mask = 0;

  shader_core_ctx *mutable_core = const_cast<shader_core_ctx *>(core);
  ptx_thread_info **thread_info =
      mutable_core != NULL ? mutable_core->get_thread_info() : NULL;
  const unsigned warp_size =
      mutable_core != NULL ? mutable_core->get_warp_size() : 32;

  for (unsigned lane = 0; lane < 32 && lane < warp_size; ++lane) {
    const unsigned lane_mask = 1u << lane;
    if ((sbt_address_ready_mask & lane_mask) == 0) {
      continue;
    }

    ptx_thread_info *thread = NULL;
    if (thread_info != NULL) {
      const unsigned hw_tid = warp_id * warp_size + lane;
      thread = thread_info[hw_tid];
    }
    if (thread == NULL) {
      missing_thread_mask |= lane_mask;
      continue;
    }

    const ptx_instruction *pI = thread->get_inst(inst.pc);
    if (pI == NULL) {
      missing_instruction_pointer_mask |= lane_mask;
      continue;
    }
    if (rtcore_v04_direct_completion(snapshot) &&
        !rtcore_validate_v04_native_source_authority(
            snapshot, owner_hw_sid, lane, pI, thread)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_V04_NATIVE_CONTINUATION_FAULT "
              "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
              "fault=source_resident_authority_mismatch\n",
              owner_hw_sid, warp_uid, warp_id, lane);
      fflush(stderr);
      abort();
    }

    candidate_mask |= lane_mask;
  }

  const unsigned unresolved_target_mask =
      target_reason_mask & ~candidate_mask;
  if (unresolved_target_mask != 0) {
    fprintf(stderr,
            "GPGPU-Sim "
            "RTCORE_SHADER_CONTINUATION_TARGET_RESOLUTION_FAIL_CLOSED "
            "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
            "target_reason_mask=0x%08x candidate_mask=0x%08x "
            "unresolved_target_mask=0x%08x missing_thread_mask=0x%08x "
            "missing_instruction_pointer_mask=0x%08x "
            "target_resolution_state=pre_content_decode\n",
            owner_hw_sid, warp_uid, warp_id, active_mask, target_reason_mask,
            candidate_mask, unresolved_target_mask, missing_thread_mask,
            missing_instruction_pointer_mask);
    fflush(stderr);
    abort();
  }

  const bool v04_direct = rtcore_v04_direct_completion(snapshot);
  const char *action =
      candidate_mask == 0
          ? "no_ready_context"
          : (v04_direct ? "enqueued_pending_handoff_selection"
                        : "enqueued_pending_sbt_device_decode");
  if (candidate_mask != 0) {
    unsigned cohort_shader_ids[32];
    unsigned cohort_lane_masks[32] = {};
    unsigned long long cohort_context_ptrs[32] = {};
    unsigned long long cohort_sbt_record_addrs[32] = {};
    unsigned long long cohort_sbt_aligned_32b_addrs[32] = {};
    unsigned cohort_sbt_record_components[32] = {};
    for (unsigned index = 0; index < 32; ++index) {
      cohort_shader_ids[index] = UINT_MAX;
    }
    const unsigned cohort_count =
        rtcore_shader_continuation_collect_sbt_address_cohorts(
            snapshot, candidate_mask, target_reason_mask, cohort_lane_masks);
    for (unsigned cohort_index = 0;
         !v04_direct && cohort_index < cohort_count; ++cohort_index) {
      bool cohort_address_ready = false;
      for (unsigned lane = 0; lane < 32 && lane < warp_size; ++lane) {
        const unsigned lane_mask = 1u << lane;
        if ((cohort_lane_masks[cohort_index] & lane_mask) == 0) {
          continue;
        }
        ptx_thread_info *thread =
            thread_info != NULL
                ? thread_info[warp_id * warp_size + lane]
                : NULL;
        const ptx_instruction *source_inst =
            thread != NULL ? thread->get_inst(inst.pc) : NULL;
        unsigned long long context_ptr = 0;
        unsigned long long sbt_record_addr = 0;
        unsigned long long aligned_32b_addr = 0;
        unsigned shader_record_component = 0;
        if (!rtcore_shader_continuation_load_sbt_metadata_request_address(
                source_inst, thread, snapshot.lane_completion_reason[lane],
                rtcore_shader_continuation_sbt_record_selector_key(snapshot,
                                                                   lane),
                &context_ptr, &sbt_record_addr, &aligned_32b_addr,
                &shader_record_component)) {
          fprintf(stderr,
                  "GPGPU-Sim "
                  "RTCORE_SHADER_CONTINUATION_SBT_METADATA_FAULT "
                  "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
                  "cohort_index=%u "
                  "fault=context_sbt_address_decode_fail_closed\n",
                  owner_hw_sid, warp_uid, warp_id, lane, cohort_index);
          fflush(stderr);
          abort();
        }
        if (!cohort_address_ready) {
          cohort_context_ptrs[cohort_index] = context_ptr;
          cohort_sbt_record_addrs[cohort_index] = sbt_record_addr;
          cohort_sbt_aligned_32b_addrs[cohort_index] = aligned_32b_addr;
          cohort_sbt_record_components[cohort_index] =
              shader_record_component;
          cohort_address_ready = true;
        } else if (cohort_sbt_record_addrs[cohort_index] != sbt_record_addr ||
                   cohort_sbt_aligned_32b_addrs[cohort_index] !=
                       aligned_32b_addr ||
                   cohort_sbt_record_components[cohort_index] !=
                       shader_record_component) {
          fprintf(stderr,
                  "GPGPU-Sim "
                  "RTCORE_SHADER_CONTINUATION_SBT_METADATA_FAULT "
                  "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
                  "cohort_index=%u expected_record_addr=0x%llx "
                  "observed_record_addr=0x%llx "
                  "fault=cohort_sbt_address_mismatch_fail_closed\n",
                  owner_hw_sid, warp_uid, warp_id, lane, cohort_index,
                  cohort_sbt_record_addrs[cohort_index], sbt_record_addr);
          fflush(stderr);
          abort();
        }
      }
      if (!cohort_address_ready) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_SHADER_CONTINUATION_SBT_METADATA_FAULT "
                "owner_hw_sid=%u warp_uid=%u warp_id=%u cohort_index=%u "
                "fault=empty_cohort_address_fail_closed\n",
                owner_hw_sid, warp_uid, warp_id, cohort_index);
        fflush(stderr);
        abort();
      }
    }
    rtcore_enqueue_shader_continuation_dispatcher_pending(
        owner_hw_sid, warp_uid, warp_id, inst.dynamic_warp_id(), active_mask,
        0, candidate_mask, cohort_count,
        cohort_lane_masks, cohort_shader_ids, cohort_context_ptrs,
        cohort_sbt_record_addrs, cohort_sbt_aligned_32b_addrs,
        cohort_sbt_record_components, inst.pc, snapshot, current_cycle);
  }

  printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_DIRECT_CALLSHADER_ACTION "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
         "synchronous_rtunit_callshader=0 "
         "shadercore_pseudo_op_enqueued=%u "
         "direct_callshader_sbt_address_ready_mask=0x%08x "
         "direct_callshader_target_shader_id_ready_mask=0x00000000 "
         "direct_callshader_action=%s "
         "direct_callshader_candidate_mask=0x%08x "
         "direct_callshader_null_target_mask=deferred "
         "direct_callshader_terminal_no_shader_mask=deferred "
         "direct_callshader_lane_mask=0x%08x "
         "direct_callshader_missing_thread_mask=0x%08x "
         "direct_callshader_missing_instruction_pointer_mask=0x%08x "
         "direct_callshader_missing_target_function_mask=deferred "
         "direct_callshader_failed_invocation_mask=0x00000000 "
         "cohort_backend_invocation=deferred_shadercore_control_transfer "
         "shader_side_decision_cycle=%llu\n",
         owner_hw_sid, warp_uid, warp_id, active_mask,
         candidate_mask != 0 ? 1u : 0u, sbt_address_ready_mask, action,
         candidate_mask, 0u, missing_thread_mask,
         missing_instruction_pointer_mask, current_cycle);
}

rt_unit::rtcore_completion_timing_snapshot
rt_unit::rtcore_make_completion_timing_snapshot(
    const rtcore_synthetic_completion_event &event) const {
  rtcore_completion_timing_snapshot snapshot;
  snapshot.stats_mode = rtcore_stats_completion_latency_enabled();
  snapshot.fixed_latency = snapshot.stats_mode
                               ? rtcore_stats_latency_base()
                               : rtcore_synthetic_completion_latency();
  snapshot.node_cost = snapshot.stats_mode ? rtcore_stats_node_cost() : 0;
  snapshot.primitive_cost =
      snapshot.stats_mode ? rtcore_stats_primitive_cost() : 0;
  snapshot.adapter_max_node_visits = event.adapter_max_node_visits;
  snapshot.adapter_max_primitive_tests = event.adapter_max_primitive_tests;
  snapshot.active_lane_count =
      rtcore_count_active_mask_lanes(event.issued_active_mask);
  snapshot.traversal_stack_entries_per_active_lane_demand =
      snapshot.adapter_max_node_visits;
  const unsigned long long traversal_stack_entries_per_warp_demand =
      (unsigned long long)snapshot.active_lane_count *
      snapshot.traversal_stack_entries_per_active_lane_demand;
  snapshot.traversal_stack_entries_per_warp_demand =
      traversal_stack_entries_per_warp_demand > UINT_MAX
          ? UINT_MAX
          : (unsigned)traversal_stack_entries_per_warp_demand;
  unsigned long long stats_latency = snapshot.fixed_latency;
  if (snapshot.stats_mode) {
    stats_latency +=
        (unsigned long long)snapshot.adapter_max_node_visits *
        snapshot.node_cost;
    stats_latency +=
        (unsigned long long)snapshot.adapter_max_primitive_tests *
        snapshot.primitive_cost;
  }
  snapshot.completion_latency =
      stats_latency > UINT_MAX ? UINT_MAX : (unsigned)stats_latency;
  snapshot.enqueue_cycle = event.enqueue_cycle;
  snapshot.ready_cycle =
      snapshot.enqueue_cycle + snapshot.completion_latency;
  rtcore_hardware_model_boundary_snapshot hardware_snapshot =
      rtcore_make_hardware_model_boundary_snapshot(event, snapshot);
  rtcore_log_hardware_model_boundary_snapshot(hardware_snapshot);

  printf("GPGPU-Sim PTX: RT-unit synthetic-completion-latency, "
         "warp_uid=%u, warp_id=%u, mode=%s, fixed_latency=%u, "
         "stats_latency=%u, node_cost=%u, primitive_cost=%u, "
         "max_node_visits=%u, max_primitive_tests=%u, "
         "completion_latency=%u, enqueue_cycle=%llu, ready_cycle=%llu, "
         "active_lanes=%u, "
         "traversal_stack_entries_per_active_lane_demand=%u, "
         "traversal_stack_entries_per_warp_demand=%u\n",
         event.warp_uid, event.warp_id,
         snapshot.stats_mode ? "stats" : "fixed",
         snapshot.fixed_latency, snapshot.completion_latency,
         snapshot.node_cost, snapshot.primitive_cost,
         snapshot.adapter_max_node_visits,
         snapshot.adapter_max_primitive_tests,
         snapshot.completion_latency, snapshot.enqueue_cycle,
         snapshot.ready_cycle, snapshot.active_lane_count,
         snapshot.traversal_stack_entries_per_active_lane_demand,
         snapshot.traversal_stack_entries_per_warp_demand);
  fflush(stdout);

  if (rtcore_existing_backend_latency_resource_binding_enabled()) {
    printf("GPGPU-Sim PTX: RT-unit existing-backend-latency-resource-binding, "
           "warp_uid=%u, warp_id=%u, "
           "source=existing_vulkan_sim_traversal_intersection_backend, "
           "existing_backend_stats_bound=1, "
           "completion_latency_resource_accounting_bound=1, "
           "claims_new_hardware_bvh_engine=0, "
           "active_lanes=%u, max_node_visits=%u, "
           "max_primitive_tests=%u, completion_latency=%u, "
           "node_cost=%u, primitive_cost=%u, "
           "traversal_stack_entries_per_active_lane_demand=%u, "
           "traversal_stack_entries_per_warp_demand=%u\n",
           event.warp_uid, event.warp_id, snapshot.active_lane_count,
           snapshot.adapter_max_node_visits,
           snapshot.adapter_max_primitive_tests,
           snapshot.completion_latency, snapshot.node_cost,
           snapshot.primitive_cost,
           snapshot.traversal_stack_entries_per_active_lane_demand,
           snapshot.traversal_stack_entries_per_warp_demand);
  }
  fflush(stdout);
  return snapshot;
}

rt_unit::rtcore_hardware_model_boundary_snapshot
rt_unit::rtcore_make_hardware_model_boundary_snapshot(
    const rtcore_synthetic_completion_event &event,
    const rtcore_completion_timing_snapshot &timing_snapshot) const {
  rtcore_hardware_model_boundary_snapshot snapshot;
  snapshot.snapshot_source = "rtunit_completion_timing_resource_boundary";
  snapshot.traversal_component_source =
      "existing_vulkan_sim_traversal_intersection_backend";
  snapshot.intersection_component_source =
      "existing_vulkan_sim_traversal_intersection_backend";
  snapshot.memory_cache_component_source =
      "existing_vulkan_sim_memory_transaction_records";
  snapshot.stack_component_source = "rt_unit_completion_timing_snapshot";
  snapshot.completion_component_source = "rt_unit_completion_timing_snapshot";
  snapshot.backpressure_component_source =
      "rt_unit_warp_completion_entry_state_snapshot";
  snapshot.warp_completion_entry_state_source =
      "rt_unit_warp_completion_entry_state_snapshot";
  snapshot.custom_abi_input_authority_admitted =
      event.provider_materialized_traversal_input_actual_abi_snapshot_admitted &&
      event.provider_backend_input_authority_pre_call_guard_ready;
  snapshot.uses_reused_traversal_backend = true;
  snapshot.claims_new_hardware_bvh_engine = false;
  snapshot.warp_completion_entry_capacity =
      rtcore_warp_completion_entry_capacity();
  snapshot.warp_completion_entry_inflight =
      rtcore_warp_completion_entry_inflight();
  snapshot.warp_completion_entry_reserved =
      rtcore_warp_completion_entry_reservation_count(m_sid);
  const unsigned long long warp_completion_entry_live_plus_reserved =
      (unsigned long long)snapshot.warp_completion_entry_inflight +
      snapshot.warp_completion_entry_reserved;
  snapshot.warp_completion_entry_live_plus_reserved =
      warp_completion_entry_live_plus_reserved > UINT_MAX
          ? UINT_MAX
          : (unsigned)warp_completion_entry_live_plus_reserved;
  snapshot.warp_completion_entry_capacity_enabled =
      snapshot.warp_completion_entry_capacity != 0;
  snapshot.warp_completion_entry_capacity_available =
      !snapshot.warp_completion_entry_capacity_enabled ||
      snapshot.warp_completion_entry_live_plus_reserved <
          snapshot.warp_completion_entry_capacity;
  snapshot.warp_completion_entry_backpressure_observed =
      snapshot.warp_completion_entry_capacity_enabled &&
      !snapshot.warp_completion_entry_capacity_available;
  snapshot.adapter_max_node_visits = timing_snapshot.adapter_max_node_visits;
  snapshot.adapter_max_primitive_tests =
      timing_snapshot.adapter_max_primitive_tests;
  snapshot.traversal_stack_entries_per_warp_demand =
      timing_snapshot.traversal_stack_entries_per_warp_demand;
  snapshot.completion_latency = timing_snapshot.completion_latency;
  return snapshot;
}

void rt_unit::rtcore_log_hardware_model_boundary_snapshot(
    const rtcore_hardware_model_boundary_snapshot &snapshot) const {
  printf("GPGPU-Sim PTX: RT-unit hardware-model-boundary-snapshot, "
         "hardware_model_boundary_snapshot=1, snapshot_source=%s, "
         "traversal_component_source=%s, "
         "intersection_component_source=%s, "
         "memory_cache_component_source=%s, stack_component_source=%s, "
         "completion_component_source=%s, backpressure_component_source=%s, "
         "warp_completion_entry_state_source=%s, "
         "custom_abi_input_authority_admitted=%u, "
         "uses_reused_traversal_backend=%u, "
         "claims_new_hardware_bvh_engine=%u, "
         "warp_completion_entry_capacity_enabled=%u, "
         "warp_completion_entry_capacity_available=%u, "
         "warp_completion_entry_backpressure_observed=%u, "
         "adapter_max_node_visits=%u, adapter_max_primitive_tests=%u, "
         "traversal_stack_entries_per_warp_demand=%u, "
         "warp_completion_entry_capacity=%u, "
         "warp_completion_entry_inflight=%u, "
         "warp_completion_entry_reserved=%u, "
         "warp_completion_entry_live_plus_reserved=%u, "
         "completion_latency=%u\n",
         snapshot.snapshot_source, snapshot.traversal_component_source,
         snapshot.intersection_component_source,
         snapshot.memory_cache_component_source, snapshot.stack_component_source,
         snapshot.completion_component_source,
         snapshot.backpressure_component_source,
         snapshot.warp_completion_entry_state_source,
         snapshot.custom_abi_input_authority_admitted ? 1 : 0,
         snapshot.uses_reused_traversal_backend ? 1 : 0,
         snapshot.claims_new_hardware_bvh_engine ? 1 : 0,
         snapshot.warp_completion_entry_capacity_enabled ? 1 : 0,
         snapshot.warp_completion_entry_capacity_available ? 1 : 0,
         snapshot.warp_completion_entry_backpressure_observed ? 1 : 0,
         snapshot.adapter_max_node_visits,
         snapshot.adapter_max_primitive_tests,
         snapshot.traversal_stack_entries_per_warp_demand,
         snapshot.warp_completion_entry_capacity,
         snapshot.warp_completion_entry_inflight,
         snapshot.warp_completion_entry_reserved,
         snapshot.warp_completion_entry_live_plus_reserved,
         snapshot.completion_latency);
  fflush(stdout);
}

void rt_unit::rtcore_apply_completion_timing_snapshot(
    rtcore_synthetic_completion_event *event,
    const rtcore_completion_timing_snapshot &snapshot) const {
  if (event == NULL) {
    return;
  }
  event->completion_latency = snapshot.completion_latency;
  event->ready_cycle = snapshot.ready_cycle;
}

unsigned rt_unit::rtcore_effective_completion_latency(
    const rtcore_synthetic_completion_event &event) const {
  rtcore_completion_timing_snapshot timing_snapshot =
      rtcore_make_completion_timing_snapshot(event);
  return timing_snapshot.completion_latency;
}

static bool rtcore_test_adapter_mask_mismatch_enabled() {
  const char *value = getenv("VULKAN_SIM_RTCORE_TEST_ADAPTER_MASK_MISMATCH");
  return value != NULL && *value != '\0' && strcmp(value, "0") != 0;
}

static unsigned rtcore_first_active_lane_mask(unsigned active_mask) {
  if (active_mask == 0) {
    return 0;
  }
  return active_mask & (0u - active_mask);
}

static bool rtcore_test_delayed_completion_drop_lane_enabled() {
  const char *value =
      getenv("VULKAN_SIM_RTCORE_TEST_DELAYED_COMPLETION_DROP_LANE");
  return value != NULL && *value != '\0' && strcmp(value, "0") != 0;
}

static bool rtcore_test_delayed_completion_metadata_mismatch_enabled() {
  const char *value =
      getenv("VULKAN_SIM_RTCORE_TEST_DELAYED_COMPLETION_METADATA_MISMATCH");
  return value != NULL && *value != '\0' && strcmp(value, "0") != 0;
}

extern "C" bool rtcore_service_pending_traversal_completion(
    unsigned warp_uid, unsigned warp_id, unsigned owner_hw_sid,
    unsigned issued_active_mask);

extern "C" bool rtcore_claim_adapter_completion(
    unsigned warp_uid, unsigned warp_id, unsigned owner_hw_sid,
    unsigned *active_mask, unsigned *completed_lane_mask,
    unsigned *static_inst_uid, unsigned *max_node_visits,
    unsigned *max_primitive_tests);

extern "C" bool rtcore_claim_adapter_completion_snapshot(
    unsigned warp_uid, unsigned warp_id, unsigned owner_hw_sid,
    rtcore_adapter_completion_claim_snapshot *snapshot);

rt_unit::rtcore_adapter_readiness_snapshot
rt_unit::rtcore_make_adapter_readiness_snapshot(
    const rtcore_adapter_completion_claim_snapshot &claim_snapshot,
    unsigned issued_active_mask) const {
  rtcore_adapter_readiness_snapshot snapshot;
  snapshot.claim_accepted = claim_snapshot.accepted;
  snapshot.adapter_active_mask = claim_snapshot.active_mask;
  snapshot.adapter_completed_lane_mask = claim_snapshot.completed_lane_mask;
  snapshot.adapter_static_inst_uid = claim_snapshot.static_inst_uid;
  snapshot.adapter_max_node_visits = claim_snapshot.max_node_visits;
  snapshot.adapter_max_primitive_tests = claim_snapshot.max_primitive_tests;
  snapshot.has_provider_materialized_traversal_input_snapshot =
      claim_snapshot.has_provider_materialized_traversal_input_snapshot;
  snapshot.provider_materialized_traversal_input_snapshot_valid =
      claim_snapshot.provider_materialized_traversal_input_snapshot_valid;
  snapshot.provider_materialized_traversal_input_snapshot_source =
      claim_snapshot.provider_materialized_traversal_input_snapshot_source;
  snapshot.provider_materialized_traversal_input_actual_abi_snapshot_admitted =
      claim_snapshot
          .provider_materialized_traversal_input_actual_abi_snapshot_admitted;
  snapshot.provider_materialized_traversal_input_decoded_value_record_valid =
      claim_snapshot
          .provider_materialized_traversal_input_decoded_value_record_valid;
  snapshot.provider_materialized_traversal_input_decoded_value_record_source =
      claim_snapshot
          .provider_materialized_traversal_input_decoded_value_record_source;
  snapshot.provider_materialized_traversal_input_decoded_value_record_consumed =
      claim_snapshot
          .provider_materialized_traversal_input_decoded_value_record_consumed;
  snapshot
      .provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid =
      claim_snapshot
          .provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid;
  snapshot
      .provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted =
      claim_snapshot
          .provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted;
  snapshot
      .provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed =
      claim_snapshot
          .provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed;
  snapshot
      .provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason =
      claim_snapshot
          .provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason;
  snapshot.provider_backend_input_authority_pre_call_guard_required =
      claim_snapshot
          .provider_backend_input_claim_authority_pre_call_guard_required;
  snapshot.provider_backend_input_authority_pre_call_guard_ready =
      claim_snapshot.provider_backend_input_claim_authority_pre_call_guard_ready;
  snapshot.issue_mask_match =
      snapshot.adapter_active_mask == issued_active_mask;
  snapshot.issued_lanes_complete =
      issued_active_mask != 0 &&
      (snapshot.adapter_completed_lane_mask & issued_active_mask) ==
          issued_active_mask;
  snapshot.adapter_ready =
      snapshot.claim_accepted && snapshot.issue_mask_match &&
      snapshot.issued_lanes_complete;
  return snapshot;
}

void rt_unit::rtcore_apply_adapter_readiness_snapshot(
    rtcore_synthetic_completion_event *event,
    const rtcore_adapter_readiness_snapshot &snapshot) const {
  if (event == NULL) {
    return;
  }
  event->adapter_completion_claimed = snapshot.claim_accepted;
  event->adapter_active_mask = snapshot.adapter_active_mask;
  event->adapter_completed_lane_mask = snapshot.adapter_completed_lane_mask;
  event->adapter_static_inst_uid = snapshot.adapter_static_inst_uid;
  event->adapter_max_node_visits = snapshot.adapter_max_node_visits;
  event->adapter_max_primitive_tests = snapshot.adapter_max_primitive_tests;
  event->has_provider_materialized_traversal_input_snapshot =
      snapshot.has_provider_materialized_traversal_input_snapshot;
  event->provider_materialized_traversal_input_snapshot_valid =
      snapshot.provider_materialized_traversal_input_snapshot_valid;
  event->provider_materialized_traversal_input_snapshot_source =
      snapshot.provider_materialized_traversal_input_snapshot_source;
  event->provider_materialized_traversal_input_actual_abi_snapshot_admitted =
      snapshot
          .provider_materialized_traversal_input_actual_abi_snapshot_admitted;
  event->provider_materialized_traversal_input_decoded_value_record_valid =
      snapshot
          .provider_materialized_traversal_input_decoded_value_record_valid;
  event->provider_materialized_traversal_input_decoded_value_record_source =
      snapshot
          .provider_materialized_traversal_input_decoded_value_record_source;
  event->provider_materialized_traversal_input_decoded_value_record_consumed =
      snapshot
          .provider_materialized_traversal_input_decoded_value_record_consumed;
  event
      ->provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid =
      snapshot
          .provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid;
  event
      ->provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted =
      snapshot
          .provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted;
  event
      ->provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed =
      snapshot
          .provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed;
  event
      ->provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason =
      snapshot
          .provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason;
  event->provider_backend_input_authority_pre_call_guard_required =
      snapshot.provider_backend_input_authority_pre_call_guard_required;
  event->provider_backend_input_authority_pre_call_guard_ready =
      snapshot.provider_backend_input_authority_pre_call_guard_ready;
  event->adapter_completion_issue_mask_match = snapshot.issue_mask_match;
  event->adapter_completion_issued_lanes_complete =
      snapshot.issued_lanes_complete;
  event->adapter_completion_ready = snapshot.adapter_ready;
}

bool rt_unit::claim_adapter_completion_for_issue(
    rtcore_synthetic_completion_event *event) {
  if (event == NULL) {
    return false;
  }
  if (event->adapter_completion_claimed) {
    return event->adapter_completion_ready;
  }

  const bool serviced_delayed_completion =
      rtcore_service_pending_traversal_completion(
          event->warp_uid, event->warp_id, m_sid, event->issued_active_mask);
  rtcore_adapter_completion_claim_snapshot claim_snapshot;
  rtcore_claim_adapter_completion_snapshot(event->warp_uid, event->warp_id,
                                           m_sid, &claim_snapshot);
  rtcore_adapter_readiness_snapshot readiness_snapshot =
      rtcore_make_adapter_readiness_snapshot(claim_snapshot,
                                             event->issued_active_mask);
  if (!readiness_snapshot.claim_accepted) {
    if (serviced_delayed_completion &&
        rtcore_test_delayed_completion_metadata_mismatch_enabled()) {
      printf("GPGPU-Sim PTX: RT-unit delayed-completion metadata-mismatch fail-closed, "
             "warp_uid=%u, warp_id=%u, owner_hw_sid=%u, "
             "issued_active_mask=0x%08x, serviced=%u, accepted=0\n",
             event->warp_uid, event->warp_id, m_sid,
             event->issued_active_mask, serviced_delayed_completion ? 1 : 0);
      fflush(stdout);
      abort();
    }
    if (serviced_delayed_completion &&
        rtcore_test_delayed_completion_drop_lane_enabled()) {
      printf("GPGPU-Sim PTX: RT-unit delayed-completion fail-closed, "
             "warp_uid=%u, warp_id=%u, owner_hw_sid=%u, "
             "issued_active_mask=0x%08x, serviced=%u, accepted=0\n",
             event->warp_uid, event->warp_id, m_sid,
             event->issued_active_mask, serviced_delayed_completion ? 1 : 0);
      fflush(stdout);
      abort();
    }
    return false;
  }

  rtcore_apply_adapter_readiness_snapshot(event, readiness_snapshot);

  const bool test_adapter_mask_mismatch =
      rtcore_test_adapter_mask_mismatch_enabled();
  if (test_adapter_mask_mismatch) {
    const unsigned mismatch_lane_mask =
        rtcore_first_active_lane_mask(event->issued_active_mask);
    if (mismatch_lane_mask != 0) {
      event->adapter_active_mask &= ~mismatch_lane_mask;
    }
  }

  event->adapter_completion_issue_mask_match =
      event->adapter_active_mask == event->issued_active_mask;
  event->adapter_completion_issued_lanes_complete =
      event->issued_active_mask != 0 &&
      (event->adapter_completed_lane_mask & event->issued_active_mask) ==
          event->issued_active_mask;
  event->adapter_completion_ready =
      event->adapter_completion_issue_mask_match &&
      event->adapter_completion_issued_lanes_complete;

  printf("GPGPU-Sim PTX: RT-unit adapter-completion-ready, "
         "warp_uid=%u, warp_id=%u, owner_hw_sid=%u, "
         "issued_active_mask=0x%08x, adapter_active_mask=0x%08x, "
         "adapter_completed_lane_mask=0x%08x, adapter_static_inst_uid=%u, "
         "adapter_max_node_visits=%u, "
         "adapter_max_primitive_tests=%u, "
         "claimed=%u, issue_mask_match=%u, issued_lanes_complete=%u, "
         "rt_unit_materialized_traversal_input_readiness_provenance=1, "
         "provider_materialized_traversal_input_snapshot=1, "
         "has_provider_materialized_traversal_input_snapshot=%u, "
         "provider_materialized_traversal_input_snapshot_valid=%u, "
         "provider_materialized_traversal_input_snapshot_source=%s, "
         "provider_materialized_traversal_input_actual_abi_snapshot_admitted=%u, "
         "provider_materialized_traversal_input_decoded_value_record_valid=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source=%s, "
         "provider_materialized_traversal_input_decoded_value_record_consumed=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason=%s, "
         "rt_unit_backend_input_authority_pre_call_guard_required=%u, "
         "rt_unit_backend_input_authority_pre_call_guard_ready=%u, "
         "rt_unit_readiness_materialized_input_consumes_adapter_ready=0, "
         "rt_unit_readiness_decoded_value_record_consumes_adapter_ready=0, "
         "rt_unit_readiness_decoded_value_record_source_snapshot_consumes_adapter_ready=0, "
         "rt_unit_readiness_backend_input_authority_pre_call_guard_consumes_adapter_ready=0, "
         "accepted=%u\n",
         event->warp_uid, event->warp_id, m_sid, event->issued_active_mask,
         event->adapter_active_mask, event->adapter_completed_lane_mask,
         event->adapter_static_inst_uid,
         event->adapter_max_node_visits,
         event->adapter_max_primitive_tests,
         event->adapter_completion_claimed ? 1 : 0,
         event->adapter_completion_issue_mask_match ? 1 : 0,
         event->adapter_completion_issued_lanes_complete ? 1 : 0,
         event->has_provider_materialized_traversal_input_snapshot ? 1 : 0,
         event->provider_materialized_traversal_input_snapshot_valid ? 1 : 0,
         event->provider_materialized_traversal_input_snapshot_source,
         event->provider_materialized_traversal_input_actual_abi_snapshot_admitted
             ? 1
             : 0,
         event->provider_materialized_traversal_input_decoded_value_record_valid
             ? 1
             : 0,
         event->provider_materialized_traversal_input_decoded_value_record_source,
         event->provider_materialized_traversal_input_decoded_value_record_consumed
             ? 1
             : 0,
         event
                 ->provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid
             ? 1
             : 0,
         event
                 ->provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted
             ? 1
             : 0,
         event
                 ->provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed
             ? 1
             : 0,
         event
             ->provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason,
         event->provider_backend_input_authority_pre_call_guard_required ? 1
                                                                         : 0,
         event->provider_backend_input_authority_pre_call_guard_ready ? 1 : 0,
         event->adapter_completion_ready ? 1 : 0);
  fflush(stdout);

  if (test_adapter_mask_mismatch && !event->adapter_completion_ready) {
    printf("GPGPU-Sim PTX: RT-unit adapter-completion fail-closed, "
           "warp_uid=%u, warp_id=%u, owner_hw_sid=%u, "
           "issued_active_mask=0x%08x, adapter_active_mask=0x%08x, "
           "adapter_completed_lane_mask=0x%08x, issue_mask_match=%u, "
           "issued_lanes_complete=%u, accepted=%u\n",
           event->warp_uid, event->warp_id, m_sid, event->issued_active_mask,
           event->adapter_active_mask, event->adapter_completed_lane_mask,
           event->adapter_completion_issue_mask_match ? 1 : 0,
           event->adapter_completion_issued_lanes_complete ? 1 : 0,
           event->adapter_completion_ready ? 1 : 0);
    fflush(stdout);
    abort();
  }
  return event->adapter_completion_ready;
}

void rt_unit::rtcore_record_submit_pending_ownership(
    const warp_inst_t &inst, const rtcore_synthetic_completion_event &event,
    unsigned long long current_cycle) const {
  if (inst.rt_subop != RT_CORE_SUBOP_SUBMIT) {
    return;
  }

  g_rtcore_scoreboard_visible_wake_stats.pending_ownership_count++;
  g_rtcore_scoreboard_visible_wake_stats.waiting_rtcore_count++;

  printf("GPGPU-Sim RTCORE_SUBMIT_PENDING_OWNERSHIP "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u static_inst_pc=0x%llx "
         "issued_active_mask=0x%08x scoreboard_pending_ownership=1 "
         "waiting_rtcore_enqueue_cycle=%llu current_cycle=%llu\n",
         m_sid, event.warp_uid, event.warp_id, inst.pc,
         event.issued_active_mask, event.waiting_rtcore_enqueue_cycle,
         current_cycle);
  printf("GPGPU-Sim RTCORE_RESIDENT_WARP_WAITING_RTCORE "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
         "resident_warp_state=waiting_rtcore "
         "counts_resident_warp_occupancy=1 consumes_shader_issue_slot=0 "
         "scoreboard_pending_ownership=1 enqueue_cycle=%llu\n",
         m_sid, event.warp_uid, event.warp_id, event.issued_active_mask,
         event.waiting_rtcore_enqueue_cycle);
  fflush(stdout);
}

void rt_unit::rtcore_record_completion_ready_but_scoreboard_blocked(
    const warp_inst_t &inst, rtcore_synthetic_completion_event *event,
    unsigned packet_schema_version, unsigned completion_valid_mask,
    unsigned terminal_lane_mask, unsigned continuation_lane_mask,
    unsigned long long current_cycle) {
  if (inst.rt_subop != RT_CORE_SUBOP_SUBMIT || event == NULL ||
      event->scoreboard_blocked_logged) {
    return;
  }

  event->scoreboard_blocked_logged = true;
  g_rtcore_scoreboard_visible_wake_stats
      .completion_ready_but_scoreboard_blocked_count++;

  printf("GPGPU-Sim RTCORE_COMPLETION_READY_BUT_SCOREBOARD_BLOCKED "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
         "packet_schema_version=%u completion_valid_mask=0x%08x "
         "terminal_lane_mask=0x%08x continuation_lane_mask=0x%08x "
         "completion_ready_but_scoreboard_blocked=1 "
         "memory_response_path_blocked=0 current_cycle=%llu\n",
         m_sid, event->warp_uid, event->warp_id, event->issued_active_mask,
         packet_schema_version, completion_valid_mask, terminal_lane_mask,
         continuation_lane_mask, current_cycle);
  fflush(stdout);
}

void rt_unit::rtcore_record_resident_warp_wakeup(
    const warp_inst_t &inst, rtcore_synthetic_completion_event *event,
    unsigned packet_schema_version, unsigned completion_valid_mask,
    unsigned terminal_lane_mask, unsigned continuation_lane_mask,
    unsigned long long current_cycle) const {
  if (inst.rt_subop != RT_CORE_SUBOP_SUBMIT || event == NULL ||
      event->scoreboard_packet_acquired) {
    return;
  }

  event->scoreboard_packet_acquired = true;
  event->waiting_rtcore_pending = false;
  event->scoreboard_wakeup_cycle = current_cycle;
  const unsigned long long wait_cycles =
      current_cycle >= event->waiting_rtcore_enqueue_cycle
          ? current_cycle - event->waiting_rtcore_enqueue_cycle
          : 0;
  g_rtcore_scoreboard_visible_wake_stats.resident_warp_wakeup_count++;
  g_rtcore_scoreboard_visible_wake_stats.waiting_rtcore_cycle_total +=
      wait_cycles;
  if (wait_cycles >
      g_rtcore_scoreboard_visible_wake_stats.max_waiting_rtcore_cycles) {
    g_rtcore_scoreboard_visible_wake_stats.max_waiting_rtcore_cycles =
        wait_cycles;
  }

  printf("GPGPU-Sim RTCORE_RESIDENT_WARP_WAKEUP "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
         "packet_schema_version=%u completion_valid_mask=0x%08x "
         "terminal_lane_mask=0x%08x continuation_lane_mask=0x%08x "
         "scoreboard_packet_acquired=1 resident_warp_state=ready "
         "waiting_rtcore_cycles=%llu wakeup_cycle=%llu\n",
         m_sid, event->warp_uid, event->warp_id, event->issued_active_mask,
         packet_schema_version, completion_valid_mask, terminal_lane_mask,
         continuation_lane_mask, wait_cycles, current_cycle);
  fflush(stdout);
}

void rt_unit::rtcore_materialize_scoreboard_v_result(
    const warp_inst_t &inst,
    const rtcore_replay_warp_completion_entry_snapshot &candidate_completion,
    unsigned long long current_cycle) const {
  assert(inst.rt_subop == RT_CORE_SUBOP_SUBMIT);
  assert(candidate_completion.enabled && candidate_completion.found);
  assert(candidate_completion.all_active_lanes_complete);
  assert(m_core != NULL);

  ptx_thread_info **thread_info = m_core->get_thread_info();
  for (unsigned lane = 0; lane < m_config->warp_size && lane < 32; ++lane) {
    const unsigned lane_mask = 1u << lane;
    if ((candidate_completion.result_valid_mask & lane_mask) == 0) continue;

    ptx_thread_info *thread =
        thread_info[inst.warp_id() * m_config->warp_size + lane];
    assert(thread != NULL);
    const ptx_instruction *source_inst = thread->get_inst(inst.pc);
    assert(source_inst != NULL && source_inst->get_num_operands() == 3);
    const operand_info &result = source_inst->operand_lookup(0);
    const unsigned result_word = candidate_completion.result_data_slot[lane];
    assert((result_word & 0x80000000u) != 0);
    assert((result_word & 0xffu) ==
           candidate_completion.lane_completion_reason[lane]);

    ptx_reg_t result_data;
    result_data.u32 = result_word;
    thread->set_reg(result.get_symbol(), result_data);
    printf("GPGPU-Sim RTCORE_SCOREBOARD_V_RESULT_WRITEBACK "
           "owner_hw_sid=%u warp_uid=%u warp_id=%u lane_id=%u "
           "result=0x%08x reason=%u "
           "scoreboard_result_producer=rtcore_completion_packet "
           "writeback_cycle=%llu\n",
           m_sid, inst.get_uid(), inst.warp_id(), lane, result_word,
           result_word & 0xffu, current_cycle);
  }
  fflush(stdout);
}

void rt_unit::rtcore_record_shader_continuation_loop_decision(
    const warp_inst_t &inst, rtcore_synthetic_completion_event *event,
    unsigned packet_schema_version, unsigned completion_valid_mask,
    unsigned terminal_lane_mask, unsigned continuation_lane_mask,
    unsigned unsupported_reason_mask, unsigned handoff_software_return_valid_mask,
    unsigned reason_oracle_anyhit_mask,
    unsigned reason_oracle_intersection_mask,
    unsigned reason_synthetic_split_mask,
    unsigned target_selector_ready_mask,
    unsigned target_selector_missing_dispatch_mask,
    unsigned target_selector_missing_hit_mask,
    unsigned target_selector_fallback_reason_mask,
    unsigned target_selector_cohort_count,
    unsigned raw_fact_ray_sbt_inputs_ready_mask,
    unsigned raw_fact_geometry_primitive_ready_mask,
    unsigned raw_fact_instance_sbt_contribution_ready_mask,
    unsigned raw_fact_hit_record_selector_formula_ready_mask,
    unsigned raw_fact_hit_record_selector_formula_cohort_count,
    unsigned sbt_address_ready_mask,
    unsigned sbt_address_missing_mask,
    unsigned sbt_address_cohort_count,
    unsigned long long current_cycle) const {
  if (inst.rt_subop != RT_CORE_SUBOP_SUBMIT || event == NULL ||
      event->shader_continuation_loop_decision_logged) {
    return;
  }

  const unsigned issued_active_mask = event->issued_active_mask;
  const unsigned completion_visible_mask =
      issued_active_mask & completion_valid_mask;
  const unsigned continuation_candidate_mask =
      completion_visible_mask & continuation_lane_mask &
      ~unsupported_reason_mask;
  const unsigned missing_resume_handoff_mask =
      continuation_candidate_mask & ~handoff_software_return_valid_mask;
  const unsigned raw_next_active_mask =
      continuation_candidate_mask & handoff_software_return_valid_mask;
  const bool shader_continuation_forced_no_resubmit =
      rtcore_shader_continuation_force_no_resubmit_enabled() &&
      raw_next_active_mask != 0;
  const unsigned next_active_mask =
      shader_continuation_forced_no_resubmit ? 0 : raw_next_active_mask;
  const unsigned final_like_mask =
      completion_visible_mask & terminal_lane_mask & ~next_active_mask;
  const unsigned masked_off_lane_consume_mask =
      completion_valid_mask & ~issued_active_mask;
  const bool pre_submit_guard_passed =
      missing_resume_handoff_mask == 0 && masked_off_lane_consume_mask == 0;
  const unsigned handoff_result_consume_mask = completion_visible_mask;
  const unsigned resume_handoff_publish_mask =
      pre_submit_guard_passed ? next_active_mask : 0;
  const unsigned handoff_consume_lane_count =
      rtcore_count_active_mask_lanes(handoff_result_consume_mask);
  const unsigned resume_publish_lane_count =
      rtcore_count_active_mask_lanes(resume_handoff_publish_mask);
  const bool dispatcher_candidate = continuation_candidate_mask != 0;
  const unsigned dispatcher_cohort_count =
      rtcore_shader_continuation_dispatcher_cohort_count(
          reason_oracle_anyhit_mask, reason_oracle_intersection_mask,
          reason_synthetic_split_mask);
  const unsigned target_reason_mask =
      reason_oracle_anyhit_mask | reason_oracle_intersection_mask |
      reason_synthetic_split_mask;
  const unsigned raw_fact_sbt_region_metadata_ready_mask = target_reason_mask;
  const unsigned raw_fact_record_selector_ready_mask =
      target_selector_ready_mask;
  const unsigned raw_fact_resolved_target_ready_mask = 0;
  const unsigned raw_fact_sufficient_mask =
      target_reason_mask & raw_fact_ray_sbt_inputs_ready_mask &
      raw_fact_geometry_primitive_ready_mask &
      raw_fact_instance_sbt_contribution_ready_mask &
      raw_fact_record_selector_ready_mask;
  const unsigned raw_fact_missing_mask =
      target_reason_mask & ~raw_fact_sufficient_mask;
  const unsigned shader_continuation_handoff_load_cycles =
      handoff_consume_lane_count *
      rtcore_shader_continuation_handoff_load_cost();
  const unsigned shader_continuation_resume_publish_cycles =
      resume_publish_lane_count *
      rtcore_shader_continuation_resume_publish_cost();
  const unsigned shader_continuation_sbt_metadata_cycles =
      dispatcher_candidate ? rtcore_shader_continuation_sbt_metadata_cost() : 0;
  const unsigned shader_continuation_dispatch_call_cycles =
      dispatcher_candidate ? rtcore_shader_continuation_dispatch_call_cost()
                           : 0;
  const unsigned shader_continuation_total_cycles =
      rtcore_shader_continuation_base_cost() +
      shader_continuation_handoff_load_cycles +
      shader_continuation_resume_publish_cycles +
      shader_continuation_sbt_metadata_cycles +
      shader_continuation_dispatch_call_cycles;

  event->shader_continuation_loop_decision_logged = true;
  event->shader_continuation_next_active_mask = next_active_mask;
  event->shader_continuation_final_like_mask = final_like_mask;
  event->shader_continuation_missing_resume_handoff_mask =
      missing_resume_handoff_mask;
  event->shader_continuation_handoff_consume_mask =
      handoff_result_consume_mask;
  event->shader_continuation_resume_handoff_publish_mask =
      resume_handoff_publish_mask;
  event->shader_continuation_decision_cycle = current_cycle;

  g_rtcore_scoreboard_visible_wake_stats.shader_continuation_decision_count++;
  g_rtcore_scoreboard_visible_wake_stats.shader_continuation_cycle_total +=
      shader_continuation_total_cycles;
  g_rtcore_scoreboard_visible_wake_stats
      .shader_continuation_handoff_load_cycle_total +=
      shader_continuation_handoff_load_cycles;
  g_rtcore_scoreboard_visible_wake_stats
      .shader_continuation_resume_publish_cycle_total +=
      shader_continuation_resume_publish_cycles;
  g_rtcore_scoreboard_visible_wake_stats
      .shader_continuation_sbt_metadata_cycle_total +=
      shader_continuation_sbt_metadata_cycles;
  g_rtcore_scoreboard_visible_wake_stats
      .shader_continuation_dispatch_call_cycle_total +=
      shader_continuation_dispatch_call_cycles;
  if (next_active_mask != 0) {
    g_rtcore_scoreboard_visible_wake_stats
        .shader_continuation_resubmit_candidate_count++;
  }
  if (!pre_submit_guard_passed) {
    g_rtcore_scoreboard_visible_wake_stats
        .shader_continuation_pre_submit_blocked_count++;
  }
  const bool bridge_enqueued = rtcore_record_shader_continuation_resubmit_decision(
      m_sid, event->warp_uid, event->warp_id, issued_active_mask,
      packet_schema_version, completion_visible_mask, terminal_lane_mask,
      continuation_lane_mask, unsupported_reason_mask,
      handoff_software_return_valid_mask, next_active_mask, final_like_mask,
      missing_resume_handoff_mask, handoff_result_consume_mask,
      resume_handoff_publish_mask, pre_submit_guard_passed, current_cycle);

  printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_COST "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
         "completion_visible_mask=0x%08x continuation_candidate_mask=0x%08x "
         "next_active_mask=0x%08x handoff_consume_lane_count=%u "
         "resume_publish_lane_count=%u "
         "shader_continuation_handoff_load_cycles=%u "
         "shader_continuation_resume_publish_cycles=%u "
         "shader_continuation_sbt_metadata_cycles=%u "
         "shader_continuation_dispatch_call_cycles=%u "
         "shader_continuation_total_cycles=%u "
         "shader_continuation_cycle_total=%llu "
         "shader_side_decision_cycle=%llu\n",
         m_sid, event->warp_uid, event->warp_id, issued_active_mask,
         completion_visible_mask, continuation_candidate_mask,
         next_active_mask, handoff_consume_lane_count,
         resume_publish_lane_count,
         shader_continuation_handoff_load_cycles,
         shader_continuation_resume_publish_cycles,
         shader_continuation_sbt_metadata_cycles,
         shader_continuation_dispatch_call_cycles,
         shader_continuation_total_cycles,
         g_rtcore_scoreboard_visible_wake_stats.shader_continuation_cycle_total,
         current_cycle);

  printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_DISPATCHER_COHORT_SUMMARY "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
         "dispatcher_source=custom_handoff_facts "
         "completion_visible_mask=0x%08x continuation_candidate_mask=0x%08x "
         "dispatcher_reason_intersection_mask=0x%08x "
         "dispatcher_reason_anyhit_mask=0x%08x "
         "dispatcher_reason_synthetic_split_mask=0x%08x "
         "dispatcher_reason_final_mask=0x%08x "
         "dispatcher_reason_unsupported_mask=0x%08x "
         "dispatcher_handoff_software_return_valid_mask=0x%08x "
         "dispatcher_next_active_mask=0x%08x "
         "dispatcher_cohort_count=%u "
         "compatibility_target_resolution=deferred "
         "shader_side_decision_cycle=%llu\n",
         m_sid, event->warp_uid, event->warp_id, issued_active_mask,
         completion_visible_mask, continuation_candidate_mask,
         reason_oracle_intersection_mask,
         reason_oracle_anyhit_mask,
         reason_synthetic_split_mask,
         terminal_lane_mask,
         unsupported_reason_mask,
         handoff_software_return_valid_mask,
         next_active_mask,
         dispatcher_cohort_count, current_cycle);

  printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_TARGET_RESOLUTION_SUMMARY "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
         "target_resolution_source=compatibility_selector_summary_bridge "
         "target_resolution_input_source=custom_handoff_facts "
         "target_resolution_metadata_producer=application_sbt "
         "target_resolution_resolved=0 "
         "target_reason_intersection_mask=0x%08x "
         "target_reason_anyhit_mask=0x%08x "
         "target_reason_synthetic_split_mask=0x%08x "
         "target_selector_ready_mask=0x%08x "
         "target_selector_missing_dispatch_mask=0x%08x "
         "target_selector_missing_hit_mask=0x%08x "
         "target_selector_fallback_reason_mask=0x%08x "
         "target_selector_cohort_count=%u "
         "target_hit_record_selector_formula_ready_mask=0x%08x "
         "target_hit_record_selector_formula_cohort_count=%u "
         "target_sbt_address_ready_mask=0x%08x "
         "target_sbt_address_missing_mask=0x%08x "
         "target_sbt_address_cohort_count=%u "
         "target_shader_id_resolution=deferred_until_lsu_response "
         "shader_side_decision_cycle=%llu\n",
         m_sid, event->warp_uid, event->warp_id, issued_active_mask,
         reason_oracle_intersection_mask,
         reason_oracle_anyhit_mask,
         reason_synthetic_split_mask,
         target_selector_ready_mask,
         target_selector_missing_dispatch_mask,
         target_selector_missing_hit_mask,
         target_selector_fallback_reason_mask,
         target_selector_cohort_count,
         raw_fact_hit_record_selector_formula_ready_mask,
         raw_fact_hit_record_selector_formula_cohort_count,
         sbt_address_ready_mask,
         sbt_address_missing_mask,
         sbt_address_cohort_count, current_cycle);

  printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_RAW_FACT_SUFFICIENCY_AUDIT "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
         "raw_fact_source=custom_handoff_facts "
         "sbt_metadata_producer=application_sbt "
         "raw_fact_required_mask=0x%08x "
         "raw_fact_ray_sbt_inputs_ready_mask=0x%08x "
         "raw_fact_geometry_primitive_ready_mask=0x%08x "
         "raw_fact_instance_sbt_contribution_ready_mask=0x%08x "
         "raw_fact_hit_record_selector_formula_ready_mask=0x%08x "
         "raw_fact_hit_record_selector_formula_cohort_count=%u "
         "raw_fact_sbt_region_metadata_ready_mask=0x%08x "
         "raw_fact_record_selector_ready_mask=0x%08x "
         "raw_fact_resolved_target_ready_mask=0x%08x "
         "device_sbt_address_ready_mask=0x%08x "
         "raw_fact_sufficient_mask=0x%08x "
         "raw_fact_missing_mask=0x%08x "
         "raw_fact_audit_status=target_decode_deferred_until_lsu_response "
         "shader_side_decision_cycle=%llu\n",
         m_sid, event->warp_uid, event->warp_id, issued_active_mask,
         target_reason_mask,
         raw_fact_ray_sbt_inputs_ready_mask,
         raw_fact_geometry_primitive_ready_mask,
         raw_fact_instance_sbt_contribution_ready_mask,
         raw_fact_hit_record_selector_formula_ready_mask,
         raw_fact_hit_record_selector_formula_cohort_count,
         raw_fact_sbt_region_metadata_ready_mask,
         raw_fact_record_selector_ready_mask,
         raw_fact_resolved_target_ready_mask,
         sbt_address_ready_mask,
         raw_fact_sufficient_mask,
         raw_fact_missing_mask, current_cycle);

  printf("GPGPU-Sim RTCORE_SHADER_CONTINUATION_LOOP_DECISION "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
         "packet_schema_version=%u completion_visible_mask=0x%08x "
         "terminal_lane_mask=0x%08x continuation_lane_mask=0x%08x "
         "unsupported_reason_mask=0x%08x "
         "handoff_software_return_valid_mask=0x%08x "
         "next_active_mask=0x%08x final_like_mask=0x%08x "
         "missing_resume_handoff_mask=0x%08x "
         "shader_continuation_handoff_consume_mask=0x%08x "
         "shader_continuation_resume_handoff_publish_mask=0x%08x "
         "masked_off_lane_consume_mask=0x%08x "
         "shader_continuation_forced_no_resubmit=%u "
         "pre_submit_guard_passed=%u actual_resubmit_issued=0 "
         "shader_continuation_bridge_enqueued=%u "
         "shader_side_decision_cycle=%llu\n",
         m_sid, event->warp_uid, event->warp_id, issued_active_mask,
         packet_schema_version, completion_visible_mask, terminal_lane_mask,
         continuation_lane_mask, unsupported_reason_mask,
         handoff_software_return_valid_mask, next_active_mask, final_like_mask,
         missing_resume_handoff_mask, handoff_result_consume_mask,
         resume_handoff_publish_mask, masked_off_lane_consume_mask,
         shader_continuation_forced_no_resubmit ? 1u : 0u,
         pre_submit_guard_passed ? 1u : 0u,
         bridge_enqueued ? 1u : 0u, current_cycle);
  fflush(stdout);
}

void rt_unit::enqueue_synthetic_completion(
    const warp_inst_t &inst, unsigned long long current_cycle) {
  if (inst.rt_subop != RT_CORE_SUBOP_SUBMIT) {
    return;
  }

  rtcore_synthetic_completion_event event;
  event.warp_uid = inst.get_uid();
  event.warp_id = inst.warp_id();
  event.rt_subop = inst.rt_subop;
  event.issued_active_mask =
      static_cast<unsigned>(inst.get_warp_active_mask().to_ulong());
  event.adapter_active_mask = 0;
  event.adapter_completed_lane_mask = 0;
  event.adapter_static_inst_uid = 0;
  event.adapter_max_node_visits = 0;
  event.adapter_max_primitive_tests = 0;
  event.has_provider_materialized_traversal_input_snapshot = false;
  event.provider_materialized_traversal_input_snapshot_valid = false;
  event.provider_materialized_traversal_input_snapshot_source = "unavailable";
  event.provider_materialized_traversal_input_actual_abi_snapshot_admitted =
      false;
  event.provider_materialized_traversal_input_decoded_value_record_valid =
      false;
  event.provider_materialized_traversal_input_decoded_value_record_source =
      "unavailable";
  event.provider_materialized_traversal_input_decoded_value_record_consumed =
      false;
  event
      .provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid =
      false;
  event
      .provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted =
      false;
  event
      .provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed =
      false;
  event
      .provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason =
      "unavailable";
  event.provider_backend_input_authority_pre_call_guard_required = false;
  event.provider_backend_input_authority_pre_call_guard_ready = false;
  event.adapter_completion_ready = false;
  event.adapter_completion_claimed = false;
  event.adapter_completion_issue_mask_match = false;
  event.adapter_completion_issued_lanes_complete = false;
  event.enqueue_cycle = current_cycle;
  event.waiting_rtcore_pending = true;
  event.scoreboard_blocked_logged = false;
  event.scoreboard_packet_acquired = false;
  event.waiting_rtcore_enqueue_cycle = current_cycle;
  event.scoreboard_wakeup_cycle = 0;
  event.shader_continuation_loop_decision_logged = false;
  event.shader_continuation_next_active_mask = 0;
  event.shader_continuation_final_like_mask = 0;
  event.shader_continuation_missing_resume_handoff_mask = 0;
  event.shader_continuation_handoff_consume_mask = 0;
  event.shader_continuation_resume_handoff_publish_mask = 0;
  event.shader_continuation_decision_cycle = 0;
  claim_adapter_completion_for_issue(&event);
  rtcore_completion_timing_snapshot timing_snapshot =
      rtcore_make_completion_timing_snapshot(event);
  rtcore_apply_completion_timing_snapshot(&event, timing_snapshot);
  const bool new_event =
      m_synthetic_warp_completion_entries.find(inst.get_uid()) ==
      m_synthetic_warp_completion_entries.end();
  m_synthetic_warp_completion_entries[inst.get_uid()] = event;
  if (new_event) {
    rtcore_record_warp_completion_entry_enqueue(inst);
  }
  rtcore_record_submit_pending_ownership(inst, event, current_cycle);
}

bool rt_unit::synthetic_completion_ready(
    const warp_inst_t &inst, unsigned long long current_cycle) {
  if (inst.rt_subop != RT_CORE_SUBOP_SUBMIT) {
    return true;
  }
  std::map<unsigned, rtcore_synthetic_completion_event>::iterator event =
      m_synthetic_warp_completion_entries.find(inst.get_uid());
  if (event == m_synthetic_warp_completion_entries.end()) {
    return false;
  }
  if (!event->second.adapter_completion_ready) {
    const bool was_ready = event->second.adapter_completion_ready;
    claim_adapter_completion_for_issue(&event->second);
    if (!was_ready && event->second.adapter_completion_ready) {
      rtcore_completion_timing_snapshot timing_snapshot =
          rtcore_make_completion_timing_snapshot(event->second);
      rtcore_apply_completion_timing_snapshot(&event->second, timing_snapshot);
    }
  }
  return event->second.adapter_completion_ready &&
         current_cycle >= event->second.ready_cycle;
}

void rt_unit::retire_synthetic_completion(const warp_inst_t &inst) {
  if (inst.rt_subop == RT_CORE_SUBOP_SUBMIT) {
    rtcore_record_warp_completion_entry_retire(inst);
    std::map<unsigned, rtcore_synthetic_completion_event>::const_iterator event =
        m_synthetic_warp_completion_entries.find(inst.get_uid());
    if (event != m_synthetic_warp_completion_entries.end()) {
      const bool completion_released =
          rtcore_release_replay_warp_completion_entry(
              m_sid, inst.get_uid(), inst.warp_id(),
              event->second.issued_active_mask);
      if ((rtcore_v04_native_boundary_completion_gate_active() ||
           rtcore_v04_functional_only_engine_gate_active()) &&
          !completion_released) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_V04_NATIVE_BOUNDARY_FAULT "
                "owner_hw_sid=%u warp_uid=%u warp_id=%u "
                "active_mask=0x%08x phase=release "
                "fault=native_completion_release_rejected\n",
                m_sid, inst.get_uid(), inst.warp_id(),
                event->second.issued_active_mask);
        fflush(stderr);
        abort();
      }
    }
    m_synthetic_warp_completion_entries.erase(inst.get_uid());
  } else if (inst.rt_subop == RT_CORE_SUBOP_RETIRE_CONTEXT) {
    std::map<unsigned, rtcore_retire_transaction>::const_iterator transaction =
        m_retire_transactions.find(inst.get_uid());
    assert(transaction != m_retire_transactions.end());
    assert(transaction->second.ack_ready);
    m_retire_transactions.erase(inst.get_uid());
  }
}

void rt_unit::enqueue_retire_transaction(
    const warp_inst_t &inst, unsigned long long current_cycle) {
  assert(inst.rt_subop == RT_CORE_SUBOP_RETIRE_CONTEXT);
  if (!m_retire_transactions.empty()) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_RETIRE_TRANSACTION_INVARIANT "
            "reason=ADMISSION_FRONTEND_ALREADY_BUSY owner_hw_sid=%u "
            "warp_uid=%u warp_id=%u\n",
            m_sid, inst.get_uid(), inst.warp_id());
    fflush(stderr);
    abort();
  }

  const unsigned active_mask =
      static_cast<unsigned>(inst.get_warp_active_mask().to_ulong());
  const char *claim_failure = "accepted";
  if (!rtcore_claim_symbolic_retire_transaction(
          m_sid, inst.get_uid(), inst.warp_id(), active_mask, current_cycle,
          &claim_failure)) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_RETIRE_TRANSACTION_INVARIANT "
            "reason=%s phase=intent_claim owner_hw_sid=%u warp_uid=%u "
            "warp_id=%u active_mask=0x%08x\n",
            claim_failure, m_sid, inst.get_uid(), inst.warp_id(), active_mask);
    fflush(stderr);
    abort();
  }

  unsigned resident_generation = 0;
  unsigned bound_lane_mask = 0;
  unsigned pending_release_mask = 0;
  unsigned already_released_lane_mask = 0;
  unsigned resident_occupancy = 0;
  const char *begin_failure = "accepted";
  if (!rtcore_begin_retire_resident_rt_warp_transaction(
          m_sid, inst.get_uid(), inst.warp_id(), active_mask,
          &resident_generation, &bound_lane_mask, &pending_release_mask,
          &already_released_lane_mask, &resident_occupancy, &begin_failure) ||
      bound_lane_mask != active_mask) {
    fprintf(stderr,
            "GPGPU-Sim RTCORE_RETIRE_TRANSACTION_INVARIANT "
            "reason=%s phase=resident_begin owner_hw_sid=%u warp_uid=%u "
            "warp_id=%u active_mask=0x%08x bound_lane_mask=0x%08x\n",
            begin_failure, m_sid, inst.get_uid(), inst.warp_id(), active_mask,
            bound_lane_mask);
    fflush(stderr);
    abort();
  }

  rtcore_retire_transaction transaction;
  transaction.owner_hw_sid = m_sid;
  transaction.warp_uid = inst.get_uid();
  transaction.warp_id = inst.warp_id();
  transaction.active_mask = active_mask;
  transaction.resident_generation = resident_generation;
  transaction.bound_lane_mask = bound_lane_mask;
  transaction.pending_release_mask = pending_release_mask;
  transaction.already_released_lane_mask = already_released_lane_mask;
  transaction.retired_lane_mask = already_released_lane_mask;
  transaction.release_budget =
      rtcore_request_state_release_budget_config();
  transaction.resident_occupancy_at_begin = resident_occupancy;
  transaction.enqueue_cycle = current_cycle;
  if (transaction.pending_release_mask == 0) {
    transaction.last_lane_release_cycle = current_cycle;
    transaction.commit_ready_cycle = current_cycle + 1;
  }
  m_retire_transactions[inst.get_uid()] = transaction;

  printf("GPGPU-Sim RTCORE_RETIRE_TRANSACTION_ENQUEUE "
         "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
         "resident_generation=%u bound_lane_mask=0x%08x "
         "pending_release_mask=0x%08x already_released_lane_mask=0x%08x "
         "request_state_release_budget=%u "
         "resident_occupancy=%u scoreboard_pending=1 enqueue_cycle=%llu\n",
         m_sid, inst.get_uid(), inst.warp_id(), active_mask,
         resident_generation, bound_lane_mask, pending_release_mask,
         already_released_lane_mask, transaction.release_budget,
         resident_occupancy, current_cycle);
  fflush(stdout);
}

void rt_unit::service_retire_transaction(unsigned long long current_cycle) {
  if (m_retire_transactions.empty()) {
    return;
  }
  assert(m_retire_transactions.size() == 1);
  rtcore_retire_transaction &transaction =
      m_retire_transactions.begin()->second;

  if (transaction.pending_release_mask != 0) {
    unsigned released_this_cycle = 0;
    unsigned released_count = 0;
    for (unsigned lane = 0;
         lane < 32 && released_count < transaction.release_budget; ++lane) {
      const unsigned lane_mask = 1u << lane;
      if ((transaction.pending_release_mask & lane_mask) == 0) {
        continue;
      }
      unsigned retired_lane_mask = 0;
      unsigned remaining_lane_mask = 0;
      const char *drain_failure = "accepted";
      if (!rtcore_drain_retire_resident_rt_warp_lane(
              transaction.owner_hw_sid, transaction.warp_uid,
              transaction.warp_id, transaction.resident_generation, lane,
              current_cycle, &retired_lane_mask, &remaining_lane_mask,
              &drain_failure)) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_RETIRE_TRANSACTION_INVARIANT "
                "reason=%s phase=request_state_drain owner_hw_sid=%u "
                "warp_uid=%u warp_id=%u lane_id=%u\n",
                drain_failure, transaction.owner_hw_sid,
                transaction.warp_uid, transaction.warp_id, lane);
        fflush(stderr);
        abort();
      }
      if (transaction.resident_generation == 0) {
        transaction.retired_lane_mask |= lane_mask;
      } else {
        transaction.retired_lane_mask = retired_lane_mask;
      }
      transaction.pending_release_mask &= ~lane_mask;
      if (transaction.resident_generation != 0 &&
          remaining_lane_mask != transaction.pending_release_mask) {
        fprintf(stderr,
                "GPGPU-Sim RTCORE_RETIRE_TRANSACTION_INVARIANT "
                "reason=REQUEST_STATE_DRAIN_MASK_MISMATCH "
                "owner_hw_sid=%u warp_uid=%u warp_id=%u "
                "event_pending_mask=0x%08x replay_remaining_mask=0x%08x\n",
                transaction.owner_hw_sid, transaction.warp_uid,
                transaction.warp_id, transaction.pending_release_mask,
                remaining_lane_mask);
        fflush(stderr);
        abort();
      }
      released_this_cycle |= lane_mask;
      released_count++;
    }

    printf("GPGPU-Sim RTCORE_RETIRE_REQUEST_STATE_DRAIN "
           "owner_hw_sid=%u warp_uid=%u warp_id=%u "
           "request_state_release_budget=%u released_this_cycle_mask=0x%08x "
           "retired_lane_mask=0x%08x pending_release_mask=0x%08x "
           "resident_record_live=1 long_lifetime_resources_live=1 "
           "service_cycle=%llu\n",
           transaction.owner_hw_sid, transaction.warp_uid,
           transaction.warp_id, transaction.release_budget,
           released_this_cycle, transaction.retired_lane_mask,
           transaction.pending_release_mask, current_cycle);
    fflush(stdout);
    if (transaction.pending_release_mask == 0) {
      transaction.last_lane_release_cycle = current_cycle;
      transaction.commit_ready_cycle = current_cycle + 1;
    }
    return;
  }

  if (!transaction.lifecycle_committed &&
      current_cycle >= transaction.commit_ready_cycle) {
    const bool scoreboard_pending_before_ack =
        m_scoreboard != NULL &&
        m_scoreboard->isRtWarpPending(transaction.warp_id);
    if (!scoreboard_pending_before_ack) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_RETIRE_TRANSACTION_INVARIANT "
              "reason=RETIRE_ACK_SCOREBOARD_NOT_PENDING phase=lifecycle_commit "
              "owner_hw_sid=%u warp_uid=%u warp_id=%u\n",
              transaction.owner_hw_sid, transaction.warp_uid,
              transaction.warp_id);
      fflush(stderr);
      abort();
    }

    const rtcore_v04_retire_live_release_status live_release_status =
        rtcore_service_v04_global384_retire_live_release(
            transaction.owner_hw_sid, transaction.warp_uid,
            transaction.warp_id, transaction.resident_generation,
            transaction.active_mask, current_cycle);
    if (live_release_status == RTCORE_V04_RETIRE_LIVE_RELEASE_WAIT) {
      return;
    }
    if (live_release_status == RTCORE_V04_RETIRE_LIVE_RELEASE_FAULT) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_RETIRE_TRANSACTION_INVARIANT "
              "reason=GLOBAL384_LIVE_RELEASE_FAULT "
              "phase=live_bridge_release owner_hw_sid=%u "
              "warp_uid=%u warp_id=%u active_mask=0x%08x\n",
              transaction.owner_hw_sid, transaction.warp_uid,
              transaction.warp_id, transaction.active_mask);
      fflush(stderr);
      abort();
    }

    unsigned released_lane_mask = 0;
    const char *external_commit_failure = "accepted";
    if (!rtcore_commit_symbolic_retire_transaction(
            transaction.owner_hw_sid, transaction.warp_uid,
            transaction.warp_id, transaction.active_mask, current_cycle,
            &released_lane_mask, &external_commit_failure) ||
        released_lane_mask != transaction.active_mask) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_RETIRE_TRANSACTION_INVARIANT "
              "reason=%s phase=external_lifecycle_commit owner_hw_sid=%u "
              "warp_uid=%u warp_id=%u released_lane_mask=0x%08x\n",
              external_commit_failure, transaction.owner_hw_sid,
              transaction.warp_uid, transaction.warp_id,
              released_lane_mask);
      fflush(stderr);
      abort();
    }

    const char *resident_commit_failure = "accepted";
    if (!rtcore_commit_retire_resident_rt_warp_lifecycle(
            transaction.owner_hw_sid, transaction.warp_uid,
            transaction.warp_id, transaction.resident_generation,
            transaction.active_mask, true, current_cycle,
            &transaction.resident_occupancy_before_commit,
            &transaction.resident_occupancy_after_commit,
            &resident_commit_failure)) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_RETIRE_TRANSACTION_INVARIANT "
              "reason=%s phase=resident_lifecycle_commit owner_hw_sid=%u "
              "warp_uid=%u warp_id=%u\n",
              resident_commit_failure, transaction.owner_hw_sid,
              transaction.warp_uid, transaction.warp_id);
      fflush(stderr);
      abort();
    }
    const bool retire_frontend_busy_after_commit =
        rtcore_retire_lifecycle_busy_for_owner(transaction.owner_hw_sid);
    if (retire_frontend_busy_after_commit) {
      fprintf(stderr,
              "GPGPU-Sim RTCORE_RETIRE_TRANSACTION_INVARIANT "
              "reason=RETIRE_FRONTEND_NOT_RELEASED phase=lifecycle_commit "
              "owner_hw_sid=%u warp_uid=%u warp_id=%u\n",
              transaction.owner_hw_sid, transaction.warp_uid,
              transaction.warp_id);
      fflush(stderr);
      abort();
    }

    transaction.lifecycle_committed = true;
    transaction.lifecycle_commit_cycle = current_cycle;
    transaction.ack_ready = true;
    printf("GPGPU-Sim RTCORE_RETIRE_LIFECYCLE_ACK "
           "owner_hw_sid=%u warp_uid=%u warp_id=%u active_mask=0x%08x "
           "last_lane_release_cycle=%llu commit_ready_cycle=%llu "
           "lifecycle_commit_cycle=%llu retire_lifecycle_commit_cycles=1 "
           "resident_occupancy_before=%u resident_occupancy_after=%u "
           "scoreboard_pending_before_ack=%u ack_only=1 "
           "normal_register_writeback=0 v_result_writeback=0 "
           "handoff_result_writeback=0 "
           "retire_frontend_busy_after_commit=%u\n",
           transaction.owner_hw_sid, transaction.warp_uid,
           transaction.warp_id, transaction.active_mask,
           transaction.last_lane_release_cycle,
           transaction.commit_ready_cycle,
           transaction.lifecycle_commit_cycle,
           transaction.resident_occupancy_before_commit,
           transaction.resident_occupancy_after_commit,
           scoreboard_pending_before_ack ? 1u : 0u,
           retire_frontend_busy_after_commit ? 1u : 0u);
    fflush(stdout);
  }
}

bool rt_unit::retire_ack_ready(const warp_inst_t &inst) const {
  if (inst.rt_subop != RT_CORE_SUBOP_RETIRE_CONTEXT) {
    return false;
  }
  std::map<unsigned, rtcore_retire_transaction>::const_iterator transaction =
      m_retire_transactions.find(inst.get_uid());
  return transaction != m_retire_transactions.end() &&
         transaction->second.ack_ready;
}

rt_unit::rtcore_replay_release_identity_join_snapshot
rt_unit::rtcore_make_replay_release_identity_join_snapshot(
    bool identity_valid, bool progressed, bool memory_progressed,
    bool ready_progressed, unsigned identity_owner_hw_sid,
    unsigned identity_thread_uid, unsigned identity_lane_id,
    bool identity_has_warp_metadata, unsigned identity_warp_uid,
    unsigned identity_warp_id, unsigned identity_active_mask,
    unsigned identity_static_inst_uid,
    unsigned long long cycle, warp_inst_t &inst) const {
  rtcore_replay_release_identity_join_snapshot snapshot;
  snapshot.enabled = true;
  snapshot.identity_valid = identity_valid;
  snapshot.progressed = progressed;
  snapshot.memory_progressed = memory_progressed;
  snapshot.ready_progressed = ready_progressed;
  snapshot.identity_has_warp_metadata = identity_has_warp_metadata;
  snapshot.owner_hw_sid = m_sid;
  snapshot.cycle = cycle;
  snapshot.identity_owner_hw_sid = identity_owner_hw_sid;
  snapshot.identity_thread_uid = identity_thread_uid;
  snapshot.identity_lane_id = identity_lane_id;
  snapshot.identity_warp_uid = identity_warp_uid;
  snapshot.identity_warp_id = identity_warp_id;
  snapshot.identity_active_mask = identity_active_mask;
  snapshot.identity_static_inst_uid = identity_static_inst_uid;
  snapshot.joined_warp_uid = inst.get_uid();
  snapshot.joined_warp_id = inst.warp_id();
  snapshot.joined_static_inst_pc = inst.pc;

  if (identity_valid && identity_has_warp_metadata) {
    rtcore_replay_warp_completion_entry_snapshot completion_snapshot = {};
    rtcore_query_replay_warp_completion_entry(
        identity_owner_hw_sid, identity_warp_uid, identity_warp_id,
        identity_active_mask, &completion_snapshot);
    snapshot.warp_completion_entry_enabled =
        completion_snapshot.enabled;
    snapshot.warp_completion_entry_found = completion_snapshot.found;
    snapshot.warp_completion_all_active_lanes_complete =
        completion_snapshot.all_active_lanes_complete;
    snapshot.warp_completion_active_mask = completion_snapshot.active_mask;
    snapshot.warp_completion_admitted_lane_mask =
        completion_snapshot.admitted_lane_mask;
    snapshot.warp_completion_completed_lane_mask =
        completion_snapshot.completed_lane_mask;
    snapshot.warp_completion_completed_lane_count =
        completion_snapshot.completed_lane_count;
    snapshot.warp_completion_scoreboard_handoff_ready =
        completion_snapshot.scoreboard_handoff_ready;
    snapshot.warp_completion_scoreboard_handoff_delivered =
        completion_snapshot.scoreboard_handoff_delivered;
    snapshot.warp_completion_scoreboard_handoff_cycle =
        completion_snapshot.scoreboard_handoff_cycle;
  }

  if (!identity_valid || !identity_has_warp_metadata) {
    return snapshot;
  }

  snapshot.owner_sid_match = identity_owner_hw_sid == m_sid;
  snapshot.identity_warp_uid_match = identity_warp_uid == inst.get_uid();
  snapshot.identity_warp_id_match = identity_warp_id == inst.warp_id();
  snapshot.lane_in_range =
      identity_lane_id < inst.warp_size() && identity_lane_id < 32;
  std::map<unsigned, rtcore_synthetic_completion_event>::const_iterator event =
      m_synthetic_warp_completion_entries.find(inst.get_uid());
  snapshot.completion_event_found =
      event != m_synthetic_warp_completion_entries.end();
  if (snapshot.completion_event_found) {
    snapshot.joined_issued_active_mask = event->second.issued_active_mask;
  }

  if (snapshot.completion_event_found && snapshot.lane_in_range) {
    snapshot.issued_lane_active =
        (event->second.issued_active_mask & (1u << identity_lane_id)) != 0;
  }
  snapshot.joined = progressed && snapshot.owner_sid_match &&
                    snapshot.lane_in_range &&
                    snapshot.identity_warp_uid_match &&
                    snapshot.identity_warp_id_match &&
                    snapshot.issued_lane_active &&
                    snapshot.completion_event_found;
  return snapshot;
}

rt_unit::rtcore_synthetic_release_snapshot
rt_unit::rtcore_make_synthetic_release_snapshot(
    const warp_inst_t &inst, const rtcore_synthetic_completion_event &event,
    unsigned long long current_cycle) const {
  rtcore_synthetic_release_snapshot snapshot;
  snapshot.action = RTCORE_SYNTHETIC_RELEASE_ACTION_RELEASE;
  snapshot.submit = inst.rt_subop == RT_CORE_SUBOP_SUBMIT;
  snapshot.warp_uid = event.warp_uid;
  snapshot.warp_id = event.warp_id;
  snapshot.owner_hw_sid = m_sid;
  snapshot.static_inst_pc = inst.pc;
  snapshot.issued_active_mask = event.issued_active_mask;
  snapshot.adapter_active_mask = event.adapter_active_mask;
  snapshot.adapter_completed_lane_mask = event.adapter_completed_lane_mask;
  snapshot.adapter_max_node_visits = event.adapter_max_node_visits;
  snapshot.adapter_max_primitive_tests = event.adapter_max_primitive_tests;
  snapshot.has_provider_materialized_traversal_input_snapshot =
      event.has_provider_materialized_traversal_input_snapshot;
  snapshot.provider_materialized_traversal_input_snapshot_valid =
      event.provider_materialized_traversal_input_snapshot_valid;
  snapshot.provider_materialized_traversal_input_snapshot_source =
      event.provider_materialized_traversal_input_snapshot_source;
  snapshot.provider_materialized_traversal_input_actual_abi_snapshot_admitted =
      event
          .provider_materialized_traversal_input_actual_abi_snapshot_admitted;
  snapshot.provider_materialized_traversal_input_decoded_value_record_valid =
      event.provider_materialized_traversal_input_decoded_value_record_valid;
  snapshot.provider_materialized_traversal_input_decoded_value_record_source =
      event.provider_materialized_traversal_input_decoded_value_record_source;
  snapshot.provider_materialized_traversal_input_decoded_value_record_consumed =
      event
          .provider_materialized_traversal_input_decoded_value_record_consumed;
  snapshot
      .provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid =
      event
          .provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid;
  snapshot
      .provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted =
      event
          .provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted;
  snapshot
      .provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed =
      event
          .provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed;
  snapshot
      .provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason =
      event
          .provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason;
  snapshot.provider_backend_input_authority_pre_call_guard_required =
      event.provider_backend_input_authority_pre_call_guard_required;
  snapshot.provider_backend_input_authority_pre_call_guard_ready =
      event.provider_backend_input_authority_pre_call_guard_ready;
  snapshot.enqueue_cycle = event.enqueue_cycle;
  snapshot.ready_cycle = event.ready_cycle;
  snapshot.current_cycle = current_cycle;
  return snapshot;
}

void rt_unit::rtcore_apply_synthetic_release_snapshot(
    const rtcore_synthetic_release_snapshot &snapshot) const {
  if (!snapshot.submit) {
    return;
  }
  if (snapshot.action != RTCORE_SYNTHETIC_RELEASE_ACTION_RELEASE) {
    return;
  }

  printf("GPGPU-Sim PTX: RT-unit synthetic-completion-release, action=release, "
         "warp_uid=%u, warp_id=%u, owner_hw_sid=%u, "
         "static_inst_pc=0x%llx, issued_active_mask=0x%08x, "
         "adapter_active_mask=0x%08x, "
         "adapter_completed_lane_mask=0x%08x, ready_cycle=%llu, "
         "current_cycle=%llu, adapter_max_node_visits=%u, "
         "adapter_max_primitive_tests=%u, "
         "rt_unit_materialized_traversal_input_release_provenance=1, "
         "provider_materialized_traversal_input_snapshot=1, "
         "has_provider_materialized_traversal_input_snapshot=%u, "
         "provider_materialized_traversal_input_snapshot_valid=%u, "
         "provider_materialized_traversal_input_snapshot_source=%s, "
         "provider_materialized_traversal_input_actual_abi_snapshot_admitted=%u, "
         "provider_materialized_traversal_input_decoded_value_record_valid=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source=%s, "
         "provider_materialized_traversal_input_decoded_value_record_consumed=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason=%s, "
         "synthetic_release_backend_input_authority_pre_call_guard_required=%u, "
         "synthetic_release_backend_input_authority_pre_call_guard_ready=%u, "
         "synthetic_release_materialized_input_consumes_release_behavior=0, "
         "synthetic_release_decoded_value_record_consumes_release_behavior=0, "
         "synthetic_release_decoded_value_record_source_snapshot_consumes_release_behavior=0, "
         "synthetic_release_backend_input_authority_pre_call_guard_consumes_release_behavior=0\n",
         snapshot.warp_uid, snapshot.warp_id, snapshot.owner_hw_sid,
         static_cast<unsigned long long>(snapshot.static_inst_pc),
         snapshot.issued_active_mask, snapshot.adapter_active_mask,
         snapshot.adapter_completed_lane_mask, snapshot.ready_cycle,
         snapshot.current_cycle, snapshot.adapter_max_node_visits,
         snapshot.adapter_max_primitive_tests,
         snapshot.has_provider_materialized_traversal_input_snapshot ? 1 : 0,
         snapshot.provider_materialized_traversal_input_snapshot_valid ? 1 : 0,
         snapshot.provider_materialized_traversal_input_snapshot_source,
         snapshot.provider_materialized_traversal_input_actual_abi_snapshot_admitted
             ? 1
             : 0,
         snapshot.provider_materialized_traversal_input_decoded_value_record_valid
             ? 1
             : 0,
         snapshot
             .provider_materialized_traversal_input_decoded_value_record_source,
         snapshot
                 .provider_materialized_traversal_input_decoded_value_record_consumed
             ? 1
             : 0,
         snapshot
                 .provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid
             ? 1
             : 0,
         snapshot
                 .provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted
             ? 1
             : 0,
         snapshot
                 .provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed
             ? 1
             : 0,
         snapshot
             .provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason,
         snapshot.provider_backend_input_authority_pre_call_guard_required ? 1
                                                                           : 0,
         snapshot.provider_backend_input_authority_pre_call_guard_ready ? 1
                                                                       : 0);
  fflush(stdout);

  rtcore_shadow_table_release_snapshot shadow_table_release =
      rtcore_make_shadow_table_release_snapshot(snapshot);
  rtcore_apply_shadow_table_release_snapshot(shadow_table_release);
  if (rtcore_scheduler_credit_ledger_shadow_table_real_mutation_preflight_enabled()) {
    rtcore_scheduler_credit_ledger_shadow_table_owner_key
        rtcore_scheduler_credit_ledger_shadow_table_key;
    rtcore_scheduler_credit_ledger_shadow_table_key.owner_hw_sid =
        snapshot.owner_hw_sid;
    rtcore_scheduler_credit_ledger_shadow_table_key.warp_uid =
        snapshot.warp_uid;
    rtcore_scheduler_credit_ledger_shadow_table_key.warp_id = snapshot.warp_id;
    rtcore_scheduler_credit_ledger_shadow_table_key.static_inst_pc =
        snapshot.static_inst_pc;
    rtcore_scheduler_credit_ledger_shadow_table_key.issued_active_mask =
        snapshot.issued_active_mask;
    rtcore_scheduler_credit_ledger_shadow_table_mutation_result
        rtcore_scheduler_credit_ledger_shadow_table_mutation =
            rtcore_scheduler_credit_ledger_shadow_table_release_mutation_preflight(
                rtcore_scheduler_credit_ledger_shadow_table_key);
    printf("GPGPU-Sim PTX: RT-unit "
           "scheduler-credit-ledger-shadow-table-real-mutation-preflight=1, "
           "mutation_phase=completion_release, owner_hw_sid=%u, "
           "warp_uid=%u, warp_id=%u, "
           "static_inst_pc=0x%llx, issued_active_mask=0x%08x, "
           "release_attempted=%u, entry_found=%u, capacity_limit=%u, "
           "table_entries_before=%u, table_entries_after=%u, "
           "owner_tuple_released=%u, capacity_reclaimed=%u, "
           "capacity_mutated=%u, reusable_slot_published=%u, "
           "mutation_result=%s, transition_reason=%s\n",
           snapshot.owner_hw_sid, snapshot.warp_uid, snapshot.warp_id,
           static_cast<unsigned long long>(snapshot.static_inst_pc),
           snapshot.issued_active_mask, 1,
           rtcore_scheduler_credit_ledger_shadow_table_mutation.entry_found ? 1
                                                                            : 0,
           rtcore_scheduler_credit_ledger_shadow_table_mutation.capacity_limit,
           rtcore_scheduler_credit_ledger_shadow_table_mutation
               .table_entries_before,
           rtcore_scheduler_credit_ledger_shadow_table_mutation
               .table_entries_after,
           rtcore_scheduler_credit_ledger_shadow_table_mutation
                   .owner_tuple_released
               ? 1
               : 0,
           rtcore_scheduler_credit_ledger_shadow_table_mutation
                   .capacity_reclaimed
               ? 1
               : 0,
           rtcore_scheduler_credit_ledger_shadow_table_mutation.capacity_mutated
               ? 1
               : 0,
           rtcore_scheduler_credit_ledger_shadow_table_mutation
                   .reusable_slot_published
               ? 1
               : 0,
           rtcore_scheduler_credit_ledger_shadow_table_mutation.mutation_result,
           rtcore_scheduler_credit_ledger_shadow_table_mutation
               .transition_reason);
    fflush(stdout);
    if (rtcore_scheduler_credit_ledger_reusable_slot_publication_preflight_enabled()) {
      if (rtcore_scheduler_credit_ledger_shadow_table_mutation
              .reusable_slot_published) {
        rtcore_scheduler_credit_ledger_publish_reusable_credit_provenance_preflight(
            shadow_table_release
                .has_provider_materialized_traversal_input_snapshot,
            shadow_table_release
                .provider_materialized_traversal_input_snapshot_valid,
            shadow_table_release
                .provider_materialized_traversal_input_snapshot_source,
            shadow_table_release
                .provider_materialized_traversal_input_actual_abi_snapshot_admitted,
            shadow_table_release
                .provider_materialized_traversal_input_decoded_value_record_valid,
            shadow_table_release
                .provider_materialized_traversal_input_decoded_value_record_source,
            shadow_table_release
                .provider_materialized_traversal_input_decoded_value_record_consumed,
            shadow_table_release
                .provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid,
            shadow_table_release
                .provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted,
            shadow_table_release
                .provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed,
            shadow_table_release
                .provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason);
      }
      const bool rtcore_scheduler_credit_ledger_publication_negative_fault =
          rtcore_scheduler_credit_ledger_shadow_table_real_mutation_duplicate_fault_enabled() ||
          rtcore_scheduler_credit_ledger_shadow_table_real_mutation_capacity_full_fault_enabled();
      const char *rtcore_scheduler_credit_ledger_publication_result =
          rtcore_scheduler_credit_ledger_shadow_table_mutation
                  .reusable_slot_published
              ? "reusable_slot_published_after_release"
              : (!rtcore_scheduler_credit_ledger_shadow_table_mutation
                          .owner_tuple_released
                     ? "reusable_slot_publication_skipped_missing_owner"
                     : (rtcore_scheduler_credit_ledger_publication_negative_fault
                            ? "reusable_slot_publication_blocked_negative_fault"
                            : "reusable_slot_publication_not_published"));
      printf("GPGPU-Sim PTX: RT-unit "
             "scheduler-credit-ledger-reusable-slot-publication-preflight=1, "
             "owner_hw_sid=%u, warp_uid=%u, warp_id=%u, "
             "static_inst_pc=0x%llx, issued_active_mask=0x%08x, "
             "publication_attempted=%u, owner_tuple_released=%u, "
             "capacity_reclaimed=%u, reusable_slot_published=%u, "
             "scheduler_credit_ledger_reusable_slot_publication_materialized_input_provenance=1, "
             "provider_materialized_traversal_input_snapshot=1, "
             "has_provider_materialized_traversal_input_snapshot=%u, "
             "provider_materialized_traversal_input_snapshot_valid=%u, "
             "provider_materialized_traversal_input_snapshot_source=%s, "
             "provider_materialized_traversal_input_actual_abi_snapshot_admitted=%u, "
             "provider_materialized_traversal_input_decoded_value_record_valid=%u, "
             "provider_materialized_traversal_input_decoded_value_record_source=%s, "
             "provider_materialized_traversal_input_decoded_value_record_consumed=%u, "
             "provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid=%u, "
             "provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted=%u, "
             "provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed=%u, "
             "provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason=%s, "
             "publication_materialized_input_consumes_publication_behavior=0, "
             "reusable_slot_decoded_value_record_source_snapshot_consumes_publication_behavior=0, "
             "publication_result=%s, transition_reason=%s\n",
             snapshot.owner_hw_sid, snapshot.warp_uid, snapshot.warp_id,
             static_cast<unsigned long long>(snapshot.static_inst_pc),
             snapshot.issued_active_mask, 1,
             rtcore_scheduler_credit_ledger_shadow_table_mutation
                     .owner_tuple_released
                 ? 1
                 : 0,
             rtcore_scheduler_credit_ledger_shadow_table_mutation
                     .capacity_reclaimed
                 ? 1
                 : 0,
             rtcore_scheduler_credit_ledger_shadow_table_mutation
                     .reusable_slot_published
                 ? 1
                 : 0,
             shadow_table_release
                     .has_provider_materialized_traversal_input_snapshot
                 ? 1
                 : 0,
             shadow_table_release
                     .provider_materialized_traversal_input_snapshot_valid
                 ? 1
                 : 0,
             shadow_table_release
                 .provider_materialized_traversal_input_snapshot_source,
             shadow_table_release
                     .provider_materialized_traversal_input_actual_abi_snapshot_admitted
                 ? 1
                 : 0,
             shadow_table_release
                     .provider_materialized_traversal_input_decoded_value_record_valid
                 ? 1
                 : 0,
             shadow_table_release
                 .provider_materialized_traversal_input_decoded_value_record_source,
             shadow_table_release
                     .provider_materialized_traversal_input_decoded_value_record_consumed
                 ? 1
                 : 0,
             shadow_table_release
                     .provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid
                 ? 1
                 : 0,
             shadow_table_release
                     .provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted
                 ? 1
                 : 0,
             shadow_table_release
                     .provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed
                 ? 1
                 : 0,
             shadow_table_release
                 .provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason,
             rtcore_scheduler_credit_ledger_publication_result,
             "reusable_slot_publication_preflight");
      fflush(stdout);
    }
  }
}

bool rt_unit::rtcore_shadow_table_release_enabled() const {
  const char *value = getenv(rtcore_shadow_table_release_skeleton_env_name());
  return value != NULL && *value != '\0' && strcmp(value, "0") != 0;
}

rt_unit::rtcore_shadow_table_release_snapshot
rt_unit::rtcore_make_shadow_table_release_snapshot(
    const rtcore_synthetic_release_snapshot &release_snapshot) const {
  rtcore_shadow_table_release_snapshot snapshot;
  snapshot.enabled =
      release_snapshot.submit &&
      release_snapshot.action == RTCORE_SYNTHETIC_RELEASE_ACTION_RELEASE &&
      rtcore_shadow_table_release_enabled();
  snapshot.submit = release_snapshot.submit;
  snapshot.owner_hw_sid = release_snapshot.owner_hw_sid;
  snapshot.warp_uid = release_snapshot.warp_uid;
  snapshot.warp_id = release_snapshot.warp_id;
  snapshot.static_inst_pc = release_snapshot.static_inst_pc;
  snapshot.issued_active_mask = release_snapshot.issued_active_mask;
  snapshot.has_provider_materialized_traversal_input_snapshot =
      release_snapshot.has_provider_materialized_traversal_input_snapshot;
  snapshot.provider_materialized_traversal_input_snapshot_valid =
      release_snapshot.provider_materialized_traversal_input_snapshot_valid;
  snapshot.provider_materialized_traversal_input_snapshot_source =
      release_snapshot.provider_materialized_traversal_input_snapshot_source;
  snapshot.provider_materialized_traversal_input_actual_abi_snapshot_admitted =
      release_snapshot
          .provider_materialized_traversal_input_actual_abi_snapshot_admitted;
  snapshot.provider_materialized_traversal_input_decoded_value_record_valid =
      release_snapshot
          .provider_materialized_traversal_input_decoded_value_record_valid;
  snapshot.provider_materialized_traversal_input_decoded_value_record_source =
      release_snapshot
          .provider_materialized_traversal_input_decoded_value_record_source;
  snapshot.provider_materialized_traversal_input_decoded_value_record_consumed =
      release_snapshot
          .provider_materialized_traversal_input_decoded_value_record_consumed;
  snapshot
      .provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid =
      release_snapshot
          .provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid;
  snapshot
      .provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted =
      release_snapshot
          .provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted;
  snapshot
      .provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed =
      release_snapshot
          .provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed;
  snapshot
      .provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason =
      release_snapshot
          .provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason;
  snapshot.provider_backend_input_authority_pre_call_guard_required =
      release_snapshot.provider_backend_input_authority_pre_call_guard_required;
  snapshot.provider_backend_input_authority_pre_call_guard_ready =
      release_snapshot.provider_backend_input_authority_pre_call_guard_ready;
  snapshot.release_attempted = snapshot.enabled;
  snapshot.entry_found = snapshot.enabled;
  snapshot.would_release_owner_tuple = snapshot.enabled;
  snapshot.owner_tuple_released = false;
  snapshot.would_reclaim_capacity = snapshot.enabled;
  snapshot.capacity_reclaimed = false;
  snapshot.capacity_mutated = false;
  snapshot.reusable_slot_published = false;
  snapshot.release_result =
      snapshot.enabled ? "shadow_table_would_release_noop"
                       : "shadow_table_release_skeleton_default_off";
  snapshot.transition_reason =
      snapshot.enabled ? "shadow_table_release_skeleton_noop"
                       : "shadow_table_release_skeleton_default_off";
  return snapshot;
}

void rt_unit::rtcore_apply_shadow_table_release_snapshot(
    const rtcore_shadow_table_release_snapshot &snapshot) const {
  if (!snapshot.enabled) {
    return;
  }

  printf("GPGPU-Sim PTX: RT-unit "
         "scheduler-credit-ledger-shadow-table-release-skeleton=1, "
         "owner_hw_sid=%u, warp_uid=%u, warp_id=%u, "
         "static_inst_pc=0x%llx, issued_active_mask=0x%08x, "
         "release_attempted=%u, entry_found=%u, "
         "would_release_owner_tuple=%u, owner_tuple_released=%u, "
         "would_reclaim_capacity=%u, capacity_reclaimed=%u, "
         "capacity_mutated=%u, reusable_slot_published=%u, "
         "scheduler_credit_ledger_shadow_table_release_materialized_input_provenance=1, "
         "provider_materialized_traversal_input_snapshot=1, "
         "has_provider_materialized_traversal_input_snapshot=%u, "
         "provider_materialized_traversal_input_snapshot_valid=%u, "
         "provider_materialized_traversal_input_snapshot_source=%s, "
         "provider_materialized_traversal_input_actual_abi_snapshot_admitted=%u, "
         "provider_materialized_traversal_input_decoded_value_record_valid=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source=%s, "
         "provider_materialized_traversal_input_decoded_value_record_consumed=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed=%u, "
         "provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason=%s, "
         "shadow_table_release_backend_input_authority_pre_call_guard_required=%u, "
         "shadow_table_release_backend_input_authority_pre_call_guard_ready=%u, "
         "shadow_table_release_materialized_input_consumes_mutation=0, "
         "shadow_table_release_decoded_value_record_source_snapshot_consumes_mutation=0, "
         "shadow_table_release_backend_input_authority_pre_call_guard_consumes_mutation=0, "
         "release_result=%s, transition_reason=%s\n",
         snapshot.owner_hw_sid, snapshot.warp_uid, snapshot.warp_id,
         static_cast<unsigned long long>(snapshot.static_inst_pc),
         snapshot.issued_active_mask, snapshot.release_attempted ? 1 : 0,
         snapshot.entry_found ? 1 : 0,
         snapshot.would_release_owner_tuple ? 1 : 0,
         snapshot.owner_tuple_released ? 1 : 0,
         snapshot.would_reclaim_capacity ? 1 : 0,
         snapshot.capacity_reclaimed ? 1 : 0,
         snapshot.capacity_mutated ? 1 : 0,
         snapshot.reusable_slot_published ? 1 : 0,
         snapshot.has_provider_materialized_traversal_input_snapshot ? 1 : 0,
         snapshot.provider_materialized_traversal_input_snapshot_valid ? 1 : 0,
         snapshot.provider_materialized_traversal_input_snapshot_source,
         snapshot.provider_materialized_traversal_input_actual_abi_snapshot_admitted
             ? 1
             : 0,
         snapshot.provider_materialized_traversal_input_decoded_value_record_valid
             ? 1
             : 0,
         snapshot
             .provider_materialized_traversal_input_decoded_value_record_source,
         snapshot
                 .provider_materialized_traversal_input_decoded_value_record_consumed
             ? 1
             : 0,
         snapshot
                 .provider_materialized_traversal_input_decoded_value_record_source_snapshot_valid
             ? 1
             : 0,
         snapshot
                 .provider_materialized_traversal_input_decoded_value_record_source_snapshot_admitted
             ? 1
             : 0,
         snapshot
                 .provider_materialized_traversal_input_decoded_value_record_source_snapshot_consumed
             ? 1
             : 0,
         snapshot
             .provider_materialized_traversal_input_decoded_value_record_source_snapshot_block_reason,
         snapshot.provider_backend_input_authority_pre_call_guard_required ? 1
                                                                           : 0,
         snapshot.provider_backend_input_authority_pre_call_guard_ready ? 1
                                                                       : 0,
         snapshot.release_result,
         snapshot.transition_reason);
  fflush(stdout);
}

void rt_unit::cycle() {
  // Debugging roofline plot
  cacheline_count = 0;
  
  // Copy ldst unit injection mechanism
  warp_inst_t &pipe_reg = *m_dispatch_reg;
  
  occupied >>=1;
  
  unsigned long long current_cycle =  m_core->get_gpu()->gpu_sim_cycle +
                                      m_core->get_gpu()->gpu_tot_sim_cycle;

  unsigned resident_context_warps = 0;
  (void)rtcore_query_resident_rt_warp_record(
      m_sid, 0, NULL, NULL, NULL, &resident_context_warps);
  rtcore_v04_multiwarp_begin_cycle(
      m_sid, current_cycle, n_warps, resident_context_warps,
      m_config->m_rt_max_warps,
      m_config->m_L1D_config.get_total_size_inKB());

  rtcore_replay_cycle_hook_result replay_cycle_result =
      rtcore_maybe_service_replay_cycle_from_rt_unit(m_sid, current_cycle);
  rtcore_consume_replay_cycle_hook_result_from_rt_unit(
      replay_cycle_result, m_mf_allocator, m_config, m_core,
      (baseline_cache *)L1D, (baseline_cache *)m_L0_complet, m_stats, m_sid);

  // RT unit stats
  if (!pipe_reg.empty()) {
    n_warps++;
    RT_DPRINTF("Shader %d: A new warp has arrived! uid: %d, warp id: %d\n", m_sid, pipe_reg.get_uid(), pipe_reg.warp_id());
    // for (unsigned i=0; i<m_config->warp_size; i++) {
    //   RT_DPRINTF("\tThread %d (%d mem): ", i, pipe_reg.mem_list_length(i));
    //   for (auto it=pipe_reg.get_thread_info(i).RT_mem_accesses.begin(); it!=pipe_reg.get_thread_info(i).RT_mem_accesses.end(); it++) {
    //     RT_DPRINTF("0x%x\t", it->address);
    //   }
    //   RT_DPRINTF("\n");
    // }
    
    pipe_reg.set_start_cycle(current_cycle);
    pipe_reg.set_thread_end_cycle(current_cycle);
    if (pipe_reg.rt_subop == RT_CORE_SUBOP_SUBMIT) {
      if (rtcore_v04_multiwarp_stats_enabled()) {
        rtcore_v04_multiwarp_stats_for(m_sid).submit_arrivals++;
      }
      enqueue_synthetic_completion(pipe_reg, current_cycle);
    } else if (pipe_reg.rt_subop == RT_CORE_SUBOP_RETIRE_CONTEXT) {
      enqueue_retire_transaction(pipe_reg, current_cycle);
    }

    if (m_config->m_rt_coherence_engine) {
      if (!m_ray_coherence_engine->m_initialized) {
        // Get world min/max
        m_ray_coherence_engine->set_world(
          GPGPU_Context()->func_sim->g_rt_world_min,
          GPGPU_Context()->func_sim->g_rt_world_max
        );
        m_ray_coherence_engine->m_initialized = true;
      }
      m_ray_coherence_engine->insert(pipe_reg);
    }
  }

  if (replay_cycle_result.progressed &&
      replay_cycle_result.identity_valid &&
      replay_cycle_result.identity_has_warp_metadata) {
    rtcore_v04_multiwarp_stats &stats =
        rtcore_v04_multiwarp_stats_for(m_sid);
    rtcore_v04_multiwarp_mark_progress(
        m_sid, replay_cycle_result.identity_warp_id,
        &stats.replay_progress_observations);
  }
  if (replay_cycle_result.lsu_sideband_valid) {
    rtcore_v04_multiwarp_stats &stats =
        rtcore_v04_multiwarp_stats_for(m_sid);
    rtcore_v04_multiwarp_mark_progress(
        m_sid, replay_cycle_result.memory_unit_snapshot.resident_warp_id,
        &stats.memory_issue_progress_observations);
  }

  service_retire_transaction(current_cycle);
  
  if (n_warps > 0 || !pipe_reg.empty()) {
    m_stats->rt_total_cycles[m_sid]++;
    m_stats->rt_total_cycles_sum++;
  }
  
  // Cycle intersection tests + get stats
  unsigned n_threads = 0;
  unsigned active_threads = 0;
  std::map<new_addr_type, unsigned> addr_set;
  for (auto it=m_current_warps.begin(); it!=m_current_warps.end(); ++it) {
    n_threads += (it->second).dec_thread_latency(mem_store_q);
    active_threads += (it->second).get_rt_active_threads();
    (it->second).num_unique_mem_access(addr_set);
  }
  if (m_config->m_rt_coherence_engine) m_ray_coherence_engine->dec_thread_latency();
  // Number of threads currently completing intersection tests are the number of intersection operations this cycle
  assert(n_threads <= (m_config->warp_size * m_config->m_rt_max_warps));
  m_stats->rt_total_intersection_stages[m_sid] += n_threads;
  
  if (mem_store_q.size() > m_stats->rt_max_store_q) {
    m_stats->rt_max_store_q = mem_store_q.size();
  }
  if (!mem_store_q.empty()) {
    m_stats->rt_mem_store_q_cycles[m_sid]++;
  }

  // Cycle coherence engine
  if (m_config->m_rt_coherence_engine)
    m_ray_coherence_engine->cycle();

  // AerialVision stats
  m_stats->rt_nwarps[m_sid] = n_warps;
  m_stats->rt_nthreads[m_sid] = active_threads;
  m_stats->rt_naccesses[m_sid] = addr_set.size();
  m_stats->rt_nthreads_intersection[m_sid] = n_threads;
  unsigned max = 0;
  for (auto it=addr_set.begin(); it!=addr_set.end(); it++) {
    if (it->second > max) {
      max = it->second;
    }
  }
  m_stats->rt_max_coalesce[m_sid] = max;
  m_stats->rt_mshr_size[m_sid] = L1D->num_mshr_entries();
  
  // Check memory request responses
  if (!m_response_fifo.empty()) {
      
    // Retrieve mf from response fifo
    mem_fetch *mf = m_response_fifo.front();
    m_response_fifo.pop_front();
    if (rtcore_v04_multiwarp_stats_enabled()) {
      rtcore_v04_multiwarp_stats &stats =
          rtcore_v04_multiwarp_stats_for(m_sid);
      rtcore_v04_multiwarp_mark_progress(
          m_sid, mf->get_wid(),
          &stats.memory_response_progress_observations);
    }
    new_addr_type addr = mf->get_addr();
 
    new_addr_type uncoalesced_base_addr = mf->get_uncoalesced_base_addr();
    
    RT_DPRINTF("Shader %d: Memory response for 0x%x\n", m_sid, uncoalesced_base_addr);
    
    // Update MF
    mf->set_status(IN_SHADER_FETCHED,
                  m_core->get_gpu()->gpu_sim_cycle +
                  m_core->get_gpu()->gpu_tot_sim_cycle);

    // Handle write ACKs
    if (mf->get_is_write()) {
      m_stats->rt_writes++;

      // Find warp (expect a unique warp)
      bool found = false;
      for (auto it=m_current_warps.begin(); it!=m_current_warps.end(); it++) {
        if (it->second.check_pending_writes(uncoalesced_base_addr)) {
          // Found instruction that sent the pending write
          found = true;
          break;
        }
      }
      assert(found);
      delete mf;
    }

    else {      
      // Every returned mf is a fetched cacheline
      m_stats->rt_total_cacheline_fetched[m_sid]++;
      cacheline_count++;
                            
      // Update cache
      if (!m_config->bypassL0Complet) {
        if (m_config->m_rt_use_l1d) {
          L1D->fill( mf, m_core->get_gpu()->gpu_sim_cycle +
                          m_core->get_gpu()->gpu_tot_sim_cycle);
        }
        else {
          m_L0_complet->fill( mf, m_core->get_gpu()->gpu_sim_cycle +
                            m_core->get_gpu()->gpu_tot_sim_cycle);
        }
      }
      
      if (m_config->m_rt_coherence_engine) {
        std::map<unsigned, warp_inst_t *> m_warp_pointers;
        for (auto it=m_current_warps.begin(); it!=m_current_warps.end(); it++) {
          m_warp_pointers[it->first] = &it->second;
        }
        m_ray_coherence_engine->process_response(mf, m_warp_pointers, &pipe_reg);
      }
      else {
        process_memory_response(mf, pipe_reg);
      }
    }
  }
    
  writeback();
  
  // Cycle caches
  m_L0_complet->cycle();
  
  // Move new warp into collection of warps
  if (!pipe_reg.empty()) m_current_warps[pipe_reg.get_uid()] = pipe_reg;
  m_dispatch_reg->clear();

  // Choose next warp
  warp_inst_t rt_inst;

  // Check if there are outstanding chunks to request
  if (!mem_access_q.empty()) {
    // Check if warp still exists
    if (m_current_warps.find(mem_access_q_warp_uid) == m_current_warps.end()) {
      printf("Memory chunk original warp not found (w_uid: %d); erasing memory accesses starting with 0x%x.\n", mem_access_q_warp_uid, mem_access_q.front());
      mem_access_q.clear();
      if (mem_store_q.empty()) {
        schedule_next_warp(rt_inst);
      }
    }
    else {
      // Find the appropriate warp
      rt_inst = m_current_warps[mem_access_q_warp_uid];
      m_current_warps.erase(mem_access_q_warp_uid);
    }
  }
  else if (mem_store_q.empty() && !m_config->m_rt_coherence_engine) {
    // Choose next warp
    schedule_next_warp(rt_inst);
  }
  else if (mem_store_q.empty() && m_config->m_rt_coherence_engine) {
    // Check if active
    if (m_ray_coherence_engine->active()) {
      unsigned warp_uid = m_ray_coherence_engine->schedule_next_warp();
      rt_inst = m_current_warps[warp_uid];
      m_current_warps.erase(warp_uid);
    }
  }
  
  // Get cycle status
  if (!rt_inst.empty()) rt_inst.track_rt_cycles(true);
  for (auto it=m_current_warps.begin(); it!=m_current_warps.end(); it++) {
    (it->second).track_rt_cycles(false);
  }

  // Schedule next memory request
  if (!rt_inst.empty() && rtcore_v04_multiwarp_stats_enabled()) {
    rtcore_v04_multiwarp_stats &stats =
        rtcore_v04_multiwarp_stats_for(m_sid);
    rtcore_v04_multiwarp_mark_progress(
        m_sid, rt_inst.warp_id(),
        &stats.scheduled_warp_progress_observations);
  }
  memory_cycle(rt_inst);

  // Place warp back
  if (!rt_inst.empty()) m_current_warps[rt_inst.get_uid()] = rt_inst;
  
  // Check to see if any warps are complete
  int completed_warp_uid = -1;
  for (auto it=m_current_warps.begin(); it!=m_current_warps.end(); it++) {
    warp_inst_t debug_inst = it->second;
    assert(it->first == debug_inst.get_uid());
    RT_DPRINTF("Checking warp inst uid: %d\n", debug_inst.get_uid());
    const bool synthetic_submit_completion_ready =
        synthetic_completion_ready(it->second, current_cycle);
    rtcore_replay_release_identity_join_snapshot release_identity_join =
        rtcore_make_replay_release_identity_join_snapshot(
            replay_cycle_result.identity_valid, replay_cycle_result.progressed,
            replay_cycle_result.memory_progressed,
            replay_cycle_result.ready_progressed,
            replay_cycle_result.identity_owner_hw_sid,
            replay_cycle_result.identity_thread_uid,
            replay_cycle_result.identity_lane_id,
            replay_cycle_result.identity_has_warp_metadata,
            replay_cycle_result.identity_warp_uid,
            replay_cycle_result.identity_warp_id,
            replay_cycle_result.identity_active_mask,
            replay_cycle_result.identity_static_inst_uid,
            replay_cycle_result.cycle,
            it->second);
    rtcore_replay_warp_completion_entry_snapshot candidate_completion = {};
    const bool synthetic_submit_release_candidate =
        it->second.rt_subop == RT_CORE_SUBOP_SUBMIT &&
        synthetic_submit_completion_ready;
    const std::map<unsigned, rtcore_synthetic_completion_event>::const_iterator
        candidate_completion_event =
            m_synthetic_warp_completion_entries.find(it->second.get_uid());
    const bool candidate_completion_event_found =
        candidate_completion_event != m_synthetic_warp_completion_entries.end();
    const unsigned candidate_issued_active_mask =
        candidate_completion_event_found
            ? candidate_completion_event->second.issued_active_mask
            : 0;
    if (synthetic_submit_release_candidate &&
        candidate_completion_event_found) {
      rtcore_query_replay_warp_completion_entry(m_sid, it->second.get_uid(),
          it->second.warp_id(), candidate_issued_active_mask,
          &candidate_completion);
      if (candidate_completion.enabled && candidate_completion.found &&
          candidate_completion.all_active_lanes_complete) {
        rtcore_apply_replay_completion_packet_test_corruption(
            &candidate_completion);
        const char *packet_failure_reason = NULL;
        if (!rtcore_validate_replay_completion_packet(
                candidate_completion, m_sid, it->second.get_uid(),
                it->second.warp_id(), candidate_issued_active_mask,
                &packet_failure_reason)) {
          fprintf(stderr,
                  "GPGPU-Sim RTCORE_REPLAY_COMPLETION_PACKET_INVALID "
                  "reason=%s owner_hw_sid=%u warp_uid=%u warp_id=%u "
                  "active_mask=0x%08x\n",
                  packet_failure_reason != NULL ? packet_failure_reason
                                                : "unknown",
                  m_sid, it->second.get_uid(), it->second.warp_id(),
                  candidate_issued_active_mask);
          fflush(stderr);
          abort();
        }
      }
    }
    const bool completion_ready_but_scoreboard_blocked =
        synthetic_submit_release_candidate &&
        candidate_completion_event_found &&
        candidate_completion.enabled && candidate_completion.found &&
        candidate_completion.all_active_lanes_complete &&
        !candidate_completion.scoreboard_handoff_delivered;
    if (completion_ready_but_scoreboard_blocked) {
      std::map<unsigned, rtcore_synthetic_completion_event>::iterator
          blocked_event =
              m_synthetic_warp_completion_entries.find(it->second.get_uid());
      if (blocked_event != m_synthetic_warp_completion_entries.end()) {
        rtcore_record_completion_ready_but_scoreboard_blocked(
            it->second, &blocked_event->second,
            candidate_completion.packet_schema_version,
            candidate_completion.lane_completion_valid_mask,
            candidate_completion.terminal_lane_mask,
            candidate_completion.continuation_lane_mask, current_cycle);
      }
    }
    const bool candidate_scoreboard_handoff_release_allowed =
        synthetic_submit_release_candidate &&
        candidate_completion_event_found &&
        candidate_completion.enabled && candidate_completion.found &&
        candidate_completion.all_active_lanes_complete &&
        candidate_completion.scoreboard_handoff_delivered;
    const bool activation_enabled =
        rtcore_v04_functional_only_engine_gate_active() ||
        rtcore_replay_release_gate_activation_enabled() ||
        rtcore_v04_native_boundary_completion_gate_active();
    const bool activation_blocked =
        activation_enabled && synthetic_submit_release_candidate &&
        !candidate_scoreboard_handoff_release_allowed;
    const bool gated_synthetic_submit_completion_ready =
        synthetic_submit_completion_ready &&
        (!activation_enabled || it->second.rt_subop != RT_CORE_SUBOP_SUBMIT ||
         candidate_scoreboard_handoff_release_allowed);
    const bool retire_ack_ready = this->retire_ack_ready(it->second);
    const bool rtcore_instruction_completion_ready =
        it->second.rt_subop == RT_CORE_SUBOP_RETIRE_CONTEXT
            ? retire_ack_ready
            : gated_synthetic_submit_completion_ready;
    const unsigned long long candidate_release_gate_blocked_cycles =
        rtcore_update_replay_release_gate_activation_blocked_cycles(
            synthetic_submit_release_candidate &&
                candidate_completion_event_found,
            m_sid, it->second.get_uid(), it->second.warp_id(),
            candidate_issued_active_mask, activation_blocked,
            candidate_scoreboard_handoff_release_allowed);
    rtcore_record_replay_release_gate_decision(
        replay_cycle_result, synthetic_submit_completion_ready,
        release_identity_join.joined,
        release_identity_join.warp_completion_entry_enabled,
        release_identity_join.warp_completion_entry_found,
        release_identity_join.warp_completion_all_active_lanes_complete,
        release_identity_join.warp_completion_scoreboard_handoff_delivered,
        candidate_completion.enabled, candidate_completion.found,
        candidate_completion.all_active_lanes_complete,
        candidate_completion.scoreboard_handoff_delivered,
        candidate_scoreboard_handoff_release_allowed, activation_enabled,
        activation_blocked, candidate_release_gate_blocked_cycles);
    // A completed warp has no more memory accesses and all the intersection
    // delays are complete and has no pending writes
    if (rtcore_instruction_completion_ready &&
        it->second.rt_mem_accesses_empty() &&
        it->second.rt_intersection_delay_done() &&
        !it->second.has_pending_writes()) {
      RT_DPRINTF("Shader %d: Warp %d (uid: %d) completed!\n", m_sid,
                 it->second.warp_id(), it->first);
      if (retire_ack_ready || m_operand_collector->writeback(it->second)) {
        if (it->second.rt_subop == RT_CORE_SUBOP_SUBMIT) {
          std::map<unsigned, rtcore_synthetic_completion_event>::iterator
              release_event = m_synthetic_warp_completion_entries.find(
                  it->second.get_uid());
          if (release_event != m_synthetic_warp_completion_entries.end()) {
            if (candidate_scoreboard_handoff_release_allowed) {
              rtcore_log_v04_completion_boundary(
                  candidate_completion, current_cycle);
              if (!rtcore_v04_direct_completion(candidate_completion)) {
                const char *v04_shadow_image_failure_reason = NULL;
                if (!rtcore_observe_v04_shadow_completion_packet_image(
                        candidate_completion,
                        release_event->second.issued_active_mask, current_cycle,
                        &v04_shadow_image_failure_reason)) {
                  fprintf(stderr,
                          "GPGPU-Sim "
                          "RTCORE_V04_SHADOW_COMPLETION_PACKET_INVALID "
                          "reason=%s owner_hw_sid=%u warp_uid=%u "
                          "warp_id=%u active_mask=0x%08x\n",
                          v04_shadow_image_failure_reason != NULL
                              ? v04_shadow_image_failure_reason
                              : "unknown",
                          m_sid, it->second.get_uid(), it->second.warp_id(),
                          release_event->second.issued_active_mask);
                  fflush(stderr);
                  abort();
                }
              }
              rtcore_materialize_scoreboard_v_result(
                  it->second, candidate_completion, current_cycle);
              rtcore_record_resident_warp_wakeup(
                  it->second, &release_event->second,
                  candidate_completion.packet_schema_version,
                  candidate_completion.lane_completion_valid_mask,
                  candidate_completion.terminal_lane_mask,
                  candidate_completion.continuation_lane_mask, current_cycle);
              if (candidate_completion.v04_functional_only_completion ||
                  (candidate_completion.v04_native_resident_completion &&
                   rtcore_v04_continuation_lifecycle_gate_active())) {
                const unsigned native_target_reason_mask =
                    candidate_completion.lane_completion_valid_mask;
                const unsigned native_sbt_address_ready_mask =
                    rtcore_shader_continuation_sbt_record_selector_ready_mask(
                        candidate_completion, native_target_reason_mask);
                if (native_sbt_address_ready_mask !=
                    native_target_reason_mask) {
                  fprintf(stderr,
                          "GPGPU-Sim "
                          "RTCORE_V04_NATIVE_CONTINUATION_FAULT "
                          "owner_hw_sid=%u warp_uid=%u warp_id=%u "
                          "active_mask=0x%08x target_mask=0x%08x "
                          "sbt_ready_mask=0x%08x "
                          "fault=native_dispatch_input_incomplete\n",
                          m_sid, release_event->second.warp_uid,
                          release_event->second.warp_id,
                          release_event->second.issued_active_mask,
                          native_target_reason_mask,
                          native_sbt_address_ready_mask);
                  fflush(stderr);
                  abort();
                }
                rtcore_record_shader_continuation_direct_callshader_action(
                    m_core, it->second, m_sid, release_event->second.warp_uid,
                    release_event->second.warp_id,
                    release_event->second.issued_active_mask,
                    candidate_completion, native_target_reason_mask,
                    native_sbt_address_ready_mask, current_cycle);
                printf(
                    "GPGPU-Sim "
                    "RTCORE_V04_NATIVE_CONTINUATION_DISPATCH "
                    "owner_hw_sid=%u warp_uid=%u warp_id=%u "
                    "active_mask=0x%08x continuation_mask=0x%08x "
                    "terminal_mask=0x%08x "
                    "input_authority=v04_handoff "
                    "legacy_candidate_authority=0 "
                    "dispatch_cycle=%llu\n",
                    m_sid, release_event->second.warp_uid,
                    release_event->second.warp_id,
                    release_event->second.issued_active_mask,
                    candidate_completion.continuation_lane_mask,
                    candidate_completion.terminal_lane_mask, current_cycle);
                fflush(stdout);
              }
              if (!rtcore_v04_direct_completion(candidate_completion)) {
                const unsigned reason_oracle_miss_mask =
                    rtcore_shader_continuation_reason_mask(
                        candidate_completion,
                        RTCORE_SHADER_CONTINUATION_REASON_MISS);
                const unsigned reason_oracle_closest_hit_mask =
                    rtcore_shader_continuation_reason_mask(
                        candidate_completion,
                        RTCORE_SHADER_CONTINUATION_REASON_CLOSEST_HIT_READY);
                const unsigned reason_oracle_anyhit_mask =
                    rtcore_shader_continuation_reason_mask(
                        candidate_completion,
                        RTCORE_SHADER_CONTINUATION_REASON_ANY_HIT_REQUIRED);
                const unsigned reason_oracle_intersection_mask =
                    rtcore_shader_continuation_reason_mask(
                        candidate_completion,
                        RTCORE_SHADER_CONTINUATION_REASON_INTERSECTION_REQUIRED);
                const unsigned reason_synthetic_split_mask = 0;
                const unsigned target_reason_mask =
                    reason_oracle_miss_mask | reason_oracle_closest_hit_mask |
                    reason_oracle_anyhit_mask |
                    reason_oracle_intersection_mask |
                    reason_synthetic_split_mask;
                const unsigned hit_target_reason_mask =
                    reason_oracle_closest_hit_mask | reason_oracle_anyhit_mask |
                    reason_oracle_intersection_mask;
                const unsigned target_selector_ready_mask =
                    rtcore_shader_continuation_sbt_record_selector_ready_mask(
                        candidate_completion, target_reason_mask);
                const unsigned target_selector_missing_dispatch_mask =
                    target_reason_mask &
                    ~candidate_completion.handoff_selector_valid_mask;
                const unsigned target_selector_missing_hit_mask =
                    hit_target_reason_mask &
                    ~candidate_completion.handoff_candidate_valid_mask;
                const unsigned target_selector_fallback_reason_mask =
                    target_reason_mask & ~target_selector_ready_mask;
                const unsigned target_selector_cohort_count =
                    rtcore_shader_continuation_target_selector_cohort_count(
                        candidate_completion, target_selector_ready_mask,
                        reason_oracle_anyhit_mask,
                        reason_oracle_intersection_mask,
                        reason_synthetic_split_mask);
                const unsigned raw_fact_ray_sbt_inputs_ready_mask =
                    target_reason_mask &
                    candidate_completion.handoff_selector_valid_mask;
                const unsigned raw_fact_geometry_primitive_ready_mask =
                    hit_target_reason_mask &
                    candidate_completion.handoff_candidate_valid_mask;
                const unsigned raw_fact_instance_sbt_contribution_ready_mask =
                    hit_target_reason_mask &
                    candidate_completion.handoff_selector_valid_mask;
                const unsigned raw_fact_hit_record_selector_formula_ready_mask =
                    rtcore_shader_continuation_hit_record_selector_ready_mask(
                        candidate_completion, hit_target_reason_mask);
                const unsigned raw_fact_hit_record_selector_formula_cohort_count =
                    rtcore_shader_continuation_hit_record_selector_cohort_count(
                        candidate_completion,
                        raw_fact_hit_record_selector_formula_ready_mask);
                const unsigned sbt_record_selector_ready_mask =
                    rtcore_shader_continuation_sbt_record_selector_ready_mask(
                        candidate_completion, target_reason_mask);
                const unsigned sbt_address_ready_mask =
                    sbt_record_selector_ready_mask;
                const unsigned sbt_address_missing_mask =
                    target_reason_mask & ~sbt_address_ready_mask;
                const unsigned sbt_address_cohort_count =
                    rtcore_shader_continuation_sbt_address_cohort_count(
                        candidate_completion, sbt_address_ready_mask,
                        target_reason_mask);
                rtcore_record_shader_continuation_sbt_address_cohorts(
                    m_sid, release_event->second.warp_uid,
                    release_event->second.warp_id,
                    release_event->second.issued_active_mask,
                    candidate_completion, sbt_address_ready_mask,
                    target_reason_mask, current_cycle);
                rtcore_record_shader_continuation_callshader_context_preflight(
                    m_core, it->second, m_sid, release_event->second.warp_uid,
                    release_event->second.warp_id,
                    release_event->second.issued_active_mask,
                    sbt_address_ready_mask, current_cycle);
                rtcore_record_shader_continuation_direct_callshader_action(
                    m_core, it->second, m_sid, release_event->second.warp_uid,
                    release_event->second.warp_id,
                    release_event->second.issued_active_mask,
                    candidate_completion, target_reason_mask,
                    sbt_address_ready_mask, current_cycle);
                rtcore_record_shader_continuation_loop_decision(
                    it->second, &release_event->second,
                    candidate_completion.packet_schema_version,
                    candidate_completion.lane_completion_valid_mask,
                    candidate_completion.terminal_lane_mask,
                    candidate_completion.continuation_lane_mask,
                    candidate_completion.unsupported_reason_mask,
                    candidate_completion.handoff_software_return_valid_mask,
                    reason_oracle_anyhit_mask, reason_oracle_intersection_mask,
                    reason_synthetic_split_mask, target_selector_ready_mask,
                    target_selector_missing_dispatch_mask,
                    target_selector_missing_hit_mask,
                    target_selector_fallback_reason_mask,
                    target_selector_cohort_count,
                    raw_fact_ray_sbt_inputs_ready_mask,
                    raw_fact_geometry_primitive_ready_mask,
                    raw_fact_instance_sbt_contribution_ready_mask,
                    raw_fact_hit_record_selector_formula_ready_mask,
                    raw_fact_hit_record_selector_formula_cohort_count,
                    sbt_address_ready_mask, sbt_address_missing_mask,
                    sbt_address_cohort_count, current_cycle);
              }
              rtcore_synthetic_release_snapshot release_snapshot =
                  rtcore_make_synthetic_release_snapshot(
                      it->second, release_event->second, current_cycle);
              rtcore_apply_synthetic_release_snapshot(release_snapshot);
            }
          }
        }
        retire_synthetic_completion(it->second);
        m_scoreboard->releaseRegisters(&it->second);
        m_core->warp_inst_complete(it->second);
        m_core->dec_inst_in_pipeline(it->second.warp_id());

        // Track number of warps in RT core
        if (it->second.rt_subop == RT_CORE_SUBOP_SUBMIT &&
            rtcore_v04_multiwarp_stats_enabled()) {
          rtcore_v04_multiwarp_stats_for(m_sid).submit_completions++;
        }
        n_warps--;
        assert(n_warps >= 0 && n_warps <= m_config->m_rt_max_warps);

        // Track completed warp uid
        completed_warp_uid = it->first;

        // Track warp latency in RT unit
        unsigned long long start_cycle = it->second.get_start_cycle();
        unsigned long long total_cycles = current_cycle - start_cycle;
        m_stats->rt_total_warp_latency += total_cycles;
        m_stats->rt_total_warps++;

        // #define PRINT_WARP_TIMING
        #ifdef PRINT_WARP_TIMING
        printf("sid: %2d wid: %2d uid: %5d start: %8d end: %8d total: %8d\n", 
          m_sid, it->second.warp_id(), it->second.get_uid(), start_cycle, current_cycle, total_cycles);
        #endif

        // Track thread latency in RT unit
        unsigned long long total_thread_cycles = 0;
        for (unsigned i=0; i<m_config->warp_size; i++) {
          if (it->second.thread_active(i)) {
            unsigned long long end_cycle = it->second.get_thread_end_cycle(i);
            assert(end_cycle > 0);
            int n_total_cycles = end_cycle - start_cycle;
            assert(n_total_cycles >= 0);
            total_thread_cycles += n_total_cycles;
            m_stats->add_rt_latency_dist(it->second.get_latency_dist(i));
          }
        }
        float avg_thread_cycles = (float)total_thread_cycles / m_config->warp_size;
        m_stats->rt_total_thread_latency += avg_thread_cycles;

        float rt_simt_efficiency = (float)total_thread_cycles / (m_config->warp_size * total_cycles);
        m_stats->rt_total_simt_efficiency += rt_simt_efficiency;
        
        // Complete max 1 warp per cycle (?)
        break;
      }
    } else {
      RT_DPRINTF(
          "Cycle: %d, Warp inst uid: %d not done. rt_mem_accesses_empty: %d, "
          "rt_intersection_delay_done: %d, no pending_writes: %d\n",
          GPGPU_Context()->the_gpgpusim->g_the_gpu->gpu_sim_cycle,
          debug_inst.get_uid(), it->second.rt_mem_accesses_empty(),
          it->second.rt_intersection_delay_done(),
          !it->second.has_pending_writes());
    }
    }

  // Remove complete warp
  if (completed_warp_uid >= 0) {
    m_current_warps.erase(completed_warp_uid);
  }
  
  assert(n_warps == m_current_warps.size());
  assert(cacheline_count <= 2);
}

void rt_unit::process_memory_response(mem_fetch* mf, warp_inst_t &pipe_reg) {
                    
  // If more than 1 warp in RT unit:
  if (m_config->m_rt_max_warps > 0) {
    
    // Clear all warps if coalesced
    if (m_config->m_rt_coalesce_warps) {
      unsigned requester_thread_found = 0;
      requester_thread_found += pipe_reg.process_returned_mem_access(mf);
      for (auto it=m_current_warps.begin(); it!=m_current_warps.end(); ++it) {
        requester_thread_found += (it->second).process_returned_mem_access(mf);
      }

      // Make sure at least one thread accepted the response. (Other threads might still be completing intersection test)
      if (requester_thread_found == 0) {
        // Might occur in warp coalescing in rare cases when multiple requests were sent, but only 1 was necessary
        RT_DPRINTF("Requester not found for: 0x%x\n", mf->get_addr());
      }
    } 
    
    // If not coalescing warps
    else if (!m_config->bypassL0Complet){
      // Check MSHR for all accessed to this address
      std::list<mem_fetch *> response_mf;
      if (m_config->m_rt_use_l1d) {
        response_mf = L1D->probe_mshr(mf->get_addr());
      }
      else {
        response_mf = m_L0_complet->probe_mshr(mf->get_addr());
      }
      unsigned requester_thread_found = 0;
      for (auto it=response_mf.begin(); it!=response_mf.end(); ++it) {
        mem_fetch* response = *it;
        // Check all the warps
        for (auto it=m_current_warps.begin(); it!=m_current_warps.end(); it++) {
          if (it->second.warp_id() == response->get_wid()) {
            requester_thread_found += it->second.process_returned_mem_access(mf);
          }
        }
      }
      
      // Make sure at least one thread accepted the response. (Other threads might still be completing intersection test)
      if (requester_thread_found == 0) {
        RT_DPRINTF("Requester not found for: 0x%x\n", mf->get_addr());
      }
    }
    
    // If not using the cache
    else {
      for (auto it=m_current_warps.begin(); it!=m_current_warps.end(); it++) {
        if (it->second.warp_id() == mf->get_wid()) {
          it->second.process_returned_mem_access(mf);
        }
      }
    }
  } 
  
  // If only a single warp
  else {
    // Clear response from list of in flight mem accesses
    pipe_reg.process_returned_mem_access(mf);
  }   
}

void rt_unit::schedule_next_warp(warp_inst_t &inst) {
  // Return if there are no warps in the RT unit
  if (m_current_warps.empty()) return;
      
  // Otherwise, find the first non-stalled warp
  else {
    for (auto it=m_current_warps.begin(); it!=m_current_warps.end(); ++it) {
      if (!((it->second).is_stalled())) { 
        inst = it->second;
        break;
      }
    }
    if (!inst.empty()) m_current_warps.erase(inst.get_uid());
  }
}

void rt_unit::memory_cycle(warp_inst_t &inst) {
  mem_chunk = false;
  mem_fetch *mf;
  
  // If there are still accesses waiting in mem_access_q, send those first
  if (!mem_access_q.empty()) {
    mem_chunk = true;
    RT_DPRINTF("Shader %d: Prioritizing mem_access_q entries (%d entries remaining)\n", m_sid, mem_access_q.size());
    mf = process_memory_chunks(inst);
    if (mf) process_cache_access(m_config->m_rt_use_l1d ? (baseline_cache *)L1D : (baseline_cache *)m_L0_complet, inst, mf);
  }

  // Otherwise check for stores
  else if (!mem_store_q.empty()) {
    assert(inst.empty());
    RT_DPRINTF("Shader %d: Prioritizing stores\n", m_sid);
    mf = process_memory_stores();
    inst = mf->get_inst();
    m_current_warps.erase(inst.get_uid());
    mem_access_q_type = static_cast<int>(TransactionType::UNDEFINED);
    if (mf) process_cache_access(L1D, inst, mf);
  }

  else {
    // If MSHR is at the "limit" don't sent new requests
    if (m_config->m_rt_max_warps > 0 && m_L0_complet->num_mshr_entries() > m_config->m_rt_max_mshr_entries) return;
    
    // Return if there are no active threads
    if (!inst.active_count()) return;
    
    // If we make it here, there should be a valid warp to work with
    assert(inst.space.get_type() == global_space);
    
    // If waiting for responses, don't send new requests
    if (!m_config->m_rt_coherence_engine && inst.is_stalled()) return;
    
    // If coherence engine is stalled, don't send new request
    // TODO: Fix the thread intersection latencies so this doesn't happen
    if (m_config->m_rt_coherence_engine && !m_ray_coherence_engine->active()) return;

    // Continue to next step
    RT_DPRINTF("Shader %d: Processing next memory access\n", m_sid);
    mf = process_memory_access_queue(inst);
    if (mf) process_cache_access(m_config->m_rt_use_l1d ? (baseline_cache *)L1D : (baseline_cache *)m_L0_complet, inst, mf);
  }
}


void rt_unit::writeback() {
  while (m_L0_complet->access_ready()) {
    mem_fetch *mf = m_L0_complet->next_access();
    // m_next_wb = mf->get_inst();
    delete mf;
    // serviced_client = next_client;
  }
  // Check if it's for the RT unit or the LDST unit
  while (L1D->access_ready()) {
    if (!L1D->next_access_rt()) {
      rtcore_record_v02_lsu_shared_l1d_response_rt_blocked_by_normal();
      rtcore_maybe_log_memory_unit_request_offer_stats(m_sid);
      break;
    }
    mem_fetch *mf = L1D->next_access();
    // m_next_wb = mf->get_inst();
    const unsigned long long current_cycle =
        m_core->get_gpu()->gpu_sim_cycle +
        m_core->get_gpu()->gpu_tot_sim_cycle;
    rtcore_maybe_complete_v02_lsu_sideband_ready_access(
        mf, current_cycle, m_core->get_gpu()->get_global_memory());
    rtcore_record_v02_lsu_shared_l1d_response_rt_serviced();
    rtcore_maybe_log_memory_unit_request_offer_stats(m_sid);
    delete mf;
    // serviced_client = next_client;
  }
}


mem_access_t rt_unit::create_mem_access(new_addr_type addr) {
  // RT-CORE NOTE Temporary hard coded values
  unsigned segment_size = 32;
  unsigned data_size = 32;
  bool is_wr = false;
  
  unsigned warp_parts = m_config->mem_warp_parts;
  unsigned subwarp_size = m_config->warp_size / warp_parts;
  
  new_addr_type block_address = line_size_based_tag_func(addr, segment_size);
  unsigned chunk = (addr & 127) / 32;
  
  warp_inst_t::transaction_info info;
  info.chunks.set(chunk);
  unsigned idx = (addr & 127);
  for (unsigned i=0; i<data_size; i++) {
    if ((idx + i) < MAX_MEMORY_ACCESS_SIZE) info.bytes.set(idx + i);
  }
  
  assert((block_address & (segment_size - 1)) == 0);
  
  mem_access_t access(  GLOBAL_ACC_R, block_address, segment_size, is_wr,
                        info.active, info.bytes, info.chunks,
                        m_config->gpgpu_ctx);
  access.set_uncoalesced_addr(addr);
  return access;
}


mem_fetch* rt_unit::process_memory_stores() {
  assert(!mem_store_q.empty());
  
  auto next_store = mem_store_q.front();
  new_addr_type next_addr = next_store.second;
  unsigned warp_uid = next_store.first;
  unsigned size = RT_WRITE_BACK_SIZE;

  // Create the mem_access_t
  unsigned segment_size = 32;
  unsigned data_size = RT_WRITE_BACK_SIZE;
  bool is_wr = true;
  unsigned block_address = line_size_based_tag_func(next_addr, segment_size);
  unsigned chunk = (next_addr & 127) / 32;
  
  warp_inst_t::transaction_info info;
  info.chunks.set(chunk);
  unsigned idx = (next_addr & 127);
  for (unsigned i=0; i<data_size; i++) {
    if ((idx + i) < MAX_MEMORY_ACCESS_SIZE) info.bytes.set(idx + i);
  }
  
  assert((block_address & (segment_size - 1)) == 0);
  
  mem_access_t access(  GLOBAL_ACC_W, block_address, segment_size, is_wr,
                        info.active, info.bytes, info.chunks,
                        m_config->gpgpu_ctx);
  access.set_uncoalesced_addr(next_addr);
  access.set_uncoalesced_base_addr(next_addr);

  RT_DPRINTF("Shader %d: store mem_access_t created for 0x%x\n", m_sid, access.get_addr());
  
  // Create mf
  mem_fetch *mf = m_mf_allocator->alloc(
    m_current_warps[warp_uid], access, m_core->get_gpu()->gpu_sim_cycle + m_core->get_gpu()->gpu_tot_sim_cycle
  ); 
  mf->set_raytrace();

  mem_store_q.pop_front();
  return mf;
}

mem_fetch* rt_unit::process_memory_chunks(warp_inst_t &inst) {
  assert(!mem_access_q.empty());

  new_addr_type next_addr = mem_access_q.front();
  new_addr_type base_addr = mem_access_q_base_addr;
  mem_access_q.pop_front();

  // Create the mem_access_t
  mem_access_t access = create_mem_access(next_addr);
  access.set_uncoalesced_base_addr(base_addr);
  RT_DPRINTF("Shader %d: mem_access_t created for 0x%x (block address 0x%x, base address 0x%x)\n", m_sid, next_addr, access.get_addr(), base_addr);
  
  // Create mf
  mem_fetch *mf = m_mf_allocator->alloc(
    inst, access, m_core->get_gpu()->gpu_sim_cycle + m_core->get_gpu()->gpu_tot_sim_cycle
  ); 
  mf->set_raytrace();
  m_stats->gpgpu_n_rt_mem[mem_access_q_type]++;
  return mf;
}

mem_fetch* rt_unit::process_memory_access_queue(warp_inst_t &inst) {
  if (inst.rt_mem_accesses_empty()) return NULL;
  
  RTMemoryTransactionRecord next_access;
  if (m_config->m_rt_coherence_engine) {
    next_access = m_ray_coherence_engine->get_next_access();
  }
  else {
    next_access = inst.get_next_rt_mem_transaction();
  }
  new_addr_type next_addr = next_access.address;
  new_addr_type base_addr = next_access.address;
  
  // Track memory access type stats
  mem_access_q_type = static_cast<int>(next_access.type);
  
  // If the size is larger than 32B, then split into chunks and add remaining chunks into mem_access_q
  if (next_access.size > 32) {
    RT_DPRINTF("Shader %d: Memory request > 32B. %dB request at 0x%x added chunks ", m_sid, next_access.size, next_access.address);
    // Save the base address
    mem_access_q_base_addr = next_access.address;
    // Save the warp id
    mem_access_q_warp_uid = inst.get_uid();
    
    // Create the memory chunks and push to mem_access_q
    for (unsigned i=1; i<((next_access.size+31)/32); i++) {
      mem_access_q.push_back((new_addr_type)(next_access.address + (i * 32)));
      RT_DPRINTF("0x%x, ", next_access.address + (i * 32));
    }
    RT_DPRINTF("\n");
  }

  // Create the mem_access_t
  mem_access_t access = create_mem_access(next_addr);
  access.set_uncoalesced_base_addr(base_addr);
  RT_DPRINTF("Shader %d: mem_access_t created for 0x%x (block address 0x%x, base address 0x%x)\n", m_sid, next_addr, access.get_addr(), base_addr);
  
  // Create mf
  mem_fetch *mf = m_mf_allocator->alloc(
    inst, access, m_core->get_gpu()->gpu_sim_cycle + m_core->get_gpu()->gpu_tot_sim_cycle
  ); 
  mf->set_raytrace();
  m_stats->gpgpu_n_rt_mem[mem_access_q_type]++;

  return mf;
}

void rt_unit::process_cache_access(baseline_cache *cache, warp_inst_t &inst, mem_fetch *mf) {
  assert(mf != NULL);

  enum cache_request_status status;
  std::list<cache_event> events;
      
  if (m_config->bypassL0Complet) {
    // bypass L1 cache
    unsigned control_size = 8;
    unsigned size = mf->get_access_size() + control_size;
    // printf("Interconnect:Addr: %x, size=%d\n",access.get_addr(),size);
    if (!m_icnt->full(size, inst.is_store() || inst.isatomic())) {
      m_icnt->push(mf);
      return;
    }
  }

  else if (m_config->m_rt_perfect_mem) {
    new_addr_type addr = mf->get_addr();
    new_addr_type uncoalesced_base_addr = mf->get_uncoalesced_base_addr();

    // Every access is considered a cache hit
    m_stats->rt_total_cacheline_fetched[m_sid]++;
    cacheline_count++;

    // Handle write ACKs
    if (mf->get_is_write()) {
      m_stats->rt_writes++;
      inst.check_pending_writes(uncoalesced_base_addr);
    }
    else if (m_config->m_rt_coherence_engine) {
      std::map<unsigned, warp_inst_t *> m_warp_pointers;
      for (auto it=m_current_warps.begin(); it!=m_current_warps.end(); it++) {
        m_warp_pointers[it->first] = &it->second;
      }
      m_ray_coherence_engine->process_response(mf, m_warp_pointers, &inst);
      if (!inst.empty()) m_current_warps[inst.get_uid()] = inst;
      inst.clear();
    }
    else {
      unsigned found = 0;
      found += inst.process_returned_mem_access(mf);
      
      if (m_config->m_rt_coalesce_warps) {
        for (auto it=m_current_warps.begin(); it!=m_current_warps.end(); ++it) {
          if (found > 0) {
            (it->second).process_returned_mem_access(mf);
          }
          else {
            (it->second).process_returned_mem_access(mf);
          }
        }
      }
    }
    
    delete mf;
    return;
  }
    
  else {
    RT_DPRINTF("Shader %d: Sending cache request for 0x%x\n", m_sid, mf->get_uncoalesced_addr());
    
    m_stats->rt_mem_requests++;

    // Access cache
    status = cache->access(
      mf->get_addr(), mf,
      m_core->get_gpu()->gpu_sim_cycle + m_core->get_gpu()->gpu_tot_sim_cycle,
      events
    );
  }
  
  new_addr_type addr = mf->get_addr();
  new_addr_type base_addr = mf->get_uncoalesced_base_addr();

  // Stalled
  if (status == RESERVATION_FAIL) {
    // If write, add back to write queue
    if (mf->get_is_write()) {
      mem_store_q.push_front(
        std::pair<unsigned, new_addr_type>(
          mf->get_inst().get_uid(),
          mf->get_uncoalesced_base_addr()));
    }

    // Address already in MSHR, but MSHR entry is full
    else if (!cache->probe_mshr(mf->get_addr()).empty()) {
      
      // If using warp coalescing, this is irrelevant
      if (m_config->m_rt_coalesce_warps) {
        RT_DPRINTF("0x%x\n", mf->get_addr());
      }
      
      // Otherwise, the request cannot be handled this cycle
      else {
        RT_DPRINTF("Shader %d: Reservation fail, undoing request for 0x%x (base 0x%x)\n", m_sid, mf->get_uncoalesced_addr(), mf->get_uncoalesced_base_addr());
        if (mem_chunk) {
          mem_access_q.push_front(mf->get_uncoalesced_addr());
        }
        else {
          if (m_config->m_rt_coherence_engine) m_ray_coherence_engine->undo_access(mf->get_uncoalesced_addr());
          else inst.undo_rt_access(mf->get_uncoalesced_addr());
        }
        m_stats->gpgpu_n_rt_mem[mem_access_q_type]--;
      }
    }
    else {
      RT_DPRINTF("Shader %d: Reservation fail, undoing request for 0x%x (base 0x%x)\n", m_sid, mf->get_uncoalesced_addr(), mf->get_uncoalesced_base_addr());
      if (mem_chunk) {
        mem_access_q.push_front(mf->get_uncoalesced_addr());
      }
      else {
        if (m_config->m_rt_coherence_engine) m_ray_coherence_engine->undo_access(mf->get_uncoalesced_addr());
        else inst.undo_rt_access(mf->get_uncoalesced_addr());
      }
      m_stats->gpgpu_n_rt_mem[mem_access_q_type]--;
    }
    delete mf;
  }
  
  else if (status == HIT) {
    RT_DPRINTF("Shader %d: Cache hit for 0x%x (base 0x%x)\n", m_sid, mf->get_uncoalesced_addr(), mf->get_uncoalesced_base_addr());
    
    // Every cache hit is a returned cacheline
    m_stats->rt_total_cacheline_fetched[m_sid]++;
    cacheline_count++;

    if (m_config->m_rt_coherence_engine) {
      std::map<unsigned, warp_inst_t *> m_warp_pointers;
      for (auto it=m_current_warps.begin(); it!=m_current_warps.end(); it++) {
        m_warp_pointers[it->first] = &it->second;
      }
      m_ray_coherence_engine->process_response(mf, m_warp_pointers, &inst);
      if (!inst.empty()) m_current_warps[inst.get_uid()] = inst;
      inst.clear();
    }
    else {
      unsigned found = 0;
      found += inst.process_returned_mem_access(mf);
      
      if (m_config->m_rt_coalesce_warps) {
        for (auto it=m_current_warps.begin(); it!=m_current_warps.end(); ++it) {
          if (found > 0) {
            (it->second).process_returned_mem_access(mf);
          }
          else {
            (it->second).process_returned_mem_access(mf);
          }
        }
      }
    }
    
    if (!mf->is_write()) delete mf;
    
  } else {
    assert(status == MISS);
  }
}

void rt_unit::fill(mem_fetch *mf) {
  if (rtcore_maybe_consume_v02_lsu_sideband_memory_response(
          mf, m_config, m_core, (baseline_cache *)L1D,
          (baseline_cache *)m_L0_complet)) {
    return;
  }
  // RT-CORE NOTE: Add a new status (IN_SHADER_RT_RESPONSE_FIFO)
  mf->set_status(
      IN_SHADER_LDST_RESPONSE_FIFO,
      m_core->get_gpu()->gpu_sim_cycle + m_core->get_gpu()->gpu_tot_sim_cycle);
  m_response_fifo.push_back(mf);
}

void ldst_unit::init(mem_fetch_interface *icnt,
                     shader_core_mem_fetch_allocator *mf_allocator,
                     shader_core_ctx *core, opndcoll_rfu_t *operand_collector,
                     Scoreboard *scoreboard, const shader_core_config *config,
                     const memory_config *mem_config, shader_core_stats *stats,
                     unsigned sid, unsigned tpc) {
  m_memory_config = mem_config;
  m_icnt = icnt;
  m_mf_allocator = mf_allocator;
  m_core = core;
  m_operand_collector = operand_collector;
  m_scoreboard = scoreboard;
  m_stats = stats;
  m_sid = sid;
  m_tpc = tpc;
#define STRSIZE 1024
  char L1T_name[STRSIZE];
  char L1C_name[STRSIZE];
  snprintf(L1T_name, STRSIZE, "L1T_%03d", m_sid);
  snprintf(L1C_name, STRSIZE, "L1C_%03d", m_sid);
  m_L1T = new tex_cache(L1T_name, m_config->m_L1T_config, m_sid,
                        get_shader_texture_cache_id(), icnt, IN_L1T_MISS_QUEUE,
                        IN_SHADER_L1T_ROB);
  m_L1C = new read_only_cache(L1C_name, m_config->m_L1C_config, m_sid,
                              get_shader_constant_cache_id(), icnt,
                              IN_L1C_MISS_QUEUE);
  m_L1D = NULL;
  m_mem_rc = NO_RC_FAIL;
  m_num_writeback_clients =
      5;  // = shared memory, global/local (uncached), L1D, L1T, L1C
  m_writeback_arb = 0;
  m_next_global = NULL;
  m_last_inst_gpu_sim_cycle = 0;
  m_last_inst_gpu_tot_sim_cycle = 0;
}

ldst_unit::ldst_unit(mem_fetch_interface *icnt,
                     shader_core_mem_fetch_allocator *mf_allocator,
                     shader_core_ctx *core, opndcoll_rfu_t *operand_collector,
                     Scoreboard *scoreboard, const shader_core_config *config,
                     const memory_config *mem_config, shader_core_stats *stats,
                     unsigned sid, unsigned tpc)
    : pipelined_simd_unit(NULL, config, config->smem_latency, core),
      m_next_wb(config) {
  assert(config->smem_latency > 1);
  init(icnt, mf_allocator, core, operand_collector, scoreboard, config,
       mem_config, stats, sid, tpc);
  if (!m_config->m_L1D_config.disabled()) {
    char L1D_name[STRSIZE];
    snprintf(L1D_name, STRSIZE, "L1D_%03d", m_sid);
    m_L1D = new l1_cache(L1D_name, m_config->m_L1D_config, m_sid,
                         get_shader_normal_cache_id(), m_icnt, m_mf_allocator,
                         IN_L1D_MISS_QUEUE, core->get_gpu());

    l1_latency_queue.resize(m_config->m_L1D_config.l1_banks);
    assert(m_config->m_L1D_config.l1_latency > 0);

    for (unsigned j = 0; j < m_config->m_L1D_config.l1_banks; j++)
      l1_latency_queue[j].resize(m_config->m_L1D_config.l1_latency,
                                 (mem_fetch *)NULL);
  }
  m_name = "MEM ";
}

ldst_unit::ldst_unit(mem_fetch_interface *icnt,
                     shader_core_mem_fetch_allocator *mf_allocator,
                     shader_core_ctx *core, opndcoll_rfu_t *operand_collector,
                     Scoreboard *scoreboard, const shader_core_config *config,
                     const memory_config *mem_config, shader_core_stats *stats,
                     unsigned sid, unsigned tpc, l1_cache *new_l1d_cache)
    : pipelined_simd_unit(NULL, config, 3, core),
      m_L1D(new_l1d_cache),
      m_next_wb(config) {
  init(icnt, mf_allocator, core, operand_collector, scoreboard, config,
       mem_config, stats, sid, tpc);
}

void ldst_unit::issue(register_set &reg_set) {
  warp_inst_t *inst = *(reg_set.get_ready());

  // record how many pending register writes/memory accesses there are for this
  // instruction
  assert(inst->empty() == false);
  if (inst->is_load() and inst->space.get_type() != shared_space) {
    unsigned warp_id = inst->warp_id();
    unsigned n_accesses = inst->accessq_count();
    for (unsigned r = 0; r < MAX_OUTPUT_VALUES; r++) {
      unsigned reg_id = inst->out[r];
      if (reg_id > 0) {
        m_pending_writes[warp_id][reg_id] += n_accesses;
      }
    }
  }

  inst->op_pipe = MEM__OP;
  // stat collection
  m_core->mem_instruction_stats(*inst);
  m_core->incmem_stat(m_core->get_config()->warp_size, 1);
  pipelined_simd_unit::issue(reg_set);
}

void ldst_unit::release_virtual_entries(warp_inst_t &inst) {
 	if (inst.is_bru_st_fill_request()) {
 		unsigned wid = inst.warp_id();
 		address_type addr = inst.pc;
 		unsigned entry = (addr - BRU_VIR_START - (wid*m_config->warp_size)*MAX_BRU_VIR_PER_SPLIT)/(MAX_BRU_VIR_PER_SPLIT);
 		bool done = m_core->push_to_st_response_fifo(wid,entry);
 		if (done) {
 			inst.clear();
 			inst.clear_pending_mem_requests();
 		}
 	} else {
 		assert(inst.is_bru_rt_fill_request());
 		unsigned wid = inst.warp_id();
 		address_type addr = inst.pc;
 		unsigned entry = (addr - BRU_VIR_START - (wid*m_config->warp_size)*MAX_BRU_VIR_PER_SPLIT - MAX_BRU_VIR_PER_SPLIT/2)/(MAX_BRU_VIR_PER_SPLIT);
 		bool done = m_core->push_to_rt_response_fifo(wid,entry);
 		if (done) {
 			inst.clear();
 			inst.clear_pending_mem_requests();
 		}
 	}
}

void ldst_unit::writeback() {
  // process next instruction that is going to writeback
  if (!m_next_wb.empty()) {
    // if (m_operand_collector->writeback(m_next_wb)) {
    if (m_next_wb.is_bru_st_fill_request() || m_next_wb.is_bru_rt_fill_request()) {
      release_virtual_entries(m_next_wb);
      if (m_next_wb.is_bru_st_fill_request()) {
        GPGPU_Context()->the_gpgpusim->g_the_gpu->gpu_st_fills_misses++;
      } else {
        GPGPU_Context()->the_gpgpusim->g_the_gpu->gpu_rt_fills_misses++;
      }
    } else if (m_operand_collector->writeback(m_next_wb)) {
      bool insn_completed = false;
      for (unsigned r = 0; r < MAX_OUTPUT_VALUES; r++) {
        if (m_next_wb.out[r] > 0) {
          if (m_next_wb.space.get_type() != shared_space) {
            assert(m_pending_writes[m_next_wb.warp_id()][m_next_wb.out[r]] > 0);
            unsigned still_pending =
                --m_pending_writes[m_next_wb.warp_id()][m_next_wb.out[r]];
            if (!still_pending) {
              m_pending_writes[m_next_wb.warp_id()].erase(m_next_wb.out[r]);
              m_scoreboard->releaseRegister(m_next_wb.warp_id(),
                                            m_next_wb.out[r]);
              insn_completed = true;
            }
          } else {  // shared
            m_scoreboard->releaseRegister(m_next_wb.warp_id(),
                                          m_next_wb.out[r]);
            insn_completed = true;
          }
        }
      }
      if (insn_completed) {
        m_core->warp_inst_complete(m_next_wb);
      }
      m_next_wb.clear();
      m_last_inst_gpu_sim_cycle = m_core->get_gpu()->gpu_sim_cycle;
      m_last_inst_gpu_tot_sim_cycle = m_core->get_gpu()->gpu_tot_sim_cycle;
    }
  }

  unsigned serviced_client = -1;
  for (unsigned c = 0; m_next_wb.empty() && (c < m_num_writeback_clients);
       c++) {
    unsigned next_client = (c + m_writeback_arb) % m_num_writeback_clients;
    switch (next_client) {
      case 0:  // shared memory
        if (!m_pipeline_reg[0]->empty()) {
          m_next_wb = *m_pipeline_reg[0];
          if (m_next_wb.isatomic()) {
            m_next_wb.do_atomic();
            m_core->decrement_atomic_count(m_next_wb.warp_id(),
                                           m_next_wb.active_count());
          }
          m_core->dec_inst_in_pipeline(m_pipeline_reg[0]->warp_id());
          m_pipeline_reg[0]->clear();
          serviced_client = next_client;
        }
        break;
      case 1:  // texture response
        if (m_L1T->access_ready()) {
          mem_fetch *mf = m_L1T->next_access();
          m_next_wb = mf->get_inst();
          delete mf;
          serviced_client = next_client;
        }
        break;
      case 2:  // const cache response
        if (m_L1C->access_ready()) {
          mem_fetch *mf = m_L1C->next_access();
          m_next_wb = mf->get_inst();
          delete mf;
          serviced_client = next_client;
        }
        break;
      case 3:  // global/local
        if (m_next_global) {
          m_next_wb = m_next_global->get_inst();
          if (m_next_global->isatomic()) {
            m_core->decrement_atomic_count(
                m_next_global->get_wid(),
                m_next_global->get_access_warp_mask().count());
          }
          delete m_next_global;
          m_next_global = NULL;
          serviced_client = next_client;
        }
        break;
      case 4:
        if (m_L1D && m_L1D->access_ready()) {
          // Check if it's for RT unit or for LDST unit
          if (m_L1D->next_access_rt()) {
            rtcore_record_v02_lsu_shared_l1d_response_normal_blocked_by_rt();
            rtcore_maybe_log_memory_unit_request_offer_stats(m_sid);
          } else {
            mem_fetch *mf = m_L1D->next_access();
            if (!mf->israytrace()) {
              m_next_wb = mf->get_inst();
              rtcore_v04_complete_publication_ticket(
                  mf, m_core->get_gpu()->gpu_sim_cycle +
                          m_core->get_gpu()->gpu_tot_sim_cycle);
              rtcore_record_v02_lsu_shared_l1d_response_normal_serviced();
              rtcore_maybe_log_memory_unit_request_offer_stats(m_sid);
              delete mf;
              serviced_client = next_client;
            }
          }
        }
        break;
      default:
        abort();
    }
  }
  // update arbitration priority only if:
  // 1. the writeback buffer was available
  // 2. a client was serviced
  if (serviced_client != (unsigned)-1) {
    m_writeback_arb = (serviced_client + 1) % m_num_writeback_clients;
  }
}

unsigned ldst_unit::clock_multiplier() const {
  // to model multiple read port, we give multiple cycles for the memory units
  if (m_config->mem_unit_ports)
    return m_config->mem_unit_ports;
  else
    return m_config->mem_warp_parts;
}
